// ═══════════════ 每日一句：俄语口语三语数据 ═══════════════
// 14 大分类：日常 8 类 + 高分子 / 职场 / 情感 / 天气 / 科技 + 谚语熟语
// 每条 { ru, zh, en, ctx?, say? }
//   ru/zh/en：俄语场景对话（混合单句与多轮对话）+ 中英文对应
//   ctx：场景标签（中文 4-10 字）
//   say：TTS 朗读专用文本——ru 含数字/单位/缩写/拉丁字母时提供完整朗读形式
// 句子级不加重音符号 U+0301；speak() 朗读前用 ttsNormalize 兜底
// 由 src/components/russian-toolkit.tsx 的 DailyPhrase 组件按日轮换展示

export type Phrase = { ru: string; zh: string; en: string; ctx?: string; say?: string }

export type PhraseCatId =
  | 'greet'
  | 'intro'
  | 'study'
  | 'food'
  | 'transit'
  | 'shop'
  | 'health'
  | 'service'
  | 'polymer'
  | 'work'
  | 'emotion'
  | 'weather'
  | 'tech'
  | 'proverb'

export type PhraseCat = { id: PhraseCatId; items: Phrase[] }

// ── 寒暄问候 / Greetings / Приветствия ──
const GREET: Phrase[] = [
  { ru: 'Доброе утро! Как спалось? Надеюсь, без кошмаров.', zh: '早上好！睡得怎么样？但愿没做噩梦。', en: 'Good morning! Did you sleep well? No nightmares, I hope.', ctx: '早晨非正式问候' },
  { ru: '— Доброе утро, Анна Сергеевна!\n— Доброе, Миша. Проходи, чай как раз вскипел.', zh: '——早上好，安娜·谢尔盖耶夫娜！\n——早，米沙。进来吧，茶刚好烧开。', en: '— Good morning, Anna Sergeevna!\n— Morning, Misha. Come in, the tea has just boiled.', ctx: '晚辈早晨问候长辈' },
  { ru: 'Здравствуйте! Рада вас видеть у нас в офисе, проходите.', zh: '您好！很高兴在办公室见到您，请进。', en: 'Hello! I\'m glad to see you at our office, come in.', ctx: '正式欢迎访客' },
  { ru: '— Привет! Сто лет тебя не видела. Ну как ты?\n— Да ничего, потихоньку. А ты всё цветёшь!', zh: '——嗨！一百年没见你了。你怎么样？\n——还行，凑合过。你倒是越发光彩照人了！', en: '— Hi! Haven\'t seen you in ages. How are you?\n— Not bad, getting by. And you look lovelier than ever!', ctx: '老友见面问候' },
  { ru: '— Добрый день! Не подскажете, который час?\n— Половина третьего.', zh: '——下午好！请问现在几点？\n——两点半。', en: '— Good afternoon! Could you tell me the time?\n— Half past two.', ctx: '路人询问时间' },
  { ru: 'Добрый вечер, соседи! Чем это у вас так вкусно пахнет?', zh: '晚上好，邻居们！你们家什么东西这么香？', en: 'Good evening, neighbors! What\'s that delicious smell coming from your place?', ctx: '邻居晚间打招呼' },
  { ru: '— Привет-привет! Заходи, раздевайся, у нас как раз борщ.\n— О, спасибо! С дороги борщ — самое то!', zh: '——嗨嗨！快进来，脱外套，我们正好有红菜汤。\n——哦，谢谢！赶路之后来碗汤，正合适！', en: '— Hi there! Come in, take your coat off, we\'ve got borscht on.\n— Oh, thanks! Borscht after a trip is just the thing!', ctx: '迎客进门吃饭' },
  { ru: '— Здравствуй, мама! Да, доехал нормально, всё хорошо.\n— Слава богу! Ешь как следует, слышишь?', zh: '——妈，你好！我到了，一路顺利，一切都好。\n——谢天谢地！好好吃饭，听见没？', en: '— Hi, Mom! Yes, I arrived fine, everything\'s good.\n— Thank God! Eat properly, you hear me?', ctx: '到家向母亲报平安' },
  { ru: '— Доброй ночи всем!\n— Спокойной ночи, Лёша, не засиживайся допоздна.', zh: '——大家晚安！\n——晚安，廖沙，别熬到太晚。', en: '— Good night, everyone!\n— Night, Lyosha, don\'t stay up too late.', ctx: '睡前互道晚安' },
  { ru: 'О, Слава! Привет! Ты ли это? Вот не ожидала!', zh: '哦，斯拉瓦！嗨！真是你吗？完全没想到！', en: 'Oh, Slava! Hi! Is that really you? What a surprise!', ctx: '街头惊喜相遇' },
  { ru: 'Доброе утро! Просыпайся, а то опоздаешь на электричку.', zh: '早上好！快起床，不然要误了市郊火车。', en: 'Good morning! Wake up, or you\'ll miss the commuter train.', ctx: '早上催促起床' },
  { ru: '— Здравствуйте, Иван Петрович. Как ваше здоровье?\n— Спасибо, голубушка, потихоньку. А вы как?', zh: '——您好，伊万·彼得罗维奇。身体怎么样？\n——谢谢，姑娘，马马虎虎。您呢？', en: '— Hello, Ivan Petrovich. How\'s your health?\n— Thank you, dear, so-so. And how are you?', ctx: '晚辈问候老人健康' },
  { ru: 'Приветствую вас, дорогие гости! Проходите к столу.', zh: '欢迎各位亲爱的客人！请入席。', en: 'Welcome, dear guests! Please come to the table.', ctx: '宴会欢迎宾客' },
  { ru: '— Хай! Чё как?\n— Да ничё, живы будём — не помрём!', zh: '——嗨！咋样？\n——还行呗，好死不如赖活着！', en: '— Hey! What\'s up?\n— Not much, we\'ll manage somehow!', ctx: '青年俚语问候' },
  { ru: '— Добрый день, коллеги. Начнём совещание через 5 минут.\n— Хорошо, я как раз закончу письмо.', zh: '——下午好，各位同事。会议五分钟后开始。\n——好的，我正好把这封邮件写完。', en: '— Good afternoon, colleagues. The meeting starts in five minutes.\n— All right, I\'ll just finish this email.', ctx: '会议开始前通知', say: 'Добрый день, коллеги. Начнём совещание через пять минут. Хорошо, я как раз закончу письмо.' },
  { ru: 'Привет, солнце! Улыбнись, новый день начался.', zh: '早安，小太阳！笑一笑，新的一天开始了。', en: 'Good morning, sunshine! Smile, a new day has begun.', ctx: '恋人晨间问候' },
  { ru: '— Здравствуйте, это поликлиника?\n— Да, регистратура слушает вас.', zh: '——您好，请问是门诊部吗？\n——是的，这里是挂号处，请讲。', en: '— Hello, is this the clinic?\n— Yes, registration desk speaking.', ctx: '电话打到诊所' },
  { ru: 'Добрый вечер! Я дома, устал как собака.', zh: '晚上好！我到家了，累成狗了。', en: 'Good evening! I\'m home, dog-tired.', ctx: '下班回家问候' },
  { ru: '— Здорово, братан! Сколько лет, сколько зим!\n— Здорово! Годы идут, а мы не стареем!', zh: '——嘿，兄弟！多少年没见了！\n——嘿！岁月流逝，我们可一点没老！', en: '— Hey, bro! Long time no see!\n— Hey! Years go by, but we never age!', ctx: '兄弟久别打招呼' },
  { ru: '— Доброго вам вечерочка, господа хорошие!\n— И тебе доброго, старик. Садись к костру.', zh: '——晚上好啊，各位好心人！\n——你也晚上好，老哥。来篝火边坐。', en: '— A very good evening to you, good folks!\n— Good evening to you too, old man. Sit by the fire.', ctx: '旅途营地寒暄' },
  { ru: 'До свидания, Елена Викторовна! Было очень приятно пообщаться.', zh: '再见，叶莲娜·维克托罗夫娜！和您聊天非常愉快。', en: 'Goodbye, Elena Viktorovna! It was a real pleasure talking with you.', ctx: '正式告别女士' },
  { ru: '— Пока! Созвонимся вечером, ладно?\n— Конечно, жду звонка.', zh: '——拜！晚上通电话，好吗？\n——当然，等你电话。', en: '— Bye! Let\'s talk on the phone tonight, okay?\n— Sure, I\'ll be waiting for your call.', ctx: '朋友暂别约通话' },
  { ru: '— Мне пора бежать, электричка через десять минут.\n— Беги, беги! До встречи!', zh: '——我得跑了，火车十分钟后开。\n——快跑快跑！回头见！', en: '— I have to run, my train leaves in ten minutes.\n— Run, run! See you!', ctx: '赶火车匆忙告别' },
  { ru: 'Счастливого пути! Напиши, как доберёшься.', zh: '一路平安！到了给我写个信。', en: 'Have a safe trip! Write to me when you arrive.', ctx: '送行祝一路平安' },
  { ru: '— Давай, бывай! Не пропадай.\n— И ты давай. Пока!', zh: '——那走了，保重！别玩失踪。\n——你也是。拜！', en: '— All right, take care! Don\'t disappear.\n— You too. Bye!', ctx: '熟人随意道别' },
  { ru: 'До завтра, коллеги. Не засиживайтесь допоздна.', zh: '明天见，同事们。别熬到太晚。', en: 'See you tomorrow, colleagues. Don\'t stay too late.', ctx: '下班告别同事' },
  { ru: '— Ну всё, я пошла. Спасибо за чай!\n— Заходи ещё, всегда рады.', zh: '——好了，我走了。谢谢你的茶！\n——常来玩，我们随时欢迎。', en: '— Well, I\'m off. Thanks for the tea!\n— Drop by again, you\'re always welcome.', ctx: '客后辞别主人' },
  { ru: 'Прощайте, дорогие друзья! Я никогда вас не забуду.', zh: '永别了，亲爱的朋友们！我永远不会忘记你们。', en: 'Farewell, dear friends! I will never forget you.', ctx: '长久分别深情道别' },
  { ru: '— Увидимся в пятницу на тренировке.\n— Ага, если меня не завалят работой.', zh: '——周五训练见。\n——嗯，只要工作别把我埋了。', en: '— See you Friday at practice.\n— Yeah, if work doesn\'t bury me.', ctx: '约定周五训练见' },
  { ru: 'Всего хорошего! Передавайте привет семье.', zh: '一切都好！替我向家人问好。', en: 'All the best! Say hello to your family.', ctx: '道别问候家人' },
  { ru: '— Ну, до свидания, доктор.\n— До свидания, выздоравливайте.', zh: '——那么，再见了，医生。\n——再见，祝您早日康复。', en: '— Well, goodbye, doctor.\n— Goodbye, get well soon.', ctx: '病人告别医生' },
  { ru: '— Чао-какао!\n— Ну ты даёшь! Пока, пока.', zh: '——拜拜啦（俏皮的ciao）！\n——你可真行！拜，拜。', en: '— Ciao-cacao!\n— You\'re something else! Bye-bye.', ctx: '年轻人玩笑道别' },
  { ru: '— Я ухожу последним, свет выключу.\n— Хорошо. И замок проверь.', zh: '——我最后走，会把灯关掉。\n——好。锁也检查一下。', en: '— I\'m leaving last, I\'ll turn off the lights.\n— Good. Check the lock too.', ctx: '最后离开办公室' },
  { ru: 'Счастливо оставаться! Мы вернёмся через неделю.', zh: '你们好好在家！我们一周后回来。', en: 'Take care while we\'re gone! We\'ll be back in a week.', ctx: '离家远行告别' },
  { ru: '— Не провожайте меня, я сам найду дорогу.\n— Вы уверены? Тут запутанно.', zh: '——不用送我，我自己找得到路。\n——您确定吗？这里挺绕的。', en: '— Don\'t see me out, I\'ll find the way myself.\n— Are you sure? It\'s a maze here.', ctx: '婉拒客人送行' },
  { ru: 'До скорого! Надеюсь, скоро опять соберёмся всей компанией.', zh: '回头见！希望很快咱们一帮人又能聚齐。', en: 'See you soon! I hope the whole gang gets together again before long.', ctx: '聚会散场话别' },
  { ru: '— Ладно, полетел я. Самолёт через два часа.\n— Мягкой посадки! Фотки присылай!', zh: '——好了，我要飞了。飞机两小时后起飞。\n——祝你平稳降落！记得发照片！', en: '— All right, I\'m off. My flight leaves in two hours.\n— Soft landing! Send me photos!', ctx: '机场送别朋友' },
  { ru: '— Покедова! Кепку не забудь на вешалке.\n— Ой, точно, спасибо!', zh: '——拜拜！衣架上的帽子别忘了。\n——哎呀，对，谢谢！', en: '— Bye for now! Don\'t forget your cap on the rack.\n— Oh, right, thanks!', ctx: '临出门提醒带帽子' },
  { ru: '— Спокойной ночи, малыш.\n— Спокойной ночи, мамочка. Поцелуй меня.', zh: '——晚安，宝贝。\n——晚安，妈妈。亲亲我。', en: '— Good night, little one.\n— Good night, Mommy. Give me a kiss.', ctx: '哄孩子睡觉' },
  { ru: '— До встречи осенью! Если что, пишите в мессенджер.\n— Хорошо, держим связь!', zh: '——秋天见！有事就在通讯软件上留言。\n——好的，保持联系！', en: '— See you in the fall! If anything, message me.\n— All right, let\'s keep in touch!', ctx: '夏令营结束道别' },
  { ru: 'Спасибо большое за помощь! Без тебя я бы не справился.', zh: '非常感谢你的帮助！没有你我真搞不定。', en: 'Thank you so much for your help! I couldn\'t have managed without you.', ctx: '感谢朋友帮忙' },
  { ru: '— Спасибо за подарок, он прекрасен!\n— Не за что, носи на здоровье.', zh: '——谢谢你的礼物，太棒了！\n——不客气，随你欢喜地用吧。', en: '— Thank you for the gift, it\'s wonderful!\n— Don\'t mention it, wear it in good health.', ctx: '收到礼物道谢' },
  { ru: 'Благодарю вас за оказанное доверие.', zh: '感谢您给予的信任。', en: 'Thank you for the trust you have placed in me.', ctx: '正式书面致谢' },
  { ru: '— Огромное спасибо, что подвезли!\n— Пустяки, мне было по пути.', zh: '——太感谢了，捎了我一程！\n——小事一桩，我正好顺路。', en: '— Thank you so much for the ride!\n— No trouble at all, it was on my way.', ctx: '感谢顺路搭载' },
  { ru: 'Спасибочки! Ты меня просто спасла с этим отчётом.', zh: '太谢谢啦！这份报告你可真是救了我。', en: 'Thanks a bunch! You totally saved me with this report.', ctx: '感谢救急交报告' },
  { ru: 'Благодарим за тёплый приём!', zh: '谢谢你们的热情款待！', en: 'Thank you for the warm welcome!', ctx: '谢主人盛情款待' },
  { ru: 'Век не забуду вашу доброту, господа.', zh: '各位先生，你们的好意我一辈子不会忘。', en: 'I will never forget your kindness, gentlemen.', ctx: '深情感谢众人' },
  { ru: '— Спасибо за вкусный ужин!\n— На здоровье! Приходите завтра на блины.', zh: '——谢谢这顿美味的晚餐！\n——别客气！明天来吃薄饼。', en: '— Thank you for the delicious dinner!\n— You\'re welcome! Come for pancakes tomorrow.', ctx: '谢晚餐邀请再来' },
  { ru: 'Премного благодарен вам за своевременный совет.', zh: '非常感谢您及时的建议。', en: 'I am most grateful to you for the timely advice.', ctx: '庄重感谢建议' },
  { ru: 'Спасибо, что дождался меня.', zh: '谢谢你等我。', en: 'Thank you for waiting for me.', ctx: '感谢对方等候' },
  { ru: '— Низкий поклон за всё, что вы для нас сделали.\n— Полно вам, не стоит благодарности.', zh: '——您为我们所做的一切，我深深鞠躬致谢。\n——快别这么说，不值一谢。', en: '— I bow low to you for everything you\'ve done for us.\n— Please, no thanks are needed.', ctx: '郑重致谢回应' },
  { ru: 'Спасибо от всей души! Ты настоящий друг.', zh: '发自内心地谢谢你！你是真正的朋友。', en: 'Thank you from the bottom of my heart! You\'re a true friend.', ctx: '由衷感谢挚友' },
  { ru: '— Благодарю за цветы, они чудесные!\n— Это вам, ваша улыбка того стоит.', zh: '——谢谢你的花，太美了！\n——这是送您的，您的笑容值得拥有。', en: '— Thank you for the flowers, they\'re lovely!\n— They\'re yours; your smile is worth it.', ctx: '谢送鲜花赞美' },
  { ru: 'Тысяча благодарностей за гостеприимство!', zh: '万分感谢你们的盛情款待！', en: 'A thousand thanks for your hospitality!', ctx: '夸张感谢款待' },
  { ru: '— Мерси за шоколадку!\n— Пожалуйста-пожалуйста.', zh: '——谢谢你的巧克力！（俏皮说法）\n——不谢不谢。', en: '— Merci for the chocolate bar!\n— You\'re very, very welcome.', ctx: '俏皮道谢零食' },
  { ru: 'Я так вам признательна, что даже слов не нахожу.', zh: '我太感激您了，甚至找不到话来表达。', en: 'I\'m so grateful to you that I can\'t even find words.', ctx: '感激到无言' },
  { ru: '— Спасибо, что прикрыл меня на совещании.\n— Обращайся, мы же команда.', zh: '——谢谢你在会上替我打掩护。\n——尽管开口，咱们是一个团队嘛。', en: '— Thanks for covering for me at the meeting.\n— Anytime, we\'re a team.', ctx: '谢同事会上掩护' },
  { ru: 'Благодарствую, как говорили в старину!', zh: '多谢多谢——就像古人说的那样！', en: 'Thank ye kindly, as they used to say in the old days!', ctx: '仿古幽默致谢' },
  { ru: '— Вы спасли мне жизнь, доктор.\n— Это моя работа, не благодарите.', zh: '——医生，您救了我的命。\n——这是我的本职工作，不用谢。', en: '— You saved my life, doctor.\n— It\'s my job, no need to thank me.', ctx: '感谢救命医生' },
  { ru: 'Спасибо тебе, родной, за эти счастливые годы.', zh: '谢谢你，亲爱的，陪我走过这些幸福岁月。', en: 'Thank you, my dear, for these happy years.', ctx: '伴侣感谢岁月' },
  { ru: '— Извините, я нечаянно.\n— Ничего страшного, бывает.', zh: '——对不起，我不是故意的。\n——没关系，常有的事。', en: '— Sorry, I didn\'t mean to.\n— It\'s all right, it happens.', ctx: '无意碰撞道歉' },
  { ru: 'Прости, пожалуйста, я совсем забыл про нашу встречу.', zh: '对不起，我把咱们的约会忘得一干二净。', en: 'I\'m so sorry, I completely forgot about our meeting.', ctx: '忘记约会道歉' },
  { ru: '— Прошу прощения за опоздание, пробки ужасные.\n— Ничего, мы только сели.', zh: '——请原谅我迟到，堵车太可怕了。\n——没关系，我们也刚坐下。', en: '— Sorry I\'m late, the traffic was terrible.\n— It\'s fine, we\'ve only just sat down.', ctx: '迟到致歉谅解' },
  { ru: 'Извини, что накричала вчера. Погорячилась.', zh: '对不起，昨天冲你喊了。一时上头。', en: 'Sorry I yelled at you yesterday. I lost my temper.', ctx: '为发脾气道歉' },
  { ru: '— Виноват, каюсь, больше не повторится.\n— Ладно, прощаю. Но это в последний раз!', zh: '——是我的错，我认罪，下不为例。\n——行吧，原谅你。但这是最后一次！', en: '— My fault, I confess, it won\'t happen again.\n— All right, I forgive you. But this is the last time!', ctx: '认错请求原谅' },
  { ru: 'Примите мои глубочайшие извинения за доставленные неудобства.', zh: '对于给您带来的不便，请接受我最深切的歉意。', en: 'Please accept my deepest apologies for the inconvenience caused.', ctx: '官方正式致歉' },
  { ru: '— Ой, простите, я вам на ногу наступил!\n— Да ничего, не больно.', zh: '——哎呀，对不起，踩到您的脚了！\n——没事儿，不疼。', en: '— Oops, sorry, I stepped on your foot!\n— It\'s fine, it didn\'t hurt.', ctx: '踩脚忙道歉' },
  { ru: '— Сорри, опять завтыкал.\n— Бывает, с кем не бывает.', zh: '——抱歉，又走神了。\n——没事，谁没个走神的时候。', en: '— Sorry, I spaced out again.\n— It happens to everyone.', ctx: '走神俏皮道歉' },
  { ru: 'Простите ради Бога, я не хотел вас обидеть.', zh: '看在上帝的份上原谅我，我不是有意冒犯您的。', en: 'Forgive me, for God\'s sake, I didn\'t mean to offend you.', ctx: '恳切请求原谅' },
  { ru: '— Извините за поздний звонок.\n— Ничего, я ещё не спал. Что случилось?', zh: '——抱歉这么晚打电话。\n——没事，我还没睡。出什么事了？', en: '— Sorry for calling so late.\n— It\'s fine, I wasn\'t asleep. What happened?', ctx: '深夜来电致歉' },
  { ru: '— Мне так жаль, что всё так получилось.\n— Не вини себя, от тебя ничего не зависело.', zh: '——事情变成这样，我真的很抱歉。\n——别自责，这根本不由你决定。', en: '— I\'m so sorry it turned out this way.\n— Don\'t blame yourself, it was out of your hands.', ctx: '遗憾安慰对方' },
  { ru: '— Прошу простить моего сына за разбитое окно.\n— Пустяки, дети есть дети.', zh: '——请原谅我儿子打碎了您家的玻璃。\n——小事，孩子嘛。', en: '— Please forgive my son for the broken window.\n— It\'s nothing, kids will be kids.', ctx: '为子闯祸赔礼' },
  { ru: '— Извиняюсь, не туда нажал.\n— Всякое бывает, разберёмся.', zh: '——抱歉，我按错了。\n——难免的，咱们来弄明白。', en: '— Sorry, I pressed the wrong button.\n— It happens, we\'ll sort it out.', ctx: '误操作道歉' },
  { ru: '— Прости, что раскрыл твой секрет.\n— Ты меня подвёл, если честно.', zh: '——对不起，我把你的秘密说出去了。\n——说实话，你真让我失望。', en: '— Sorry I let your secret slip.\n— You really let me down, honestly.', ctx: '泄密求原谅' },
  { ru: 'Тысяча извинений, я перепутал даты.', zh: '万分抱歉，我把日期搞混了。', en: 'A thousand apologies, I mixed up the dates.', ctx: '记错日期道歉' },
  { ru: 'Приносим извинения за временные неудобства.', zh: '对于暂时的不便，我们深表歉意。', en: 'We apologize for the temporary inconvenience.', ctx: '施工告示致歉' },
  { ru: 'Прости, дружище, деньги верну на следующей неделе, честное слово.', zh: '对不起，兄弟，钱下周一定还，我说话算话。', en: 'Sorry, pal, I\'ll pay the money back next week, word of honor.', ctx: '拖欠还钱致歉' },
  { ru: '— Я была неправа, признаю.\n— Молодец, что признала. Это дорогого стоит.', zh: '——是我不对，我承认。\n——能承认就是好样的。这很可贵。', en: '— I was wrong, I admit it.\n— Good for you for admitting it. That counts for a lot.', ctx: '承认错误获谅' },
  { ru: '— Ох, простите, перебил вас. Продолжайте, пожалуйста.\n— Да ничего, я уже закончил мысль.', zh: '——哦，对不起，打断您了。请继续。\n——没事，我已经说完了。', en: '— Oh, sorry, I interrupted you. Please go on.\n— It\'s fine, I\'d finished my thought.', ctx: '打断发言致歉' },
  { ru: '— Виноват ли я? Наверное, да. Прости.\n— Хорошо, забудем. Мир?', zh: '——是我的错吗？大概是吧。对不起。\n——好吧，既往不咎。和好了？', en: '— Is it my fault? Probably, yes. Forgive me.\n— All right, let\'s forget it. Peace?', ctx: '自问认错求和' },
  { ru: '— С днём рождения! Желаю здоровья и исполнения желаний.\n— Спасибо! Загадывать желание буду при всех.', zh: '——生日快乐！祝你健康，心想事成。\n——谢谢！我要当着大家的面许愿。', en: '— Happy birthday! I wish you health and all your wishes come true.\n— Thank you! I\'ll make my wish in front of everyone.', ctx: '生日祝福经典' },
  { ru: '— С Новым 2026 годом!\n— И тебя! Пусть новый год принесёт удачу.', zh: '——2026年新年快乐！\n——也祝你快乐！愿新年带来好运。', en: '— Happy New Year 2026!\n— You too! May the new year bring you luck.', ctx: '新年互致祝福', say: 'С Новым две тысячи двадцать шестым годом! И тебя! Пусть новый год принесёт удачу.' },
  { ru: 'С Рождеством Христовым! Мира и добра вашему дому.', zh: '圣诞快乐！愿平安与善意降临你的家。', en: 'Merry Christmas! Peace and goodness to your home.', ctx: '圣诞节祝福' },
  { ru: 'Поздравляю с 50-летием! Полвека прожито не зря.', zh: '祝贺五十岁生日！半个世纪没有白活。', en: 'Congratulations on your 50th birthday! Half a century well lived.', ctx: '五十寿辰祝贺', say: 'Поздравляю с пятидесятилетием! Полвека прожито не зря.' },
  { ru: 'С днём свадьбы! Совет да любовь!', zh: '新婚快乐！祝你们相敬相爱！', en: 'Happy wedding day! Love and harmony!', ctx: '婚礼祝福新人' },
  { ru: '— С окончанием университета! Теперь ты дипломированный специалист.\n— Ура, наконец-то! Пять лет пролетели.', zh: '——祝贺大学毕业！现在你是有文凭的专业人士了。\n——万岁，终于毕业了！五年一晃而过。', en: '— Congratulations on graduating! Now you\'re a certified specialist.\n— Hurray, finally! Five years flew by.', ctx: '祝贺大学毕业' },
  { ru: 'С новосельем! Пусть новый дом будет полной чашей.', zh: '乔迁快乐！愿新家丰衣足食。', en: 'Happy housewarming! May your new home be a full cup.', ctx: '乔迁之喜祝福' },
  { ru: '— Поздравляем с повышением! Ты это заслужил.\n— Спасибо, коллеги! Теперь работать ещё больше.', zh: '——祝贺升职！这是你应得的。\n——谢谢同事们！接下来得更卖力干活了。', en: '— Congratulations on the promotion! You earned it.\n— Thank you, colleagues! Now there\'s even more work ahead.', ctx: '祝贺升职' },
  { ru: '— С праздником весны, милые дамы!\n— Спасибо! Как же приятно!', zh: '——春天节日快乐，亲爱的女士们！\n——谢谢！真让人开心！', en: '— Happy spring holiday, dear ladies!\n— Thank you! How lovely!', ctx: '妇女节祝福' },
  { ru: '— С днём Победы! Вечная память героям.\n— С праздником. Мой дед дошёл до Берлина.', zh: '——胜利日快乐！英雄永垂不朽。\n——节日快乐。我祖父一路打到了柏林。', en: '— Happy Victory Day! Eternal memory to the heroes.\n— Happy holiday. My grandfather fought all the way to Berlin.', ctx: '胜利日祝福' },
  { ru: '— Христос воскрес!\n— Воистину воскрес!', zh: '——基督复活了！\n——真的复活了！', en: '— Christ is risen!\n— Truly He is risen!', ctx: '复活节问候' },
  { ru: 'С 1 сентября, ребята! Знаний вам и хороших оценок.', zh: '九月一日开学快乐，同学们！祝你们收获知识、取得好成绩。', en: 'Happy September 1st, kids! Knowledge and good grades to you.', ctx: '开学日祝福学生', say: 'С первого сентября, ребята! Знаний вам и хороших оценок.' },
  { ru: '— С днём учителя! Спасибо за терпение и труд.\n— Спасибо, ребята! Вы — моя лучшая награда.', zh: '——教师节快乐！感谢您的耐心和付出。\n——谢谢你们，孩子们！你们是我最好的奖赏。', en: '— Happy Teacher\'s Day! Thank you for your patience and hard work.\n— Thank you, kids! You are my best reward.', ctx: '教师节祝福' },
  { ru: '— С серебряной свадьбой! Двадцать пять лет вместе!\n— Спасибо, дети, что собрались все.', zh: '——银婚快乐！二十五年相濡以沫！\n——谢谢孩子们都聚齐了。', en: '— Happy silver anniversary! Twenty-five years together!\n— Thank you, kids, for all gathering here.', ctx: '银婚纪念祝贺' },
  { ru: '— С успешной защитой диплома!\n— Спасибо! Я так волновался, руки тряслись.', zh: '——祝贺论文答辩顺利通过！\n——谢谢！我紧张得手都在抖。', en: '— Congratulations on defending your thesis!\n— Thank you! I was so nervous my hands were shaking.', ctx: '祝贺论文答辩' },
  { ru: 'С Масленицей! Блинов вам румяных и весны скорой.', zh: '谢肉节快乐！祝你们吃上金黄的薄饼，春天早日到来。', en: 'Happy Maslenitsa! Golden pancakes and an early spring to you.', ctx: '谢肉节祝福' },
  { ru: '— Пусть в новом году сбудутся все твои мечты!\n— И твои тоже! Загадаем под бой курантов?', zh: '——愿新的一年里你的梦想全都实现！\n——你的也是！咱们听着钟声许愿吧？', en: '— May all your dreams come true in the new year!\n— Yours too! Shall we make a wish to the chimes?', ctx: '新年许愿祝福' },
  { ru: '— С профессиональным праздником, коллеги!\n— И вас! Работаем дальше, как пчёлки.', zh: '——职业节日快乐，同事们！\n——同乐！咱们继续像小蜜蜂一样干活。', en: '— Happy professional holiday, colleagues!\n— You too! Let\'s keep working like busy bees.', ctx: '职业节日祝贺' },
  { ru: 'Поднимем бокалы за молодых! Пусть живут долго и счастливо.', zh: '为新人干杯！愿他们长久幸福。', en: 'Let\'s raise our glasses to the newlyweds! May they live long and happily.', ctx: '婚宴举杯祝酒' },
  { ru: 'С днём матери, мама! Ты лучшая на свете.', zh: '母亲节快乐，妈妈！你是世界上最好的妈妈。', en: 'Happy Mother\'s Day, Mom! You\'re the best in the world.', ctx: '母亲节祝福' },
  { ru: '— Вот это да! Иваныч, ты что, себя не узнаёшь?\n— Сам в шоке, сбросил пятнадцать кило.', zh: '——天哪！伊万内奇，你认不出自己了吧？\n——我自己都震惊了，减了十五公斤。', en: '— Wow! Ivanych, don\'t you recognize yourself?\n— I\'m in shock myself, lost fifteen kilos.', ctx: '重逢惊讶外貌变化' },
  { ru: '— Сколько лет, сколько зим! Настя, это правда ты?\n— Ах ты мой старый друг! Как же я соскучилась!', zh: '——多少年没见了！娜斯佳，真的是你吗？\n——啊，我的老朋友！我可想死你了！', en: '— Long time no see! Nastya, is that really you?\n— Oh, my old friend! I\'ve missed you so much!', ctx: '惊喜认出老友' },
  { ru: '— Давно не виделись! Что нового расскажешь?\n— Да вроде всё по-старому. А у тебя?', zh: '——好久不见！有什么新鲜事儿？\n——好像一切照旧。你呢？', en: '— Haven\'t seen you in ages! What\'s new?\n— Seems like nothing\'s changed. What about you?', ctx: '老友寒暄近况' },
  { ru: '— Ты помнишь, как мы летом 2018-го на велосипедах до Байкала доехали?\n— Как забуду? Сёдла ещё месяц вспоминали!\n— А щас у меня уже дети на великах катаются.', zh: '——你还记得2018年夏天咱们骑车到贝加尔湖的事吗？\n——怎么可能忘？那一个月车座子硌得屁股疼！\n——现在我自己的小孩都在骑自行车了。', en: '— Do you remember how we cycled to Baikal in the summer of 2018?\n— How could I forget? Our saddles haunted us for a month!\n— And now my kids are riding bikes themselves.', ctx: '重提共同回忆', say: 'Ты помнишь, как мы летом две тысячи восемнадцатого на велосипедах до Байкала доехали? Как забуду? Сёдла ещё месяц вспоминали! А щас у меня уже дети на великах катаются.' },
  { ru: '— О, Дима! Сменил причёску? Или это парик?\n— Ха-ха, нет, просто перестал скрывать лысину!', zh: '——哦，季马！换发型了？还是假发？\n——哈哈，不是，就是不再藏着秃顶了！', en: '— Oh, Dima! New hairstyle? Or is that a wig?\n— Ha-ha, no, I just stopped hiding my bald spot!', ctx: '幽默重逢调侃' },
  { ru: '— Ты выросла, Катюша! Я тебя последний раз видела на подъезде в тапочках.\n— А я вас всё помню, тётя Лида!', zh: '——你长大了，卡秋莎！我最后一次见你还是穿着拖鞋在门口。\n——可我什么都记得，莉达阿姨！', en: '— You\'ve grown up, Katyusha! The last time I saw you, you were in slippers at the entrance.\n— But I remember everything, Aunt Lida!', ctx: '重逢见晚辈成长' },
  { ru: '— Где тебя носило всё это время?\n— Да по свету шатался, пять стран за два года объездил.', zh: '——这些年你都去哪儿浪了？\n——全世界乱跑，两年跑了五个国家。', en: '— Where have you been all this time?\n— Just wandering around the world, visited five countries in two years.', ctx: '久别重逢问行程' },
  { ru: '— Мы ведь четырнадцать лет не виделись!\n— Невероятно... а кажется, как будто вчера.', zh: '——我们可是十四年没见了！\n——不可思议……却感觉像昨天。', en: '— We haven\'t seen each other in fourteen years!\n— Unbelievable... it feels like yesterday.', ctx: '十四年重逢感慨' },
  { ru: '— Во, Серёга! Ты всё ещё таскаешь эту старую куртку?\n— Это не куртка, это память!', zh: '——看啊，谢廖加！你还穿着这件旧夹克？\n——这不是夹克，这是回忆！', en: '— Look, Seryoga! You still lugging around that old jacket?\n— It\'s not a jacket, it\'s a memory!', ctx: '重逢调侃旧物' },
  { ru: '— Алёна, ты как будто не изменилась.\n— Это ты себе кажется. Я на двадцать кило больше.', zh: '——阿廖娜，你好像一点没变。\n——是你觉得而已。我胖了二十公斤。', en: '— Alyona, you look like you haven\'t changed at all.\n— That\'s what you think. I\'m twenty kilos heavier.', ctx: '重逢外貌赞美' },
  { ru: '— Что скажешь, старичок? Жизнь удалась?\n— Удалась бы, если бы ребёнок не кашлял. А у тебя?', zh: '——怎么样，老伙计？日子过得还行？\n——还行，要是孩子不咳嗽就好了。你呢？', en: '— What do you say, old man? Life treating you well?\n— It would, if the kid wasn\'t coughing. And you?', ctx: '老友寒暄各自现状' },
  { ru: 'Мама, это бабушкин сосед по даче!', zh: '妈妈，这是外婆在别墅的邻居！', en: 'Mom, it\'s Grandma\'s dacha neighbor!', ctx: '重遇长辈故人' },
  { ru: '— Неужели ты сам? Я думал, ты давно эмигрировал.\n— Планировал, да не сложилось. Вернулись к истокам.', zh: '——真的是你吗？我以为你早就移民了。\n——计划过，但没成。又回归故土了。', en: '— Is that really you? I thought you\'d emigrated long ago.\n— I planned to, but it didn\'t work out. Came back to my roots.', ctx: '惊讶故人归国' },
  { ru: '— Выглядишь отдохнувшей!\n— Спасибо, я только из Греции. Море работает чудеса.', zh: '——你气色真好！\n——谢谢，我刚从希腊回来。大海有奇效。', en: '— You look refreshed!\n— Thank you, I just got back from Greece. The sea works wonders.', ctx: '重逢称赞气色' },
  { ru: '— Мы жили в одном общежитии на третьем этаже!\n— Ах да, \'чердак гордых\' мы себя называли!', zh: '——我们以前住同一栋宿舍三楼！\n——对了，我们自称\'骄傲的阁楼\'！', en: '— We lived in the same dorm on the third floor!\n— Oh right, we called ourselves the \'attic of the proud\'!', ctx: '回忆大学宿舍往事' },
  { ru: '— Давай, зайдём к нашему старому бару, вспомним молодость.\n— Там уже ресторан.', zh: '——走，去咱们以前的老酒吧，回忆青春。\n——那里已经变成餐厅了。', en: '— Come on, let\'s drop by our old bar and remember our youth.\n— It\'s a restaurant now.', ctx: '故地重游怀旧' },
  { ru: '— Ты помнишь, как я вдребезги разбил твой велосипед?\n— А ты помнишь, как я потом тебя догнал?', zh: '——你还记得我把你的自行车撞得稀碎吗？\n——那你还记得我后来追上你了吗？', en: '— Do you remember how I smashed your bike to pieces?\n— And do you remember how I caught up with you afterward?', ctx: '重逢叙少年糗事' },
  { ru: '— А это кто? Маша? Ты ли это, малышка?\n— Тётя Оля, а как меня помнишь?', zh: '——这是谁？玛莎？小丫头，是你吗？\n——奥莉娅阿姨，您还记得我？', en: '— And who is this? Masha? Is that you, little one?\n— Aunt Olya, you still remember me?', ctx: '重遇儿时淘气鬼' },
  { ru: '— Чёрт возьми, Рома! Я думал, ты в другой галактике.\n— Нет, я на Луне работал. Шучу, тут рядом.', zh: '——见鬼了，罗马！我以为你在另一个星系。\n——不，我在月球上班。开玩笑，就在附近。', en: '— Damn, Roma! I thought you were in another galaxy.\n— No, I was working on the Moon. Just kidding, nearby.', ctx: '夸张重逢玩笑' },
  { ru: '— Какая встреча! Давайте кофе, я угощаю.\n— Не стоит, это же я в вашем городе.', zh: '——真是巧遇！走，喝咖啡，我请客。\n——不用，是我到了你的城市。', en: '— What a meeting! Let\'s have coffee, my treat.\n— You shouldn\'t, I\'m the one in your city.', ctx: '偶遇请客寒暄' },
  { ru: '— Очень приятно! Меня зовут Екатерина.\n— А я Артём. Как вас лучше называть?', zh: '——很高兴认识您！我叫叶卡捷琳娜。\n——我叫阿尔乔姆。怎么称呼您合适？', en: '— Very pleased to meet you! I\'m Ekaterina.\n— And I\'m Artem. How should I address you?', ctx: '正式介绍自己' },
  { ru: '— Разрешите представиться, Олег Васильевич, ваш новый коллега.\n— Здравствуйте, Олег Васильевич. Желаю успехов.', zh: '——请允许我自我介绍，奥列格·瓦西里耶维奇，您的新同事。\n——您好，奥列格·瓦西里耶维奇。祝您工作顺利。', en: '— Allow me to introduce myself, Oleg Vasilyevich, your new colleague.\n— Hello, Oleg Vasilyevich. I wish you success.', ctx: '新同事初次见面' },
  { ru: '— Прошу любить и жаловать — мой племянник, будущий программист.\n— Здравствуйте! Рад знакомству.', zh: '——请多关照——这是我侄子，未来的程序员。\n——您好！很高兴认识您。', en: '— Please be kind to my nephew, the future programmer.\n— Hello! Pleased to meet you.', ctx: '长辈引见晚辈' },
  { ru: 'Добро пожаловать на борт! Надеюсь, наше сотрудничество будет плодотворным.', zh: '欢迎加入！希望我们的合作富有成效。', en: 'Welcome aboard! I hope our cooperation will be fruitful.', ctx: '正式场合欢迎' },
  { ru: '— Мне говорили, что вы отличный специалист. Наконец-то лично знакомимся!\n— Спасибо за тёплые слова. Я тоже слышал о вас.', zh: '——我听人说您是位出色的专家。终于当面认识了！\n——谢谢您的抬爱。我也久仰您的大名。', en: '— I was told you\'re an excellent specialist. Finally we meet in person!\n— Thank you for the kind words. I\'ve heard about you too.', ctx: '慕名初次见面' },
  { ru: '— Привет! Я Петя, сосед сверху.\n— О, привет, я Маша. Заходи, если что нужно.', zh: '——你好！我是彼佳，住楼上。\n——哦你好，我是玛莎。有事尽管来。', en: '— Hi! I\'m Petya, the neighbor from upstairs.\n— Oh hi, I\'m Masha. Drop by if you need anything.', ctx: '邻居初次打招呼' },
  { ru: '— Разрешите представить нашего гостя из Японии, господина Танаку.\n— Здравствуйте, господин Танака. Добро пожаловать в Россию.', zh: '——请允许我介绍来自日本的客人田中先生。\n——您好，田中先生。欢迎来到俄罗斯。', en: '— Allow me to introduce our guest from Japan, Mr. Tanaka.\n— Hello, Mr. Tanaka. Welcome to Russia.', ctx: '介绍外宾' },
  { ru: '— Ой, а мы раньше не встречались?\n— Нет, не думаю. А вы откуда?', zh: '——咦，我们是不是以前见过？\n——没有吧。您是哪儿的？', en: '— Oh, haven\'t we met before?\n— No, I don\'t think so. Where are you from?', ctx: '似曾相识攀谈' },
  { ru: 'Приветствую, товарищ капитан! Я ваш новый штурман.', zh: '您好，舰长同志！我是您的新领航员。', en: 'Greetings, Comrade Captain! I\'m your new navigator.', ctx: '角色正式介绍' },
  { ru: 'Меня зовут Лиза, я приехала из Казани.', zh: '我叫莉扎，从喀山来的。', en: 'My name is Liza, I\'m from Kazan.', ctx: '新同学/新人自我介绍' },
  { ru: '— Вот моя визитка. Будем на связи.\n— Обязательно. А вот моя.', zh: '——这是我的名片。保持联系。\n——一定。这是我的。', en: '— Here\'s my business card. Let\'s keep in touch.\n— Absolutely. And here\'s mine.', ctx: '交换名片' },
  { ru: '— Позвольте вас приветствовать от имени всей нашей команды.\n— Благодарю за приём. Для меня это большая честь.', zh: '——请允许我代表我们全队向您致意。\n——谢谢您的接待。这是我的荣幸。', en: '— Allow me to greet you on behalf of our entire team.\n— Thank you for the welcome. It\'s a great honor for me.', ctx: '代表团队欢迎' },
  { ru: '— Вы из Англии? Я из Лондона, а вы?\n— Из Манчестера. О, мы почти земляки!', zh: '——您从英国来？我来自伦敦，您呢？\n——曼彻斯特。哦，咱们几乎算老乡！', en: '— You\'re from England? I\'m from London, and you?\n— From Manchester. Oh, we\'re practically compatriots!', ctx: '异国他乡攀老乡' },
  { ru: '— Наконец-то мы познакомились лично, а не по зуму!\n— Да, живое общение — совсем другое дело.', zh: '——终于当面认识了，而不是在Zoom上！\n——对，真人交流完全是另一回事。', en: '— Finally we meet in person, not on Zoom!\n— Yes, live communication is a completely different matter.', ctx: '网友线下见面' },
  { ru: '— Я ваш поклонник, читал все ваши книги.\n— Ой, как неожиданно. Спасибо за внимание.', zh: '——我是您的粉丝，您所有的书我都读过。\n——哎呀，真没想到。谢谢关注。', en: '— I\'m your fan, I\'ve read all your books.\n— Oh, how unexpected. Thank you for your attention.', ctx: '粉丝初见偶像' },
  { ru: 'Как жаль, что мы только сейчас познакомились! Вы удивительный человек.', zh: '真遗憾我们直到现在才认识！您是个了不起的人。', en: 'What a pity we only just met! You\'re an amazing person.', ctx: '相见恨晚' },
  { ru: 'Это мой сын, он пока стесняется.', zh: '这是我儿子，他还有点害羞。', en: 'This is my son, he\'s still a bit shy.', ctx: '大人引导小孩开口' },
  { ru: '— Здравствуйте, мы вам цветы принесли. Как вы себя чувствуете?\n— Спасибо, дети. Лучше уже, правда.', zh: '——您好，我们给您带了花。您感觉怎么样？\n——谢谢，孩子们。确实好多了。', en: '— Hello, we brought you flowers. How are you feeling?\n— Thank you, kids. I really am better.', ctx: '探望病人慰问' },
  { ru: '— Мы слышали, что случилось. Принимайте наши соболезнования.\n— Спасибо, что пришли. Мне очень тяжело.', zh: '——我们听说了这件事。请接受我们的哀悼。\n——谢谢你们能来。我很难受。', en: '— We heard what happened. Please accept our condolences.\n— Thank you for coming. I\'m in great pain.', ctx: '吊唁安慰' },
  { ru: '— Очень жаль, что приходится работать в таких условиях.\n— Да уж, но что поделать. Жизнь продолжается.', zh: '——很遗憾您不得不在这样的条件下工作。\n——是啊，但有什么办法呢。生活还得继续。', en: '— I\'m very sorry you have to work in these conditions.\n— Yeah, but what can you do. Life goes on.', ctx: '慰问困难同事' },
  { ru: 'Поздравляю с рождением дочки! Вот маленький подарочек.', zh: '祝贺喜得千金！这是小小的心意。', en: 'Congratulations on the birth of your daughter! Here\'s a little gift.', ctx: '祝贺得子送礼' },
  { ru: 'Как перенесли операцию?', zh: '手术怎么样？', en: 'How did the surgery go?', ctx: '术后探望' },
  { ru: '— Мы все за вас болели и молились.\n— Вы не представляете, как это для меня важно.', zh: '——我们大家都在为您加油祈祷。\n——您不知道这对我有多重要。', en: '— We were all rooting and praying for you.\n— You have no idea how much that means to me.', ctx: '重病康复鼓励' },
  { ru: '— Держитесь, это невыносимо, но время лечит.\n— Я не знаю, как без него...', zh: '——撑住，这难以承受，但时间会治愈一切。\n——我不知道没有他该怎么过……', en: '— Hold on, it\'s unbearable, but time heals.\n— I don\'t know how to live without him...', ctx: '劝慰丧偶者' },
  { ru: '— Пусть этот торт хоть чуть-чуть поднимет вам настроение.\n— Какая вы внимательная. Спасибо, родные.', zh: '——希望这个蛋糕能稍微让你心情好一点。\n——您真贴心。谢谢，我的亲人。', en: '— Let this cake cheer you up at least a little.\n— How attentive you are. Thank you, my dear.', ctx: '探病送蛋糕' },
  { ru: '— Мы с соседями собрали немного для вашей семьи.\n— Боже, да зачем вы так?', zh: '——我们和邻居们给您家凑了一点东西。\n——天哪，你们何必呢？', en: '— We neighbors gathered a little something for your family.\n— Oh my, why did you do that?', ctx: '邻里援助困难户' },
  { ru: '— Сочувствую вашей потере. Это страшное горе.\n— Спасибо, что пришли. Он любил вас всех.', zh: '——对您的不幸深表同情。这是巨大的悲痛。\n——谢谢你们能来。他生前很喜欢你们大家。', en: '— I sympathize with your loss. This is a terrible grief.\n— Thank you for coming. He loved all of you.', ctx: '葬礼吊唁家属' },
  { ru: '— Поздравляю! Мальчик родился весом 3,6 кг!\n— 3,6? Ох, крепыш! Мама как?\n— Устала, но счастлива.', zh: '——祝贺您！男孩出生，体重3.6公斤！\n——3.6？哦，小壮汉！妈妈怎么样？\n——累了，但很幸福。', en: '— Congratulations! The boy was born weighing 3.6 kg!\n— 3.6? Oh, a strong boy! How\'s the mother?\n— Tired, but happy.', ctx: '新生儿贺喜问母子', say: 'Поздравляю! Мальчик родился весом три целых шесть десятых килограмма! Три целых шесть десятых? Ох, крепыш! Мама как? Устала, но счастлива.' },
  { ru: '— Вы справитесь, я в вас верю. Вот телефон психолога, если нужно.\n— Спасибо. Пока держусь.', zh: '——您能挺过去的，我相信您。如果需要，这是心理医生的电话。\n——谢谢。目前还能撑住。', en: '— You\'ll cope, I believe in you. Here\'s a psychologist\'s number if you need it.\n— Thank you. I\'m holding up for now.', ctx: '安慰失意者' },
  { ru: 'Поздравляю с выздоровлением! Теперь запасайтесь витаминами.', zh: '祝贺康复！现在得多补补维生素。', en: 'Congratulations on your recovery! Now stock up on vitamins.', ctx: '祝贺康复' },
  { ru: '— Поздравляем, операция прошла успешно! Врач сказал, всё чисто.\n— Спасибо вам, что всё это время были рядом.', zh: '——祝贺你，手术很成功！医生说一切都没问题了。\n——谢谢你们这段时间一直陪在身边。', en: '— Congratulations, the operation was a success! The doctor said everything is clear.\n— Thank you for being by my side all this time.', ctx: '手术成功祝贺' },
  { ru: '— Мы услышали о пожаре. Вы не пострадали?\n— Слава богу, все живы. Только вещи сгорели.', zh: '——我们听说了火灾的事。你们没受伤吧？\n——谢天谢地，人都平安。只有东西烧掉了。', en: '— We heard about the fire. Were you hurt?\n— Thank God, everyone\'s alive. Only belongings burned.', ctx: '慰问受灾邻居' },
  { ru: 'Ну как наша мамочка? Малышка уже кушает?', zh: '我们的新妈妈怎么样？小宝宝吃奶了吗？', en: 'How\'s our new mommy? Is the baby feeding yet?', ctx: '探望产妇' },
  { ru: '— Примите наши искренние соболезнования, Николай был душой коллектива.\n— Спасибо. Он очень дорожил вашей дружбой.\n— Мы поможем с организацией, не отказывайтесь.', zh: '——请接受我们诚挚的哀悼，尼古拉曾是我们集体的灵魂。\n——谢谢。他非常珍视你们的友谊。\n——我们会帮忙料理后事，请不要推辞。', en: '— Please accept our sincere condolences, Nikolai was the soul of the team.\n— Thank you. He treasured your friendship dearly.\n— We\'ll help with the arrangements, please don\'t refuse.', ctx: '单位同事吊唁' },
  { ru: '— Алло? Алло! Вас плохо слышно, перезвоните.\n— Это я, мама! Я в метро, связь прерывается.\n— А, тогда дома поговорим, не кричи в трубку.', zh: '——喂？喂！听不清，你回拨过来。\n——是我，妈妈！我在地铁里，信号断断续续。\n——哦，那回家再说吧，别对着话筒喊。', en: '— Hello? Hello! I can\'t hear you well, call back.\n— It\'s me, Mom! I\'m in the subway, the signal keeps dropping.\n— Oh, then we\'ll talk at home, don\'t shout into the phone.', ctx: '地铁信号差通话' },
  { ru: '— Здравствуйте, это квартира Смирновых?\n— Нет, вы ошиблись номером.\n— Ох, извините! Прошу прощения за беспокойство.', zh: '——您好，是斯米尔诺夫家吗？\n——不是，您打错了。\n——哦，对不起！打扰您了。', en: '— Hello, is this the Smirnovs\' apartment?\n— No, you have the wrong number.\n— Oh, sorry! I apologize for the trouble.', ctx: '打错电话道歉' },
  { ru: '— Привет! Ну как там в горах? Интернет нормальный?\n— Еле-еле ловит, фотки грузятся вечность.\n— Тогда просто звони, голосом надёжнее.', zh: '——嗨！山里怎么样？网络正常吗？\n——勉强能连上，照片要加载一辈子。\n——那就直接打电话吧，语音更靠谱。', en: '— Hi! How are the mountains? Is the internet okay?\n— It barely connects, photos take forever to load.\n— Then just call, voice is more reliable.', ctx: '山区网络差聊天' },
  { ru: '— Оставьте сообщение после сигнала. Пи-и-и...\n— Мама, это Лена. Перезвони, как услышишь, договорились?\n— (Перезвон) Лена, привет! Всё слышала, что случилось?', zh: '——请在哔声后留言。哔……\n——妈，我是列娜。听到后回我电话，说好了？\n——（回拨）列娜，你好！我都听到了，出什么事了？', en: '— Leave a message after the beep. Beeeep...\n— Mom, it\'s Lena. Call me back when you hear this, okay?\n— (Callback) Lena, hi! I heard everything, what happened?', ctx: '语音留言及回电' },
  { ru: '— Ты в сети? Видео идёт с квадратиками.\n— Попробую выключить камеру, так полегче.\n— Лучше! Теперь хоть голос нормальный.', zh: '——你在线吗？视频全是马赛克。\n——我试着关掉摄像头，这样轻松点。\n——好多了！现在至少声音正常了。', en: '— Are you online? The video is all pixelated.\n— I\'ll try turning off the camera, that should ease the load.\n— Better! Now at least the voice is normal.', ctx: '视频卡顿处理' },
  { ru: '— Звонила тебе весь вечер, ты трубку не берёшь!\n— Прости, телефон на беззвучном был, не слышал.\n— Ладно, прощаю. Завтра позвони первым.', zh: '——我打了一晚上电话，你都不接！\n——对不起，手机调静音了，没听见。\n——行吧，原谅你。明天你先打过来。', en: '— I\'ve been calling you all evening, you didn\'t pick up!\n— Sorry, my phone was on silent, I didn\'t hear it.\n— All right, I forgive you. Call me first tomorrow.', ctx: '抱怨不接电话' },
  { ru: '— Это опять робот-звонилка про кредиты?\n— Сбрось и забудь. В чёрный список его!\n— Уже заблокировала, третий раз за неделю.', zh: '——又是那种贷款机器人电话吗？\n——挂了别理。拉黑名单！\n——已经拉黑了，这周第三次了。', en: '— Is that the loan robo-call again?\n— Just hang up. Blacklist it!\n— Already blocked, third time this week.', ctx: '屏蔽骚扰电话' },
  { ru: '— Скинь мне фотки в мессенджер, я весь день жду.\n— Они по 10 МБ, с моим интернетом до ночи грузиться будут.\n— Тогда на флешку скинь, завтра принеси.', zh: '——把照片发到通讯软件给我，我等了一整天。\n——每张10MB，就我这网速得传一晚上。\n——那拷到U盘上，明天带来。', en: '— Send me the photos in the messenger, I\'ve been waiting all day.\n— They\'re 10 MB each, with my internet they\'ll take all night.\n— Then copy them to a flash drive and bring it tomorrow.', ctx: '传照片遇网速慢', say: 'Скинь мне фотки в мессенджер, я весь день жду. Они по десять мегабайт, с моим интернетом до ночи грузиться будут. Тогда на флешку скинь, завтра принеси.' },
  { ru: '— Алло, я сейчас в лифте, могу пропасть.\n— Говори быстрее, главное!\n— Всё, вышел. Так о чём ты?', zh: '——喂，我在电梯里，可能随时断线。\n——说重点，快点！\n——好了，出来了。你刚才说什么？', en: '— Hello, I\'m in the elevator, might lose signal.\n— Say the main thing, quickly!\n— All right, I\'m out. What were you saying?', ctx: '电梯里长话短说' },
  { ru: 'Видишь меня? А теперь?', zh: '看得见我吗？现在呢？', en: 'Can you see me? And now?', ctx: '视频通话玩笑' },
  { ru: '— Напиши ему в вотсапе, он там быстрее отвечает.\n— Я предпочитаю по-своему, звонком.\n— Ну тогда жди, он вечно занят.', zh: '——用WhatsApp给他发消息，他在那儿回得快。\n——我更喜欢按我的方式来，打电话。\n——那你就等着吧，他总是很忙。', en: '— Message him on WhatsApp, he replies faster there.\n— I prefer my way, a phone call.\n— Then you\'ll be waiting, he\'s always busy.', ctx: '选通讯方式' },
  { ru: '— Ты зависла. Алло! Ты меня слышишь?\n— Да-да, я тут, просто задумалась.\n— Ну не пугай так, думала, связь оборвалась.', zh: '——你卡住了。喂！听得见吗？\n——在在，我在，只是走神了。\n——别这样吓人，我还以为断线了。', en: '— You\'re frozen. Hello! Can you hear me?\n— Yes, yes, I\'m here, just spaced out.\n— Don\'t scare me like that, I thought the connection dropped.', ctx: '视频走神虚惊' },
  { ru: '— Позвони бабушке, она ждёт.\n— Набираю... Алло, бабуль, это я!\n— Внученька! Наконец-то, а то глазки выглядела у окна.', zh: '——给奶奶打个电话，她在等呢。\n——拨了……喂，奶奶，是我！\n——乖孙女！终于来了，我眼睛都在窗边望穿了。', en: '— Call your grandmother, she\'s waiting.\n— Dialing... Hello, Granny, it\'s me!\n— Granddaughter! Finally, I\'ve been wearing my eyes out at the window.', ctx: '给长辈打电话' },
  { ru: '— Простите, можно пройти? Я на следующей выхожу.\n— Да-да, конечно, проходите.\n— Спасибо большое!', zh: '——不好意思，能让我过去吗？我下一站下车。\n——可以可以，请过。\n——非常感谢！', en: '— Excuse me, may I pass? I\'m getting off at the next stop.\n— Yes, yes, of course, go ahead.\n— Thank you very much!', ctx: '公交请让路' },
  { ru: '— Вы последний? Стану за вами.\n— Нет, я не последний, вон та женщина с собакой.\n— Спасибо, подсказали.', zh: '——您是最后一个吗？我排在您后面。\n——不是，我不是最后一个，是那边牵狗的女士。\n——谢谢提醒。', en: '— Are you last in line? I\'ll get behind you.\n— No, I\'m not last, it\'s that woman with the dog over there.\n— Thanks for telling me.', ctx: '排队问顺序' },
  { ru: '— Молодой человек, уступите место бабушке!\n— Ой, извините, задумался. Садитесь, пожалуйста.\n— Спасибо, сынок, вежливый какой.', zh: '——年轻人，给老奶奶让个座！\n——哦，对不起，我走神了。请坐。\n——谢谢，小伙子，真有礼貌。', en: '— Young man, give up your seat for the granny!\n— Oh, sorry, I was daydreaming. Please, sit down.\n— Thank you, son, how polite.', ctx: '公交让座' },
  { ru: '— Добрый день! Третий этаж, пожалуйста.\n— Вам повезло, лифт сегодня работает.\n— О, это уже праздник!', zh: '——下午好！请按三楼。\n——您运气真好，电梯今天能用。\n——哦，这已经算过节了！', en: '— Good afternoon! Third floor, please.\n— You\'re lucky, the elevator works today.\n— Oh, that\'s already a celebration!', ctx: '电梯请按楼层' },
  { ru: '— Передайте за проезд, пожалуйста.\n— Держите. Сдачу потом отдам.\n— Спасибо, не торопитесь.', zh: '——请帮忙传一下车费。\n——拿着。找零一会儿给你。\n——谢谢，不急。', en: '— Please pass the fare forward.\n— Here you go. I\'ll give you the change later.\n— Thank you, no rush.', ctx: '公交传车费' },
  { ru: 'С праздником, соседи!', zh: '节日快乐，邻居们！', en: 'Happy holiday, neighbors!', ctx: '邻里节日问候' },
  { ru: 'Приятного аппетита!', zh: '请慢用！', en: 'Enjoy your meal!', ctx: '食堂互致用餐' },
  { ru: '— Тише, пожалуйста, ребёнок только уснул.\n— Ох, простите! Мы на цыпочках.\n— Спасибо за понимание, соседи.', zh: '——请小声点，孩子刚睡着。\n——哎呀，对不起！我们踮着脚走。\n——谢谢理解，邻居们。', en: '— Quiet, please, the baby just fell asleep.\n— Oh, sorry! We\'ll tiptoe.\n— Thank you for understanding, neighbors.', ctx: '请邻居安静' },
  { ru: '— Извините, место свободно?\n— Занято, тут подруга сидит, вот-вот вернётся.\n— Понял, поищу другое.', zh: '——不好意思，这位置有人吗？\n——有人，我朋友坐这儿，马上回来。\n——明白，我再找别的。', en: '— Excuse me, is this seat taken?\n— It\'s taken, my friend sits here, she\'ll be right back.\n— Got it, I\'ll look for another.', ctx: '询问空位' },
  { ru: 'Женщина, вы обронили перчатку!', zh: '女士，您的手套掉了！', en: 'Ma\'am, you dropped your glove!', ctx: '提醒路人失物' },
  { ru: '— Мужчина, вы мне на ногу наступили!\n— Пардон, толкнули. Сейчас отойду.\n— Ладно, бывает, час пик.', zh: '——先生，您踩到我脚了！\n——抱歉，被人挤的。我这就挪开。\n——算了，难免的，高峰期嘛。', en: '— Sir, you stepped on my foot!\n— Pardon, I got pushed. I\'ll move now.\n— All right, it happens, rush hour.', ctx: '拥挤被踩交涉' },
  { ru: '— Постучаться надо, молодой человек, прежде чем войти.\n— Тук-тук! Можно?\n— Вот теперь можно. Заходите.', zh: '——年轻人，进来之前应该先敲门。\n——咚咚！可以进吗？\n——现在可以了。请进。', en: '— You should knock first, young man, before entering.\n— Knock-knock! May I?\n— Now you may. Come in.', ctx: '进门前敲门' },
  { ru: 'Помогите донести сумку до подъезда, пожалуйста.', zh: '请帮我把袋子提到单元门口吧。', en: 'Please help me carry this bag to the entrance.', ctx: '帮老人提东西' },
  { ru: '— Доброе утро! Ваша собачка не кусается?\n— Нет-нет, она только лается громко, а сердце доброе.\n— Тогда можно погладить?\n— Конечно, она это обожает.', zh: '——早上好！您的小狗咬人吗？\n——不咬不咬，它只是叫得凶，心肠可好了。\n——那我可以摸摸吗？\n——当然，它最喜欢这个了。', en: '— Good morning! Does your doggy bite?\n— No, no, she just barks loudly, but her heart is kind.\n— Then may I pet her?\n— Of course, she adores it.', ctx: '楼道遇邻居狗' },
  { ru: '— С Новым годом, дорогие соседи! Мира и уюта вашим квартирам.\n— И вам того же! А у нас как раз оливье готово.\n— О, тогда мы с тарелками!', zh: '——新年快乐，亲爱的邻居们！祝你们家里平安温馨。\n——也祝你们！我们正好做好了奥利维耶沙拉。\n——哦，那我们自带盘子来！', en: '— Happy New Year, dear neighbors! Peace and coziness to your apartments.\n— Same to you! We\'ve just made the Olivier salad.\n— Oh, then we\'re coming with our plates!', ctx: '新年邻里串门' },
  { ru: 'Прошу прощения, можно я пройду к окну?', zh: '请原谅，能让我走到窗边吗？', en: 'Pardon me, may I get to the window?', ctx: '请让路靠窗' },
  { ru: '— Вы на какой этаж? Я нажму.\n— На седьмой, спасибо.\n— О, мы почти соседи, я на восьмой!', zh: '——您去几楼？我来按。\n——七楼，谢谢。\n——哦，我们几乎是邻居，我住八楼！', en: '— Which floor? I\'ll press the button.\n— Seventh, thank you.\n— Oh, we\'re practically neighbors, I\'m on the eighth!', ctx: '电梯互帮按楼层' },
  { ru: 'Уступите дорогу, у меня тут горячее!', zh: '请让个路，我手上是烫的！', en: 'Make way, I\'m carrying something hot!', ctx: '餐厅端热菜让路' },
  { ru: '— Сосед, у вас музыка на всю округу, можно потише?\n— Ох, простите! Дочь дискотеку устроила. Сейчас убавлю.\n— Спасибо! А то завтра смена в шесть утра.', zh: '——邻居，你们家音乐全小区都听见了，能小点声吗？\n——哎呀，对不起！女儿在家开迪斯科呢。这就调小。\n——谢谢！不然我明早六点就要上班。', en: '— Neighbor, your music is heard all over the block, could you turn it down?\n— Oh, sorry! My daughter threw a disco. Turning it down now.\n— Thank you! My shift starts at six in the morning.', ctx: '请邻居调低音量' },
  { ru: '— Счастливого пути! До встречи в следующем году.\n— И вам всего доброго! Пишите, не забывайте.\n— Непременно! Фотографии пришлю.', zh: '——一路平安！明年见。\n——也祝您一切顺利！常写信，别忘了。\n——一定！我会把照片寄来的。', en: '— Safe travels! See you next year.\n— All the best to you too! Write, don\'t forget.\n— Without fail! I\'ll send photos.', ctx: '送别约定通信' },
  { ru: '— Как самочувствие после химиотерапии?\n— Тошнит, но держусь. Врачи говорят, динамика хорошая.\n— Вот и отлично! Мы все в тебя верим.', zh: '——化疗后感觉怎么样？\n——恶心，但还撑着。医生说指标在好转。\n——那太好了！我们都相信你能行。', en: '— How are you feeling after the chemotherapy?\n— Nauseous, but holding on. The doctors say the progress is good.\n— That\'s great! We all believe in you.', ctx: '慰问化疗病人' },
  { ru: 'Примите наши глубочайшие соболезнования. Он был светлым человеком и останется в наших сердцах.', zh: '请接受我们最深切的哀悼。他是个光明磊落的人，将永远活在我们心中。', en: 'Please accept our deepest condolences. He was a bright soul and will remain in our hearts.', ctx: '正式吊唁致辞' },
  { ru: '— Слышали, у вас двойня родилась? Поздравляем!\n— Спасибо! Теперь сна не будет года два.\n— Зато радости вдвойне!', zh: '——听说你们生了双胞胎？恭喜恭喜！\n——谢谢！接下来两年别想睡觉了。\n——但快乐也是双倍的！', en: '— We heard you had twins? Congratulations!\n— Thank you! No sleep for the next two years.\n— But the joy is doubled!', ctx: '祝贺双胞胎出生' },
  { ru: '— Принесли тебе апельсины и мёд, бабушка гостинцы передаёт.\n— Ой, как не стыдно, я же лежу, а вы хлопочете.\n— Лежи-лежи, поправляйся, это от всей души.', zh: '——给你带了橙子和蜂蜜，奶奶捎来的心意。\n——哎呀，真不好意思，我躺着不动，你们还忙活。\n——躺着吧躺着吧，好好养病，这是大家的一片心。', en: '— We brought you oranges and honey, a gift from Grandma.\n— Oh, how embarrassing, I\'m just lying here while you fuss.\n— Lie still, get well, it\'s from all our hearts.', ctx: '探病转达心意' },
  { ru: '— Слышал, тебя сократили. Крепись, найдём что-нибудь вместе.\n— Спасибо, брат. Пока на вахту подамся.\n— Главное — не опускай руки. Помнишь, как мы в девяностых выживали?', zh: '——听说你被裁员了。挺住，咱们一起想办法。\n——谢谢，兄弟。我先去干轮班工的活。\n——关键是别灰心。还记得咱们九十年代是怎么熬过来的吗？', en: '— I heard you were laid off. Hang in there, we\'ll figure something out together.\n— Thanks, brother. I\'ll take shift work for now.\n— The main thing is don\'t lose heart. Remember how we survived the nineties?', ctx: '安慰失业朋友' },
  { ru: '— Завтра выписка! Наконец-то домой.\n— С возвращением к нормальной жизни!\n— Спасибо всем, кто навещал. Вы меня вытащили.', zh: '——明天出院！终于能回家了。\n——欢迎回到正常生活！\n——谢谢所有来探望我的人。是你们把我拉回来的。', en: '— Discharge tomorrow! Finally going home.\n— Welcome back to normal life!\n— Thanks to everyone who visited. You pulled me through.', ctx: '庆祝出院回家' },
  { ru: '— Видишь, бабушка, это твой правнук по видеосвязи.\n— Где? А, вон он, маленький! А ну улыбнись бабушке!\n— Он сейчас заплачет, он спать хочет.', zh: '——奶奶你看，这是你重孙子，视频通话呢。\n——哪儿呢？啊，在那儿，小家伙！快给奶奶笑一个！\n——他马上要哭了，他想睡觉了。', en: '— Look, Grandma, it\'s your great-grandson on the video call.\n— Where? Ah, there he is, the little one! Smile for Grandma!\n— He\'s about to cry, he wants to sleep.', ctx: '视频连线见重孙' },
  { ru: '— Скинь голосовое в чат, мне лень читать длинные тексты.\n— Уже записал, полторы минуты.\n— Полторы?! Сократи до двадцати секунд!', zh: '——发条语音到群里吧，我懒得看长文字。\n——已经录好了，一分半钟。\n——一分半？！给我压缩到二十秒！', en: '— Send a voice message to the chat, I\'m too lazy to read long texts.\n— Already recorded, a minute and a half.\n— A minute and a half?! Cut it down to twenty seconds!', ctx: '群聊语音消息' },
  { ru: '— Алло... ты пропадаешь... повтори последнее...\n— Я сказал: встречаемся у фонтана в шесть!\n— Всё, понял! У фонтана! Если отключусь — там и жди.', zh: '——喂……你断断续续的……最后一句再说一遍……\n——我说：六点在喷泉边见面！\n——好，明白了！喷泉边！要是我断线了——就在那儿等。', en: '— Hello... you\'re cutting out... repeat the last part...\n— I said: we meet at the fountain at six!\n— Got it! At the fountain! If I disconnect — wait there.', ctx: '信号差重复约定' },
  { ru: '— Это международный звонок, говори быстрее, тариф дикий.\n— Понял! Коротко: документы получил, визу дали!\n— Ура! Обнимаю через восемь тысяч километров!', zh: '——这是国际长途，说快点，资费太吓人。\n——明白！简短说：文件拿到了，签证批了！\n——万岁！隔着八千公里拥抱你！', en: '— It\'s an international call, speak fast, the rate is crazy.\n— Got it! In short: got the documents, the visa is approved!\n— Hurray! Hugging you across eight thousand kilometers!', ctx: '国际长途报喜' },
  { ru: '— Дочь, ты опять по незнакомому номеру звонишь?\n— Мам, мой телефон украли, это телефон подруги.\n— Господи! Ты сама-то цела?', zh: '——闺女，你又用陌生号码打来？\n——妈，我手机被偷了，这是朋友的手机。\n——天哪！你人没事吧？', en: '— Honey, are you calling from an unknown number again?\n— Mom, my phone was stolen, this is a friend\'s phone.\n— Oh my God! Are you all right yourself?', ctx: '借手机报平安' },
  { ru: '— Давай созвонимся вечером по видео, покажешь ремонт.\n— Договорились. В восемь удобно?\n— В восемь самое то. Не забудь зарядить планшет.', zh: '——晚上咱们视频通话吧，你给我看看装修。\n——说定了。八点方便吗？\n——八点正好。别忘了给平板充电。', en: '— Let\'s have a video call tonight, show me the renovation.\n— Deal. Is eight convenient?\n— Eight is perfect. Don\'t forget to charge the tablet.', ctx: '约定视频看装修' },
  { ru: '— У меня телефон сел, пишу с компьютера.\n— Поняла. Завтра купи нормальный повербанк.\n— Уже в корзине лежит, осталось оплатить.', zh: '——我手机没电了，用电脑给你发消息。\n——明白了。明天买个像样的充电宝吧。\n——已经在购物车里了，就差付款。', en: '— My phone died, I\'m writing from the computer.\n— Got it. Buy a proper power bank tomorrow.\n— It\'s already in the cart, just need to pay.', ctx: '手机没电换设备' },
]

// ── 自我介绍 / Self-intro / О себе ──
const INTRO: Phrase[] = [
  { ru: 'Меня зовут Анна, а как вас зовут?', zh: '我叫安娜，您叫什么名字？', en: 'My name is Anna, and what is your name?', ctx: '初次见面介绍' },
  { ru: '— Как тебя зовут?\n— Меня зовут Дмитрий, можно просто Дима.', zh: '— 你叫什么名字？\n— 我叫德米特里，可以直接叫我季马。', en: '— What\'s your name?\n— My name is Dmitry, you can just call me Dima.', ctx: '询问对方名字' },
  { ru: 'Разрешите представиться: меня зовут Елена Петровна.', zh: '请允许我自我介绍：我叫叶莲娜·彼得罗夫娜。', en: 'Allow me to introduce myself: my name is Elena Petrovna.', ctx: '正式自我介绍' },
  { ru: '— Давай познакомимся! Я Сергей.\n— Очень приятно, Сергей. Я Наташа.\n— Взаимно, Наташа. Ты здесь недавно?', zh: '— 我们认识一下吧！我是谢尔盖。\n— 很高兴认识你，谢尔盖。我是娜塔莎。\n— 彼此彼此，娜塔莎。你是新来的吗？', en: '— Let\'s get acquainted! I\'m Sergey.\n— Nice to meet you, Sergey. I\'m Natasha.\n— Same here, Natasha. Are you new here?', ctx: '互相认识' },
  { ru: '— Кто этот молодой человек рядом с тобой?\n— Это мой друг, его зовут Артём.', zh: '— 你旁边这个年轻人是谁？\n— 这是我朋友，他叫阿尔乔姆。', en: '— Who is this young man next to you?\n— This is my friend, his name is Artyom.', ctx: '介绍朋友姓名' },
  { ru: '— Простите, как ваше имя-отчество?\n— Владимир Иванович, но для коллег просто Володя.', zh: '— 请问，您的名字和父称是什么？\n— 弗拉基米尔·伊万诺维奇，不过同事们都叫我沃洛佳。', en: '— Excuse me, what is your first name and patronymic?\n— Vladimir Ivanovich, but for colleagues I\'m just Volodya.', ctx: '询问姓名与父称' },
  { ru: 'Мою старшую сестру зовут Екатерина.', zh: '我姐姐叫叶卡捷琳娜。', en: 'My older sister\'s name is Ekaterina.', ctx: '介绍家人名字' },
  { ru: '— Ты не помнишь, как зовут того парня?\n— Кажется, его зовут Максим, а что?', zh: '— 你不记得那个小伙子叫什么了吗？\n— 好像叫马克西姆，怎么了？', en: '— Don\'t you remember that guy\'s name?\n— I think his name is Maksim, why?', ctx: '记不清名字' },
  { ru: '— Простите, мы с вами не знакомы.\n— Меня зовут Елена, а вас?\n— Очень приятно, я Николай.', zh: '— 抱歉，我们还不认识。\n— 我叫叶莲娜，您呢？\n— 很高兴认识您，我是尼古拉。', en: '— Excuse me, we haven\'t met.\n— My name is Elena, and yours?\n— Pleased to meet you, I\'m Nikolay.', ctx: '正式场合初识' },
  { ru: '— Можно я буду звать тебя Настя?\n— Конечно, так меня зовут дома.', zh: '— 我可以叫你娜斯佳吗？\n— 当然，家里人都这么叫我。', en: '— Can I call you Nastya?\n— Sure, that\'s what they call me at home.', ctx: '称呼昵称' },
  { ru: '— Назовите, пожалуйста, ваше полное имя.\n— Екатерина Владимировна Смирнова.', zh: '— 请说出您的全名。\n— 叶卡捷琳娜·弗拉基米罗夫娜·斯米尔诺娃。', en: '— Please state your full name.\n— Ekaterina Vladimirovna Smirnova.', ctx: '登记全名' },
  { ru: '— Нас с тобой не представили. Я Олег.\n— Марина. Очень приятно!\n— Мне тоже. Ты из этого универа?\n— Ага, с филфака, а ты?', zh: '— 没人给我们介绍过。我是奥列格。\n— 我是玛丽娜，很高兴认识你！\n— 我也是。你是这所大学的吗？\n— 嗯，语文系的，你呢？', en: '— We weren\'t introduced. I\'m Oleg.\n— Marina. Nice to meet you!\n— Me too. Are you from this university?\n— Yep, philology faculty, and you?', ctx: '校园初识' },
  { ru: 'У меня редкое имя — Святослав.', zh: '我的名字很少见——斯维亚托斯拉夫。', en: 'I have a rare name — Svyatoslav.', ctx: '名字特别' },
  { ru: '— Как пишется твоё имя?\n— А-н-н-а, через две «н».', zh: '— 你的名字怎么写？\n— А-н-н-а，有两个“н”。', en: '— How do you spell your name?\n— A-n-n-a, with a double \'n\'.', ctx: '名字拼写' },
  { ru: '— Какое у тебя красивое имя!\n— Спасибо, меня так назвала бабушка.', zh: '— 你的名字真好听！\n— 谢谢，是奶奶给我起的。', en: '— What a beautiful name you have!\n— Thank you, my grandmother named me that.', ctx: '赞美名字' },
  { ru: 'Я из Китая, но живу в Москве уже два года.', zh: '我来自中国，但已经在莫斯科住了两年。', en: 'I\'m from China, but I\'ve been living in Moscow for two years.', ctx: '自我介绍国籍' },
  { ru: '— Откуда вы родом?\n— Я из России, родилась в Санкт-Петербурге.', zh: '— 您是哪里人？\n— 我是俄罗斯人，出生在圣彼得堡。', en: '— Where are you from originally?\n— I\'m from Russia, I was born in Saint Petersburg.', ctx: '询问籍贯' },
  { ru: 'Мои родители из Казахстана, а я вырос в Пекине.', zh: '我父母来自哈萨克斯坦，而我在北京长大。', en: 'My parents are from Kazakhstan, but I grew up in Beijing.', ctx: '父母出身' },
  { ru: '— Ты откуда? По говору не пойму.\n— Да я местный, из пригорода.', zh: '— 你是哪儿人？听口音我听不出来。\n— 我就是本地人，郊区的。', en: '— Where are you from? I can\'t tell from your accent.\n— I\'m local, from the suburbs.', ctx: '从口音猜籍贯' },
  { ru: '— Вы из Японии или из Кореи?\n— Ни то ни другое, я из Китая.', zh: '— 您是日本人还是韩国人？\n— 都不是，我是中国人。', en: '— Are you from Japan or Korea?\n— Neither, I\'m from China.', ctx: '猜测对方国籍' },
  { ru: '— Где находится твой родной город?\n— На юге Китая, у самого моря.\n— Наверное, там очень жарко?\n— Жарко, зато какие фрукты!', zh: '— 你的家乡在哪里？\n— 在中国南方，就在海边。\n— 那里肯定很热吧？\n— 热是热，但水果可好了！', en: '— Where is your hometown?\n— In the south of China, right by the sea.\n— It must be very hot there?\n— Hot, but the fruit is amazing!', ctx: '家乡地理位置' },
  { ru: 'Она француженка, но отлично говорит по-русски.', zh: '她是法国人，但俄语说得很好。', en: 'She is French, but she speaks excellent Russian.', ctx: '她是法国人' },
  { ru: '— Вы давно переехали в Россию?\n— Уже пять лет, в две тысячи двадцатом году.', zh: '— 您搬到俄罗斯很久了吗？\n— 已经五年了，二〇二〇年来的。', en: '— Did you move to Russia long ago?\n— Five years already, in twenty twenty.', ctx: '移民年限' },
  { ru: '— Ты не думал вернуться на родину насовсем?\n— На твоём месте я бы не спешил с ответом.', zh: '— 你没想过彻底回国吗？\n— 换作是我，就不会急着下结论。', en: '— Haven\'t you thought about moving back home for good?\n— If I were you, I wouldn\'t rush to answer.', ctx: '考虑回国' },
  { ru: '— Скучаешь по дому?\n— Ещё как скучаю, особенно по бабушкиной еде.', zh: '— 想家吗？\n— 可想了，尤其想念奶奶做的饭。', en: '— Do you miss home?\n— I really do, especially my grandma\'s cooking.', ctx: '思念家乡' },
  { ru: '— А какой город является столицей твоей страны?\n— Пекин, это огромный шумный город.\n— Я там был один раз, очень впечатляет.', zh: '— 那你们国家的首都是哪个城市？\n— 北京，一座巨大而喧闹的城市。\n— 我去过一次，非常令人震撼。', en: '— And which city is the capital of your country?\n— Beijing, a huge, noisy city.\n— I\'ve been there once, it\'s very impressive.', ctx: '祖国首都' },
  { ru: '— Кстати, ты гражданин России?\n— Нет, у меня китайское гражданство, но вид на жительство есть.', zh: '— 对了，你是俄罗斯公民吗？\n— 不是，我持中国国籍，但有居住证。', en: '— By the way, are you a Russian citizen?\n— No, I have Chinese citizenship, but I have a residence permit.', ctx: '国籍与居留' },
  { ru: 'Я много лет живу за границей, но родину не забываю.', zh: '我在国外生活多年，但没有忘记祖国。', en: 'I\'ve lived abroad for many years, but I don\'t forget my homeland.', ctx: '他乡生活' },
  { ru: '— Ты где так выучила китайский?\n— Нигде, я из Шанхая.\n— Ой, а я и не догадался!', zh: '— 你在哪儿把中文学得这么好？\n— 哪儿也没学，我是上海人。\n— 哎呀，我居然没猜出来！', en: '— Where did you learn Chinese so well?\n— Nowhere, I\'m from Shanghai.\n— Oh, I never would have guessed!', ctx: '猜不到国籍' },
  { ru: '— Расскажи о своём городе.\n— Он маленький, зато очень зелёный и уютный.', zh: '— 讲讲你的城市吧。\n— 它很小，但非常绿化，也很舒适。', en: '— Tell me about your city.\n— It\'s small, but very green and cozy.', ctx: '描述家乡小城' },
  { ru: 'Мне 25 лет, и я давно работаю.', zh: '我25岁，而且已经工作很久了。', en: 'I\'m 25 and I\'ve been working for a long time.', ctx: '自报年龄', say: 'Мне двадцать пять лет и я давно работаю' },
  { ru: '— Сколько тебе лет, если не секрет?\n— Никакого секрета: мне 22 года.', zh: '— 你多大了，如果不是秘密的话？\n— 没什么可保密的：我22岁。', en: '— How old are you, if it\'s not a secret?\n— No secret at all: I\'m 22.', ctx: '询问年龄', say: 'Сколько тебе лет если не секрет Никакого секрета мне двадцать два года' },
  { ru: 'В следующем месяце мне исполнится тридцать.', zh: '下个月我就满三十岁了。', en: 'I\'ll turn thirty next month.', ctx: '即将满三十' },
  { ru: '— Когда у тебя день рождения?\n— 15 мая, как раз весной.', zh: '— 你的生日是什么时候？\n— 5月15日，正好在春天。', en: '— When is your birthday?\n— May 15th, right in spring.', ctx: '生日日期', say: 'Когда у тебя день рождения Пятнадцатого мая как раз весной' },
  { ru: 'Моя младшая сестра на три года младше меня.', zh: '我妹妹比我小三岁。', en: 'My younger sister is three years younger than me.', ctx: '兄妹年龄差' },
  { ru: '— Тебе уже есть восемнадцать?\n— Да, я отметил совершеннолетие в январе.\n— Ну и как, ощущения изменились?\n— Не особо, честно говоря.', zh: '— 你已经满十八岁了吗？\n— 满了，我一月份刚庆祝了成年。\n— 那感觉有变化吗？\n— 说实话，没什么变化。', en: '— Are you eighteen yet?\n— Yes, I celebrated coming of age in January.\n— So, has the feeling changed?\n— Not really, honestly.', ctx: '是否成年' },
  { ru: '— С днём рождения! Вот мой подарок.\n— Спасибо, ты не забыл!\n— Да как же можно забыть.', zh: '— 生日快乐！这是我的礼物。\n— 谢谢，你居然没忘！\n— 这怎么能忘呢。', en: '— Happy birthday! Here\'s my present.\n— Thanks, you didn\'t forget!\n— How could anyone forget.', ctx: '生日送礼' },
  { ru: '— Сколько лет твоим родителям?\n— Папе 50, а маме 48.', zh: '— 你父母多大年纪了？\n— 爸爸50，妈妈48。', en: '— How old are your parents?\n— Dad is 50 and Mom is 48.', ctx: '父母年龄', say: 'Сколько лет твоим родителям Папе пятьдесят а маме сорок восемь' },
  { ru: '— В каком году ты родился?\n— В две тысячи втором, я совсем молодой.', zh: '— 你哪一年出生的？\n— 二〇〇二年，我还很年轻。', en: '— What year were you born?\n— In two thousand two, I\'m still very young.', ctx: '出生年份' },
  { ru: '— Ты старше брата или младше?\n— Я старше на целых шесть лет.', zh: '— 你比哥哥大还是小？\n— 我比他整整大六岁。', en: '— Are you older or younger than your brother?\n— I\'m six whole years older.', ctx: '排行年龄' },
  { ru: 'День рождения я обычно отмечаю в кругу семьи.', zh: '我通常和家人一起庆祝生日。', en: 'I usually celebrate my birthday with my family.', ctx: '庆祝生日方式' },
  { ru: '— Придёшь на мой день рождения в субботу?\n— Конечно приду, во сколько он начинается?', zh: '— 星期六你来我的生日聚会吗？\n— 当然来，几点开始？', en: '— Will you come to my birthday party on Saturday?\n— Of course I\'ll come, what time does it start?', ctx: '邀请生日会' },
  { ru: '— Сколько лет твоей бабушке?\n— Уже 78, но она прекрасно выглядит.', zh: '— 你奶奶多大岁数了？\n— 已经78了，但她气色很好。', en: '— How old is your grandmother?\n— She\'s already 78, but she looks great.', ctx: '祖母年龄', say: 'Сколько лет твоей бабушке Уже семьдесят восемь но она прекрасно выглядит' },
  { ru: '— Мне через неделю 27 стукнет.\n— Серьёзно? И где празднуешь?\n— Думал в кафе, но, может, дома соберёмся.', zh: '— 再过一周我就27了。\n— 真的吗？你打算在哪儿庆祝？\n— 本来想在咖啡馆，但也许在家里聚。', en: '— I\'ll turn 27 in a week.\n— Really? Where are you celebrating?\n— I was thinking of a cafe, but maybe we\'ll gather at home.', ctx: '快过生日', say: 'Мне через неделю двадцать семь стукнет Серьёзно И где празднуешь Думал в кафе но может дома соберёмся' },
  { ru: '— Ты бы хотел вернуться в детство?\n— Иногда да, но жить лучше настоящим.', zh: '— 你想回到童年吗？\n— 有时候想，但还是活在当下更好。', en: '— Would you like to go back to childhood?\n— Sometimes, but it\'s better to live in the present.', ctx: '回到童年' },
  { ru: 'Я учусь на экономическом факультете, на третьем курсе.', zh: '我在经济系读大三。', en: 'I study at the economics faculty, in my third year.', ctx: '专业年级' },
  { ru: '— Кем ты работаешь?\n— Я программист, пишу мобильные приложения.', zh: '— 你是做什么工作的？\n— 我是程序员，写手机应用。', en: '— What do you do for work?\n— I\'m a programmer, I write mobile apps.', ctx: '从事职业' },
  { ru: 'Моя специальность — международная торговля.', zh: '我的专业是国际贸易。', en: 'My major is international trade.', ctx: '所学专业' },
  { ru: '— Вы довольны своей работой?\n— В целом да, хотя нагрузка бывает большой.', zh: '— 您对自己的工作满意吗？\n— 总体满意，不过工作量有时很大。', en: '— Are you satisfied with your job?\n— Overall yes, although the workload can be heavy.', ctx: '工作满意度' },
  { ru: 'Я работаю в IT уже четыре года.', zh: '我在IT行业已经工作四年了。', en: 'I\'ve been working in IT for four years.', ctx: '信息技术行业', say: 'Я работаю в айти уже четыре года' },
  { ru: '— На кого ты учишься?\n— На переводчика, изучаю русский и английский.', zh: '— 你学的是什么方向？\n— 翻译方向，学俄语和英语。', en: '— What are you studying to be?\n— An interpreter, I study Russian and English.', ctx: '学什么专业' },
  { ru: 'После университета я хочу открыть своё дело.', zh: '大学毕业后我想自己创业。', en: 'After university I want to start my own business.', ctx: '毕业打算' },
  { ru: '— Ты работаешь по специальности?\n— Не совсем, диплом инженера, а работаю в продажах.\n— И как, нравится?\n— Зарплата устраивает, но скучаю по технике.', zh: '— 你做的是本专业的工作吗？\n— 不完全是，文凭是工程师，却在做销售。\n— 那你喜欢吗？\n— 工资还行，但我挺想念技术工作。', en: '— Do you work in your field?\n— Not exactly, my degree is in engineering, but I work in sales.\n— So do you like it?\n— The pay is fine, but I miss engineering.', ctx: '专业对口吗' },
  { ru: '— Кем работает твоя мама?\n— Она врач в детской больнице.', zh: '— 你妈妈是做什么的？\n— 她是儿童医院的医生。', en: '— What does your mother do?\n— She\'s a doctor at a children\'s hospital.', ctx: '母亲职业' },
  { ru: '— Какая у тебя профессия?\n— Я журналист, пишу о путешествиях.', zh: '— 你的职业是什么？\n— 我是记者，撰写旅行题材。', en: '— What\'s your profession?\n— I\'m a journalist, I write about travel.', ctx: '职业与专业' },
  { ru: '— Расскажи, чем ты занимаешься на работе.\n— Я веду переговоры и подписываю контракты.', zh: '— 说说你工作中都做些什么。\n— 我负责谈判和签署合同。', en: '— Tell me what you do at work.\n— I conduct negotiations and sign contracts.', ctx: '日常工作' },
  { ru: '— Тебя повысили? Поздравляю!\n— Спасибо, теперь я руководитель отдела.', zh: '— 你升职了？恭喜！\n— 谢谢，现在我是部门主管了。', en: '— You got promoted? Congratulations!\n— Thanks, now I\'m head of the department.', ctx: '升职祝贺' },
  { ru: '— Твой отец тоже инженер?\n— Нет, он строитель, строит мосты.\n— Настоящая мужская работа!', zh: '— 你父亲也是工程师吗？\n— 不，他是建筑工人，修建桥梁。\n— 真是男子汉的工作！', en: '— Is your father an engineer too?\n— No, he\'s a builder, he builds bridges.\n— Real men\'s work!', ctx: '父亲职业' },
  { ru: '— Кем ты мечтала стать в детстве?\n— Космонавтом, как и все, наверное.\n— А сейчас?\n— А сейчас я просто учитель математики.', zh: '— 你小时候梦想成为什么？\n— 宇航员，大概和所有人一样吧。\n— 那现在呢？\n— 现在我只是一名数学老师。', en: '— What did you dream of becoming as a child?\n— An astronaut, like everyone else, I suppose.\n— And now?\n— Now I\'m just a math teacher.', ctx: '童年理想' },
  { ru: '— Ты бы сменил профессию, если бы мог?\n— Смог бы, будь у меня больше смелости.', zh: '— 如果可以，你会换职业吗？\n— 会的，要是我再勇敢一点的话。', en: '— Would you change professions if you could?\n— I would, if I had more courage.', ctx: '是否转行' },
  { ru: 'У меня большая семья: родители и две сестры.', zh: '我有一个大家庭：父母和两个姐妹。', en: 'I have a big family: my parents and two sisters.', ctx: '家庭规模' },
  { ru: '— У тебя есть братья или сёстры?\n— Да, у меня есть старший брат.', zh: '— 你有兄弟姐妹吗？\n— 有，我有一个哥哥。', en: '— Do you have any brothers or sisters?\n— Yes, I have an older brother.', ctx: '有无兄弟姐妹' },
  { ru: 'Мои родители уже на пенсии, но не скучают.', zh: '我父母已经退休了，但并不寂寞。', en: 'My parents are already retired, but they don\'t get bored.', ctx: '退休父母' },
  { ru: '— Ты живёшь с родителями?\n— Нет, я снимаю квартиру с друзьями.', zh: '— 你和父母一起住吗？\n— 不，我和朋友合租公寓。', en: '— Do you live with your parents?\n— No, I rent an apartment with friends.', ctx: '是否同住' },
  { ru: '— Где вы обычно собираетесь всей семьёй?\n— Чаще всего у бабушки, на выходных.', zh: '— 你们通常在哪里全家团聚？\n— 多半在奶奶家，周末的时候。', en: '— Where do you usually gather as a family?\n— Most often at grandma\'s, on weekends.', ctx: '家庭聚会' },
  { ru: '— Ты женат?\n— Да, у меня есть жена и маленький сын.\n— А сколько лет сыну?\n— Ему недавно исполнилось три года.', zh: '— 你结婚了吗？\n— 结了，我有妻子和一个小儿子。\n— 儿子几岁了？\n— 他刚满三岁。', en: '— Are you married?\n— Yes, I have a wife and a little son.\n— How old is your son?\n— He recently turned three.', ctx: '婚否子女' },
  { ru: '— Кто у вас в семье лучше всех готовит?\n— Мама, она печёт удивительные пироги.\n— Звучит вкусно, сразу есть захотелось.', zh: '— 你们家谁做饭最好吃？\n— 妈妈，她烤的馅饼特别棒。\n— 听着就香，我马上就饿了。', en: '— Who in your family cooks best?\n— Mom, she bakes amazing pies.\n— Sounds delicious, I\'m already hungry.', ctx: '家中厨艺' },
  { ru: '— Как зовут твою жену?\n— Её зовут Ольга, она бухгалтер.', zh: '— 你妻子叫什么？\n— 她叫奥尔加，是会计。', en: '— What\'s your wife\'s name?\n— Her name is Olga, she\'s an accountant.', ctx: '妻子姓名职业' },
  { ru: 'У моей сестры недавно родился ребёнок.', zh: '我姐姐不久前生了孩子。', en: 'My sister recently had a baby.', ctx: '外甥出生' },
  { ru: '— Вы часто видитесь с роднёй?\n— Редко, они живут в другом городе.', zh: '— 您常和亲戚见面吗？\n— 很少，他们住在另一个城市。', en: '— Do you often see your relatives?\n— Rarely, they live in another city.', ctx: '与亲戚见面' },
  { ru: '— Кто научил тебя ездить на велосипеде?\n— Отец, он же подарил мне первый велик.', zh: '— 是谁教你骑自行车的？\n— 爸爸，我的第一辆自行车也是他送的。', en: '— Who taught you to ride a bike?\n— My dad, he also gave me my first bike.', ctx: '父亲教骑车' },
  { ru: '— Кто в вашей семье главный?\n— Ну у нас все решаем вместе, по-честному.', zh: '— 你们家谁说了算？\n— 呃，我们都是一起商量，公平得很。', en: '— Who is the head of your family?\n— Well, we decide everything together, fairly.', ctx: '谁说了算' },
  { ru: 'Летом мы поедем к дедушке в деревню.', zh: '夏天我们要去乡下爷爷家。', en: 'In the summer we\'ll go to Grandpa\'s in the village.', ctx: '暑期探亲' },
  { ru: '— Ты похож на отца?\n— Говорят, что вылитый он.\n— А характер тоже отцовский?\n— Такой же упрямый, к сожалению.', zh: '— 你长得像爸爸吗？\n— 大家都说我跟他一模一样。\n— 性格也像他吗？\n— 遗憾的是，一样固执。', en: '— Do you look like your father?\n— They say I\'m his spitting image.\n— Is your character his too?\n— Just as stubborn, unfortunately.', ctx: '外貌像父亲' },
  { ru: '— У тебя есть дети?\n— Пока нет, но мы с мужем очень хотим.', zh: '— 你有孩子吗？\n— 暂时没有，但我和丈夫很想要。', en: '— Do you have children?\n— Not yet, but my husband and I really want them.', ctx: '有无孩子' },
  { ru: 'В свободное время я люблю читать детективы.', zh: '空闲时我喜欢看侦探小说。', en: 'In my free time I like to read detective stories.', ctx: '阅读爱好' },
  { ru: '— Чем ты увлекаешься?\n— Я обожаю фотографировать закаты.', zh: '— 你对什么感兴趣？\n— 我特别喜欢拍日落。', en: '— What are you into?\n— I love photographing sunsets.', ctx: '摄影爱好' },
  { ru: 'Мне нравится готовить итальянскую кухню.', zh: '我喜欢做意大利菜。', en: 'I enjoy cooking Italian food.', ctx: '喜欢烹饪' },
  { ru: '— Ты играешь на чём-нибудь?\n— Да, немного на гитаре.', zh: '— 你会演奏什么乐器吗？\n— 会，会弹一点吉他。', en: '— Do you play anything?\n— Yes, a bit of guitar.', ctx: '乐器爱好' },
  { ru: 'Мы с друзьями каждую неделю играем в футбол.', zh: '我和朋友们每周都踢足球。', en: 'My friends and I play football every week.', ctx: '周末踢球' },
  { ru: '— Какое у тебя хобби?\n— Я коллекционирую старые монеты.\n— Правда? А сколько их уже у тебя?\n— Около двухсот, есть очень редкие.', zh: '— 你有什么爱好？\n— 我收集旧硬币。\n— 真的吗？你已经有多少枚了？\n— 大约两百枚，还有很稀有的。', en: '— What\'s your hobby?\n— I collect old coins.\n— Really? How many do you have now?\n— About two hundred, some very rare ones.', ctx: '钱币收藏' },
  { ru: '— Чем ты занимаешься зимой?\n— Катаюсь на лыжах, а летом плаваю.', zh: '— 你冬天做什么？\n— 滑雪，夏天就游泳。', en: '— What do you do in winter?\n— I ski, and in summer I swim.', ctx: '冬夏运动' },
  { ru: '— Пойдёшь с нами в горы?\n— С удовольствием, я давно мечтал об этом.', zh: '— 你跟我们一起去山里吗？\n— 很乐意，我早就想去了。', en: '— Will you come to the mountains with us?\n— Gladly, I\'ve long dreamed of it.', ctx: '约去爬山' },
  { ru: '— Ты ходишь в спортзал?\n— Нет, я танцую уже десять лет.\n— Серьёзно? И даже выступаешь на сцене?', zh: '— 你去健身房吗？\n— 不去，我跳舞已经十年了。\n— 真的吗？还登台演出吗？', en: '— Do you go to the gym?\n— No, I\'ve been dancing for ten years.\n— Really? Do you even perform on stage?', ctx: '跳舞经历' },
  { ru: '— Ты смотришь сериалы?\n— Не без этого, особенно зимними вечерами.', zh: '— 你看连续剧吗？\n— 也看，尤其是冬天的晚上。', en: '— Do you watch TV series?\n— I do, especially on winter evenings.', ctx: '看剧习惯' },
  { ru: '— Давай запишемся в бассейн?\n— Какая замечательная идея, я только за!', zh: '— 我们报名去游泳吧？\n— 好主意，我完全赞成！', en: '— Let\'s sign up for the pool?\n— What a wonderful idea, I\'m all for it!', ctx: '报名游泳' },
  { ru: '— Что ты обычно делаешь на выходных?\n— Гуляю, встречаюсь с друзьями, иногда рисую.', zh: '— 你周末通常做什么？\n— 散步、见朋友，有时画画。', en: '— What do you usually do on weekends?\n— I walk, meet friends, sometimes draw.', ctx: '周末安排' },
  { ru: 'Я бы научился рисовать, будь у меня терпение.', zh: '要是有耐心的话，我早就学画画了。', en: 'I would learn to draw if I had the patience.', ctx: '假设学画画' },
  { ru: '— Хочешь попробовать новый вид спорта?\n— Какой, например?\n— Скалолазание, говорят, это сильно затягивает.', zh: '— 想试试新的运动吗？\n— 比如什么？\n— 攀岩，听说特别让人上瘾。', en: '— Want to try a new sport?\n— Like what, for example?\n— Rock climbing, they say it\'s really addictive.', ctx: '尝试新运动' },
  { ru: '— Кстати, ты любишь путешествовать?\n— Очень, уже объехал полстраны.', zh: '— 对了，你喜欢旅行吗？\n— 非常喜欢，大半个国家都走遍了。', en: '— By the way, do you like traveling?\n— A lot, I\'ve already traveled around half the country.', ctx: '爱好旅行' },
  { ru: 'Я довольно спокойный и терпеливый человек.', zh: '我是个相当沉稳、有耐心的人。', en: 'I\'m a fairly calm and patient person.', ctx: '性格沉稳' },
  { ru: '— Какой ты по характеру?\n— Думаю, я общительный и весёлый.', zh: '— 你性格怎么样？\n— 我觉得我开朗又乐观。', en: '— What\'s your personality like?\n— I think I\'m sociable and cheerful.', ctx: '自述性格' },
  { ru: 'Иногда я бываю слишком упрямым.', zh: '有时我会太固执。', en: 'Sometimes I\'m too stubborn.', ctx: '偶尔固执' },
  { ru: '— Она добрая?\n— Не то слово, она всем готова помочь.', zh: '— 她善良吗？\n— 岂止善良，她随时愿意帮助任何人。', en: '— Is she kind?\n— That\'s an understatement, she\'s ready to help everyone.', ctx: '为人善良' },
  { ru: '— На твоего друга можно положиться?\n— Да, он человек ответственный.\n— Тогда я обращусь к нему за помощью.', zh: '— 你的朋友靠得住吗？\n— 靠得住，他是个负责任的人。\n— 那我就找他帮忙了。', en: '— Can your friend be relied on?\n— Yes, he\'s a responsible person.\n— Then I\'ll turn to him for help.', ctx: '为人可靠' },
  { ru: '— Ты интроверт или экстраверт?\n— Скорее интроверт, большие компании меня утомляют.\n— А как же твоя работа с людьми?\n— Привык, хотя после неё нужно отдыхать.', zh: '— 你是内向的人还是外向的人？\n— 更偏内向，人多的场合让我疲惫。\n— 那你和人打交道的工作怎么办？\n— 习惯了，不过下班后需要休息。', en: '— Are you an introvert or an extrovert?\n— More of an introvert, big crowds tire me out.\n— What about your job working with people?\n— I\'ve gotten used to it, though I need rest afterward.', ctx: '内向还是外向' },
  { ru: '— Легко ли она сходится с людьми?\n— Да, находит общий язык даже с незнакомцами.', zh: '— 她容易和人熟络吗？\n— 容易，连陌生人都能聊得来。', en: '— Does she make friends easily?\n— Yes, she finds common ground even with strangers.', ctx: '擅长交际' },
  { ru: '— Ты легко принимаешь решения?\n— Не всегда, подолгу всё обдумываю.', zh: '— 你做决定容易吗？\n— 不总是容易，我会考虑很久。', en: '— Do you make decisions easily?\n— Not always, I think things over for a long time.', ctx: '决断风格' },
  { ru: 'Не люблю, когда люди опаздывают, я очень пунктуальный.', zh: '我讨厌别人迟到，我是个很守时的人。', en: 'I don\'t like it when people are late; I\'m very punctual.', ctx: '讨厌迟到' },
  { ru: '— Он и правда такой ленивый?\n— Ну не без этого, но если надо — сделает.', zh: '— 他真的那么懒吗？\n— 嗯，确实有点，但需要时他还是会做。', en: '— Is he really that lazy?\n— Well, not entirely without it, but if he has to, he\'ll do it.', ctx: '是否懒惰' },
  { ru: 'В незнакомой компании я сначала стесняюсь.', zh: '在陌生的人群里，我一开始会不好意思。', en: 'In an unfamiliar group I feel shy at first.', ctx: '生人面前腼腆' },
  { ru: '— Почему ты всегда такой серьёзный?\n— Я не серьёзный, я просто сосредоточенный.', zh: '— 你为什么总是这么严肃？\n— 我不是严肃，只是专注而已。', en: '— Why are you always so serious?\n— I\'m not serious, I\'m just focused.', ctx: '严肃专注' },
  { ru: '— Какой у твоей подруги характер?\n— Лёгкий, с ней никогда не бывает скучно.', zh: '— 你的朋友性格怎么样？\n— 很随和，跟她在一起从不无聊。', en: '— What\'s your friend\'s personality like?\n— Easy-going, it\'s never boring with her.', ctx: '性格随和' },
  { ru: '— Как бы ты описал себя одним словом?\n— Наверное, любопытный.\n— Любопытный? По-моему, это скорее хорошо.', zh: '— 如果用一个词形容自己，你会怎么说？\n— 大概是“好奇”吧。\n— 好奇？我倒觉得这是优点。', en: '— How would you describe yourself in one word?\n— Curious, probably.\n— Curious? I think that\'s more of a good thing.', ctx: '一词自评' },
  { ru: '— Ты злишься, когда проигрываешь?\n— Бывает, но я быстро отхожу, честно.', zh: '— 你输了会生气吗？\n— 有时会，但说实话我很快就消气了。', en: '— Do you get angry when you lose?\n— Sometimes, but honestly I get over it quickly.', ctx: '生气后恢复' },
  { ru: 'Я говорю по-русски, но ещё делаю ошибки.', zh: '我会说俄语，但还会犯错误。', en: 'I speak Russian, but I still make mistakes.', ctx: '俄语水平' },
  { ru: '— Какие языки ты знаешь?\n— Китайский, английский и немного русский.', zh: '— 你会哪些语言？\n— 汉语、英语，还有一点俄语。', en: '— What languages do you know?\n— Chinese, English, and a little Russian.', ctx: '会哪些语言' },
  { ru: 'Она свободно владеет тремя иностранными языками.', zh: '她流利掌握三门外语。', en: 'She is fluent in three foreign languages.', ctx: '精通外语' },
  { ru: '— Вы понимаете китайскую речь на слух?\n— Понимаю, а вот говорю пока с трудом.', zh: '— 您能听懂汉语口语吗？\n— 能听懂，但说起来还比较吃力。', en: '— Can you understand spoken Chinese?\n— I understand it, but speaking is still hard for me.', ctx: '听力理解' },
  { ru: 'Я учу русский язык уже два года.', zh: '我学俄语已经两年了。', en: 'I\'ve been learning Russian for two years.', ctx: '学俄语时长' },
  { ru: '— Ты бегло говоришь по-английски?\n— Читаю свободно, а в разговоре теряюсь.\n— Зря, практика ведь всё решает.\n— Ты прав, надо больше общаться.', zh: '— 你英语说得流利吗？\n— 阅读没问题，可一开口就慌。\n— 别这样，练习决定一切。\n— 你说得对，我得多交流。', en: '— Do you speak English fluently?\n— I read freely, but I get lost in conversation.\n— Nonsense, practice is what matters.\n— You\'re right, I need to talk more.', ctx: '英语口语' },
  { ru: 'Из-за акцента меня иногда не понимают.', zh: '因为口音，别人有时听不懂我说话。', en: 'Because of my accent, people sometimes don\'t understand me.', ctx: '口音困扰' },
  { ru: '— Как у тебя с грамматикой?\n— Падежи до сих пор даются с трудом.', zh: '— 你语法怎么样？\n— 格的变化至今还让我头疼。', en: '— How\'s your grammar?\n— The cases are still hard for me.', ctx: '语法难点' },
  { ru: '— Повторите, пожалуйста, помедленнее.\n— Да, конечно, я скажу то же самое ещё раз.', zh: '— 请您再说一遍，慢一点。\n— 好的，当然，我把同样的话再说一遍。', en: '— Please repeat it more slowly.\n— Yes, of course, I\'ll say the same thing again.', ctx: '请求放慢语速' },
  { ru: '— Ты бы смог перевести этот текст без словаря?\n— Попробовал бы, но пару слов наверняка бы забыл.', zh: '— 你能不用词典翻译这篇课文吗？\n— 可以试试，但肯定有几个词会想不起来。', en: '— Could you translate this text without a dictionary?\n— I\'d try, but I\'d surely forget a couple of words.', ctx: '无词典翻译' },
  { ru: '— В твоей семье говорят на иностранных языках?\n— Дедушка немного говорит по-немецки.\n— Здорово, было бы у кого поучиться.', zh: '— 你家里有人说外语吗？\n— 爷爷会说一点德语。\n— 真好，有人可以请教。', en: '— Does anyone in your family speak foreign languages?\n— Grandpa speaks a little German.\n— That\'s great, you\'d have someone to learn from.', ctx: '家人会外语' },
  { ru: '— Почему ты изучаешь именно русский?\n— Нравится литература, да и звучит он красиво.\n— Согласна, но грамматика у него просто ужасная.', zh: '— 你为什么偏偏学俄语？\n— 我喜欢俄罗斯文学，而且俄语也好听。\n— 同意，不过它的语法实在太难了。', en: '— Why do you learn Russian of all languages?\n— I like the literature, and it sounds beautiful.\n— Agreed, but its grammar is just terrible.', ctx: '学俄语原因' },
  { ru: '— Как сказать «спасибо» по-китайски?\n— Очень просто: «сесе».', zh: '— “спасибо”用中文怎么说？\n— 很简单：“谢谢”。', en: '— How do you say \'thank you\' in Chinese?\n— Very simple: \'xiexie\'.', ctx: '中文怎么说' },
  { ru: '— Над чем ты сейчас работаешь в языке?\n— Хочу избавиться от сильного акцента.', zh: '— 你目前在语言方面攻克什么？\n— 我想改掉浓重的口音。', en: '— What are you working on in the language now?\n— I want to get rid of my strong accent.', ctx: '纠正口音' },
  { ru: '— Ты смотришь фильмы с субтитрами?\n— Сначала с русскими, потом уже без них.', zh: '— 你看电影带字幕吗？\n— 先看俄语字幕，后来就不用了。', en: '— Do you watch films with subtitles?\n— First with Russian ones, later without them.', ctx: '看片学语言' },
  { ru: 'На вечеринке я познакомился с интересными людьми.', zh: '我在聚会上认识了一些有趣的人。', en: 'At the party I met some interesting people.', ctx: '派对交友' },
  { ru: '— Можно добавить тебя в друзья?\n— Конечно, скинь ссылку на свою страницу.', zh: '— 可以加你好友吗？\n— 当然，把你主页的链接发给我。', en: '— Can I add you as a friend?\n— Sure, send me the link to your page.', ctx: '请求加好友' },
  { ru: 'Мы дружим ещё со школы, лет десять уже.', zh: '我们从上学时就是朋友，已经十年了。', en: 'We\'ve been friends since school, about ten years now.', ctx: '多年老友' },
  { ru: '— Давай сходим куда-нибудь в пятницу!\n— Отличная мысль, я как раз свободен.', zh: '— 星期五我们去哪儿玩吧！\n— 好主意，我正好有空。', en: '— Let\'s go somewhere on Friday!\n— Great idea, I happen to be free.', ctx: '周五邀约' },
  { ru: '— Почему ты так доверяешь этому другу?\n— Он всегда помогает мне в трудную минуту.\n— Настоящий друг, тебе повезло.', zh: '— 你为什么这么信任这个朋友？\n— 我遇到困难时他总会帮忙。\n— 真正的朋友，你很幸运。', en: '— Why do you trust this friend so much?\n— He always helps me in difficult times.\n— A true friend, you\'re lucky.', ctx: '患难之交' },
  { ru: '— Ты знаком с Ирой?\n— Лично нет, но мы часто переписываемся.\n— Ну так приходи на её день рождения, я вас познакомлю!\n— Спасибо, с радостью приду.', zh: '— 你认识伊拉吗？\n— 没见过面，但我们常聊天。\n— 那你来她的生日聚会吧，我给你们介绍！\n— 谢谢，我很乐意来。', en: '— Do you know Ira?\n— Not in person, but we often text.\n— Then come to her birthday party, I\'ll introduce you!\n— Thanks, I\'ll gladly come.', ctx: '牵线认识' },
  { ru: '— Ну что, рад был с тобой познакомиться!\n— Я тоже. До скорой встречи!', zh: '— 那么，很高兴认识你！\n— 我也是，回头见！', en: '— Well, it was nice meeting you!\n— Me too. See you soon!', ctx: '初次道别' },
  { ru: '— Почему вы поссорились?\n— Из-за ерунды, на следующий день уже помирились.', zh: '— 你们为什么吵架？\n— 为了点小事，第二天就和好了。', en: '— Why did you quarrel?\n— Over nothing, we made up the next day.', ctx: '吵架和好' },
  { ru: 'Не люблю большие компании, мне уютнее вдвоём.', zh: '我不喜欢人多的场合，两个人相处更自在。', en: 'I don\'t like big groups; I feel cozier with just one person.', ctx: '不喜热闹' },
  { ru: '— Останься ещё, все только собрались!\n— Не могу, завтра рано вставать.', zh: '— 再待会儿吧，大家才刚到齐！\n— 不行，明天得早起。', en: '— Stay a bit longer, everyone just gathered!\n— I can\'t, I have to get up early tomorrow.', ctx: '派对挽留' },
  { ru: 'Мы договорились встретиться у входа в парк в шесть.', zh: '我们约好六点在公园门口见面。', en: 'We arranged to meet at the park entrance at six.', ctx: '约定见面' },
  { ru: '— Ты придёшь? Я жду тебя уже двадцать минут.\n— Прости, стою в пробке, буду через десять.\n— Ладно, я пока выпью кофе.', zh: '— 你来吗？我已经等你二十分钟了。\n— 抱歉，我堵车了，再过十分钟到。\n— 好吧，我先喝杯咖啡。', en: '— Are you coming? I\'ve been waiting for twenty minutes.\n— Sorry, I\'m stuck in traffic, I\'ll be there in ten.\n— Fine, I\'ll have a coffee meanwhile.', ctx: '迟到致歉' },
  { ru: '— Давай обменяемся номерами?\n— Давай, диктуй, я запишу.', zh: '— 我们交换一下电话号码吧？\n— 好啊，你说，我记一下。', en: '— Let\'s exchange numbers?\n— Okay, dictate, I\'ll write it down.', ctx: '交换电话' },
  { ru: '— Она быстро осваивается в новом коллективе?\n— Да, она легко заводит знакомства где угодно.', zh: '— 她在新团队里适应得快吗？\n— 快，她在哪儿都能轻松交到朋友。', en: '— Does she settle into a new team quickly?\n— Yes, she easily makes friends anywhere.', ctx: '擅长交友' },
  { ru: '— Ты не против, если я приглашу Марину?\n— Нисколько, я буду только рад.', zh: '— 我邀请玛琳娜来你不介意吧？\n— 一点也不，我高兴还来不及呢。', en: '— Do you mind if I invite Marina?\n— Not at all, I\'d only be glad.', ctx: '邀请他人' },
  { ru: 'В 2019 году я впервые поехал за границу.', zh: '2019年我第一次出国。', en: 'In 2019 I went abroad for the first time.', ctx: '首次出国', say: 'В две тысячи девятнадцатом году я впервые поехал за границу' },
  { ru: '— Ты когда-нибудь летал на самолёте?\n— Да, и однажды чуть не опоздал на рейс.', zh: '— 你坐过飞机吗？\n— 坐过，有一次差点误了航班。', en: '— Have you ever flown on a plane?\n— Yes, and once I almost missed my flight.', ctx: '乘机经历' },
  { ru: 'Я полгода жил в общежитии с иностранцами.', zh: '我和外国人一起在宿舍住过半年。', en: 'I lived in a dormitory with foreigners for half a year.', ctx: '宿舍生活' },
  { ru: '— Расскажи самый смешной случай из школы.\n— Ой, я однажды заснул на уроке географии.', zh: '— 讲一件上学时最好笑的事吧。\n— 哎呀，有一次我在地理课上睡着了。', en: '— Tell the funniest story from school.\n— Oh, once I fell asleep in geography class.', ctx: '课堂糗事' },
  { ru: 'На будущий год я обязательно выучу японский.', zh: '明年我一定要学会日语。', en: 'Next year I will definitely learn Japanese.', ctx: '未来计划' },
  { ru: '— Ты уже был в новом музее?\n— Был вчера, провёл там целых четыре часа.\n— И как впечатления?\n— Потрясающие, очень советую сходить.', zh: '— 你去过新博物馆了吗？\n— 昨天去了，在里面待了整整四个小时。\n— 感觉怎么样？\n— 好极了，强烈推荐你去。', en: '— Have you been to the new museum yet?\n— I went yesterday, spent four whole hours there.\n— And what are your impressions?\n— Amazing, I highly recommend going.', ctx: '参观博物馆' },
  { ru: '— Ты падал когда-нибудь с велосипеда?\n— В детстве, когда мне было лет десять.', zh: '— 你从自行车上摔下来过吗？\n— 小时候摔过，那时我大概十岁。', en: '— Have you ever fallen off a bike?\n— In childhood, when I was about ten.', ctx: '骑车摔跤' },
  { ru: '— Приходилось ли тебе выступать перед публикой?\n— Один раз пришлось, я тогда сильно волновался.', zh: '— 你有过当众演出的经历吗？\n— 有过一次，当时我特别紧张。', en: '— Have you ever had to perform in front of an audience?\n— Once I had to, I was very nervous then.', ctx: '公开演讲' },
  { ru: '— Ты уже был в русской бане?\n— Никогда не был, но очень хочу попробовать.\n— Тогда поедем зимой на дачу!', zh: '— 你洗过俄式桑拿吗？\n— 从没洗过，但很想试试。\n— 那冬天我们去别墅吧！', en: '— Have you been to a Russian banya yet?\n— Never, but I really want to try.\n— Then let\'s go to the dacha in winter!', ctx: '俄式桑拿' },
  { ru: '— Как прошёл твой первый день на работе?\n— Ужасно: я заблудился в здании и пролил кофе.', zh: '— 你上班第一天过得怎么样？\n— 糟透了：我在楼里迷路，还洒了咖啡。', en: '— How was your first day at work?\n— Awful: I got lost in the building and spilled coffee.', ctx: '入职第一天' },
  { ru: '— Как ты вообще оказался в этом городе?\n— Расскажу как-нибудь за чашкой чая.', zh: '— 你到底是怎么来到这座城市的？\n— 改天喝杯茶时我再讲给你听。', en: '— How did you even end up in this city?\n— I\'ll tell you sometime over a cup of tea.', ctx: '来到此城' },
  { ru: '— Представляешь, я встретил школьного друга!\n— Где, если не секрет?\n— В метро, спустя десять лет после выпуска.', zh: '— 你猜怎么着，我遇到老同学了！\n— 在哪儿，如果不是秘密的话？\n— 在地铁里，毕业十年之后。', en: '— Imagine, I met a school friend!\n— Where, if it\'s not a secret?\n— In the metro, ten years after graduation.', ctx: '偶遇老友' },
  { ru: '— Ты жил раньше в другом городе?\n— Да, в детстве мы переехали из Новосибирска.', zh: '— 你以前住在别的城市吗？\n— 对，小时候我们从新西伯利亚搬来的。', en: '— Did you used to live in another city?\n— Yes, we moved from Novosibirsk in my childhood.', ctx: '搬家经历' },
  { ru: 'Если бы я знал язык, то остался бы там надолго.', zh: '要是我当时懂那门语言，就会在那儿多待一阵。', en: 'If I had known the language, I would have stayed there for long.', ctx: '假设经历' },
  { ru: '— Это был лучший день в твоей жизни?\n— Один из лучших, это точно.', zh: '— 那是你人生中最美好的一天吗？\n— 是最美好的日子之一，这一点肯定。', en: '— Was that the best day of your life?\n— One of the best, that\'s for sure.', ctx: '美好一天' },
]

// ── 校园学习 / Campus & study / Учёба ──
const STUDY: Phrase[] = [
  { ru: 'Преподаватель вошёл в аудиторию, и все сразу замолчали.', zh: '老师走进教室，大家立刻安静了下来。', en: 'The teacher walked into the classroom and everyone fell silent at once.', ctx: '上课开始' },
  { ru: '— Откройте учебники на двадцать седьмой странице.\n— А мы уже на следующей, здесь двадцать восьмая.', zh: '— 请把课本翻到第二十七页。— 我们已经翻到后一页了，这里是二十八页。', en: '— \'Open your textbooks to page twenty-seven.\' \'We are already on the next page; this is twenty-eight.\'', ctx: '翻书上课' },
  { ru: '— Можно я выйду на минуту? Мне срочно нужно ответить маме.\n— Хорошо, только вернись к концу опроса.', zh: '— 我能出去一下吗？我得马上给妈妈回个电话。— 好，不过提问结束前要回来。', en: '— \'May I step out for a minute? I urgently need to call my mum back.\' \'All right, just be back by the end of the Q and A.\'', ctx: '请假离开' },
  { ru: '— На какой странице мы остановились в прошлый раз?\n— Кажется, на сорок пятой.\n— Точно, спасибо. Продолжим чтение.', zh: '— 上次我们停在哪一页？— 好像是第四十五页。— 对，谢谢，我们继续读。', en: '— \'Which page did we stop at last time?\' \'Page forty-five, I think.\' \'Exactly, thank you. Let us continue reading.\'', ctx: '接续课文' },
  { ru: '— Не опаздывай завтра на семинар, преподаватель обещал устроить опрос.\n— Тогда я точно выйду пораньше.', zh: '— 明天研讨课别迟到，老师说要提问。— 那我肯定早点出门。', en: '— \'Do not be late for tomorrow\'s seminar; the teacher promised a quiz.\' \'Then I will definitely leave earlier.\'', ctx: '提醒别迟到' },
  { ru: '— Кто пойдёт к доске решать второй пример?\n— Можно я попробую? Я вчера разобрал это правило.', zh: '— 谁到黑板前面来做第二道题？— 我可以试试吗？我昨天弄懂了这条规则。', en: '— \'Who will come to the board and solve the second problem?\' \'May I try? I worked through this rule yesterday.\'', ctx: '黑板做题' },
  { ru: 'Как тихо в аудитории перед контрольной! Слышно даже тиканье часов.', zh: '小测前的教室真安静啊，连钟表的滴答声都听得见。', en: 'How quiet the classroom is before the quiz! You can even hear the clock ticking.', ctx: '考前安静' },
  { ru: '— Запишите домашнее задание: упражнения с третьего по седьмое.\n— А восьмое делать? Оно очень лёгкое.\n— По желанию, для тренировки.', zh: '— 记下家庭作业：第三到第七题。— 第八题做吗？挺简单的。— 选做，用来练习。', en: '— \'Write down the homework: exercises three through seven.\' \'Should we do number eight? It is very easy.\' \'Optional, just for practice.\'', ctx: '布置作业' },
  { ru: 'Если бы я не прослушал лекцию, я бы понял новую тему.', zh: '我要是没漏掉那场讲座，就能明白新课题了。', en: 'If I had not missed that lecture, I would understand the new topic.', ctx: '懊悔缺课' },
  { ru: '— Можно войти? Извините за опоздание, застрял в метро.\n— Входи, но в следующий раз выходи заранее.', zh: '— 可以进来吗？抱歉迟到，我在地铁里卡住了。— 进来吧，不过下次早点出门。', en: '— \'May I come in? Sorry I am late, I got stuck on the metro.\' \'Come in, but next time leave ahead of schedule.\'', ctx: '迟到进门' },
  { ru: '— Ты идёшь на эту пару или опять останешься в буфете?\n— Иду, сегодня же будет перекличка.', zh: '— 这节课你去上吗，还是又留在小卖部？— 去，今天要点名的。', en: '— \'Are you going to this class or staying in the canteen again?\' \'I am going; there is roll call today.\'', ctx: '相约上课' },
  { ru: '— Ребята, уберите телефоны, сейчас будем работать в парах.\n— А можно оставить для словаря?\n— Нет, пользуйтесь бумажным.', zh: '— 同学们把手机收起来，现在两人一组练习。— 能留着查词典吗？— 不行，用纸词典。', en: '— \'Everyone put away your phones; we will work in pairs now.\' \'Can I keep mine for a dictionary?\' \'No, use a paper one.\'', ctx: '收起手机' },
  { ru: '— Ты что, спишь? Преподаватель на нас смотрит.\n— Я просто очень устал, всю ночь писал реферат.', zh: '— 你怎么睡着了？老师在看我们呢。— 我就是太累了，通宵写了小论文。', en: '— \'Are you asleep? The teacher is looking at us.\' \'I am just exhausted; I spent the whole night writing an essay.\'', ctx: '课上犯困' },
  { ru: '— Повторите, пожалуйста, последнюю фразу. Я не расслышал.\n— Конечно, я говорю медленнее. Записывайте.', zh: '— 请重复一下最后一句话，我没听清。— 好的，我放慢一点，大家记下来。', en: '— \'Could you repeat the last sentence, please? I did not catch it.\' \'Of course. I will speak more slowly. Take notes.\'', ctx: '请老师重复' },
  { ru: 'Занятия в пятницу заканчиваются в 16:40, потом можно погулять.', zh: '周五的课十六点四十结束，之后可以去逛逛。', en: 'Classes on Friday end at 4:40 p.m., and then we can hang out.', ctx: '下课时间', say: 'Занятия в пятницу заканчиваются в шестнадцать часов сорок минут потом можно погулять' },
  { ru: '— Давай поменяемся местами: отсюда совсем не видно доску.\n— А мне что с этого?\n— Я угощу тебя кофе на перемене.\n— Договорились.', zh: '— 我们换个座位吧，这儿完全看不到黑板。— 我有什么好处？— 课间我请你喝咖啡。— 说定了。', en: '— \'Let us swap seats; I cannot see the board at all from here.\' \'What is in it for me?\' \'I will treat you to coffee at the break.\' \'Deal.\'', ctx: '调换座位' },
  { ru: 'Посмотрите на карту и найдите города, основанные в девятнадцатом веке.', zh: '请看地图，找出建于十九世纪的城市。', en: 'Look at the map and find the cities founded in the nineteenth century.', ctx: '看图标注' },
  { ru: '— У вас есть вопросы по пройденному материалу?\n— Да, я не понял разницу между этими двумя терминами.', zh: '— 对学过的内容有什么问题吗？— 有，我没弄懂这两个术语的区别。', en: '— \'Do you have any questions on the material we covered?\' \'Yes, I do not understand the difference between these two terms.\'', ctx: '课堂答疑' },
  { ru: 'Вот звонок! Сдавайте работы, даже если не успели дописать.', zh: '铃响了！就算没写完也把卷子交上来。', en: 'There is the bell! Hand in your papers, even if you have not finished.', ctx: '下课收卷' },
  { ru: '— Не забудь, что завтра первая пара начинается в восемь.\n— Спасибо, что напомнил, а то бы я проспал.', zh: '— 别忘了明天第一节课八点开始。— 谢谢你提醒，不然我就睡过头了。', en: '— \'Do not forget that tomorrow\'s first class starts at eight.\' \'Thanks for reminding me, or I would have slept in.\'', ctx: '提醒早课' },
  { ru: 'Если не понимаешь слово, лучше сразу спроси, чем догадываться.', zh: '不懂一个词最好马上问，而不是瞎猜。', en: 'If you do not understand a word, it is better to ask right away than to guess.', ctx: '不懂就问' },
  { ru: '— Подскажите, пожалуйста, как правильно: «прийти» или «придти»?\n— Только «прийти», второй вариант устарел.', zh: '— 请问哪种写法正确：прийти 还是 придти？— 只能用 прийти，第二种写法已经过时。', en: '— \'Could you tell me which is correct: «прийти» or «придти»?\' \'Only «прийти»; the second form is outdated.\'', ctx: '拼写提问' },
  { ru: '— В чём разница между «учить» и «выучить»?\n— Первое — это процесс, а второе — результат.', zh: '— учить 和 выучить 有什么区别？— 前者是过程，后者是结果。', en: '— \'What is the difference between «учить» and «выучить»?\' \'The first is the process, the second is the result.\'', ctx: '词义辨析' },
  { ru: '— Можно задать вопрос?\n— Да, конечно, слушаю вас.\n— Эта формула действует и в обратном случае?\n— Хороший вопрос: да, но с оговоркой.', zh: '— 我能提个问题吗？— 当然可以，您说。— 这条公式反过来也成立吗？— 问题提得好：成立，但有个附加条件。', en: '— \'May I ask a question?\' \'Yes, of course, go ahead.\' \'Does this formula work the other way around too?\' \'Good question: yes, but with a caveat.\'', ctx: '课堂提问' },
  { ru: '— Ты понял, что он сказал про крайний срок?\n— Не совсем, давай после пары переспросим вместе.', zh: '— 你听清他说截止日期是什么时候了吗？— 没太听懂，下课后我们一起再去问问吧。', en: '— \'Did you understand what he said about the deadline?\' \'Not really. Let us ask again together after class.\'', ctx: '课后追问' },
  { ru: '— Почему ты не отвечаешь, хотя тебя спрашивают?\n— Я боюсь ошибиться и выглядеть глупо.', zh: '— 老师问你呢，你怎么不回答？— 我怕答错，显得很蠢。', en: '— \'Why don\'t you answer when you are asked?\' \'I am afraid of making a mistake and looking stupid.\'', ctx: '不敢回答' },
  { ru: 'Не стесняйся задавать глупые вопросы — стыдно не хотеть знать.', zh: '别害怕问傻问题，不想求知才丢人。', en: 'Do not be shy about asking silly questions; what is shameful is not wanting to know.', ctx: '鼓励提问' },
  { ru: '— Отвечайте полным предложением, а не одним словом.\n— То есть нужно начать с подлежащего?\n— Именно, тогда фраза звучит законченно.', zh: '— 请用完整句子回答，不要只说一个词。— 也就是说要从主语开始？— 没错，这样句子才完整。', en: '— \'Answer with a full sentence, not just one word.\' \'You mean I should start with the subject?\' \'Exactly; then the sentence sounds complete.\'', ctx: '完整回答' },
  { ru: 'Если бы ты поднял руку раньше, тебя бы вызвали первым.', zh: '你要是早点举手，就会第一个叫你回答了。', en: 'If you had raised your hand earlier, they would have called on you first.', ctx: '举手发言' },
  { ru: '— А что будет, если я отвечу неправильно?\n— Ничего страшного, разберём ошибку и пойдём дальше.', zh: '— 我要是答错了会怎样？— 没什么大不了，我们分析完错误继续。', en: '— \'What happens if I answer incorrectly?\' \'Nothing terrible; we will go over the mistake and move on.\'', ctx: '答错无碍' },
  { ru: '— Как по-русски называется эта деталь?\n— Не знаю, посмотри в словаре или спроси ассистента.', zh: '— 这个零件俄语叫什么？— 不知道，你查查词典或者问问助教。', en: '— \'What do you call this part in Russian?\' \'I do not know. Look it up or ask the assistant.\'', ctx: '询问术语' },
  { ru: '— Ну что, готов отвечать?\n— Кажется, да, только повторил билет минут десять.\n— Тогда иди к доске, не тяни.', zh: '— 怎么样，准备好回答了吗？— 应该吧，我刚把考题复习了十来分钟。— 那就上黑板来吧，别磨蹭。', en: '— \'Well, are you ready to answer?\' \'I think so; I only reviewed the prompt for ten minutes.\' \'Then come to the board, do not drag it out.\'', ctx: '被叫回答' },
  { ru: '— Можно переспросить? Вы сказали «отвечает» или «отвечают»?\n— Я сказал «отвечают», во множественном числе.', zh: '— 能再问一下吗？您说的是 отвечает 还是 отвечают？— 我说的是 отвечают，复数形式。', en: '— \'Sorry, could you repeat that? Did you say «отвечает» or «отвечают»?\' \'I said «отвечают», in the plural.\'', ctx: '确认听辨' },
  { ru: '— Почему оценку снизили, хотя ответ верный?\n— Из-за грамматической ошибки в последнем предложении.', zh: '— 答案是对的，为什么还扣分？— 因为最后一句有语法错误。', en: '— \'Why was my grade lowered even though the answer is correct?\' \'Because of a grammar mistake in the last sentence.\'', ctx: '质问扣分' },
  { ru: 'В аудитории подняли руки всего 3 студента.', zh: '教室里只有三名学生举手。', en: 'Only three students in the classroom raised their hands.', ctx: '举手人数', say: 'В аудитории подняли руки всего три студента' },
  { ru: '— Как спросить дорогу, если не знаешь названия улицы?\n— Можно сказать: «Как пройти к ближайшей станции?»\n— Звучит просто, попробую так и сказать.', zh: '— 不知道街名的时候该怎么问路？— 可以说：“最近的车站怎么走？”— 听起来不难，我就试着这么说。', en: '— \'How do I ask for directions if I do not know the street name?\' \'You can say: How do I get to the nearest station?\' \'That sounds simple; I will try saying it that way.\'', ctx: '情景问答' },
  { ru: 'Отвечая, смотри на собеседника, а не в пол.', zh: '回答时看着对方，别盯着地板。', en: 'When answering, look at the person you are speaking to rather than at the floor.', ctx: '回答礼仪' },
  { ru: '— Ты уже спрашивал у профессора про пересдачу?\n— Спрашивал, он разрешил прийти в среду.', zh: '— 你问过教授补考的事了吗？— 问过了，他让我周三去。', en: '— \'Have you asked the professor about the retake yet?\' \'I have; he let me come on Wednesday.\'', ctx: '询问补考' },
  { ru: 'Вот увидишь: после первого удачного ответа страх пропадёт.', zh: '等着瞧吧，第一次成功回答之后，紧张就会消失。', en: 'You will see: after your first successful answer, the fear will be gone.', ctx: '克服紧张' },
  { ru: '— Разрешите уточнить: речь о главе третьей или четвёртой?\n— О третьей, четвёртую обсудим на следующей неделе.', zh: '— 请问您指的是第三章还是第四章？— 第三章，第四章我们下周讨论。', en: '— \'May I clarify: are we talking about chapter three or four?\' \'Chapter three. We will discuss four next week.\'', ctx: '确认范围' },
  { ru: 'К сессии лучше готовиться заранее, а не в последнюю ночь.', zh: '考季最好提前准备，别拖到最后一夜。', en: 'It is better to prepare for exam season in advance rather than on the final night.', ctx: '备考建议' },
  { ru: '— Ты уже взял список вопросов к экзамену?\n— Взял, их там целых сорок пять.', zh: '— 你拿到考试的问题清单了吗？— 拿到了，足足有四十五道。', en: '— \'Have you got the list of exam questions yet?\' \'I have; there are forty-five of them.\'', ctx: '考试范围' },
  { ru: '— Когда будет пересдача по математике?\n— Вроде бы в пятницу, точное время висит на стенде.', zh: '— 数学什么时候补考？— 好像是周五，准确时间贴在公告栏上。', en: '— \'When is the math retake?\' \'Friday, I think. The exact time is on the notice board.\'', ctx: '补考时间' },
  { ru: '— Как прошёл зачёт?\n— Отлично, поставили автоматом за активность.\n— Везёт же тебе, а мне ещё готовиться.', zh: '— 查核考得怎么样？— 很好，因为平时积极直接给过了。— 你可真走运，我还得复习呢。', en: '— \'How did the pass-fail exam go?\' \'Great; I got an automatic pass for participation.\' \'Lucky you; I still have to study.\'', ctx: '查问成绩' },
  { ru: '— Я провалил первый вопрос, но остальные ответил хорошо.\n— Значит, тройку-то ты точно получишь.', zh: '— 第一道题我答砸了，但其余的答得不错。— 那三分你肯定能拿到。', en: '— \'I messed up the first question but answered the rest well.\' \'Then you will definitely get at least a three.\'', ctx: '估测成绩' },
  { ru: '— Не волнуйся так, ты же всё выучил!\n— Легко говорить, у меня от страха всё вылетело из головы.', zh: '— 别这么紧张，你不都复习好了吗！— 说起来容易，我一害怕就全忘了。', en: '— \'Do not worry so much; you have learned it all!\' \'Easy to say. Fear has wiped everything from my mind.\'', ctx: '考前安慰' },
  { ru: 'На контрольной было так трудно, что я не решил даже первую задачу.', zh: '小测太难了，我连第一道题都没做出来。', en: 'The quiz was so hard that I did not solve even the first problem.', ctx: '测验太难' },
  { ru: '— Шпаргалки с собой есть?\n— Есть, но достать их почти невозможно.\n— Тогда надейся на память, друг.', zh: '— 带小抄了吗？— 带了，但根本没法掏出来。— 那就靠记性吧，朋友。', en: '— \'Do you have cheat sheets with you?\' \'I do, but getting them out is almost impossible.\' \'Then rely on your memory, friend.\'', ctx: '夹带小抄' },
  { ru: 'До экзамена осталось всего 10 минут, а я ещё не повторил формулы.', zh: '离考试只剩十分钟了，我还没复习公式。', en: 'Only ten minutes are left before the exam, and I have not reviewed the formulas yet.', ctx: '考前紧张', say: 'До экзамена осталось всего десять минут а я ещё не повторил формулы' },
  { ru: '— Преподаватель разрешил пользоваться калькулятором?\n— Да, но только простым, без программируемых функций.', zh: '— 老师允许用计算器吗？— 允许，但只能用简单的，不能有编程功能。', en: '— \'Did the teacher allow calculators?\' \'Yes, but only basic ones, without programmable functions.\'', ctx: '考试规则' },
  { ru: '— Какая оценка у тебя за тест?\n— Четвёрка, обидно, до пятёрки не хватило балла.', zh: '— 你测验得了几分？— 四分，真可惜，差一分就五分了。', en: '— \'What grade did you get on the test?\' \'A four. Annoying; I was one point short of a five.\'', ctx: '测验出分' },
  { ru: '— Ты идёшь на консультацию перед экзаменом?\n— Иду, хочу разобрать сложные темы.\n— Тогда запиши и мой вопрос, пожалуйста.', zh: '— 你去考前答疑吗？— 去，我想把难懂的专题弄明白。— 那请帮我也把问题记上。', en: '— \'Are you going to the review session before the exam?\' \'I am; I want to go over the hard topics.\' \'Then please write down my question too.\'', ctx: '考前答疑' },
  { ru: '— За списывание сразу удалят с экзамена?\n— Запросто, потом ещё и докладную напишут.', zh: '— 作弊会马上被赶出考场吗？— 那还用说，之后还会写进报告。', en: '— \'Will they kick you out of the exam for copying?\' \'Easily, and then they will file a report too.\'', ctx: '作弊后果' },
  { ru: '— Мне поставили неуд, хотя я ответил на всё!\n— Тогда подай на апелляцию, имеешь право.', zh: '— 我明明全答了，却给了不及格！— 那你就申诉，这是你的权利。', en: '— \'They failed me even though I answered everything!\' \'Then file an appeal; you have the right.\'', ctx: '申请复议' },
  { ru: 'Если бы я решал тесты медленнее, я бы не наделал глупых ошибок.', zh: '我要是做题慢一点，就不会犯这么多低级错误。', en: 'If I had done the tests more slowly, I would not have made so many silly mistakes.', ctx: '反省失误' },
  { ru: '— Сколько баллов нужно для зачёта?\n— Не меньше шестидесяти из ста, кажется.', zh: '— 查核要多少分才过？— 好像至少六十分，满分一百。', en: '— \'How many points do you need to pass?\' \'At least sixty out of a hundred, I think.\'', ctx: '及格分数' },
  { ru: 'Экзамен начинается ровно в 9:00, опаздывать нельзя.', zh: '考试九点整开始，不能迟到。', en: 'The exam starts sharp at 9:00; you must not be late.', ctx: '考试时间', say: 'Экзамен начинается ровно в девять часов опаздывать нельзя' },
  { ru: '— Помнишь, какой билет ты вытащил?\n— Нет, я от волнения даже номер не посмотрел.\n— Ну ты даёшь! И как, ответил?', zh: '— 你记得抽到的是几号题吗？— 不记得，紧张得连号都没看。— 你可真行！那答上来了吗？', en: '— \'Do you remember which ticket you drew?\' \'No; I was so nervous I did not even look at the number.\' \'Wow! Did you manage to answer?\'', ctx: '抽签答题' },
  { ru: 'Сдав последний экзамен, студенты выбежали на улицу кричать от радости.', zh: '考完最后一门，学生们跑到街上欢呼。', en: 'After passing the last exam, the students ran outside shouting with joy.', ctx: '考完狂欢' },
  { ru: '— Ты уже закрыл сессию?\n— Почти, остался один зачёт по физкультуре.', zh: '— 你考季都结束了吗？— 差不多，就差体育查核了。', en: '— \'Have you finished exam season yet?\' \'Almost; just one pass-fail in PE left.\'', ctx: '学期收尾' },
  { ru: 'В читальном зале запрещено разговаривать и есть.', zh: '阅览室内禁止交谈和吃东西。', en: 'Talking and eating are not allowed in the reading room.', ctx: '馆内规定' },
  { ru: '— У вас есть эта книга в открытом доступе?\n— Нет, её можно заказать только из хранилища.', zh: '— 这本书在开放阅览区有吗？— 没有，只能从书库调取。', en: '— \'Is this book available in the open stacks?\' \'No; it can only be ordered from storage.\'', ctx: '借书咨询' },
  { ru: '— На сколько дней можно взять учебник?\n— На месяц, потом можно один раз продлить.', zh: '— 教材可以借多少天？— 一个月，之后可以续借一次。', en: '— \'How many days can I borrow the textbook for?\' \'A month, and it can be renewed once after that.\'', ctx: '借书期限' },
  { ru: '— Ты занял мне место у розетки?\n— Занял, но тут дует от окна.\n— Ничего, я принесу кофту.', zh: '— 你帮我占到插座旁边的位子了吗？— 占到了，但这儿窗户漏风。— 没事，我带件外套。', en: '— \'Did you save me a seat by a power outlet?\' \'I did, but there is a draft from the window.\' \'Never mind; I will bring a cardigan.\'', ctx: '占座自习' },
  { ru: '— Я забыл читательский билет, меня пустят?\n— Пустят по студенческому, в первый раз.', zh: '— 我忘带借书证了，能进去吗？— 第一次可以凭学生证进。', en: '— \'I forgot my library card; will they let me in?\' \'They will let you in with a student ID the first time.\'', ctx: '忘带证件' },
  { ru: '— Куда сдавать книги после закрытия зала?\n— В ящик при входе, его потом разберут библиотекари.', zh: '— 阅览室关门后书还到哪里？— 放进门口的箱子，之后由馆员处理。', en: '— \'Where do I return books after the room closes?\' \'In the box at the entrance; librarians will sort it later.\'', ctx: '还书方式' },
  { ru: 'Тишина библиотеки помогает мне сосредоточиться лучше, чем дома.', zh: '图书馆的安静比家里更能帮我集中注意力。', en: 'The library\'s silence helps me concentrate better than at home.', ctx: '安静效率' },
  { ru: '— Этот словарь свободен?\n— Бери, я как раз закончил.\n— Отлично, а то электронный ужасно неудобный.', zh: '— 这本词典没人用吧？— 拿去吧，我刚好用完。— 太好了，电子词典实在太难用。', en: '— \'Is this dictionary free?\' \'Take it; I have just finished.\' \'Great; the electronic one is terribly awkward.\'', ctx: '共用资料' },
  { ru: 'Книга хранится в отделе на 3 этаже, стеллаж двенадцатый.', zh: '书在三楼的文献部，第十二架。', en: 'The book is kept in the department on the third floor, shelf twelve.', ctx: '找书位置', say: 'Книга хранится в отделе на третьем этаже стеллаж двенадцатый' },
  { ru: '— Можно здесь сделать ксерокопию статьи?\n— Да, в копировальном центре у входа, оплата картой.', zh: '— 这里能复印论文吗？— 可以，在入口的复印中心，刷卡付费。', en: '— \'Can I make a photocopy of the article here?\' \'Yes, at the copy center by the entrance; pay by card.\'', ctx: '复印资料' },
  { ru: '— Ты когда-нибудь засыпал в библиотеке?\n— Было дело, меня даже будила уборщица.', zh: '— 你在图书馆睡着过吗？— 有过，保洁阿姨还把我叫醒了。', en: '— \'Have you ever fallen asleep in the library?\' \'I have once; the cleaner even woke me up.\'', ctx: '学困睡着' },
  { ru: '— Давай останемся здесь до закрытия.\n— До скольких она работает?\n— До десяти вечера, успеем всё повторить.', zh: '— 我们留到关门再走吧。— 它开到几点？— 晚上十点，我们来得及全部复习完。', en: '— \'Let us stay until closing.\' \'How late is it open?\' \'Until ten p.m.; we will have time to review everything.\'', ctx: '留馆复习' },
  { ru: '— Почему этот учебник нельзя выносить из зала?\n— Он единственный, поэтому выдаётся только под запись.', zh: '— 为什么这本教材不能带出阅览室？— 只有这一本，所以只登记借阅。', en: '— \'Why cannot this textbook be taken out of the room?\' \'It is the only copy, so it is lent out only by sign-in.\'', ctx: '孤本不外借' },
  { ru: '— Верни книгу вовремя, иначе дадут штраф.\n— Да знаю я, уже не первокурсник.', zh: '— 按时还书，不然会罚款。— 我知道，我又不是新生了。', en: '— \'Return the book on time or you will get a fine.\' \'I know; I am not a freshman anymore.\'', ctx: '按时还书' },
  { ru: 'За просрочку берут 5 рублей в день.', zh: '逾期每天收五卢布。', en: 'They charge five rubles a day for overdue books.', ctx: '逾期罚款', say: 'За просрочку берут пять рублей в день' },
  { ru: '— Здесь кто-нибудь сел?\n— Пока нет, но место держат для девушки с сумкой.\n— Ладно, поищу другой стол.', zh: '— 这儿有人坐吗？— 暂时没有，但有人给一个放包的女生留了座。— 好吧，我再找一张桌子。', en: '— \'Is anyone sitting here?\' \'Not yet, but the seat is kept for a girl with a bag.\' \'OK, I will find another table.\'', ctx: '寻找座位' },
  { ru: 'К полуночи глаза устали, и строчки начали расплываться.', zh: '到了半夜，眼睛累了，字行开始发花。', en: 'By midnight my eyes were tired and the lines had begun to blur.', ctx: '深夜苦读' },
  { ru: '— Где я могу найти подшивку журнала за прошлый год?\n— Спросите в справочном бюро, она есть в электронном каталоге.', zh: '— 去年的合订本杂志在哪里找？— 去咨询台问，它在电子目录里有。', en: '— \'Where can I find last year\'s bound volume of the journal?\' \'Ask at the reference desk; it is in the electronic catalog.\'', ctx: '查找期刊' },
  { ru: 'Вот бы библиотека работала круглосуточно во время сессии!', zh: '考季图书馆要是通宵开放就好了！', en: 'If only the library were open around the clock during exams!', ctx: '愿望吐槽' },
  { ru: '— Я потерял библиотечную книгу, что теперь будет?\n— Придётся купить такую же или заплатить её стоимость.', zh: '— 我把图书馆的书弄丢了，会怎么样？— 得买一本一样的，或者照价赔偿。', en: '— \'I lost a library book. What happens now?\' \'You will have to buy the same one or pay its value.\'', ctx: '丢书赔偿' },
  { ru: 'В нашем общежитии комендант строгий, но справедливый.', zh: '我们宿舍的楼管很严厉，但为人公正。', en: 'Our dorm warden is strict but fair.', ctx: '楼管其人' },
  { ru: '— Во сколько закрывается вход в общежитие?\n— В двенадцать, после этого звони вахтёру.', zh: '— 宿舍大门几点关？— 十二点，之后要按铃叫值班员。', en: '— \'What time does the dorm entrance close?\' \'At midnight; after that ring the duty officer.\'', ctx: '宿舍门禁' },
  { ru: '— Ты уже получил постельное бельё?\n— Получил, две простыни и наволочку.', zh: '— 你领到床上用品了吗？— 领到了，两条床单和一个枕套。', en: '— \'Have you picked up your bedding yet?\' \'I have: two sheets and a pillowcase.\'', ctx: '领取床品' },
  { ru: '— Сосед по комнате тебя не раздражает?\n— Ещё как раздражает: он слушает музыку без наушников.\n— Ну так поговори с ним, не молчи.', zh: '— 室友不惹你烦吗？— 烦得很，他听歌不戴耳机。— 那你就跟他说，别憋着。', en: '— \'Isn\'t your roommate getting on your nerves?\' \'He is: he listens to music without headphones.\' \'Then talk to him; don\'t stay silent.\'', ctx: '室友矛盾' },
  { ru: '— Можно сегодня привести гостей?\n— Можно, только до одиннадцати и не шуми сильно.', zh: '— 今天能请客人来吗？— 可以，但只能待到十一点，别太吵。', en: '— \'Can I bring guests over today?\' \'You can, just until eleven, and do not be loud.\'', ctx: '访客规定' },
  { ru: '— У тебя чайник найдётся?\n— Возьми в тумбочке, только не забудь выключить потом.', zh: '— 你那儿有烧水壶吗？— 床头柜里拿，用完别忘了关。', en: '— \'Do you happen to have a kettle?\' \'Take it from the bedside cabinet; just do not forget to turn it off.\'', ctx: '借用物品' },
  { ru: '— Почему утром в душ не попасть?\n— Он один на всё крыло, вот все и толпятся.', zh: '— 为什么早上根本用不上淋浴？— 整个侧翼只有一间，大家都挤在那儿。', en: '— \'Why is it impossible to use the shower in the morning?\' \'There is just one for the whole wing, so everyone crowds there.\'', ctx: '公共卫浴' },
  { ru: '— Кто сегодня моет пол? По графику вроде ты.\n— Я вчера мыл, теперь очередь соседа.\n— Ладно, я ему напомню.', zh: '— 今天谁拖地？按表好像是你。— 我昨天拖了，现在轮到室友。— 行，我提醒他。', en: '— \'Who is washing the floor today? According to the schedule it is you.\' \'I did it yesterday; now it is my roommate\'s turn.\' \'OK, I will remind him.\'', ctx: '值日打扫' },
  { ru: 'Наша комната — номер 508, поднимайся на пятый этаж.', zh: '我们房间是508，上五楼。', en: 'Our room is 508; come up to the fifth floor.', ctx: '房间号码', say: 'Наша комната номер пятьсот восемь поднимайся на пятый этаж' },
  { ru: '— Стиральная машина свободна?\n— Занята, запусти после восьми, когда тариф дешевле.', zh: '— 洗衣机空着吗？— 占着呢，八点以后再洗，那时电费便宜。', en: '— \'Is the washing machine free?\' \'It is taken. Run it after eight, when the rate is cheaper.\'', ctx: '洗衣安排' },
  { ru: '— Ты будешь готовить на общей кухне?\n— Да, сделаю макароны, хочешь с нами?', zh: '— 你要去公共厨房做饭吗？— 对，我煮通心粉，想一起吃吗？', en: '— \'Are you going to cook in the shared kitchen?\' \'Yeah, I will make pasta. Want to join us?\'', ctx: '公用厨房' },
  { ru: '— Опять отключили горячую воду!\n— Не ругайся, объявление висит уже неделю.\n— Значит, пойду греть чайники.', zh: '— 热水又停了！— 别骂了，通知一周前就贴上了。— 那我去烧水凑合。', en: '— \'They have cut the hot water again!\' \'Do not complain; the notice has been up for a week.\' \'Then I will go heat kettles.\'', ctx: '停水烦恼' },
  { ru: '— Не забудь пропуск, без него не впустят.\n— Спасибо, вечно он у меня вылетает из головы.', zh: '— 别忘了通行证，没有它进不来。— 谢谢，我老是忘这回事。', en: '— \'Do not forget your pass; without it they will not let you in.\' \'Thanks; it keeps slipping my mind.\'', ctx: '门禁刷卡' },
  { ru: 'Wi-Fi в моей комнате ловит только у окна.', zh: '我房间的无线网只有窗边有信号。', en: 'The Wi-Fi in my room only works next to the window.', ctx: '宿舍网络', say: 'вай фай в моей комнате ловит только у окна' },
  { ru: 'Если бы соседи не пели до трёх ночи, я бы выспался.', zh: '邻居们要是不唱歌到凌晨三点，我就能睡够了。', en: 'If the neighbors had not sung until three in the morning, I would have slept properly.', ctx: '噪音难眠' },
  { ru: '— Давай купим общий холодильник на комнату.\n— А где мы его поставим?\n— Придвинем к окну, там как раз есть место.', zh: '— 我们合买一台房间共用的冰箱吧。— 放哪儿呢？— 挪到窗边，那儿正好有空地。', en: '— \'Let us buy a shared fridge for the room.\' \'Where will we put it?\' \'We will move it to the window; there is just enough space.\'', ctx: '合买家电' },
  { ru: 'За стеной кто-то громко смеялся, и я долго не мог уснуть.', zh: '隔壁有人大声笑，我半天都睡不着。', en: 'Someone was laughing loudly next door, and I could not fall asleep for ages.', ctx: '隔壁吵闹' },
  { ru: '— Ты уже написал заявление на заселение в следующем году?\n— Нет ещё, а когда крайний срок?', zh: '— 你写明年的续住申请了吗？— 还没，截止到什么时候？', en: '— \'Have you written the application to stay next year yet?\' \'Not yet. When is the deadline?\'', ctx: '续住申请' },
  { ru: 'Залог за комнату — 3000 рублей, вернут при выезде.', zh: '房间押金是三千卢布，离校时退还。', en: 'The deposit for the room is three thousand rubles, returned when you move out.', ctx: '住宿押金', say: 'Залог за комнату три тысячи рублей вернут при выезде' },
  { ru: '— Переезжаешь в новую комнату?\n— Да, на следующей неделе, поможешь с сумками?', zh: '— 你要搬到新房间去？— 对，下周搬，帮我拎包行吗？', en: '— \'Are you moving to a new room?\' \'Yeah, next week. Will you help with the bags?\'', ctx: '调换宿舍' },
  { ru: 'С однокурсниками легко дружить, ведь у вас общие заботы.', zh: '和同学很容易交朋友，因为你们有共同的烦恼。', en: 'It is easy to be friends with classmates since you share the same worries.', ctx: '同窗友谊' },
  { ru: '— Давай сядем вместе на лекции.\n— Идём, я как раз занял тебе место.', zh: '— 讲座我们坐一起吧。— 走，我正好给你占了座。', en: '— \'Let us sit together at the lecture.\' \'Come on; I have saved you a seat.\'', ctx: '结伴上课' },
  { ru: '— Ты не будешь против, если я позову её в кафе?\n— С чего бы мне против? Я же не её парень.', zh: '— 我约她去咖啡馆，你不会介意吧？— 我凭什么介意？我又不是她男朋友。', en: '— \'You will not mind if I ask her out to a cafe?\' \'Why would I mind? I am not her boyfriend.\'', ctx: '暗恋情愫' },
  { ru: '— Почему ты с ним не здороваешься?\n— Мы поссорились из-за проекта, он меня подвёл.\n— Ну так помиритесь, дело прошлое.', zh: '— 你怎么不跟他打招呼？— 我们因为项目吵架了，他坑了我。— 那就和好呗，事情都过去了。', en: '— \'Why don\'t you say hello to him?\' \'We fell out over a project; he let me down.\' \'Then make up; it is all in the past.\'', ctx: '同学矛盾' },
  { ru: '— Поздравь меня, я получил ту стажировку!\n— Поздравляю, я всегда верил в тебя.', zh: '— 快祝贺我，我拿到那个实习了！— 恭喜，我一直相信你。', en: '— \'Congratulate me; I got that internship!\' \'Congratulations; I always believed in you.\'', ctx: '祝贺同学' },
  { ru: '— Одолжишь сто рублей до стипендии?\n— Держи, только вернуть не забудь.', zh: '— 能借我一百卢布吗，发了助学金就还。— 拿着，可别忘了还。', en: '— \'Can you lend me a hundred rubles until the scholarship comes?\' \'Here you go; just do not forget to pay it back.\'', ctx: '同学借钱' },
  { ru: 'Настоящий друг скажет правду в глаза, а не будет обсуждать за спиной.', zh: '真正的朋友会当面讲真话，而不是在背后议论。', en: 'A true friend says the truth to your face instead of talking behind your back.', ctx: '真诚友谊' },
  { ru: '— Ты идёшь на встречу выпускников школы?\n— Вряд ли, все давно разъехались.\n— А я пойду, хочу всех увидеть.', zh: '— 你去参加中学同学聚会吗？— 估计不去，大家早就各奔东西了。— 我倒要去，想见见所有人。', en: '— \'Are you going to the school reunion?\' \'Probably not; everyone moved away long ago.\' \'I will go; I want to see everyone.\'', ctx: '同学聚会' },
  { ru: 'Мы знакомы уже 5 лет, с первого дня университета.', zh: '从大学第一天算起，我们已经认识五年了。', en: 'We have known each other for five years, since the first day of university.', ctx: '多年好友', say: 'Мы знакомы уже пять лет с первого дня университета' },
  { ru: '— Он опять списал у тебя идею?\n— Списал, но в следующий раз я промолчать не стану.', zh: '— 他又抄了你的点子？— 抄了，但下次我不会再忍气吞声。', en: '— \'Did he copy your idea again?\' \'He did, but next time I will not keep quiet.\'', ctx: '被占便宜' },
  { ru: '— Почему ты перестал отвечать на сообщения?\n— Просто захотелось побыть одному, без обид.', zh: '— 你怎么不回消息了？— 就是想一个人待待，你别多心。', en: '— \'Why did you stop replying to messages?\' \'I just felt like being alone; no hard feelings.\'', ctx: '暂时疏远' },
  { ru: '— Давай сделаем совместный проект, у нас хорошо выходит.\n— Согласен, кто будет писать теорию?\n— Ты, а я займусь данными и графиками.', zh: '— 我们一起做项目吧，配合得挺好。— 行，谁来写理论部分？— 你写，我负责数据和图表。', en: '— \'Let us do a joint project; we work well together.\' \'Agreed. Who will write the theory?\' \'You will, and I will handle the data and charts.\'', ctx: '组队合作' },
  { ru: '— Ты выглядишь расстроенной, что-то случилось?\n— Родители разводятся, и мне очень тяжело.', zh: '— 你看起来很难过，出什么事了？— 我父母要离婚，我心里特别难受。', en: '— \'You look upset. Did something happen?\' \'My parents are getting divorced, and it is really hard.\'', ctx: '关心同学' },
  { ru: '— Не обращай на него внимания, он просто завидует.\n— Ты прав, не буду из-за него плакать.', zh: '— 别理他，他就是嫉妒。— 你说得对，我才不为他哭呢。', en: '— \'Pay no attention to him; he is just jealous.\' \'You are right; I will not cry over him.\'', ctx: '安慰受气' },
  { ru: 'Как же здорово, когда есть человек, которому можно всё рассказать!', zh: '有一个什么都能倾诉的人，真是太好了！', en: 'How great it is to have someone you can tell everything to!', ctx: '知己难得' },
  { ru: '— Пойдём после пар в кино, там новый фильм.\n— Не могу, нужно готовиться к коллоквиуму.\n— Ну ты и зануда! Ладно, в другой раз.', zh: '— 下课去看电影吧，有部新片。— 去不了，我得准备课堂讨论。— 你可真没劲！好吧，下次再说。', en: '— \'Let us go to the cinema after classes; there is a new film.\' \'I cannot; I need to prepare for the colloquium.\' \'You are such a bore! Fine, another time.\'', ctx: '邀约被拒' },
  { ru: 'Она всегда всем помогает, поэтому её так любят в группе.', zh: '她总是帮助所有人，所以班里大家都喜欢她。', en: 'She always helps everyone, which is why she is so loved in the group.', ctx: '热心同学' },
  { ru: '— Ты идёшь на день рождения Иванова?\n— Иду, уже купил ему книгу.', zh: '— 你去参加伊万诺夫的生日聚会吗？— 去，我已经给他买了本书。', en: '— \'Are you going to Ivanov\'s birthday?\' \'I am; I have already bought him a book.\'', ctx: '生日聚会' },
  { ru: 'В нашей группе учатся 12 человек, и все очень дружные.', zh: '我们班有十二个人，大家都很要好。', en: 'There are twelve people in our group, and everyone is very close.', ctx: '班级人数', say: 'В нашей группе учатся двенадцать человек и все очень дружные' },
  { ru: '— Ты на меня сердишься?\n— Есть немного, но к вечеру пройдёт.', zh: '— 你生我气了？— 有一点，不过到晚上就好了。', en: '— \'Are you angry with me?\' \'A bit, but it will pass by evening.\'', ctx: '小闹别扭' },
  { ru: 'Научный руководитель похвалил мою гипотезу и попросил проверить её на данных.', zh: '导师表扬了我的假设，并让我用数据加以检验。', en: 'My advisor praised my hypothesis and asked me to test it on data.', ctx: '导师反馈' },
  { ru: '— Ты уже выбрал тему дипломной работы?\n— Выбираю между двумя, обе про поведение потребителей.', zh: '— 你毕业论文题目选定了吗？— 在两个之间犹豫，都是关于消费者行为的。', en: '— \'Have you chosen your thesis topic yet?\' \'I am choosing between two; both are on consumer behavior.\'', ctx: '选定题目' },
  { ru: '— Сколько источников нужно в списке литературы?\n— Профессор сказал, не меньше тридцати, причём свежих.', zh: '— 参考文献要列多少个来源？— 教授说至少三十个，而且要新的。', en: '— \'How many sources do we need in the bibliography?\' \'The professor said at least thirty, and recent ones.\'', ctx: '文献数量' },
  { ru: '— Эксперимент провалился.\n— Не переживай, отрицательный результат — тоже результат.\n— Легко тебе говорить, время-то уходит.', zh: '— 实验失败了。— 别难过，否定的结果也是结果。— 说起来轻巧，时间可不等人。', en: '— \'The experiment failed.\' \'Do not worry; a negative result is still a result.\' \'Easy for you to say; time is slipping away.\'', ctx: '实验失败' },
  { ru: '— Ты пойдёшь на конференцию в апреле?\n— Обязательно, меня даже включили в программу.', zh: '— 你四月去参加学术会议吗？— 一定去，我还被排进日程了。', en: '— \'Will you go to the conference in April?\' \'Definitely; I have even been included in the program.\'', ctx: '学术会议' },
  { ru: '— Помоги, пожалуйста, оформить ссылки по стандарту.\n— Давай, скинь мне список вечером.', zh: '— 帮我按规范排一下参考文献好吗？— 行，晚上把清单发给我。', en: '— \'Help me format the references to the standard, please.\' \'Sure; send me the list tonight.\'', ctx: '引用格式' },
  { ru: 'До защиты диплома осталось 3 недели, а у меня не готова даже глава.', zh: '离毕业论文答辩还有三周，我却连一章都没写完。', en: 'Three weeks remain until the thesis defense, and I do not even have one chapter ready.', ctx: '答辩临近', say: 'До защиты диплома осталось три недели а у меня не готова даже глава' },
  { ru: '— Какой метод ты используешь?\n— Качественный, беру интервью у экспертов.\n— Тогда запиши вопросы и покажи мне.', zh: '— 你用的是什么方法？— 定性研究，对专家进行访谈。— 那你把问题写好给我看看。', en: '— \'What method are you using?\' \'Qualitative; I interview experts.\' \'Then write down the questions and show them to me.\'', ctx: '研究方法' },
  { ru: 'Прочитав сто статей, я наконец понял, где искать разрыв в литературе.', zh: '读了上百篇文章后，我终于明白该到哪里找文献空白。', en: 'After reading a hundred articles, I finally understood where to look for the gap in the literature.', ctx: '文献综述' },
  { ru: '— Твою статью приняли в сборник?\n— Пока нет, прислали рецензию с замечаниями.', zh: '— 你的文章被论文集收录了吗？— 还没有，收到一份带修改意见的评审。', en: '— \'Was your paper accepted for the volume?\' \'Not yet; they sent a review with comments.\'', ctx: '论文投稿' },
  { ru: '— Где ты взял такую статистику?\n— Из базы данных министерства, там открытый доступ.', zh: '— 你从哪儿弄来的这些统计数据？— 来自部委的数据库，是公开的。', en: '— \'Where did you get those statistics?\' \'From the ministry database; it is open access.\'', ctx: '数据来源' },
  { ru: '— Руководитель опять вернул работу с правками.\n— Что на этот раз?\n— Говорит, выводы слишком слабые.', zh: '— 导师又把稿子打回修改了。— 这次又是什么问题？— 他说结论太薄弱。', en: '— \'My advisor sent the paper back with edits again.\' \'What is it this time?\' \'He says the conclusions are too weak.\'', ctx: '修改论文' },
  { ru: '— Защита пройдёт в форме доклада на пятнадцать минут?\n— Да, потом ещё десять минут на вопросы комиссии.', zh: '— 答辩是做十五分钟报告的形式吗？— 对，之后还有十分钟回答委员会提问。', en: '— \'Will the defense be a fifteen-minute presentation?\' \'Yes, then ten more minutes for the committee questions.\'', ctx: '答辩流程' },
  { ru: '— Ты уже подал заявку на грант?\n— Подал, но конкуренция огромная, вряд ли дадут.', zh: '— 你提交基金申请了吗？— 交了，但竞争太激烈，估计没戏。', en: '— \'Have you applied for the grant yet?\' \'I have, but the competition is huge; they probably will not give it.\'', ctx: '申请经费' },
  { ru: 'К утру я так и не закончил введение, но зато перечитал все заметки.', zh: '到早上导论还是没写完，不过笔记倒重新看了一遍。', en: 'By morning I still had not finished the introduction, but I had at least reread all my notes.', ctx: '通宵写论文' },
  { ru: '— Можно цитировать этого автора?\n— Можно, но осторожно: его много критикуют.\n— Тогда подберу кого-нибудь поавторитетнее.', zh: '— 可以引用这位作者吗？— 可以，但要小心：他争议很大。— 那我换个更权威的人。', en: '— \'Can I cite this author?\' \'You can, but carefully; he is widely criticized.\' \'Then I will pick someone more authoritative.\'', ctx: '引用争议' },
  { ru: 'В анкетировании приняли участие 250 человек из трёх городов.', zh: '来自三个城市的二百五十人参加了问卷调查。', en: '250 people from three cities took part in the questionnaire survey.', ctx: '样本规模', say: 'В анкетировании приняли участие двести пятьдесят человек из трёх городов' },
  { ru: '— Ты будешь поступать в аспирантуру?\n— Буду, если получу красный диплом.', zh: '— 你要考研究生吗？— 如果能拿到优秀毕业生文凭就考。', en: '— \'Are you going to apply for a PhD program?\' \'I will if I get a diploma with distinction.\'', ctx: '继续深造' },
  { ru: 'Если бы данные сходились, статью можно было бы отправить уже сейчас.', zh: '数据要是能对上，文章现在就可以投出去。', en: 'If only the data matched; the paper could be sent off right now.', ctx: '数据矛盾' },
  { ru: '— Поздравляю, комиссия поставила отлично!\n— Спасибо, я до последнего не верил в себя.', zh: '— 恭喜，委员会给了优秀！— 谢谢，我直到最后都不相信自己。', en: '— \'Congratulations; the committee gave you an excellent!\' \'Thanks; I did not believe in myself until the very end.\'', ctx: '答辩通过' },
  { ru: 'К профессору Петрову лучше обращаться по имени-отчеству.', zh: '称呼彼得罗夫教授最好用名字加父称。', en: 'It is best to address Professor Petrov by his first name and patronymic.', ctx: '称呼礼仪' },
  { ru: '— Иван Петрович, можно вас на пару слов после лекции?\n— Да, пройдёмте в мой кабинет.', zh: '— 伊万·彼得罗维奇，课后能和您说两句吗？— 好，我们到我办公室去。', en: '— \'Ivan Petrovich, may I have a word after the lecture?\' \'Yes; let us go to my office.\'', ctx: '课后约谈' },
  { ru: '— Разрешите сдать работу на два дня позже?\n— Хорошо, но это в последний раз.', zh: '— 请允许我晚两天交作业好吗？— 好吧，但这是最后一次。', en: '— \'May I hand the work in two days late?\' \'All right, but this is the last time.\'', ctx: '请求延期' },
  { ru: '— Здравствуйте, я ваша новая студентка по обмену.\n— Очень приятно, расскажите о себе.\n— Я приехала из Китая, изучаю литературу.', zh: '— 您好，我是新来的交换生。— 很高兴认识你，介绍一下自己吧。— 我来自中国，学文学的。', en: '— \'Hello; I am your new exchange student.\' \'Very nice to meet you. Tell me about yourself.\' \'I come from China and study literature.\'', ctx: '初次见师' },
  { ru: '— Профессор, вы получили моё письмо с эссе?\n— Давай проверю... да, вижу, всё открылось.', zh: '— 教授，您收到我带小论文的邮件了吗？— 我看一下……收到了，能打开。', en: '— \'Professor, did you receive my email with the essay?\' \'Let me check... yes, I see it; everything opened.\'', ctx: '确认邮件' },
  { ru: '— Можно узнать ваше мнение о моём докладе?\n— Идея сильная, но структура хромает.', zh: '— 能听听您对我报告的意见吗？— 想法很好，但结构有问题。', en: '— \'May I hear your opinion on my presentation?\' \'The idea is strong, but the structure is weak.\'', ctx: '征求意见' },
  { ru: 'Приёмные часы у декана — с 14:00 до 16:00.', zh: '系主任的接待时间是十四点到十六点。', en: 'The dean\'s office hours are from 2 p.m. to 4 p.m.', ctx: '接待时间', say: 'Приёмные часы у декана с четырнадцати часов до шестнадцати часов' },
  { ru: '— Извините, я не смогла прийти на зачёт по болезни.\n— Принесите справку из поликлиники, тогда решим.\n— Я уже взяла её, вот она.', zh: '— 对不起，我因为生病没能参加查核。— 把诊所的证明带来，我们再安排。— 我已经开好了，给您。', en: '— \'Sorry; I could not come to the pass-fail exam due to illness.\' \'Bring a certificate from the clinic and we will arrange it.\' \'I have already got one; here it is.\'', ctx: '病假申请' },
  { ru: 'Если не успеваешь, честно скажи преподавателю заранее.', zh: '要是赶不及，就提前如实告诉老师。', en: 'If you cannot make it in time, honestly tell the teacher beforehand.', ctx: '坦诚沟通' },
  { ru: '— А можно пересдать, чтобы улучшить оценку?\n— Официально нет, но для стипендии это и не требуется.', zh: '— 为了提高成绩可以重考吗？— 按规定不行，但助学金也不需要这个。', en: '— \'Can I retake it to improve the grade?\' \'Officially no, but it is not required for the scholarship anyway.\'', ctx: '刷分请求' },
  { ru: '— Кстати, профессор рекомендовал мне хорошую монографию.\n— Вот видишь, не зря ты к нему подошёл.', zh: '— 对了，教授给我推荐了一本很好的专著。— 你看，去找他没白去吧。', en: '— \'By the way, the professor recommended a good monograph to me.\' \'There, you see; it was not for nothing that you went to see him.\'', ctx: '老师荐书' },
  { ru: '— Почему вы не были на моей консультации?\n— Простите, я перепутал аудиторию и время.\n— Такое бывает, но больше не повторяйте.', zh: '— 您怎么没来参加我的答疑？— 抱歉，我把教室和时间都搞错了。— 这种事难免，但下不为例。', en: '— \'Why weren\'t you at my consultation?\' \'Sorry; I mixed up the room and the time.\' \'These things happen, but don\'t let it happen again.\'', ctx: '错过答疑' },
  { ru: '— Могу я получить обратную связь по эссе?\n— Конечно, давайте обсудим после семинара.', zh: '— 我能得到关于小论文的反馈吗？— 当然，研讨课结束后我们来谈谈。', en: '— \'May I get feedback on the essay?\' \'Of course; let us discuss it after the seminar.\'', ctx: '作业反馈' },
  { ru: '— Учитель, а это будет на экзамене?\n— Будет, обязательно повторите эту тему.', zh: '— 老师，这个会考吗？— 会考，这个专题一定要复习。', en: '— \'Teacher, will this be on the exam?\' \'It will; make sure you review this topic.\'', ctx: '询问重点' },
  { ru: 'Профессор ответил на моё письмо только через 4 дня.', zh: '教授过了四天才回我的邮件。', en: 'The professor replied to my email only four days later.', ctx: '等待回信', say: 'Профессор ответил на моё письмо только через четыре дня' },
  { ru: '— Вы не против, если я сменю тему исследования?\n— А что именно вас не устраивает?\n— Не хватает источников на русском языке.', zh: '— 您不介意我更换研究课题吧？— 您具体对哪里不满意呢？— 俄语的资料不够。', en: '— \'You do not mind if I change my research topic?\' \'What exactly does not suit you?\' \'There are not enough sources in Russian.\'', ctx: '更换课题' },
  { ru: 'Преподаватель всегда подчёркивал, что думать важнее, чем запоминать.', zh: '老师总是强调，思考比记忆更重要。', en: 'The teacher always emphasized that thinking matters more than memorizing.', ctx: '师者教诲' },
  { ru: '— Разрешите присутствовать на вашей лекции вольнослушателем?\n— Приходите, место в аудитории найдётся.', zh: '— 请允许我作为旁听生来听您的讲座好吗？— 来吧，教室里会有位置的。', en: '— \'May I attend your lecture as an auditor?\' \'Do come; there will be a seat in the room.\'', ctx: '旁听课程' },
  { ru: 'Как я рад, что выбрал именно этого научного руководителя!', zh: '我真高兴当初选了这位导师！', en: 'How glad I am that I chose this particular advisor!', ctx: '庆幸选师' },
  { ru: '— Спасибо вам за терпение и советы.\n— Не за что, вы сами отлично поработали.', zh: '— 谢谢您的耐心和指导。— 不客气，是你自己努力。', en: '— \'Thank you for your patience and advice.\' \'You are welcome; you did great work yourself.\'', ctx: '感谢老师' },
  { ru: 'Мою учебную визу нужно продлить до конца семестра.', zh: '我的学习签证要在学期结束前办理延期。', en: 'My student visa needs to be extended before the end of the semester.', ctx: '签证续签' },
  { ru: '— Какие документы нужны для регистрации?\n— Паспорт, виза и миграционная карта, сделайте копии.', zh: '— 办理登记需要哪些文件？— 护照、签证和移民卡，请各备复印件。', en: '— \'What documents are needed for registration?\' \'Passport, visa and migration card; make copies.\'', ctx: '落地登记' },
  { ru: '— Ты уже встал на миграционный учёт?\n— Нет ещё, записался на среду в многофункциональный центр.', zh: '— 你办移民登记了吗？— 还没，我预约了周三去多功能中心。', en: '— \'Have you registered with the migration authorities yet?\' \'Not yet; I booked Wednesday at the multifunctional center.\'', ctx: '移民登记' },
  { ru: '— Помогите, пожалуйста, выбрать дисциплины на семестр.\n— Какое у вас направление?\n— Экономика, хочется добавить язык.\n— Тогда возьмите этот курс, он для всех.', zh: '— 请帮我选一下这学期的课程。— 您学的是什么方向？— 经济，还想加一门语言。— 那就选这门课，面向所有人。', en: '— \'Please help me choose courses for the semester.\' \'What is your major?\' \'Economics, and I would like to add a language.\' \'Then take this course; it is open to everyone.\'', ctx: '选课指导' },
  { ru: '— Где получают студенческий билет?\n— В деканате, после зачисления, обычно за пару дней.', zh: '— 学生证在哪里领？— 录取后在系办公室领，一般两天就能拿到。', en: '— \'Where do I get my student ID?\' \'At the dean\'s office after enrollment; usually within a couple of days.\'', ctx: '领取学生证' },
  { ru: '— Сколько стоит пошлина за продление визы?\n— Не помню точно, посмотри на официальном сайте.', zh: '— 签证延期的手续费是多少？— 我记不准，去官网上查一查。', en: '— \'How much is the fee for a visa extension?\' \'I do not remember exactly; check the official website.\'', ctx: '签证费用' },
  { ru: 'Регистрацию оформляют в течение 7 рабочих дней.', zh: '登记手续在七个工作日内办好。', en: 'Registration is processed within seven business days.', ctx: '办理时限', say: 'Регистрацию оформляют в течение семи рабочих дней' },
  { ru: '— Меня не записали на нужный курс.\n— Вы подписывали учебный план?\n— Да, но там не было этой строчки.\n— Подойдите в деканат с договором.', zh: '— 我没被选上需要的那门课。— 您在教学计划上签字了吗？— 签了，但上面没有这一行。— 带着合同去系办公室问问。', en: '— \'I was not enrolled in the course I need.\' \'Did you sign the study plan?\' \'I did, but this line was not there.\' \'Go to the dean\'s office with your contract.\'', ctx: '选课出错' },
  { ru: 'По приезде в страну нужно в течение недели оформить регистрацию.', zh: '抵达该国后，要在一周内办好登记。', en: 'Upon arrival in the country, you must complete registration within a week.', ctx: '抵达须知' },
  { ru: '— Ты взял справку о зачислении для общежития?\n— Взял, её выдали вместе с договором.', zh: '— 你为宿舍的事拿到入学证明了吗？— 拿到了，是和合同一起给的。', en: '— \'Did you get the enrollment certificate for the dorm?\' \'I did; it was issued together with the contract.\'', ctx: '入学证明' },
  { ru: '— Можно поменять группу языка после начала занятий?\n— Можно, если уровень не совпадает, напишите заявление.', zh: '— 开课后还能换语言班吗？— 如果水平不符可以，写一份申请。', en: '— \'Can I change language groups after classes start?\' \'You can if the level does not match; write an application.\'', ctx: '调班申请' },
  { ru: '— Когда крайний срок оплаты обучения?\n— До первого сентября, иначе отчислят.\n— Тогда переведу деньги завтра.', zh: '— 学费缴纳的截止时间是什么时候？— 九月一日之前，否则会被退学。— 那我明天就转账。', en: '— \'When is the deadline for tuition payment?\' \'Before September first, or they will expel you.\' \'Then I will transfer the money tomorrow.\'', ctx: '学费缴纳' },
  { ru: '— У меня через месяц заканчивается виза.\n— Срочно собирай пакет документов, это не быстро.', zh: '— 我的签证一个月后就到期了。— 赶紧准备材料，这事儿快不了。', en: '— \'My visa expires in a month.\' \'Urgently gather the document package; it will not be quick.\'', ctx: '签证将到期' },
  { ru: '— Где заверить перевод паспорта?\n— В нотариальной конторе рядом с университетом.', zh: '— 护照翻译件在哪里公证？— 大学旁边的公证处。', en: '— \'Where can I get a passport translation notarized?\' \'At the notary office next to the university.\'', ctx: '翻译公证' },
  { ru: 'За семестр обучения нужно заплатить 85000 рублей.', zh: '一个学期的学费要交八万五千卢布。', en: 'Tuition for one semester costs 85,000 rubles.', ctx: '学费金额', say: 'За семестр обучения нужно заплатить восемьдесят пять тысяч рублей' },
  { ru: '— Я потерял миграционную карту.\n— Это серьёзно, сразу заявите в полицию.\n— А восстановить её долго?', zh: '— 我把移民卡弄丢了。— 这很严重，马上去警局报案。— 补办要很久吗？', en: '— \'I lost my migration card.\' \'That is serious; report it to the police immediately.\' \'Will it take long to restore it?\'', ctx: '文件遗失' },
  { ru: 'Если регистрация просрочена, при выезде могут оштрафовать.', zh: '登记要是逾期，出境时可能被罚款。', en: 'If your registration is overdue, you may be fined when leaving the country.', ctx: '逾期风险' },
  { ru: '— Расписание уже выложили на сайт?\n— Да, смотри в личном кабинете, там же запись на курсы.', zh: '— 课表已经发到网站上了吗？— 发了，在个人主页里看，选课也在那儿。', en: '— \'Has the schedule been posted online yet?\' \'Yes; check your personal account; course enrollment is there too.\'', ctx: '查看课表' },
  { ru: 'Без медицинской страховки иностранца не прикрепят к поликлинике.', zh: '没有医疗保险，外国学生无法登记到社区诊所。', en: 'Without medical insurance, a foreign student will not be assigned to a clinic.', ctx: '医疗保险' },
  { ru: '— Ты отметился у куратора иностранных студентов?\n— Отметился, он выдал памятку на первое время.', zh: '— 你去外国学生辅导员那里报到了吗？— 报到了，他给了一份初到指南。', en: '— \'Have you checked in with the international students coordinator?\' \'I have; he gave me a handbook for the first weeks.\'', ctx: '专员报到' },
  { ru: 'Новый спортивный комплекс открыли рядом с главным корпусом.', zh: '主楼旁边新开了一座体育中心。', en: 'A new sports complex has opened next to the main building.', ctx: '体育场馆' },
  { ru: '— Ты записался в какой-нибудь студенческий клуб?\n— Да, в театральный, по средам репетиции.', zh: '— 你报名参加什么学生社团了吗？— 报了戏剧社，周三排练。', en: '— \'Have you joined any student club?\' \'Yes, the drama club; rehearsals are on Wednesdays.\'', ctx: '社团招新' },
  { ru: '— Где находится бассейн?\n— За общежитием номер три, увидишь синее здание.', zh: '— 游泳池在哪里？— 三号宿舍楼后面，你会看到一座蓝色建筑。', en: '— \'Where is the swimming pool?\' \'Behind dorm number three; you will see a blue building.\'', ctx: '寻找泳池' },
  { ru: '— Пойдёшь на студенческую вечеринку в пятницу?\n— А где она будет?\n— В актовом зале, вход по студенческому.\n— Тогда я с вами.', zh: '— 周五的学生派对你去吗？— 在哪儿办？— 大礼堂，凭学生证入场。— 那我也跟你们去。', en: '— \'Are you going to the student party on Friday?\' \'Where will it be?\' \'In the assembly hall; entry with a student ID.\' \'Then I am in.\'', ctx: '校园派对' },
  { ru: '— Столовая ещё работает?\n— До четырёх, потом только буфет в первом корпусе.', zh: '— 食堂还开着吗？— 开到四点，之后只能去一号楼的小卖部。', en: '— \'Is the canteen still open?\' \'Until four; after that only the snack bar in building one.\'', ctx: '食堂时间' },
  { ru: '— Здесь можно пообедать за двести рублей?\n— Запросто, комплексный обед стоит как раз столько.', zh: '— 这儿二百卢布能吃到午饭吗？— 完全可以，套餐正好这个价。', en: '— \'Can I have lunch here for two hundred rubles?\' \'Easily; the set lunch costs exactly that.\'', ctx: '食堂物价' },
  { ru: 'Спортзал работает с 7:00 до 23:00 без выходных.', zh: '体育馆七点到二十三点开放，没有休息日。', en: 'The gym is open from 7:00 a.m. to 11:00 p.m., seven days a week.', ctx: '场馆时间', say: 'Спортзал работает с семи часов до двадцати трёх часов без выходных' },
  { ru: '— Запиши меня на волейбол по воскресеньям.\n— Только нужна справка от врача.\n— Хорошо, завтра схожу в медпункт.', zh: '— 帮我报名周日的排球吧。— 不过需要医生证明。— 好，我明天去医务室。', en: '— \'Sign me up for Sunday volleyball.\' \'You will just need a doctor\'s note.\' \'OK; I will go to the health center tomorrow.\'', ctx: '报名运动' },
  { ru: 'В парке перед университетом студенты любят отдыхать между парами.', zh: '学生们喜欢在两节课之间到大学前面的公园休息。', en: 'Students like to relax in the park in front of the university between classes.', ctx: '校园公园' },
  { ru: '— Есть ли в корпусе бесплатная питьевая вода?\n— Да, кулер стоит у лестницы на втором этаже.', zh: '— 楼里有免费饮用水吗？— 有，二楼楼梯旁有饮水机。', en: '— \'Is there free drinking water in the building?\' \'Yes; there is a cooler by the stairs on the second floor.\'', ctx: '饮水设施' },
  { ru: '— Ты идёшь на день открытых дверей?\n— Нет, я ведь уже учусь здесь, а вот брата возьму.', zh: '— 你去校园开放日吗？— 不去，我都已经在这儿上学了，不过会带我弟弟去。', en: '— \'Are you going to the open day?\' \'No; I already study here, but I will take my brother.\'', ctx: '校园开放日' },
  { ru: '— В субботу будет фестиваль культур.\n— Кто выступает?\n— Студенты из разных стран, и мы тоже.\n— Здорово, приду поддержать.', zh: '— 周六有文化节。— 都有谁演出？— 各国学生，我们也上。— 太好了，我一定去捧场。', en: '— \'There is a cultural festival on Saturday.\' \'Who is performing?\' \'Students from different countries, and us too.\' \'Great; I will come and support you.\'', ctx: '国际文化节' },
  { ru: '— Где можно распечатать документы?\n— В компьютерном классе на первом этаже, оплата через приложение.', zh: '— 哪里可以打印文件？— 一楼的机房，通过应用付款。', en: '— \'Where can I print documents?\' \'In the computer room on the first floor; pay through the app.\'', ctx: '打印教室' },
  { ru: '— Возьми студенческий, в музеях по нему скидки.\n— Точно, я вечно про это забываю.', zh: '— 带上学生证，博物馆凭票有优惠。— 对，我老忘这事儿。', en: '— \'Take your student ID; museums give discounts with it.\' \'Right; I always forget about that.\'', ctx: '学生证优惠' },
  { ru: 'Как красиво осенью в старом дворике университета!', zh: '秋天，古老的大学庭院多美啊！', en: 'How beautiful the old university courtyard is in autumn!', ctx: '秋日校园' },
  { ru: '— Давай вступим в клуб волонтёров.\n— А чем они занимаются?\n— Помогают детям и ездят в приюты по выходным.\n— Я в деле.', zh: '— 我们加入志愿者社团吧。— 他们都做什么？— 帮助儿童，周末去收容所。— 算我一个。', en: '— \'Let us join the volunteer club.\' \'What do they do?\' \'They help kids and visit shelters on weekends.\' \'I am in.\'', ctx: '志愿活动' },
  { ru: 'До стадиона от главного корпуса идти 10 минут.', zh: '从主楼走到体育场要十分钟。', en: 'It is a ten-minute walk from the main building to the stadium.', ctx: '场馆距离', say: 'До стадиона от главного корпуса идти десять минут' },
  { ru: '— В кампусе есть где оставить велосипед?\n— Да, две велопарковки за библиотекой, под навесом.', zh: '— 校园里有地方停自行车吗？— 有，图书馆后面有两个自行车棚，带顶棚。', en: '— \'Is there anywhere to leave a bike on campus?\' \'Yes; two bike racks behind the library, under a shelter.\'', ctx: '自行车位' },
  { ru: 'Если будет свободное время, запишись в хор, там отличный дирижёр.', zh: '有空的话就报名合唱团吧，指挥很棒。', en: 'If you have free time, join the choir; the conductor there is excellent.', ctx: '推荐社团' },
  { ru: '— Тебе нравится студенческая жизнь в кампусе?\n— Очень, столько событий, что скучать некогда.', zh: '— 你喜欢校园里的学生生活吗？— 很喜欢，活动多到没空无聊。', en: '— \'Do you like student life on campus?\' \'Very much; there are so many events there is no time to be bored.\'', ctx: '校园感受' },
]

// ── 餐饮美食 / Food & dining / Еда ──
const FOOD: Phrase[] = [
  { ru: '— С чего начнём?\n— Давай сначала салат, а горячее выберем потом.', zh: '——我们先点什么？\n——先来沙拉吧，主菜待会儿再选。', en: '— What shall we start with?\n— Let\'s have salad first and pick a main course later.', ctx: '决定前菜' },
  { ru: '— Вы уже готовы сделать заказ?\n— Ещё минутку, пожалуйста, меню такое большое.', zh: '——您准备好点餐了吗？\n——请再等一会儿，菜单内容太多了。', en: '— Are you ready to order?\n— Just a minute, please, the menu is so long.', ctx: '准备点餐' },
  { ru: 'Принесите, пожалуйста, два борща и одну порцию вареников.', zh: '请给我们来两份罗宋汤和一份乌克兰甜馅饺子。', en: 'Two borschts and one portion of varenyky, please.', ctx: '点汤和饺子' },
  { ru: '— Что порекомендуете из фирменных блюд?\n— Возьмите бефстроганов, его только что принесли с кухни.\n— Тогда его и попробуем.', zh: '——招牌菜有什么推荐？\n——来份奶油牛肉丝吧，刚从厨房出锅。\n——那就尝尝它。', en: '— What do you recommend among the signature dishes?\n— Try the beef stroganoff, it just came from the kitchen.\n— Then we\'ll have that.', ctx: '求荐招牌' },
  { ru: 'Не подскажете, есть ли у вас сегодня суп дня?', zh: '请问你们今天有例汤吗？', en: 'Could you tell me whether you have a soup of the day today?', ctx: '询问例汤' },
  { ru: '— Мне уху, а жене — солянку.\n— Отличный выбор, записываю.', zh: '——我要鱼汤，我妻子要杂拌汤。\n——选得好，我记下了。', en: '— Fish soup for me, and solyanka for my wife.\n— Great choice, I\'ll write it down.', ctx: '各点各汤' },
  { ru: '— Это блюдо острое?\n— Не очень, но могу попросить повара не добавлять перец.', zh: '——这道菜辣吗？\n——不太辣，不过我可以让厨师别放辣椒。', en: '— Is this dish spicy?\n— Not really, but I can ask the chef to skip the pepper.', ctx: '询问辣度' },
  { ru: 'Какой аппетитный запах у этих котлет!', zh: '这些肉饼闻起来太有食欲了！', en: 'What an appetizing smell these cutlets have!', ctx: '夸赞香味' },
  { ru: 'Я бы заказал рыбу, если бы её приготовили на пару.', zh: '如果鱼能清蒸的话，我就点鱼。', en: 'I would order the fish if they steamed it.', ctx: '条件点鱼' },
  { ru: '— На первое у нас сегодня борщ и рассольник.\n— Давайте борщ, только без сметаны.', zh: '——今天第一道汤有罗宋汤和酸黄瓜汤。\n——来罗宋汤吧，别加酸奶油。', en: '— For the first course we have borscht and rassolnik today.\n— Borscht, please, but without sour cream.', ctx: '点头道菜' },
  { ru: 'Можно нам меню, мы только что сели за стол.', zh: '能给我们菜单吗？我们刚坐下。', en: 'Could we have menus? We\'ve just sat down.', ctx: '索要菜单' },
  { ru: '— Будете что-нибудь из закусок?\n— Пожалуй, да. А что это за солёные грибы?\n— Собственного посола, их очень хвалят.\n— Отлично, тогда тарелку грибов.', zh: '——要点开胃菜吗？\n——来点吧。这些腌蘑菇是什么？\n——自家腌的，评价很好。\n——好，那就来一盘蘑菇。', en: '— Will you have any starters?\n— I think so. What are these salted mushrooms?\n— House-brined, they get great reviews.\n— Great, then a plate of mushrooms.', ctx: '问腌蘑菇' },
  { ru: '— Не могли бы вы передать соль?\n— Конечно, вот, держите.', zh: '——能把盐递给我吗？\n——当然，给您。', en: '— Could you pass the salt?\n— Of course, here you go.', ctx: '请求递盐' },
  { ru: '— Я возьму шашлык из баранины.\n— А я, наверное, цыплёнка табака.', zh: '——我要羊肉串。\n——那我大概要格鲁吉亚铁板鸡。', en: '— I\'ll have the lamb shashlik.\n— And I\'ll probably have the tabaka chicken.', ctx: '各点烤肉' },
  { ru: '— Сколько ждать жаркое в горшочке?\n— Минут двадцать пять.\n— Хорошо, тогда подождём.', zh: '——瓦罐炖肉要等多久？\n——大约二十五分钟。\n——好，那我们就等。', en: '— How long is the pot roast?\n— About twenty-five minutes.\n— Fine, then we\'ll wait.', ctx: '询问时长' },
  { ru: '— Ты больше любишь солёное или сладкое?\n— Солёное, сладкое я почти не ем.', zh: '——你更喜欢咸的还是甜的？\n——咸的，甜的我几乎不吃。', en: '— Do you prefer savory or sweet?\n— Savory, I hardly eat sweets.', ctx: '咸甜偏好' },
  { ru: '— Вам чай с сахаром?\n— Нет, лучше с лимоном и без сахара.', zh: '——您的茶要加糖吗？\n——不用，最好加柠檬，不放糖。', en: '— Tea with sugar?\n— No, with lemon and no sugar, please.', ctx: '点柠檬茶' },
  { ru: 'Я бы съел что-нибудь кислое, например квашеную капусту.', zh: '我想吃点酸的，比如酸白菜。', en: 'I\'d eat something sour, like sauerkraut.', ctx: '想吃酸的' },
  { ru: '— Для меня это слишком жирно.\n— Тогда возьмите куриную грудку с овощами.', zh: '——这对我来说太油腻了。\n——那就要蔬菜配鸡胸肉吧。', en: '— This is too greasy for me.\n— Then have the chicken breast with vegetables.', ctx: '嫌太油腻' },
  { ru: 'Не люблю, когда в еде много чеснока.', zh: '我不喜欢饭菜里蒜太多。', en: 'I don\'t like it when food has lots of garlic.', ctx: '不爱蒜味' },
  { ru: '— Острое любите?\n— Обожаю, чем острее, тем лучше!', zh: '——您爱吃辣吗？\n——超爱，越辣越好！', en: '— Do you like spicy food?\n— I love it, the spicier the better!', ctx: '能否吃辣' },
  { ru: '— Почему вы не едите сыр?\n— Мне не нравится его вкус.\n— А брынзу пробовали? Она нежнее.', zh: '——您为什么不吃奶酪？\n——我不喜欢它的味道。\n——那您尝过羊奶酪吗？口感更柔和。', en: '— Why don\'t you eat cheese?\n— I don\'t like the taste.\n— Have you tried bryndza? It\'s milder.', ctx: '不爱奶酪' },
  { ru: 'Борщ должен быть наваристым, со сметаной и чесноком.', zh: '罗宋汤就得浓郁，配上酸奶油和大蒜。', en: 'Borscht should be hearty, with sour cream and garlic.', ctx: '好汤标准' },
  { ru: '— Картошку вам пожарить или сделать пюре?\n— Лучше пюре, оно мягче.', zh: '——土豆给您煎还是做土豆泥？\n——土豆泥吧，更软。', en: '— Shall I fry the potatoes or mash them?\n— Mash, please, it\'s softer.', ctx: '土豆做法' },
  { ru: 'Положите поменьше масла, я его не очень люблю.', zh: '油少放一点，我不太喜欢油。', en: 'Use less butter, I\'m not very fond of it.', ctx: '要求少油' },
  { ru: '— Какой кофе вы предпочитаете?\n— Крепкий, но без сахара.', zh: '——您喜欢什么样的咖啡？\n——浓一点，但不加糖。', en: '— How do you like your coffee?\n— Strong, but without sugar.', ctx: '咖啡口味' },
  { ru: '— Если бы не диета, я бы заказал торт.\n— А что вам нельзя?\n— Мучное и жирное, к сожалению.', zh: '——要不是节食，我就点蛋糕了。\n——您不能吃什么？\n——可惜面食和油腻的都不行。', en: '— If it weren\'t for my diet, I\'d order cake.\n— What can\'t you have?\n— Floury and fatty foods, unfortunately.', ctx: '节食忌口' },
  { ru: '— Этот суп пересолен, вам не кажется?\n— Да нет, по-моему, в самый раз.', zh: '——这汤太咸了，你不觉得吗？\n——没有啊，我觉得正合适。', en: '— This soup is too salty, don\'t you think?\n— Not at all, it\'s just right to me.', ctx: '汤的咸淡' },
  { ru: 'До чего же вкусная эта малосольная рыба!', zh: '这淡腌鱼太好吃了！', en: 'How delicious this lightly salted fish is!', ctx: '夸赞腌鱼' },
  { ru: '— Молоко в кашу добавить?\n— Да, совсем чуть-чуть.\n— А сахару?\n— Нет-нет, без сахара.', zh: '——粥里加牛奶吗？\n——加，一点点就好。\n——糖呢？\n——不用不用，别放糖。', en: '— Shall I add milk to the porridge?\n— Yes, just a little.\n— And sugar?\n— No, no, without sugar.', ctx: '粥加配料' },
  { ru: 'Дайте, пожалуйста, бутылку минеральной воды без газа.', zh: '请给我一瓶无气矿泉水。', en: 'A bottle of still mineral water, please.', ctx: '点矿泉水' },
  { ru: '— Что будете пить?\n— Мне яблочный сок и стакан чистой воды.', zh: '——您想喝点什么？\n——我要苹果汁和一杯白水。', en: '— What would you like to drink?\n— Apple juice and a glass of plain water.', ctx: '点杯饮品' },
  { ru: 'Один капучино и один чай с ромашкой, пожалуйста.', zh: '请来一杯卡布奇诺和一杯洋甘菊茶。', en: 'One cappuccino and one chamomile tea, please.', ctx: '点咖啡茶' },
  { ru: '— Кофе сделать навынос?\n— Да, мне с собой, в стаканчике.', zh: '——咖啡要外带吗？\n——对，带走，用纸杯。', en: '— Shall I make the coffee to go?\n— Yes, to go, in a paper cup.', ctx: '咖啡外带' },
  { ru: 'Принесите кувшин морса, нас будет четверо.', zh: '请上一罐浆果汁，我们四个人。', en: 'Bring a jug of mors, there are four of us.', ctx: '点浆果汁' },
  { ru: '— Вам чай чёрный или зелёный?\n— Зелёный, если можно.\n— С сахаром или с мёдом?\n— С мёдом, ложечки достаточно.', zh: '——茶要红茶还是绿茶？\n——可以的话要绿茶。\n——加糖还是蜂蜜？\n——加蜂蜜，一小勺就够。', en: '— Black or green tea?\n— Green, if possible.\n— With sugar or honey?\n— Honey, one spoonful is enough.', ctx: '挑选茶饮' },
  { ru: '— Есть ли у вас домашний компот?\n— Конечно, из свежих яблок и смородины.', zh: '——你们有家常糖水水果吗？\n——当然有，用新鲜苹果和醋栗做的。', en: '— Do you have homemade kompot?\n— Of course, made with fresh apples and currants.', ctx: '问糖水水果' },
  { ru: 'Сейчас бы холодного кваса, да с окрошкой!', zh: '这会儿要是有冰格瓦斯配俄式冷汤就好了！', en: 'I could go for some cold kvass right now, with okroshka!', ctx: '想喝格瓦斯' },
  { ru: '— Лёд добавить в лимонад?\n— Нет, спасибо, я не пью очень холодное.', zh: '——柠檬水里加冰吗？\n——不用，谢谢，我不喝太冰的。', en: '— Shall I add ice to the lemonade?\n— No, thanks, I don\'t drink very cold things.', ctx: '要不要加冰' },
  { ru: '— Какое вино посоветуете к рыбе?\n— Белое сухое, оно отлично подходит.\n— Тогда бутылку белого, пожалуйста.', zh: '——配鱼推荐什么酒？\n——干白葡萄酒，非常合适。\n——那就来一瓶白葡萄酒。', en: '— What wine would you recommend with fish?\n— A dry white, it goes perfectly.\n— Then a bottle of white, please.', ctx: '点佐餐酒' },
  { ru: 'Два молочных коктейля: один клубничный, один шоколадный.', zh: '两杯奶昔：一杯草莓的，一杯巧克力的。', en: 'Two milkshakes: one strawberry and one chocolate.', ctx: '点两杯奶昔' },
  { ru: '— Кипяток в чайнике свежий?\n— Да, только что вскипел.', zh: '——壶里的开水是新烧的吗？\n——是的，刚烧开。', en: '— Is the boiling water in the pot fresh?\n— Yes, it just boiled.', ctx: '询问开水' },
  { ru: '— А из безалкогольного что у вас есть?\n— Морс, лимонад и три вида сока.', zh: '——无酒精的饮料有什么？\n——浆果汁、柠檬水和三种果汁。', en: '— What do you have non-alcoholic?\n— Mors, lemonade and three kinds of juice.', ctx: '问无酒精饮' },
  { ru: '— Повторить вам кофе?\n— Не откажусь, он у вас замечательный.', zh: '——给您再来杯咖啡吗？\n——好啊，你们的咖啡很棒。', en: '— Shall I bring another coffee?\n— I wouldn\'t say no, yours is wonderful.', ctx: '再续咖啡' },
  { ru: '— Ну как чай?\n— Крепковат, но аромат потрясающий!\n— Добавить молока?\n— Пожалуй, капельку.', zh: '——茶怎么样？\n——有点浓，但香气太赞了！\n——加点牛奶吗？\n——那就来一点点。', en: '— How\'s the tea?\n— A bit strong, but the aroma is amazing!\n— Add some milk?\n— Maybe just a drop.', ctx: '评价茶味' },
  { ru: 'Можно счёт, пожалуйста? Мы уже торопимся.', zh: '请结账，好吗？我们赶时间。', en: 'Could we have the bill, please? We\'re in a hurry.', ctx: '索要账单' },
  { ru: '— Оплатить можно картой?\n— Да, терминал сейчас принесу.', zh: '——可以刷卡吗？\n——可以，我马上拿POS机来。', en: '— Can I pay by card?\n— Yes, I\'ll bring the terminal.', ctx: '刷卡支付' },
  { ru: '— Сдачи не надо.\n— Спасибо большое, приходите ещё!', zh: '——不用找零了。\n——非常感谢，欢迎再来！', en: '— Keep the change.\n— Thank you so much, come again!', ctx: '不收找零' },
  { ru: '— У вас есть скидочная карта?\n— Да, где-то была... вот она.\n— Отлично, провёл, скидка десять процентов.', zh: '——您有折扣卡吗？\n——有，好像在包里……找到了。\n——好，刷好了，打九折。', en: '— Do you have a discount card?\n— Yes, it was somewhere... here it is.\n— Great, it went through, ten percent off.', ctx: '会员折扣' },
  { ru: '— Заверните остатки с собой.\n— Секунду, упакую в контейнер.', zh: '——把剩下的打包带走。\n——稍等，我装进餐盒。', en: '— Wrap the leftovers to go.\n— One moment, I\'ll pack them in a container.', ctx: '打包剩菜' },
  { ru: 'Я бы расплатился наличными, если найду мелочь.', zh: '如果能找到零钱，我就付现金。', en: 'I\'d pay in cash if I can find some change.', ctx: '现金支付' },
  { ru: '— Чаевые уже включены в счёт?\n— Нет, они остаются на ваше усмотрение.', zh: '——账单里已经包含小费了吗？\n——没有，小费由您自行决定。', en: '— Is the tip already included in the bill?\n— No, it\'s entirely up to you.', ctx: '询问小费' },
  { ru: 'В счёте ошибка: я не заказывал вино.', zh: '账单有误：我没有点葡萄酒。', en: 'There\'s a mistake on the bill: I didn\'t order wine.', ctx: '账单有误' },
  { ru: '— Можно нас рассчитать по отдельности?\n— Конечно, разделю сумму пополам.', zh: '——可以给我们分开结账吗？\n——当然，我把金额平分。', en: '— Could we have separate bills?\n— Sure, I\'ll split the amount in half.', ctx: '分开结账' },
  { ru: '— Сколько с нас всего?\n— 3200 рублей.\n— Держите, заплачу картой.', zh: '——我们总共多少钱？\n——3200卢布。\n——给您，我刷卡。', en: '— How much do we owe in total?\n— 3200 rubles.\n— Here you go, I\'ll pay by card.', ctx: '询问总价', say: 'сколько с нас всего три тысячи двести рублей держите заплачу картой' },
  { ru: '— Пакет нужен?\n— Да, один пакет, пожалуйста.', zh: '——需要袋子吗？\n——要，请给一个袋子。', en: '— Do you need a bag?\n— Yes, one bag, please.', ctx: '要不要袋子' },
  { ru: 'Упакуйте, пожалуйста, эти пирожки с собой.', zh: '请把这些小馅饼打包带走。', en: 'Could you pack these little pirozhki to go, please?', ctx: '打包馅饼' },
  { ru: '— Я не расслышал сумму.\n— 850 рублей.\n— Секунду, найду карту.', zh: '——我没听清金额。\n——850卢布。\n——稍等，我找一下卡。', en: '— I didn\'t catch the amount.\n— 850 rubles.\n— One second, let me find my card.', ctx: '复述金额', say: 'я не расслышал сумму восемьсот пятьдесят рублей секунду найду карту' },
  { ru: '— Оплата прошла?\n— Да, вот ваш чек, всего доброго.', zh: '——支付成功了吗？\n——成功了，这是您的小票，再见。', en: '— Did the payment go through?\n— Yes, here\'s your receipt, have a good one.', ctx: '支付确认' },
  { ru: 'Если блюдо остыло, мы попросили бы упаковать его с собой.', zh: '如果菜凉了，我们就请人把它打包带走。', en: 'If the dish had gone cold, we would ask to have it packed to go.', ctx: '凉了打包' },
  { ru: 'Обслуживание было быстрым, а официант — очень внимательным.', zh: '上菜很快，服务员也很周到。', en: 'The service was fast and the waiter very attentive.', ctx: '夸赞服务' },
  { ru: '— Тебе понравилось в этом кафе?\n— Очень, особенно вид из окна.', zh: '——你喜欢这家咖啡馆吗？\n——很喜欢，尤其是窗外的景色。', en: '— Did you like this café?\n— A lot, especially the view from the window.', ctx: '评价咖啡馆' },
  { ru: 'Это лучший борщ, что я ел в жизни!', zh: '这是我这辈子喝过最好的罗宋汤！', en: 'This is the best borscht I\'ve ever had in my life!', ctx: '夸罗宋汤' },
  { ru: '— Долго несли заказ?\n— Полчаса, не меньше.\n— Надо написать об этом в отзыве.', zh: '——上菜等了很久吗？\n——至少半小时。\n——得在评价里写一笔。', en: '— Did the order take long?\n— Half an hour, at least.\n— I should mention that in a review.', ctx: '上菜太慢' },
  { ru: '— Как тебе обстановка?\n— Уютно, музыка негромкая, как я люблю.', zh: '——环境怎么样？\n——很温馨，音乐不吵，正合我意。', en: '— How do you like the atmosphere?\n— Cozy, quiet music, just how I like it.', ctx: '评价环境' },
  { ru: 'Цены тут кусаются, зато порции большие.', zh: '这儿价格有点贵，不过分量很大。', en: 'Prices are steep here, but the portions are big.', ctx: '价高量大' },
  { ru: '— Поставишь заведению пятёрку?\n— Четвёрку, из-за медленного сервиса.', zh: '——你会给这家店打五分吗？\n——四分，因为服务太慢。', en: '— Will you give the place five stars?\n— Four, because of the slow service.', ctx: '给店打几分' },
  { ru: 'Я бы смело посоветовал это место друзьям.', zh: '我会很乐意把这个地方推荐给朋友。', en: 'I would gladly recommend this place to friends.', ctx: '推荐餐厅' },
  { ru: '— Мясо получилось жестковатым.\n— А у меня рыба просто тает во рту.\n— Значит, нам просто повезло по-разному.', zh: '——肉有点老。\n——我的鱼却入口即化。\n——看来我们俩运气不一样。', en: '— The meat turned out a bit tough.\n— My fish just melts in the mouth.\n— I guess our luck simply differed.', ctx: '菜品参差' },
  { ru: '— Чаевые оставишь?\n— После такого сервиса непременно.', zh: '——你会留小费吗？\n——这样的服务，当然要留。', en: '— Will you leave a tip?\n— After service like that, absolutely.', ctx: '是否给小费' },
  { ru: 'В отзыве я отметил чистоту в зале и свежие продукты.', zh: '我在评价里称赞了大厅的整洁和食材的新鲜。', en: 'In my review I noted the clean dining room and fresh ingredients.', ctx: '点评卫生' },
  { ru: '— Столики стоят близко, это мешает?\n— Есть немного, но в целом терпимо.', zh: '——桌子摆得很近，会受影响吗？\n——有一点，但总体可以接受。', en: '— The tables are close together, does it bother you?\n— A bit, but overall it\'s tolerable.', ctx: '桌距太近' },
  { ru: '— Стоит зайти сюда на завтрак?\n— Обязательно, каши тут замечательные.', zh: '——值得来这儿吃早餐吗？\n——一定来，这儿的粥很好喝。', en: '— Is it worth coming here for breakfast?\n— Definitely, their porridges are wonderful.', ctx: '值得来吃' },
  { ru: '— Что скажешь о десертах?\n— Ради тирамису я бы вернулся отдельно.', zh: '——甜点怎么样？\n——为了提拉米苏，我愿意专门再来一趟。', en: '— What do you say about the desserts?\n— I\'d come back just for the tiramisu.', ctx: '夸赞甜点' },
  { ru: '— Ну как вечер?\n— Кухня отличная, а вот счёт удивил.\n— Насколько удивил?\n— Вдвое дороже, чем я ожидал.', zh: '——今晚怎么样？\n——菜很好，但账单让人意外。\n——怎么个意外法？\n——比我预想的贵了一倍。', en: '— How was your evening?\n— The food was excellent, but the bill surprised me.\n— How much did it surprise you?\n— Twice as expensive as I expected.', ctx: '账单意外' },
  { ru: 'Один гамбургер с картошкой фри и колу, пожалуйста.', zh: '请给我一个汉堡配薯条，再来一杯可乐。', en: 'One hamburger with fries and a cola, please.', ctx: '点汉堡套餐' },
  { ru: '— Будете есть здесь или с собой?\n— С собой, я очень тороплюсь.', zh: '——您在这儿吃还是带走？\n——带走，我赶时间。', en: '— For here or to go?\n— To go, I\'m in a hurry.', ctx: '堂食外带' },
  { ru: 'Заказ привезли за полчаса, ещё горячим.', zh: '外卖半小时就送到了，还是热的。', en: 'The order arrived in half an hour, still hot.', ctx: '外卖很快' },
  { ru: '— Какой соус взять к наггетсам?\n— Сырный, и салфеток побольше.', zh: '——鸡块配什么酱？\n——芝士酱，再多给点餐巾纸。', en: '— Which sauce for the nuggets?\n— Cheese, and extra napkins.', ctx: '选蘸酱料' },
  { ru: 'Взял бы два чизбургера, да очередь огромная.', zh: '我倒想买两个芝士堡，可队伍太长了。', en: 'I\'d get two cheeseburgers, but the line is huge.', ctx: '排队犹豫' },
  { ru: '— Ваш заказ готов, номер 27.\n— А кетчуп не забыли?\n— Ой, сейчас добавлю пакетик.', zh: '——您的餐好了，27号。\n——没忘放番茄酱吧？\n——哎哟，我这就加一包。', en: '— Your order is ready, number 27.\n— You didn\'t forget the ketchup?\n— Oops, I\'ll add a packet now.', ctx: '取餐核对', say: 'ваш заказ готов номер двадцать семь а кетчуп не забыли ой сейчас добавлю пакетик' },
  { ru: '— Доставка платная?\n— От 1000 рублей — бесплатно.', zh: '——配送收费吗？\n——满1000卢布免费送。', en: '— Is delivery charged?\n— Free from 1000 rubles.', ctx: '询问配送费', say: 'доставка платная от тысячи рублей бесплатно' },
  { ru: '— Что возьмём к пицце?\n— Двойную картошку фри и луковые кольца.', zh: '——披萨配点什么？\n——双份薯条和洋葱圈。', en: '— What shall we get with the pizza?\n— Double fries and onion rings.', ctx: '加配小食' },
  { ru: '— Можно сделать шаурму без лука?\n— Без проблем, повар учтёт.', zh: '——沙威玛可以不放洋葱吗？\n——没问题，厨师会注意。', en: '— Can I have the shawarma without onions?\n— No problem, the cook will take note.', ctx: '沙威玛去葱' },
  { ru: '— Что-то долго везут.\n— Курьер уже в двух домах от нас.\n— Надеюсь, суп не остыл.', zh: '——怎么送这么久。\n——骑手离我们就两栋楼了。\n——希望汤没凉。', en: '— They\'re taking ages.\n— The courier is two buildings away.\n— I hope the soup hasn\'t gone cold.', ctx: '催促外卖' },
  { ru: '— Добавить что-нибудь к заказу?\n— Да, мороженое на десерт.', zh: '——订单还要加点什么吗？\n——嗯，来个冰淇淋当甜点。', en: '— Anything to add to the order?\n— Yes, ice cream for dessert.', ctx: '追加下单' },
  { ru: 'Какая огромная пицца — на всю компанию хватит!', zh: '这披萨真大——够一大家人吃！', en: 'What a huge pizza — enough for the whole group!', ctx: '披萨很大' },
  { ru: '— Приборы положить?\n— Не нужно, у меня дома есть.', zh: '——要放餐具吗？\n——不用，我家里有。', en: '— Shall I include cutlery?\n— No need, I have some at home.', ctx: '要不要餐具' },
  { ru: 'Подогрейте, пожалуйста, сэндвич в микроволновке.', zh: '请帮我把三明治放微波炉加热一下。', en: 'Please heat the sandwich in the microwave.', ctx: '加热三明治' },
  { ru: '— Алло, это доставка?\n— Да, ваш заказ задерживается минут на 10.\n— Но курьер обещал к семи!\n— Приносим извинения, напиток за наш счёт.', zh: '——喂，是外卖吗？\n——是的，您的餐会晚到10分钟。\n——可骑手说好七点到的！\n——非常抱歉，饮料由我们赠送。', en: '— Hello, is this delivery?\n— Yes, your order will be about 10 minutes late.\n— But the courier promised it by seven!\n— Our apologies, the drink is on us.', ctx: '外卖延迟', say: 'алло это доставка да ваш заказ задерживается минут на десять но курьер обещал к семи приносим извинения напиток за наш счёт' },
  { ru: 'Настоящий борщ подают со сметаной и пампушками.', zh: '正宗罗宋汤要配酸奶油和蒜香小面包。', en: 'Real borscht is served with sour cream and pampushky.', ctx: '正宗罗宋汤' },
  { ru: '— Сибирские пельмени сами лепите?\n— Да, всей семьёй, по воскресеньям.', zh: '——西伯利亚饺子是自己包的吗？\n——对，每周日全家一起包。', en: '— Do you make the Siberian pelmeni yourselves?\n— Yes, the whole family, on Sundays.', ctx: '手工饺子' },
  { ru: 'Кулебяка с капустой у бабушки была выше всяких похвал.', zh: '奶奶做的白菜大馅饼好吃得没法形容。', en: 'Grandma\'s cabbage kulebyaka was beyond praise.', ctx: '奶奶的馅饼' },
  { ru: '— Из какого мяса этот шашлык?\n— Из свиной шеи, она замаринована с луком.', zh: '——这烤串是什么肉？\n——猪颈肉，用洋葱腌过。', en: '— What meat is this shashlik?\n— Pork neck, marinated with onions.', ctx: '烤肉原料' },
  { ru: 'Салат оливье у нас готовят на каждый Новый год.', zh: '我们家每年新年都做奥利维尔沙拉。', en: 'We make Olivier salad every New Year.', ctx: '节日沙拉' },
  { ru: '— Чёрный хлеб свежий?\n— Утром привезли, ещё тёплый.\n— Тогда половину буханки, пожалуйста.', zh: '——黑面包新鲜吗？\n——早上刚送来，还热乎呢。\n——那请给我半条。', en: '— Is the black bread fresh?\n— It came this morning, still warm.\n— Then half a loaf, please.', ctx: '黑麦面包' },
  { ru: '— Какая начинка в пирогах?\n— Рыба с рисом и яйцом.', zh: '——馅饼是什么馅？\n——鱼肉配米饭和鸡蛋。', en: '— What\'s the filling in the pies?\n— Fish with rice and egg.', ctx: '馅饼馅料' },
  { ru: '— Что взять к борщу?\n— Конечно сало с чёрным хлебом.', zh: '——罗宋汤配什么好？\n——当然是腌猪油配黑面包。', en: '— What goes well with borscht?\n— Salo with black bread, of course.', ctx: '汤配小菜' },
  { ru: '— Это уральские пельмени?\n— Они, с тройным фаршем: говядина, свинина, баранина.', zh: '——这是乌拉尔饺子吗？\n——是的，三种肉馅：牛肉、猪肉、羊肉。', en: '— Are these Ural pelmeni?\n— They are, with triple filling: beef, pork, lamb.', ctx: '乌拉尔饺子' },
  { ru: '— Попробовал бы ты шашлык по-карски?\n— Это такой огромный кусок?\n— Да, его готовят на вертеле.\n— Звучит заманчиво, давай рискнём.', zh: '——你想尝尝卡尔斯式大烤串吗？\n——就是那种一大块的？\n——对，在立式烤架上烤的。\n——听着诱人，那就试试。', en: '— Would you try shashlik po-karski?\n— Is that the enormous piece?\n— Yes, it\'s cooked on a spit.\n— Sounds tempting, let\'s risk it.', ctx: '巨型烤肉' },
  { ru: 'Мимозу делают слоями: рыба, яйца, сыр и морковь.', zh: '“含羞草”沙拉是分层做的：鱼、鸡蛋、奶酪和胡萝卜。', en: 'Mimosa salad is made in layers: fish, eggs, cheese and carrots.', ctx: '层层沙拉' },
  { ru: '— Винегрет бывает без квашеной капусты?\n— Бывает, но с ней вкуснее.', zh: '——甜菜沙拉可以不放酸白菜吗？\n——可以，但放了更好吃。', en: '— Can vinaigrette be made without sauerkraut?\n— It can, but it tastes better with it.', ctx: '甜菜沙拉' },
  { ru: 'Непременно отведайте расстегаи с рыбой.', zh: '一定要尝尝开口鱼肉馅饼。', en: 'Be sure to try the fish rasstegai pies.', ctx: '推荐鱼馅饼' },
  { ru: '— Почему хлеб называют бородинским?\n— По легенде, его пекли ещё под Бородином.', zh: '——这种面包为什么叫博罗季诺面包？\n——传说当年在博罗季诺就开始烤了。', en: '— Why is the bread called Borodinsky?\n— According to legend, it was baked near Borodino.', ctx: '面包得名' },
  { ru: '— Вареники с вишней — это еда или десерт?\n— Кто как считает!\n— Тогда возьмём их и вместо первого, и на сладкое.', zh: '——樱桃甜馅饺子算正餐还是甜点？\n——各有各的说法！\n——那我们既当第一道菜又当甜点。', en: '— Are cherry varenyky a meal or a dessert?\n— Everyone has their own view!\n— Then we\'ll have them both as a first course and for dessert.', ctx: '甜饺子之争' },
  { ru: 'Нарежь лук полукольцами, а морковь натри на тёрке.', zh: '把洋葱切成半圆丝，胡萝卜擦成丝。', en: 'Slice the onion into half-rings and grate the carrots.', ctx: '切菜备料' },
  { ru: '— Сколько варить яйца вкрутую?\n— 10 минут после закипания.\n— А для всмятку?\n— Ровно 4.', zh: '——煮全熟鸡蛋要几分钟？\n——水开后10分钟。\n——那溏心蛋呢？\n——正好4分钟。', en: '— How long do I hard-boil eggs?\n— 10 minutes after the water boils.\n— And for soft-boiled?\n— Exactly 4.', ctx: '煮蛋计时', say: 'сколько варить яйца вкрутую десять минут после закипания а для всмятку ровно четыре' },
  { ru: '— Что сделать сначала?\n— Разогрей масло на сковороде.', zh: '——先做什么？\n——把煎锅上的油烧热。', en: '— What should I do first?\n— Heat the oil in the pan.', ctx: '热锅凉油' },
  { ru: '— Тесто уже подошло?\n— Да, стало вдвое больше, можно лепить.', zh: '——面发好了吗？\n——好了，大了一倍，可以包了。', en: '— Has the dough risen yet?\n— Yes, it doubled in size, ready to shape.', ctx: '发面好了吗' },
  { ru: 'Я бы добавил щепотку сахара, чтобы вкус стал мягче.', zh: '我会加一小撮糖，让味道更柔和。', en: 'I\'d add a pinch of sugar to soften the taste.', ctx: '加少许糖' },
  { ru: '— Зачем ты сливаешь первый бульон?\n— Так он получается прозрачнее.\n— Не знал, возьму на заметку.', zh: '——你为什么把头道汤倒掉？\n——这样汤更清亮。\n——原来如此，我记下了。', en: '— Why do you pour off the first broth?\n— It comes out clearer this way.\n— I didn\'t know that, I\'ll keep it in mind.', ctx: '倒掉头汤' },
  { ru: '— Овощи нужно помешивать?\n— Обязательно, иначе пригорят.', zh: '——蔬菜需要翻炒吗？\n——一定要，不然会糊。', en: '— Should I stir the vegetables?\n— Definitely, or they\'ll burn.', ctx: '翻炒蔬菜' },
  { ru: 'Посоли суп по вкусу, но помни, что сыр солёный.', zh: '汤按口味放盐，但别忘了奶酪本身是咸的。', en: 'Salt the soup to taste, but remember the cheese is salty.', ctx: '放盐时机' },
  { ru: '— Как понять, что рыба готова?\n— Мякоть легко отделяется от кости.', zh: '——怎么判断鱼熟了？\n——鱼肉能轻松脱骨就行。', en: '— How do I tell when the fish is done?\n— The flesh comes off the bone easily.', ctx: '判断鱼熟' },
  { ru: 'Тушим капусту на медленном огне под крышкой сорок минут.', zh: '白菜加盖用小火炖四十分钟。', en: 'Simmer the cabbage on low heat, covered, for forty minutes.', ctx: '慢炖白菜' },
  { ru: '— Духовку разогреть?\n— До 180 градусов, не больше.', zh: '——烤箱要预热吗？\n——到180度，别再高了。', en: '— Should I preheat the oven?\n— To 180 degrees, no higher.', ctx: '烤箱温度', say: 'духовку разогреть до ста восьмидесяти градусов не больше' },
  { ru: 'Взбей яйца венчиком до появления пены.', zh: '用打蛋器把鸡蛋搅打至起泡。', en: 'Beat the eggs with a whisk until foamy.', ctx: '搅打鸡蛋' },
  { ru: '— Молоко убежало!\n— Выключай конфорку скорее!\n— Уже выключил... вот беспорядок.\n— Не беда, сейчас протрём плиту.', zh: '——牛奶溢出来了！\n——快把灶关掉！\n——关了……弄得真乱。\n——没事，咱们这就擦灶台。', en: '— The milk boiled over!\n— Turn off the burner, quick!\n— It\'s off... what a mess.\n— Never mind, we\'ll wipe the stove now.', ctx: '牛奶溢出' },
  { ru: '— Зачем замачивать фасоль?\n— Так она сварится быстрее и станет мягче.', zh: '——豆子为什么要泡？\n——泡了煮得更快，也更软。', en: '— Why soak the beans?\n— They cook faster and get softer.', ctx: '浸泡豆子' },
  { ru: '— Вода закипела!\n— Бросай пельмени и помешай шумовкой.', zh: '——水开了！\n——下饺子，再用漏勺推一推。', en: '— The water is boiling!\n— Drop in the pelmeni and stir with a skimmer.', ctx: '开水下饺子' },
  { ru: 'Я вегетарианец, поэтому мяса не ем совсем.', zh: '我是素食者，所以完全不吃肉。', en: 'I\'m a vegetarian, so I don\'t eat meat at all.', ctx: '我是素食者' },
  { ru: '— У вас есть блюда без глютена?\n— Да, блюда с этим значком как раз безглютеновые.', zh: '——你们有无麸质菜品吗？\n——有，带这个标记的就是无麸质的。', en: '— Do you have gluten-free dishes?\n— Yes, dishes with this icon are gluten-free.', ctx: '询问无麸质' },
  { ru: 'У меня аллергия на орехи, даже их следы опасны.', zh: '我对坚果过敏，哪怕微量也有危险。', en: 'I have a nut allergy, even traces are dangerous.', ctx: '坚果过敏' },
  { ru: '— Это халяльное заведение?\n— Да, у нас есть сертификат, всё мясо халяль.\n— Значит, мне можно всё из этого раздела?\n— Совершенно верно.', zh: '——这是清真餐厅吗？\n——是的，我们有认证，所有肉类都清真。\n——那这一栏的菜我都可以点？\n——完全正确。', en: '— Is this a halal establishment?\n— Yes, we\'re certified, all the meat is halal.\n— So I can have anything from this section?\n— Exactly.', ctx: '清真认证' },
  { ru: '— В этом супе есть лактоза?\n— Сливок нет, только вода и овощи.', zh: '——这汤里含乳糖吗？\n——没有奶油，只有水和蔬菜。', en: '— Does this soup contain lactose?\n— There\'s no cream, just water and vegetables.', ctx: '询问乳糖' },
  { ru: '— Можно подать блюдо на отдельной посуде?\n— Конечно, раз в нём нет молочных продуктов.', zh: '——这道菜能用单独餐具盛吗？\n——当然，既然里面没有奶制品。', en: '— Could you serve the dish on separate utensils?\n— Of course, since it contains no dairy.', ctx: '分餐餐具' },
  { ru: '— Вы не едите свинину по религиозным соображениям?\n— Верно, мы её вообще не употребляем.', zh: '——您不吃猪肉是出于宗教原因吗？\n——对，我们完全不吃。', en: '— You don\'t eat pork for religious reasons?\n— That\'s right, we don\'t eat it at all.', ctx: '不食猪肉' },
  { ru: 'Мне нельзя острое: врач запретил из-за желудка.', zh: '我不能吃辣：因为胃的问题，医生禁止了。', en: 'I can\'t have spicy food: the doctor banned it because of my stomach.', ctx: '医嘱忌辣' },
  { ru: '— На что именно у вас аллергия?\n— На арахис и морепродукты.\n— Предупрежу повара, чтобы не перепутал.', zh: '——您具体对什么过敏？\n——花生和海鲜。\n——我会提醒厨师，别弄错。', en: '— What exactly are you allergic to?\n— Peanuts and seafood.\n— I\'ll warn the chef so he doesn\'t mix things up.', ctx: '过敏告知' },
  { ru: '— Есть ли растительное молоко для кофе?\n— Овсяное и миндальное, какое налить?', zh: '——咖啡有植物奶吗？\n——燕麦奶和杏仁奶，给您倒哪种？', en: '— Do you have plant milk for coffee?\n— Oat and almond, which would you like?', ctx: '要点植物奶' },
  { ru: 'Без сахара и подсластителей, пожалуйста.', zh: '请不要放糖和任何甜味剂。', en: 'No sugar or sweeteners, please.', ctx: '要求不加糖' },
  { ru: '— Можно приготовить это без яиц?\n— Заменю их льняной мукой, не волнуйтесь.', zh: '——这个可以不放鸡蛋做吗？\n——我用亚麻籽粉代替，您放心。', en: '— Can this be made without eggs?\n— I\'ll substitute flaxseed meal, don\'t worry.', ctx: '无蛋烹饪' },
  { ru: 'Как здорово, что для вегетарианцев тут целая страница меню!', zh: '素食者居然有整整一页菜单，太好了！', en: 'How great that vegetarians get a whole page of the menu!', ctx: '素食友好' },
  { ru: '— Вы уверены, что в соусе нет рыбы?\n— Там только томаты и травы.\n— Просто у меня на неё сильная аллергия.\n— Понял, перепроверю на кухне лично.', zh: '——您确定酱汁里没有鱼吗？\n——只有番茄和香草。\n——我对鱼严重过敏。\n——明白，我亲自去厨房再确认。', en: '— Are you sure there\'s no fish in the sauce?\n— It\'s only tomatoes and herbs.\n— I just have a severe allergy to it.\n— Understood, I\'ll double-check in the kitchen myself.', ctx: '确认无鱼' },
  { ru: '— А это блюдо постное?\n— В постные дни его готовят вообще без масла.', zh: '——这道菜是斋戒菜吗？\n——斋戒日做的时候一点油都不放。', en: '— Is this dish Lenten?\n— On fasting days it\'s cooked without any oil.', ctx: '询问斋戒菜' },
  { ru: 'Хозяюшка пожелала гостям приятного аппетита.', zh: '女主人祝客人们胃口好。', en: 'The hostess wished the guests a good appetite.', ctx: '祝愿好胃口' },
  { ru: '— Приятного аппетита!\n— Спасибо, и вам того же.', zh: '——祝胃口好！\n——谢谢，您也是。', en: '— Enjoy your meal!\n— Thanks, you too.', ctx: '互祝食欲' },
  { ru: 'За столом не принято тянуться через весь стол за хлебом.', zh: '餐桌上不兴探过整张桌子去拿面包。', en: 'At the table it\'s not done to reach across the whole table for bread.', ctx: '不越桌取食' },
  { ru: '— Давайте чокнемся!\n— Только не бейте бокалы сильно.\n— Чтобы не раскололись?\n— Именно, достаточно лишь коснуться.', zh: '——咱们碰杯吧！\n——只是别把杯子撞得太用力。\n——怕碰碎吗？\n——对，轻轻碰一下就好。', en: '— Let\'s clink glasses!\n— Just don\'t clink them hard.\n— So they don\'t crack?\n— Exactly, just touching is enough.', ctx: '碰杯礼仪' },
  { ru: '— Можно уже начинать есть?\n— Да, все собрались, приступай.', zh: '——可以开始吃了吗？\n——可以，人都到齐了，动筷吧。', en: '— May we start eating?\n— Yes, everyone\'s here, go ahead.', ctx: '何时开吃' },
  { ru: 'Я бы сказал тост, если бы гости наконец расселись.', zh: '等客人们终于入座，我就要祝酒了。', en: 'I would make a toast if the guests would finally sit down.', ctx: '准备祝酒' },
  { ru: '— За что мы пьём?\n— За встречу, ребята!', zh: '——咱们为什么干杯？\n——为重逢干杯，朋友们！', en: '— What are we drinking to?\n— To our reunion, folks!', ctx: '为何干杯' },
  { ru: 'Локти на стол не кладут, их держат на весу.', zh: '手肘不要放在桌上，要悬空。', en: 'You don\'t put your elbows on the table; keep them raised.', ctx: '手肘不上桌' },
  { ru: '— Ну что, по первой?\n— По первой, но потом я пас.\n— Как скажешь, твоё здоровье!', zh: '——怎么样，先干一杯？\n——第一杯可以，之后我就不喝了。\n——随你，祝你健康！', en: '— Well, shall we have the first one?\n— The first one, but then I\'m out.\n— As you say, cheers to your health!', ctx: '先干一杯' },
  { ru: '— Почему у русских принято так долго сидеть за столом?\n— Потому что главное — общение, а не еда.', zh: '——为什么俄罗斯人习惯在餐桌旁坐那么久？\n——因为重点是聊天，不是吃饭。', en: '— Why do Russians sit at the table for so long?\n— Because the main thing is conversation, not food.', ctx: '久席文化' },
  { ru: 'Давайте все вместе выпьем за здоровье именинницы — ура!', zh: '让我们一起为寿星的健康干杯——乌拉！', en: 'Let\'s all drink together to the birthday girl\'s health — hooray!', ctx: '为寿星干杯' },
  { ru: '— На поминках ведь не чокаются, верно?\n— Да, в этот день бокалы не поднимают.', zh: '——丧宴上不碰杯，对吧？\n——对，那天不会举杯相碰。', en: '— They don\'t clink glasses at a memorial meal, right?\n— Right, glasses aren\'t raised that day.', ctx: '丧宴不碰杯' },
  { ru: '— Спасибо за угощение, всё было чудесно!\n— На здоровье, заходите ещё.', zh: '——谢谢款待，一切都太棒了！\n——别客气，欢迎再来。', en: '— Thank you for the meal, everything was wonderful!\n— You\'re welcome, do come again.', ctx: '感谢款待' },
  { ru: '— Прошу слова для тоста!\n— Слушаем тебя внимательно.\n— Этот год был непростым, но мы остались вместе.\n— За нас! — За нас!', zh: '——请允许我说几句祝酒词！\n——我们认真听着。\n——这一年不容易，但我们依然在一起。\n——为我们！——为我们！', en: '— I\'d like to propose a toast!\n— We\'re all ears.\n— This year hasn\'t been easy, but we stayed together.\n— To us! — To us!', ctx: '致辞敬酒' },
  { ru: '— Положить вам добавки?\n— Не откажусь, всё очень вкусно.', zh: '——给您再添点吗？\n——好啊，都太好吃了。', en: '— Shall I give you seconds?\n— I wouldn\'t say no, it\'s all delicious.', ctx: '劝添饭菜' },
]

// ── 交通出行 / Transport / Транспорт ──
const TRANSIT: Phrase[] = [
  { ru: 'Этот автобус идёт только до железнодорожной станции, дальше он поворачивает.', zh: '这辆公交车只到火车站，再往前就拐弯了。', en: 'This bus only goes as far as the train station; it turns after that.', ctx: '确认公交去向' },
  { ru: '— Вы не выходите на следующей?\n— Выхожу, давайте я вперёд пройду.', zh: '—您下一站下车吗？\n—下，我往前门走。', en: '—Are you getting off at the next stop?\n—I am, let me move toward the front.', ctx: '下车提前换位' },
  { ru: 'Передайте, пожалуйста, за проезд, мне один билет до парка культуры.', zh: '麻烦传一下车钱，我买一张到文化公园的票。', en: 'Please pass along the fare; I need one ticket to Park Kultury.', ctx: '递钱买票' },
  { ru: '— Не подскажете ли, где ближайшая остановка?\n— Ближайшая — у магазина, метров триста назад.', zh: '—请问最近的公交站在哪儿？\n—最近的站在商店旁边，往回走三百米左右。', en: '—Could you tell me where the nearest stop is?\n—The nearest one is by the shop, about three hundred metres back.', ctx: '寻找公交站点' },
  { ru: '— Опять сорок седьмой битком! Подождём следующий?\n— Да в такой час все такие.\n— Ладно, втиснемся, мне через две выходить.', zh: '—47路又挤得满满当当！等下一辆？\n—这时候哪辆都一样。\n—行吧，挤上去，我两站就下。', en: '—The 47 is packed again! Shall we wait for the next one?\n—They\'re all like that at this hour.\n—Fine, let\'s squeeze in; I get off in two stops.', ctx: '高峰挤公交' },
  { ru: 'Как же медленно он тащится, мы так точно никуда не успеем!', zh: '它爬得也太慢了，这样我们肯定哪儿都赶不上！', en: 'It\'s crawling so slowly; we\'ll never make it anywhere at this rate!', ctx: '抱怨车开太慢' },
  { ru: '— На остановке «Университет» автобус стоит долго?\n— Секунд тридцать, не больше.', zh: '—在“大学”站停得久吗？\n—三十秒左右，不会更久。', en: '—Does the bus wait long at the University stop?\n—About thirty seconds, no more.', ctx: '询问停靠时间' },
  { ru: '— Осторожно, двери закрываются, не лезьте!\n— Спасибо, я уже зашла.', zh: '—小心，车门要关了，别挤了！\n—谢谢，我已经上来了。', en: '—Careful, the doors are closing, don\'t push!\n—Thanks, I\'m already on.', ctx: '关门时上车' },
  { ru: '— Этот автобус до аэропорта довезёт?\n— Нет, вам нужен экспресс от вокзала.\n— А он часто ходит?\n— Раз в полчаса, как раз скоро должен быть.', zh: '—这趟车到机场吗？\n—不到，您得坐火车站发的机场快线。\n—那车班次多吗？\n—半小时一班，这会儿应该快来了。', en: '—Will this bus get me to the airport?\n—No, you need the express from the train station.\n—Does it run often?\n—Every half hour; one should be along soon.', ctx: '询问机场大巴' },
  { ru: 'Будь у вас проездной, не пришлось бы каждый раз покупать билет у водителя.', zh: '您要是有交通卡，就不用每次都找司机买票了。', en: 'If you had a transit card, you wouldn\'t have to buy a ticket from the driver every time.', ctx: '建议办交通卡' },
  { ru: '— Пересадка где у сорок пятого?\n— На площади, там сразу и трамваи, и метро.', zh: '—45路在哪儿换乘？\n—在广场，那儿一出门既有电车又有地铁。', en: '—Where do I change from the 45?\n—At the square; trams and the metro are right there.', ctx: '询问换乘地点' },
  { ru: 'В час пик в автобусе такая давка, что яблоку негде упасть!', zh: '高峰时段公交车里挤得水泄不通！', en: 'During rush hour the bus is so packed there\'s nowhere to drop an apple!', ctx: '高峰车厢拥挤' },
  { ru: '— До «Северной» сколько остановок?\n— Шесть, вам выходить примерно через 15 минут.', zh: '—到“北站”还有几站？\n—六站，您大约十五分钟后下车。', en: '—How many stops to Severnaya?\n—Six; you\'ll be getting off in about fifteen minutes.', ctx: '询问剩余站数', say: '— До Северной сколько остановок?\n— Шесть, вам выходить примерно через пятнадцать минут.' },
  { ru: '— Подскажите, я правильно еду до больницы?\n— Правильно, но вам нужно выйти раньше, на Школьной.\n— А это скоро?\n— Через три остановки, я вас предупрежу.', zh: '—请问，我去医院坐这车对吗？\n—对，但您得提前下，在学校站下。\n—那站快到了吗？\n—再过三站，我到时候提醒您。', en: '—Excuse me, is this the right bus for the hospital?\n—It is, but you should get off earlier, at Shkolnaya.\n—Is that soon?\n—In three stops. I\'ll let you know.', ctx: '请乘客提醒下' },
  { ru: '— Билет у водителя стоит 55 рублей?\n— Да, и карты он, к сожалению, не принимает.', zh: '—找司机买票是五十五卢布吗？\n—对，不过可惜他不收银行卡。', en: '—Does a ticket from the driver cost fifty-five rubles?\n—Yes, and unfortunately he doesn\'t take cards.', ctx: '询问票价支付', say: '— Билет у водителя стоит пятьдесят пять рублей?\n— Да, и карты он, к сожалению, не принимает.' },
  { ru: 'В метро всегда душно и шумно, зато до центра можно доехать за двадцать минут.', zh: '地铁里总是又闷又吵，但到市中心只要二十分钟。', en: 'The metro is always stuffy and noisy, but you can reach the centre in twenty minutes.', ctx: '评价地铁出行' },
  { ru: '— На кольцевой можно пересесть на зелёную ветку?\n— Можно, на Парке культуры, по указателям идите.', zh: '—环线上能换乘绿线吗？\n—能，在文化公园站，跟着指示牌走就行。', en: '—Can I change from the circle line to the green line?\n—Yes, at Park Kultury; just follow the signs.', ctx: '询问地铁换乘' },
  { ru: '— Девушка, уступите место пожилому человеку!\n— Ой, простите, я не заметила, сейчас встану.', zh: '—姑娘，给老人家让个座吧！\n—哎哟，对不起，我没看见，这就让。', en: '—Young lady, please give your seat to the elderly man!\n—Oh, sorry, I didn\'t notice him. I\'ll get up now.', ctx: '礼貌劝说让座' },
  { ru: 'Станция закрыта на вход, придётся ехать до следующей и возвращаться.', zh: '这站只出不进，只能坐到下一站再折回来。', en: 'The station is closed for entry, so I\'ll have to ride to the next one and come back.', ctx: '站点限流封闭' },
  { ru: '— Простите, эта ветка идёт до аэропорта?\n— Нет, вам нужна синяя, с пересадкой в центре.\n— А переход далеко?\n— Ближе к центру состава, через мостик.', zh: '—请问这条线到机场吗？\n—不到，您要坐蓝线，在市中心换乘。\n—换乘通道远吗？\n—往车头方向走近些，过天桥就是。', en: '—Excuse me, does this line go to the airport?\n—No, you need the blue line, changing in the centre.\n—Is the transfer passage far?\n—It\'s closer to the front of the train, across the footbridge.', ctx: '询问机场线路' },
  { ru: '— Не знаете ли, последний поезд во сколько?\n— Часу в первом ночи, но лучше не задерживаться.', zh: '—您知道末班车几点吗？\n—凌晨一点左右，不过最好别卡着点来。', en: '—Do you happen to know when the last train is?\n—Around one a.m., but better not to cut it close.', ctx: '询问末班车时' },
  { ru: 'Смотри, эскалатор опять сломался, придётся топать по ступенькам!', zh: '你看，自动扶梯又坏了，只好爬楼梯喽！', en: 'Look, the escalator\'s broken again; we\'ll have to trudge up the stairs!', ctx: '扶梯故障爬楼' },
  { ru: '— Вам в какую сторону?\n— Мне на север, а вам, наверное, в обратную.', zh: '—您往哪个方向坐？\n—我往北，您大概是反方向。', en: '—Which direction are you going?\n—North; you probably need the opposite way.', ctx: '确认乘车方向' },
  { ru: '— Один проездной на 5 поездок, пожалуйста.\n— Двести пятьдесят рублей, что-то ещё?\n— Да, подскажите, где третий выход?\n— По коридору направо, потом по лестнице вверх.', zh: '—请给我一张五次票。\n—二百五十卢布，还需要别的吗？\n—再问一下三号口怎么走？\n—沿走廊右转，再上楼梯。', en: '—One transit card for five rides, please.\n—250 rubles. Anything else?\n—Yes, where\'s exit three?\n—Right down the corridor, then upstairs.', ctx: '购买地铁次票', say: '— Один проездной на пять поездок, пожалуйста.\n— Двести пятьдесят рублей, что-то ещё?\n— Да, подскажите, где третий выход?\n— По коридору направо, потом по лестнице вверх.' },
  { ru: '— Двери не открываются! Что делать?\n— Нажмите кнопку вызова, машинист сейчас ответит.', zh: '—车门打不开！怎么办？\n—按呼叫按钮，司机马上会回应。', en: '—The doors won\'t open! What should I do?\n—Press the call button; the driver will answer in a moment.', ctx: '车门突发故障' },
  { ru: '— Ты не проехала свою станцию?\n— Нет, не волнуйся, я слежу за остановками.', zh: '—你没坐过站吧？\n—没有，别担心，我盯着站呢。', en: '—You didn\'t miss your stop, did you?\n—No, don\'t worry, I\'m watching the stops.', ctx: '提醒同伴下车' },
  { ru: 'На схеме кольцевая линия нарисована коричневым цветом и соединяет все вокзалы.', zh: '图上环线用棕色标出，把各个火车站都连了起来。', en: 'On the map the circle line is brown and connects all the main railway stations.', ctx: '查看线路图' },
  { ru: '— Молодой человек, вы мне выходить не даёте!\n— Простите, я просто не вижу станцию, мы выходим вместе.\n— Тогда давайте протиснемся поближе к дверям.\n— Идите вперёд, я за вами.', zh: '—小伙子，您挡着我下车啦！\n—抱歉，我也看不见站台，我也这站下。\n—那咱们往门口挤挤。\n—您先走，我跟上。', en: '—Young man, you\'re blocking my way out!\n—Sorry, I just can\'t see the platform; I\'m getting off too.\n—Then let\'s squeeze closer to the doors.\n—You go first, I\'m right behind you.', ctx: '拥挤车厢下车' },
  { ru: '— Какой интервал между поездами вечером?\n— Минут 6–7, реже, чем днём.', zh: '—晚上车与车间隔多久？\n—六七分钟，比白天长些。', en: '—What\'s the interval between trains in the evening?\n—Six or seven minutes; less frequent than in the daytime.', ctx: '询问发车间隔', say: '— Какой интервал между поездами вечером?\n— Минут шесть или семь, реже, чем днём.' },
  { ru: '— Билет действует 90 минут с пересадками?\n— Да, у вас ещё есть время на автобус.', zh: '—票是九十分钟内可以换乘吗？\n—对，您还来得及去坐公交。', en: '—Is the ticket valid for ninety minutes with transfers?\n—Yes, you still have time to catch a bus.', ctx: '确认票时换乘', say: '— Билет действует девяносто минут с пересадками?\n— Да, у вас ещё есть время на автобус.' },
  { ru: 'Ловить машину на улице сейчас почти никто не делает, все заказывают через приложение.', zh: '现在几乎没人在路边拦车了，大家都用手机软件叫车。', en: 'Hardly anyone hails a cab on the street these days; everyone uses an app.', ctx: '软件叫车习惯' },
  { ru: '— Куда едем?\n— На Ленинский проспект, дом семь, это у самого парка.', zh: '—咱们去哪儿？\n—去列宁大街7号，就在公园边上。', en: '—Where are we heading?\n—7 Leninsky Prospekt, right by the park.', ctx: '告知司机地址' },
  { ru: '— Остановите, пожалуйста, вон у того жёлтого дома.\n— Тут разметка, я проеду чуть дальше и прижмусь к обочине.', zh: '—请在那栋黄楼旁边停一下。\n—这儿是实线，我往前一点靠边停。', en: '—Please stop by that yellow building over there.\n—There are solid lines here; I\'ll pull a bit further ahead and pull over.', ctx: '商议下车地点' },
  { ru: 'Ну и ценник в этот раз — почти в два раза дороже обычного!', zh: '这回价格可真够狠的，比平时贵了快一倍！', en: 'What a price this time — almost twice the usual fare!', ctx: '惊讶打车价格' },
  { ru: '— Вы по счётчику повезёте?\n— Конечно, смотрите, вот приложение показывает.\n— А можно побыстрее, я на поезд опаздываю?\n— Постараюсь, но центр сейчас стоит, гарантировать не могу.', zh: '—您是打表走吗？\n—当然，您看，软件上都显示着。\n—能快点吗？我赶火车。\n—我尽量，可市中心现在堵死了，不敢保证。', en: '—Will you use the meter?\n—Of course; look, the app shows everything.\n—Can you go faster? I\'m late for my train.\n—I\'ll try, but the centre is gridlocked; I can\'t promise.', ctx: '确认计费赶路' },
  { ru: 'В машине нечем дышать, попроси водителя включить кондиционер.', zh: '车里闷得喘不过气，让司机开下空调吧。', en: 'There\'s no air in this car; ask the driver to turn on the AC.', ctx: '请求开空调' },
  { ru: '— Если в пробке простоим больше сорока минут, сколько выйдет?\n— Приложение само пересчитает, но можете отменить и заказать заново.', zh: '—要是堵上四十多分钟，得多少钱？\n—软件会自动重算，不过您可以取消重叫一辆。', en: '—If we\'re stuck in traffic for over forty minutes, how much will it be?\n—The app recalculates automatically, but you can cancel and reorder.', ctx: '询问堵车计费' },
  { ru: '— Подача машины через сколько?\n— Водитель будет у подъезда через 4 минуты.', zh: '—车多久能到？\n—司机四分钟后到单元门口。', en: '—How soon will the car arrive?\n—The driver will be at your entrance in four minutes.', ctx: '询问接驾时间', say: '— Подача машины через сколько?\n— Водитель будет у подъезда через четыре минуты.' },
  { ru: '— Свободны? Мне с чемоданом, в багажнике место есть?\n— Есть, давайте я помогу уложить.\n— Спасибо большое, а то я после рейса совсем без сил.', zh: '—车走吗？我带了个行李箱，后备箱有地方吗？\n—有，我来帮您放。\n—太谢谢了，下了飞机我一点力气都没了。', en: '—Are you free? I have a suitcase; is there room in the trunk?\n—There is. Let me help you with it.\n—Thanks so much; after my flight I\'m completely worn out.', ctx: '带行李打车' },
  { ru: 'Возьми с собой наличные, этот таксист карты почему-то не принимает.', zh: '带点现金，这个出租司机不知怎么不收卡。', en: 'Take some cash; this driver doesn\'t take cards for some reason.', ctx: '提醒备好现金' },
  { ru: '— Вы можете меня подождать минут двадцать? Я быстро.\n— Могу, только ожидание будет платным, учтите.', zh: '—您能等我二十分钟吗？我很快。\n—可以，不过等候是要计费的，您留意一下。', en: '—Can you wait about twenty minutes? I\'ll be quick.\n—I can, but waiting time is charged, keep that in mind.', ctx: '请司机等候' },
  { ru: '— Какой ужас, мы опять встали!\n— Да уж, на этом перекрёстке вечно кто-то бьётся.', zh: '—糟了，我们又卡住不动了！\n—可不是嘛，这个路口老有车相撞。', en: '—How awful, we\'ve stopped again!\n—Tell me about it; someone always crashes at this intersection.', ctx: '堵车无奈吐槽' },
  { ru: 'На твоём месте я бы заказала машину заранее, утром свободных может не быть.', zh: '换作我就提前叫好车，早上可能一辆空车都没有。', en: 'If I were you, I\'d book a car in advance; there might be none free in the morning.', ctx: '建议提前叫车' },
  { ru: '— Поездка до аэропорта выйдет 900 рублей?\n— Примерно, около 900, смотря какая дорога.', zh: '—打车去机场大概九百卢布？\n—差不多，九百上下，看路况。', en: '—A ride to the airport comes to about 900 rubles?\n—Roughly, around 900, depending on traffic.', ctx: '预估机场车费', say: '— Поездка до аэропорта выйдет девятьсот рублей?\n— Примерно, около девятисот, смотря какая дорога.' },
  { ru: '— Комфорт или эконом возьмём?\n— Давай эконом, переплачивать смысла нет.\n— А детское кресло нужно?\n— Да, укажи в приложении, доплатим 100 рублей.', zh: '—叫舒适型还是经济型？\n—经济型吧，没必要多花钱。\n—要儿童安全座椅吗？\n—要，在软件里勾上，加一百卢布。', en: '—Shall we take comfort or economy?\n—Economy; no point paying extra.\n—Do we need a child seat?\n—Yes, select it in the app; we\'ll pay 100 rubles extra.', ctx: '选择车型加价', say: '— Комфорт или эконом возьмём?\n— Давай эконом, переплачивать смысла нет.\n— А детское кресло нужно?\n— Да, укажи в приложении, доплатим сто рублей.' },
  { ru: 'Билеты на нижние полки разбирают за месяц, а верхние обычно остаются.', zh: '下铺票提前一个月就被抢光，上铺通常还有。', en: 'Lower-berth tickets sell out a month ahead; upper ones are usually left.', ctx: '火车票位紧俏' },
  { ru: '— Вам чай принести? У нас есть с сахаром и без.\n— Принесите два, пожалуйста, и один пакетик сахара.', zh: '—给您送茶吗？有含糖的和无糖的。\n—请来两杯，再要一袋糖。', en: '—Shall I bring you tea? We have it with or without sugar.\n—Two, please, and one packet of sugar.', ctx: '列车员送茶水' },
  { ru: '— Вы не знаете, долго ли стоянка в Самаре?\n— Минут двадцать, как раз успеете подышать.', zh: '—您知道在萨马拉停多久吗？\n—二十分钟左右，正好能下去透透气。', en: '—Do you know how long the stop is in Samara?\n—About twenty minutes, just enough for some fresh air.', ctx: '询问到站停时' },
  { ru: 'Какой же липкий столик в этом купе, надо обязательно протереть салфетками!', zh: '这包厢里的小桌板也太黏了，一定得用纸巾擦一擦！', en: 'How sticky the little table in this compartment is; I really need to wipe it with wipes!', ctx: '嫌弃车厢卫生' },
  { ru: '— Один билет до Казани, на завтра, пожалуйста.\n— Есть сидячий за 700 и плацкарт за 1200.\n— Давайте плацкарт, нижнее место найдётся?\n— К сожалению, только верхнее, нижние все выкуплены.', zh: '—请给我一张明天去喀山的票。\n—坐票七百，硬卧一千二。\n—来硬卧吧，还有下铺吗？\n—抱歉，只剩上铺，下铺都卖完了。', en: '—One ticket to Kazan for tomorrow, please.\n—There\'s a seat for 700 and an open sleeper for 1,200.\n—The open sleeper then. Any lower berth?\n—Sorry, only upper ones; the lowers are all sold.', ctx: '窗口购买火车票', say: '— Один билет до Казани, на завтра, пожалуйста.\n— Есть сидячий за семьсот и плацкарт за тысячу двести.\n— Давайте плацкарт, нижнее место найдётся?\n— К сожалению, только верхнее, нижние все выкуплены.' },
  { ru: '— Душно-то как, можно окно открыть?\n— В этом вагоне окна глухие, попросите проводника включить кондиционер.', zh: '—太闷了，能开窗吗？\n—这节车厢的窗是封死的，您找列车员开空调吧。', en: '—It\'s so stuffy; can I open the window?\n—The windows in this car are sealed; ask the attendant to turn on the air conditioning.', ctx: '车厢闷热求助' },
  { ru: 'На больших станциях можно выбежать за горячей картошкой и домашними соленьями.', zh: '大站台上可以跑下去买热土豆和自家腌的咸菜。', en: 'At major stations you can dash out for hot potatoes and homemade pickles.', ctx: '站台买小吃' },
  { ru: '— Поезд 016 на Москву с какого пути?\n— С третьего, посадка начнётся минут через десять.', zh: '—去莫斯科的016次列车在几站台？\n—三站台，十分钟左右开始检票。', en: '—Which track is train 016 to Moscow from?\n—Track three; boarding starts in about ten minutes.', ctx: '询问列车站台', say: '— Поезд ноль шестнадцать на Москву с какого пути?\n— С третьего, посадка начнётся минут через десять.' },
  { ru: 'Сосед по купе всю ночь храпел так, что я не сомкнула глаз.', zh: '包厢里的邻座打了一整夜呼噜，我一宿没合眼。', en: 'My compartment neighbour snored all night, so I didn\'t sleep a wink.', ctx: '抱怨室友打鼾' },
  { ru: '— Девушка, а титан у вас работает? Кипяток нужен.\n— Работает, стаканы возьмите на столике у проводника.', zh: '—姑娘，热水器能用吗？我要点开水。\n—能用，杯子在列车员的小桌上拿。', en: '—Miss, is the samovar working? I need boiling water.\n—It is; take the cups from the attendant\'s table.', ctx: '接水泡面' },
  { ru: '— В вагоне есть розетки у мест?\n— Только в коридоре, возле туалета.\n— Вот досада, телефон почти сел, а зарядка в чемодане.', zh: '—铺位旁边有插座吗？\n—只有走廊厕所有。\n—真要命，手机快没电了，充电器还在箱子里。', en: '—Are there sockets by the seats?\n—Only in the corridor, near the toilet.\n—What a nuisance; my phone\'s nearly dead and the charger is in my suitcase.', ctx: '寻找电源插座' },
  { ru: '— Билет невозвратный? Жаль.\n— Почему жаль, его можно вернуть за вычетом сбора, просто сумма меньше.', zh: '—票不能退吗？真可惜。\n—怎么不能，扣手续费就能退，只是钱少些。', en: '—Is the ticket non-refundable? That\'s a shame.\n—It can still be returned minus a fee; you just get less back.', ctx: '咨询退票规则' },
  { ru: '— Если я опоздаю на поезд, билет пропадёт?\n— В течение двенадцати часов его можно переоформить на следующий.', zh: '—我要是没赶上火车，票就作废了吗？\n—十二小时内可以改签后面的车次。', en: '—If I miss the train, is the ticket wasted?\n—You can rebook it for the next one within twelve hours.', ctx: '误车改签咨询' },
  { ru: '— Вот, пожалуйста, место двенадцатое, вагон 5, верно?\n— Всё правильно, проходите, вагон в середине состава.', zh: '—给您，12号铺，5车厢，对吗？\n—没错，请进，5号车厢在列车中部。', en: '—Here you are, berth twelve, car five, right?\n—That\'s correct; come through. Car five is in the middle of the train.', ctx: '检票上车核对', say: '— Вот, пожалуйста, место двенадцатое, пятый вагон, верно?\n— Всё правильно, проходите, пятый вагон в середине состава.' },
  { ru: '— Мам, а мы в вагоне-ресторане поедим?\n— Дорого там, лучше дошик заварим, я его специально взяла.\n— А можно хотя бы чаю с печеньем?\n— Можно, пойдём вместе к проводнику за кипятком.', zh: '—妈，咱们去餐车吃饭吗？\n—那儿太贵，不如泡方便面，我特意带了。\n—那至少能喝茶吃饼干吧？\n—行，一起去找列车员要开水。', en: '—Mom, shall we eat in the dining car?\n—It\'s expensive there; let\'s just make instant noodles, I brought some on purpose.\n—Can we at least have tea and cookies?\n—Yes. Let\'s go together to the attendant for hot water.', ctx: '商量车上吃饭' },
  { ru: 'Онлайн-регистрация открывается за тридцать часов и сразу даёт выбрать место у окна.', zh: '网上值机提前三十小时开放，一开放就能挑靠窗的座位。', en: 'Online check-in opens thirty hours in advance and lets you pick a window seat right away.', ctx: '网上值机选座' },
  { ru: '— Рейс SU 778 уже задержали?\n— Пока нет, но вылет может сдвинуться на сорок минут.', zh: '—SU778航班已经延误了吗？\n—暂时没有，但起飞可能推迟四十分钟。', en: '—Has flight SU 778 been delayed yet?\n—Not yet, but departure may slip by forty minutes.', ctx: '关注航班延误', say: '— Рейс эс у семьсот семьдесят восемь уже задержали?\n— Пока нет, но вылет может сдвинуться на сорок минут.' },
  { ru: '— Девушка, у меня перевес в два килограмма, что делать?\n— Доплатите на стойке или переложите что-то в ручную кладь.', zh: '—姑娘，我的行李超重两公斤，怎么办？\n—在柜台补费，或者把东西挪几件到随身包里。', en: '—Miss, my bag is two kilos overweight; what should I do?\n—Pay at the desk or move some things into your carry-on.', ctx: '行李超重处理' },
  { ru: 'Вот это турбулентность, меня прямо в кресле подбрасывает!', zh: '这颠簸也太厉害了，我在座位上都被弹起来了！', en: 'What turbulence — I\'m literally bouncing in my seat!', ctx: '遭遇强颠簸' },
  { ru: '— Мам, а когда обед принесут? Я проголодался.\n— Потерпи, после взлёта минут через сорок.\n— А сок сейчас можно попросить?\n— Можно, бортпроводник как раз идёт.', zh: '—妈，什么时候送午饭？我饿了。\n—忍忍，起飞后四十分钟左右。\n—那现在能要杯果汁吗？\n—能，你看乘务员正好过来了。', en: '—Mom, when will they serve lunch? I\'m hungry.\n—Be patient, about forty minutes after takeoff.\n—Can I ask for juice now?\n—Yes, look, the flight attendant is coming by.', ctx: '孩子询问餐食' },
  { ru: 'Без посадочного талона и паспорта вас не пропустят к выходу на посадку.', zh: '没有登机牌和护照，不会放您到登机口。', en: 'Without a boarding pass and passport they won\'t let you through to the departure gate.', ctx: '提醒登机证件' },
  { ru: '— Пристегните ремень, мы заходим на посадку.\n— Простите, а спинку кресла тоже выпрямить?', zh: '—请系好安全带，我们开始降落了。\n—请问，椅背也要调直吗？', en: '—Fasten your seatbelt; we\'re beginning our descent.\n—Excuse me, do I need to put my seatback upright too?', ctx: '降落安全检查' },
  { ru: '— Стыковка у нас 55 минут, успеем?\n— Впритык, да ещё и выходы в разных концах аэропорта.', zh: '—中转时间五十五分钟，来得及吗？\n—刚好卡着点，而且登机口还在机场两头。', en: '—Our layover is 55 minutes; will we make it?\n—It\'s tight, and the gates are at opposite ends of the airport.', ctx: '担心中转时间', say: '— Стыковка у нас пятьдесят пять минут, успеем?\n— Впритык, да ещё и выходы в разных концах аэропорта.' },
  { ru: 'Будь рейс не таким ранним, мы бы спокойно позавтракали дома.', zh: '要不是航班这么早，我们本来可以在家从容吃个早饭。', en: 'If the flight weren\'t so early, we could have had a relaxed breakfast at home.', ctx: '感慨早班机' },
  { ru: '— Мою ручную кладь придётся сдавать? Она вроде влезает.\n— Боюсь, что нет, вон рамка, проверьте габариты.', zh: '—我的随身包非得托运吗？看着放得进啊。\n—恐怕不行，那边有量框，您量一下尺寸。', en: '—Will my carry-on have to be checked? It seems to fit.\n—I\'m afraid not; there\'s the size frame, check the dimensions.', ctx: '随身行李超标' },
  { ru: '— Вам место у прохода или у иллюминатора?\n— У иллюминатора, если осталось.\n— Есть 14А, устраивает?\n— Вполне, давайте его.', zh: '—给您过道座还是靠窗座？\n—靠窗的，如果还有。\n—有14A，您看行吗？\n—挺好，就它了。', en: '—Would you like an aisle or a window seat?\n—Window, if any are left.\n—There\'s 14A; would that work?\n—Perfect, I\'ll take it.', ctx: '值机挑选座位', say: '— Вам место у прохода или у иллюминатора?\n— У иллюминатора, если осталось.\n— Есть четырнадцать а, устраивает?\n— Вполне, давайте его.' },
  { ru: '— Не подскажете ли, где выдают багаж с московского рейса?\n— Лента номер три, но багаж ещё не выгрузили.', zh: '—请问莫斯科来的航班在哪儿取行李？\n—三号传送带，不过行李还没卸下来。', en: '—Could you tell me where baggage from the Moscow flight comes out?\n—Carousel three, but the bags haven\'t been unloaded yet.', ctx: '询问行李转盘' },
  { ru: '— Чемодан так и не приехал. Что теперь?\n— Идите в бюро находок и напишите заявление, мы его разыщем.', zh: '—箱子到底还是没出来。现在怎么办？\n—去行李查询处填张表，我们会帮您找。', en: '—The suitcase never came out. What now?\n—Go to the lost-luggage desk and file a report; we\'ll track it down.', ctx: '行李丢失报案' },
  { ru: 'Какое счастье, что пакеты из дьюти-фри не взвешивают!', zh: '太好啦，免税店的袋子登机时不过秤！', en: 'Thank goodness duty-free bags aren\'t weighed at boarding!', ctx: '庆幸免税购物' },
  { ru: '— Нас из-за отмены рейса должны в гостинице разместить?\n— Да, авиакомпания даёт ваучер и талоны на питание.\n— А где их получить?\n— Стойка информации справа, там уже собирают пассажиров.', zh: '—航班取消，他们应该安排我们住酒店吧？\n—对，航空公司提供酒店券和餐券。\n—在哪儿领呢？\n—右边的问讯柜台，已经在集合乘客了。', en: '—Since the flight\'s cancelled, they have to put us up in a hotel, right?\n—Yes, the airline provides a hotel voucher and meal vouchers.\n—Where do we get them?\n—The information desk on the right; they\'re already gathering passengers.', ctx: '航班取消安置' },
  { ru: 'Идите прямо до светофора, а там вам нужно будет повернуть налево.', zh: '一直走到红绿灯，然后您需要左转。', en: 'Go straight to the traffic lights, and there you\'ll need to turn left.', ctx: '指路方向直走' },
  { ru: '— До ближайшего метро далеко пешком?\n— Минут 10 ходьбы, видите вон то высокое здание? Оно прямо у входа.', zh: '—走到最近的地铁站远吗？\n—走十分钟，看见那栋高楼了吗？就在地铁口边上。', en: '—Is the nearest metro far on foot?\n—About a ten-minute walk. See that tall building? It\'s right by the entrance.', ctx: '步行距离估算', say: '— До ближайшего метро далеко пешком?\n— Минут десять ходьбы, видите вон то высокое здание? Оно прямо у входа.' },
  { ru: '— Не подскажете, как пройти к набережной?\n— Это через парк, вход туда как раз за этой площадью.', zh: '—请问滨河路怎么走？\n—穿过公园就到，公园入口就在广场后面。', en: '—Could you tell me how to get to the embankment?\n—Go through the park; the entrance is just behind this square.', ctx: '询问景点路线' },
  { ru: 'Кажется, мы заблудились, и навигатор ведёт нас куда-то во дворы!', zh: '我们好像迷路了，导航把我们往居民区小巷里带！', en: 'I think we\'re lost, and the satnav is leading us into some residential courtyards!', ctx: '迷路发现走错' },
  { ru: '— Простите, дом 12 по этой улице?\n— Почти, это следующий, за продуктовым.\n— То есть мне по этой стороне идти?\n— Да, не переходите дорогу.', zh: '—请问，12号是在这条街上吗？\n—差不多，再下一栋，副食店后面。\n—就是说我走这边就行？\n—对，不用过马路。', en: '—Excuse me, is building 12 on this street?\n—Almost, it\'s the next one, past the grocery store.\n—So I stay on this side?\n—Yes, don\'t cross the road.', ctx: '寻找门牌号', say: '— Простите, двенадцатый дом по этой улице?\n— Почти, это следующий, за продуктовым.\n— То есть мне по этой стороне идти?\n— Да, не переходите дорогу.' },
  { ru: '— Где тут ближайшая аптека, не подскажете?\n— В переулке направо, там вывеску сразу увидите.', zh: '—附近最近的药店在哪儿，您知道吗？\n—右边的胡同里，一进去就能看见招牌。', en: '—Where\'s the nearest pharmacy around here?\n—In the lane on the right; you\'ll see the sign right away.', ctx: '询问药店位置' },
  { ru: 'Перейдите дорогу по зебре и держитесь правой стороны, там будет указатель.', zh: '走斑马线到马路对面，靠右边走，那儿有路牌。', en: 'Cross at the zebra crossing and keep to the right; there\'ll be a sign.', ctx: '指示过街路线' },
  { ru: '— Не знаете ли, эта дорога ведёт к выезду из города?\n— Что вы, она наоборот упирается в промзону.', zh: '—您知道这条路通往出城口吗？\n—哪能啊，这条路走着走着就到工业区了。', en: '—Do you happen to know if this road leads out of the city?\n—Not at all; it actually dead-ends at the industrial zone.', ctx: '确认道路去向' },
  { ru: '— Я правильно иду к главпочтамту?\n— Нет, вы не туда свернули, вернитесь на два квартала назад.', zh: '—我去邮政总局走得对吗？\n—不对，您拐错了，往回走两个街区。', en: '—Am I heading the right way for the main post office?\n—No, you turned the wrong way; go back two blocks.', ctx: '走错纠正方向' },
  { ru: '— Подскажите, пешком до собора реально дойти?\n— Реально, минут двадцать пять, но лучше на трамвае одну остановку.\n— А остановка где?\n— Вон там, у сквера, я как раз туда иду.', zh: '—请问，走路到大教堂现实吗？\n—能走到，二十五分钟左右，不过坐电车一站更好。\n—电车站在哪儿？\n—那边，小公园旁，我正好往那儿走。', en: '—Excuse me, is it realistic to walk to the cathedral?\n—It is, about twenty-five minutes, but one tram stop is better.\n—Where\'s the tram stop?\n—Over there by the little park; I\'m heading that way myself.', ctx: '远距离指路建议' },
  { ru: '— До заправки ещё сколько? У меня бензин на исходе.\n— Километра 2, не больше, она будет справа.', zh: '—到加油站还有多远？我油快没了。\n—两公里左右，不会更远，在右手边。', en: '—How much further to the gas station? I\'m running on fumes.\n—About two kilometres, no more; it\'ll be on the right.', ctx: '打听加油站距离', say: '— До заправки ещё сколько? У меня бензин на исходе.\n— Километра два, не больше, она будет справа.' },
  { ru: '— А если дворами, короче получится?\n— Получится, но там легко заплутать, лучше по проспекту.', zh: '—穿小区走会不会近点儿？\n—是近点儿，可里面容易绕晕，还是沿大街走吧。', en: '—Would cutting through the courtyards be shorter?\n—It would, but it\'s easy to get lost in there; better take the avenue.', ctx: '询问近路捷径' },
  { ru: '— Откуда отходят речные трамвайчики?\n— От причала у старого моста, минут пятнадцать пешком туда.', zh: '—水上巴士从哪儿发船？\n—老桥旁边的码头，走过去还要十五分钟。', en: '—Where do the river ferries leave from?\n—From the pier by the old bridge; about fifteen minutes on foot.', ctx: '询问码头位置' },
  { ru: 'Если дойдёте до памятника, значит, вы уже почти на месте.', zh: '您要是走到纪念碑那儿，就说明快到了。', en: 'If you reach the monument, you\'re almost there.', ctx: '地标确认位置' },
  { ru: '— Слушай, давай спросим у кого-нибудь дорогу, а?\n— Да вон бабушка стоит, она тут точно все дворы знает.\n— Пойдём, только ты спрашивай, я стесняюсь.', zh: '—哎，咱们找个人问问路吧？\n—那边正好有位老奶奶，这一片的院子她肯定都熟。\n—走，不过你去问，我不好意思。', en: '—Listen, let\'s ask someone for directions, shall we?\n—There\'s an old lady standing there; she must know every courtyard around here.\n—Let\'s go, but you ask; I\'m too shy.', ctx: '决定找人问路' },
  { ru: 'Машину я забронировал ещё месяц назад, так что цена вышла вполне человеческая.', zh: '车我一个月前就订好了，所以价格挺亲民的。', en: 'I booked the car a month ago, so the rate came out quite reasonable.', ctx: '提前订车省钱' },
  { ru: '— Права дома не забыл? И стаж у тебя больше двух лет?\n— Всё со мной, стаж 3 года, требования я смотрел.', zh: '—驾照没忘家里吧？驾龄满两年了吗？\n—都带着呢，驾龄三年，要求我看过。', en: '—You didn\'t leave your licence at home? And you\'ve had it over two years?\n—I have it with me; three years\' experience. I checked the requirements.', ctx: '确认租车资质', say: '— Права дома не забыл? И стаж у тебя больше двух лет?\n— Всё со мной, стаж три года, требования я смотрел.' },
  { ru: '— Осмотрите машину внимательно, все царапины отметим в акте.\n— А вот эта вмятина на бампере уже была, давайте сфотографирую.', zh: '—仔细检查一下车，所有划痕我们都记在单子上。\n—保险杠这个凹痕本来就有，我拍张照。', en: '—Inspect the car carefully; we\'ll mark every scratch on the sheet.\n—This dent on the bumper was already there; let me take a photo.', ctx: '验车记录损伤' },
  { ru: 'Ты только посмотри, какой у них депозит — целых тридцать тысяч!', zh: '你看看他们要多少押金，整整三万！', en: 'Just look at their deposit — a whole thirty thousand!', ctx: '惊讶押金金额' },
  { ru: '— Машину вернёте с полным баком?\n— Конечно, как и брали. А если не успею заправиться?\n— Тогда удержим из депозита по цене 70 рублей за литр.', zh: '—还车时请加满油，好吗？\n—当然，和取车时一样。要是没来得及加呢？\n—那我们按每升七十卢布从押金里扣。', en: '—You\'ll return the car with a full tank?\n—Of course, same as I took it. What if I can\'t refuel in time?\n—Then we\'ll deduct from the deposit at 70 rubles per litre.', ctx: '满油取还规则', say: '— Машину вернёте с полным баком?\n— Конечно, как и брали. А если не успею заправиться?\n— Тогда удержим из депозита по цене семьдесят рублей за литр.' },
  { ru: '— Давай возьмём машину с автоматом, я по серпантину на механике не хочу.\n— Согласна, доплатим, зато нервы целее будут.', zh: '—咱们租自动挡吧，盘山路我不想开手动挡。\n—同意，多花点儿钱，至少不用提心吊胆。', en: '—Let\'s take an automatic; I don\'t want a manual on the mountain switchbacks.\n—Agreed; we\'ll pay extra but keep our nerves intact.', ctx: '选择自动手动' },
  { ru: 'Прежде чем выезжать, настрой зеркала, сиденье и не забудь пристегнуться.', zh: '出发前调好后视镜和座椅，别忘了系安全带。', en: 'Before pulling out, adjust the mirrors and seat, and don\'t forget to fasten your belt.', ctx: '出车前检查' },
  { ru: '— Что-то меня сейчас подрезали, хорошо хоть не задел.\n— Спокойно, не тормози резко, прижмись к обочине.\n— А если бы случилось ДТП, кому звонить?\n— В ГИБДД, номер в страховке, она у тебя в бардачке.', zh: '—刚才有车别了我一下，幸好没蹭上。\n—别慌，别急刹，靠路边停。\n—万一真出了事故，该给谁打电话？\n—打给交警，号码在保险单上，保单在你手套箱里。', en: '—Someone just cut me off; good thing he didn\'t hit me.\n—Take it easy, don\'t brake hard, pull onto the shoulder.\n—If there were an accident, who would I call?\n—The traffic police; the number\'s on the insurance policy, in your glovebox.', ctx: '路险应对咨询', say: '— Что-то меня сейчас подрезали, хорошо хоть не задел.\n— Спокойно, не тормози резко, прижмись к обочине.\n— А если бы случилось дорожно-транспортное происшествие, кому звонить?\n— В Государственную инспекцию безопасности дорожного движения, номер в страховке, она у тебя в бардачке.' },
  { ru: '— Здесь ограничение 40 км/ч, не гони так!\n— Вижу, просто дорога пустая, нога сама жмёт.', zh: '—这儿限速四十公里每小时，别开这么猛！\n—看见着呢，就是路太空，脚自己往下踩。', en: '—The limit here is 40 km/h; don\'t drive so fast!\n—I see it; the road\'s just empty and my foot presses down on its own.', ctx: '限速提醒别超速', say: '— Здесь ограничение сорок километров в час, не гони так!\n— Вижу, просто дорога пустая, нога сама жмёт.' },
  { ru: '— Какой бензин этой машине нужен?\n— 95-й, на лючке бензобака так и написано.', zh: '—这车该加哪种油？\n—95号，油箱盖上就这么写着。', en: '—What fuel does this car take?\n—95; it says so on the fuel-filler cap.', ctx: '确认燃油标号', say: '— Какой бензин этой машине нужен?\n— Девяносто пятый, на лючке бензобака так и написано.' },
  { ru: '— Нас не эвакуируют здесь? Знака запрета не видно.\n— Не видно, но место узкое, давай поищем парковку пошире.', zh: '—车停这儿不会被拖走吧？没看见禁停标志。\n—是没看见，可这地方太窄，还是找个宽点儿的车位吧。', en: '—We won\'t get towed here, will we? There\'s no prohibition sign.\n—No sign, but the spot\'s tight; let\'s find a wider parking place.', ctx: '停车担心被拖' },
  { ru: 'За превышение даже на двадцать километров в час тут прилетает приличный штраф.', zh: '在这儿哪怕只超速二十公里，也会收到一张不小的罚单。', en: 'Even twenty kilometres an hour over the limit brings a hefty fine around here.', ctx: '了解超速处罚' },
  { ru: '— Слушай, а навигатор предлагает платную дорогу, берём?\n— А сколько? Если сто рублей, то да, сэкономим час.\n— Тут написано, около ста пятидесяти.\n— Тогда точно берём, время дороже.', zh: '—哎，导航建议走收费公路，走吗？\n—多少钱？要是一百卢布就走，能省一小时。\n—这儿写着大约一百五。\n—那肯定走，时间更值钱。', en: '—Listen, the satnav suggests a toll road; shall we take it?\n—How much? If it\'s a hundred rubles, yes — we save an hour.\n—It says about a hundred and fifty here.\n—Then definitely; time is worth more.', ctx: '商议收费公路' },
  { ru: '— Можно аренду продлить на 2 суток?\n— Можно, но продлевайте заранее, на месте может выйти дороже.', zh: '—租期能延长两天吗？\n—可以，但请提前续，当场办可能更贵。', en: '—Can I extend the rental by two days?\n—Yes, but extend in advance; doing it on the spot may cost more.', ctx: '申请延长租期', say: '— Можно аренду продлить на двое суток?\n— Можно, но продлевайте заранее, на месте может выйти дороже.' },
  { ru: 'На зимней дороге держи дистанцию и ни в коем случае не жми резко на тормоз.', zh: '冬天开车要保持车距，千万别猛踩刹车。', en: 'On a winter road keep your distance and never slam on the brakes.', ctx: '冰雪路面驾驶' },
  { ru: 'Номер я бронировала без завтрака, потому что вокруг полно нормальных кафе.', zh: '我订房时没带早餐，因为周围像样的咖啡馆有的是。', en: 'I booked the room without breakfast because there are plenty of decent cafés around.', ctx: '订房选择餐食' },
  { ru: '— У вас забронирован номер на фамилию Орлов?\n— Сейчас проверю... да, стандарт на две ночи, всё верно?', zh: '—您这儿有用奥尔洛夫这个名字订的房吗？\n—我查一下……有的，标准间两晚，对吗？', en: '—Do you have a room booked under the name Orlov?\n—Let me check... yes, a standard for two nights, correct?', ctx: '前台核对预订' },
  { ru: '— Ранний заезд возможен? Я прилетаю в 6 утра.\n— Только при наличии свободных номеров, иначе оставьте багаж и погуляйте.', zh: '—可以提前入住吗？我早上六点就到。\n—有空房才行，不然您先把行李寄下，出去逛逛。', en: '—Is early check-in possible? I land at six in the morning.\n—Only if rooms are free; otherwise leave your bags and go for a walk.', ctx: '申请提前入住', say: '— Ранний заезд возможен? Я прилетаю в шесть утра.\n— Только при наличии свободных номеров, иначе оставьте багаж и погуляйте.' },
  { ru: '— Дайте, пожалуйста, ключ от триста восьмого.\n— Вот ваша карта, завтрак с семи до десяти на втором этаже.\n— А Wi-Fi там какой?\n— Пароль на карточке, она вместе с ключом.', zh: '—请给我308房的钥匙。\n—这是您的房卡，早餐七点到十点，在二楼。\n—Wi-Fi是哪个？\n—密码在卡片上，和房卡在一起。', en: '—The key to room 308, please.\n—Here\'s your card. Breakfast is seven to ten on the second floor.\n—What\'s the Wi-Fi?\n—The password is on the card with the key.', ctx: '办理入住手续', say: '— Дайте, пожалуйста, ключ от триста восьмого.\n— Вот ваша карта, завтрак с семи до десяти на втором этаже.\n— А вай-фай там какой?\n— Пароль на карточке, она вместе с ключом.' },
  { ru: 'Какая здесь слышимость, будто сосед разговаривает прямо у меня над ухом!', zh: '这隔音也太差了，邻居说话就像在我耳朵边上！', en: 'The sound insulation here is terrible; it\'s like the neighbour is talking right in my ear!', ctx: '抱怨隔音差' },
  { ru: '— Простите, в номере не работает фен и нет полотенец.\n— Извините, сейчас горничная всё принесёт, пять минут.', zh: '—打扰一下，房间里电吹风坏了，毛巾也没有。\n—抱歉，服务员马上都送来，五分钟。', en: '—Excuse me, the hairdryer doesn\'t work and there are no towels in the room.\n—Sorry, the maid will bring everything right away, five minutes.', ctx: '客房报修要物' },
  { ru: 'Уходя, повесьте на ручку табличку «не беспокоить», если не нужна уборка.', zh: '出门时如果不需要打扫，请把“请勿打扰”的牌子挂在门把手上。', en: 'When you leave, hang the \'do not disturb\' sign on the handle if you don\'t need cleaning.', ctx: '请勿打扰提示' },
  { ru: '— Не подскажете ли, до скольких работает ваш бассейн?\n— До десяти вечера, полотенца выдают на входе.', zh: '—请问你们的游泳池开放到几点？\n—到晚上十点，毛巾在入口处领取。', en: '—Could you tell me how late your pool is open?\n—Until ten p.m.; towels are provided at the entrance.', ctx: '询问泳池时间' },
  { ru: '— Можно поздний выезд? Хотя бы до двух часов дня.\n— До двух не получится, но до часа продлим бесплатно.', zh: '—可以延迟退房吗？至少到下午两点。\n—两点不行，但可以免费延到一点。', en: '—Is a late checkout possible? At least until two p.m.\n—Two won\'t work, but we\'ll extend to one for free.', ctx: '申请延迟退房' },
  { ru: '— У нас в номере всю ночь кто-то шумел за стеной!\n— Приносим извинения, давайте переселим вас в другой номер.\n— А он не хуже этого будет?\n— Тот же этаж и такая же категория, идёмте, посмотрите.', zh: '—我们隔壁吵了一整夜！\n—非常抱歉，我们给您换到另一个房间。\n—不会比这间差吧？\n—同楼层同档次，走，您看看。', en: '—Someone behind our wall made noise all night!\n—We apologise; let\'s move you to another room.\n—It won\'t be worse than this one?\n—Same floor and same category; come and take a look.', ctx: '投诉要求换房' },
  { ru: '— Продлите номер ещё на 1 сутки, пожалуйста.\n— Хорошо, доплатите три тысячи на ресепшне.', zh: '—请把房间再续一天。\n—好的，请到前台补三千卢布。', en: '—Please extend the room one more night.\n—Fine; pay three thousand at reception.', ctx: '临时延长住宿', say: '— Продлите номер ещё на одни сутки, пожалуйста.\n— Хорошо, доплатите три тысячи на ресепшне.' },
  { ru: '— Скажите, а камера хранения у вас есть? Мы выезжаем, а поезд вечером.\n— Есть, бесплатно для гостей, оставляйте чемоданы внизу.', zh: '—请问有行李寄存处吗？我们要退房，可火车晚上才走。\n—有，对住客免费，箱子放楼下就行。', en: '—Tell me, do you have luggage storage? We\'re checking out but our train is in the evening.\n—Yes, free for guests; leave your suitcases downstairs.', ctx: '退房寄存行李' },
  { ru: 'При выселении не забудьте сдать карту от номера, иначе её стоимость вычтут.', zh: '退房时别忘了交房卡，不然会扣除房卡的费用。', en: 'At checkout don\'t forget to return your room card, or its cost will be deducted.', ctx: '退房交还房卡' },
  { ru: '— Здравствуйте, это обслуживание номеров?\n— Да, что желаете заказать?\n— Два кофе и что-нибудь перекусить, минут через сорок можно?\n— Конечно, записываю: триста двадцатый номер, верно?', zh: '—您好，是客房送餐吗？\n—是的，您想点什么？\n—两杯咖啡，再随便来点吃的，四十分钟左右能送到吗？\n—当然，我记一下：320房，对吗？', en: '—Hello, room service?\n—Yes, what would you like to order?\n—Two coffees and something to eat; in about forty minutes?\n—Of course. Let me note: room 320, right?', ctx: '电话点餐送房' },
  { ru: '— У меня из мини-бара взята вода, это уже в счёте?\n— Да, мини-бар автоматически добавляется, посмотрите чек.', zh: '—我拿了迷你吧的水，已经算在账单里了吗？\n—对，迷你吧费用自动计入，您看下账单。', en: '—I took water from the minibar; is it already on the bill?\n—Yes, minibar charges are added automatically; check the receipt.', ctx: '核对迷你吧消费' },
  { ru: 'Чемодан на колёсиках с лёгкостью катится даже по брусчатке.', zh: '带轮子的行李箱在鹅卵石路上也能轻松推着走。', en: 'A wheeled suitcase rolls easily even over cobblestones.', ctx: '评价行李箱轮子' },
  { ru: '— Ваш чемодан весит 23 кг, это в пределах нормы.\n— Отлично, а сумка считается ручной кладью?', zh: '—您的箱子重二十三公斤，在免费额度内。\n—太好了，这个包算随身行李吗？', en: '—Your suitcase weighs 23 kg; that\'s within the allowance.\n—Great. Does the bag count as carry-on?', ctx: '值机称重行李', say: '— Ваш чемодан весит двадцать три килограмма, это в пределах нормы.\n— Отлично, а сумка считается ручной кладью?' },
  { ru: '— Зачем ты всё так плотно набила? Молния же разойдётся.\n— Не разойдётся, я ещё сверху ремнём затяну.', zh: '—你干吗塞这么满？拉链会崩开的。\n—崩不了，我再用束带勒紧。', en: '—Why did you pack it so full? The zipper will burst.\n—It won\'t; I\'ll tighten the strap over it too.', ctx: '整理打包行李' },
  { ru: 'Вот растяпа — оставила в самолёте и телефон, и наушники!', zh: '真是个马大哈，把手机和耳机都落在飞机上了！', en: 'What a scatterbrain — she left both her phone and headphones on the plane!', ctx: '落东西在机上' },
  { ru: '— Простите, я, кажется, перепутал чемоданы, мой такой же чёрный.\n— Не волнуйтесь, давайте вернёмся к ленте, ваш, скорее всего, ещё там.\n— На моём бирка с именем есть, сразу узнаю.', zh: '—对不起，我好像拿错箱子了，我的也是一样的黑箱子。\n—别着急，咱们回传送带那儿，您的箱子八成还在。\n—我的箱子上有姓名牌，一眼就能认出来。', en: '—Excuse me, I seem to have swapped suitcases; mine is the same black one.\n—Don\'t worry, let\'s go back to the carousel; yours is probably still there.\n—Mine has a name tag; I\'ll recognise it at once.', ctx: '拿错行李处理' },
  { ru: 'Все жидкости надо перелить в маленькие бутылочки и убрать в прозрачный пакет.', zh: '所有液体都得倒进小瓶子，再装进透明袋子里。', en: 'All liquids must be poured into small bottles and put in a transparent bag.', ctx: '液体随身规定' },
  { ru: '— У меня тут пузырёк на 120 мл, он не пройдёт?\n— Нет, в ручную кладь можно не больше 100 мл, забирать придётся.', zh: '—我这儿有瓶一百二十毫升的，不能带吗？\n—不行，随身液体不能超过一百毫升，只能扔掉。', en: '—I have a 120 ml bottle here; won\'t it pass?\n—No; carry-on liquids must be under 100 ml, so it\'ll have to be surrendered.', ctx: '液体容量超标', say: '— У меня тут пузырёк на сто двадцать миллилитров, он не пройдёт?\n— Нет, в ручную кладь можно не больше ста миллилитров, забирать придётся.' },
  { ru: '— Кошелёк, паспорт и телефон держи в сумке через плечо, а не в рюкзаке.\n— Поняла, его же не снимешь незаметно, спасибо за совет.', zh: '—钱包、护照和手机放在斜挎包里，别放双肩包。\n—明白，斜挎包没法被人神不知鬼不觉地摘掉，谢谢提醒。', en: '—Keep your wallet, passport, and phone in a shoulder bag, not your backpack.\n—Got it; no one can slip it off unnoticed. Thanks for the tip.', ctx: '防盗放贵重物' },
  { ru: '— Смотри, у чемодана колесо отвалилось! Что делать?\n— Спокойно, сейчас в дьюти-фри купим сумку попрочнее и переложим.\n— Это же сколько доплатить придётся?\n— Да не переживай ты, разберёмся на месте, давай вещи собирать.', zh: '—你看，行李箱轮子掉了！怎么办？\n—别急，待会儿在免税店买个结实点儿的袋子，把东西挪过去。\n—那又得多花多少钱啊？\n—你别担心，到时候再说，先收拾东西吧。', en: '—Look, a wheel came off the suitcase! What do we do?\n—Easy; we\'ll buy a sturdier bag in duty-free and transfer everything.\n—How much extra will that cost?\n—Don\'t worry, we\'ll sort it out there; let\'s gather the things.', ctx: '箱子损坏应急' },
  { ru: '— Не знаете ли, где тут тележки для багажа?\n— У входа, но они, по-моему, только за монетку.', zh: '—请问行李车在哪儿？\n—入口处，不过我记得要投币才能用。', en: '—Do you happen to know where the luggage trolleys are?\n—By the entrance, but I think they need a coin.', ctx: '寻找行李推车' },
  { ru: 'Если чемодан не закрывается, значит, ты просто взяла слишком много вещей.', zh: '箱子要是关不上，说明你只是东西带太多了。', en: 'If the suitcase won\'t close, it just means you\'ve packed too many things.', ctx: '调侃行李过多' },
  { ru: '— Обмотаем чемодан плёнкой? Это 300 рублей стоит.\n— Давай, зато его не вскроют по дороге и ручки целее будут.', zh: '—给箱子缠层膜吧？要三百卢布。\n—缠吧，至少路上不会被撬开，提手也不容易坏。', en: '—Shall we wrap the suitcase in film? It costs 300 rubles.\n—Let\'s; at least it won\'t be opened in transit and the handles will survive.', ctx: '行李缠膜打包', say: '— Обмотаем чемодан плёнкой? Это триста рублей стоит.\n— Давай, зато его не вскроют по дороге и ручки целее будут.' },
  { ru: 'Как же я удачно засунула пауэрбанк в ручную кладь, а не в багаж!', zh: '幸好我把充电宝塞在了随身行李里，没托运！', en: 'Good thing I stuffed the power bank in my carry-on rather than my checked bag!', ctx: '庆幸充电宝随身' },
  { ru: '— У меня прямо в метро вытащили кошелёк, представляешь?\n— Вот подлецы! Надо сразу карты заблокировать и заявление написать.', zh: '—你敢信，我钱包在地铁里直接被人摸走了。\n—这帮混蛋！得马上挂失银行卡，再去报案。', en: '—Someone lifted my wallet right on the metro, can you imagine?\n—What scoundrels! Block the cards right away and file a report.', ctx: '钱包失窃应对' },
  { ru: '— Алло, это бюро находок? Я вчера оставила в камере хранения свёрток.\n— Какой номер ячейки у вас был?\n— Семнадцатый, я забрала чемодан, а пакет забыла.\n— Приезжайте после 8:00, найдём и выдадим по паспорту.', zh: '—喂，是失物招领吗？我昨天在寄存处落了一个包裹。\n—您当时用的是几号柜？\n—十七号，我取了箱子，却把袋子忘了。\n—请八点后来，我们找出来凭护照还给您。', en: '—Hello, lost property? I left a parcel in the locker storage yesterday.\n—What locker number did you have?\n—Seventeen; I took my suitcase but forgot the bag.\n—Come after eight; we\'ll find it and release it with your passport.', ctx: '联系失物招领', say: '— Алло, это бюро находок? Я вчера оставила в камере хранения свёрток.\n— Какой номер ячейки у вас был?\n— Семнадцатый, я забрала чемодан, а пакет забыла.\n— Приезжайте после восьми часов, найдём и выдадим по паспорту.' },
  { ru: 'Какая глухая пробка, мы стоим уже целых сорок минут!', zh: '这堵得也太死了，我们已经停了整整四十分钟！', en: 'What total gridlock; we\'ve been stationary for a full forty minutes!', ctx: '遭遇严重堵车' },
  { ru: '— Не знаете ли, почему всё стоит? Авария впереди?\n— Говорят, фура развернулась и перекрыла обе полосы.', zh: '—您知道为什么都不动吗？前面出事了？\n—听说是一辆大货车横过来，把两条车道都堵死了。', en: '—Do you know why everything\'s stopped? An accident ahead?\n—They say a lorry turned across and blocked both lanes.', ctx: '打听堵车原因' },
  { ru: '— Живее собирайся, выходить надо было ещё десять минут назад!\n— Бегу-бегу, только ключи никак не найду.', zh: '—快点收拾，十分钟前就该出门了！\n—来了来了，就是钥匙怎么也找不着。', en: '—Get moving, we should have left ten minutes ago!\n—Coming, coming; I just can\'t find the keys.', ctx: '催促赶紧出门' },
  { ru: 'Вышли бы мы на пятнадцать минут раньше, ехали бы сейчас по свободной дороге.', zh: '我们要是早十五分钟出门，这会儿就在畅通的路上了。', en: 'If we\'d left fifteen minutes earlier, we\'d be driving on a clear road right now.', ctx: '后悔出门太晚' },
  { ru: '— Сколько времени? Я на совещание к десяти.\n— Без двадцати десять, а мы ещё даже не выехали.\n— Это катастрофа, звони, предупреди, что опоздаю.\n— Уже звоню... не отвечают, напишу в рабочий чат.', zh: '—几点了？我十点要开会。\n—差二十分钟十点，我们还没出门呢。\n—完了，快打电话说我会迟到。\n—我正在打……没人接，我发工作群里吧。', en: '—What time is it? I have a meeting at ten.\n—Twenty to ten, and we haven\'t even left.\n—This is a disaster; call ahead and say I\'ll be late.\n—I\'m calling... no answer. I\'ll write in the work chat.', ctx: '赶会议怕迟到' },
  { ru: '— На этом светофоре всегда такой ад?\n— По пятницам вообще труба, все ломятся за город.', zh: '—这个红绿灯总是这么夸张吗？\n—周五简直要命，大家都拼命往城外赶。', en: '—Is it always this hellish at this light?\n—Fridays are a nightmare; everyone piles out of the city.', ctx: '吐槽周五晚高峰' },
  { ru: '— Долго ты обычно до работы добираешься?\n— В среднем час с небольшим, смотря какая дорога.', zh: '—你平时上班路上要多久？\n—平均一个多小时，看路况。', en: '—How long does it usually take you to get to work?\n—A little over an hour on average, depending on the roads.', ctx: '通勤时间估算' },
  { ru: '— Может, бросим машину у метро и спустимся вниз?\n— Отличная мысль, в подземке это всё равно будет быстрее.', zh: '—要不把车停在地铁口，咱们坐地铁吧？\n—好主意，坐地铁怎么都比现在快。', en: '—Maybe we leave the car by the metro and go underground?\n—Great idea; the tube will be faster anyway.', ctx: '弃车改乘地铁' },
  { ru: '— Если поедем дворами, насколько это быстрее?\n— Минут на десять, но дворы тоже забиты, я проверял.', zh: '—穿小区走能快多少？\n—快十分钟吧，不过小区里也堵满了，我看过。', en: '—If we cut through the courtyards, how much faster is it?\n—Ten minutes, but the courtyards are packed too; I checked.', ctx: '研究绕行方案' },
  { ru: '— Пап, мы точно успеем на самолёт?\n— Если больше нигде не встанем, должны, но время впритык.\n— А регистрация когда заканчивается?\n— За сорок минут до вылета. Всё, молчим, я сосредоточился.', zh: '—爸，我们真能赶上飞机吗？\n—要是别处不再堵，应该能，但时间很紧。\n—值机什么时候截止？\n—起飞前四十分钟。行了，都别说话，我得专心开。', en: '—Dad, are we definitely going to catch the plane?\n—If nothing else stops us, yes, but it\'s tight.\n—When does check-in close?\n—Forty minutes before departure. Right, quiet now; I need to concentrate.', ctx: '全家赶飞机' },
  { ru: '— На спидометре уже 110 км/ч, ты с ума сошёл?\n— Успокойся, здесь разрешено сто десять, я не нарушаю.', zh: '—时速表都一百一十公里了，你疯了吗？\n—放心，这儿限速一百一，我没违章。', en: '—The speedometer already shows 110 km/h; have you lost your mind?\n—Relax; 110 is allowed here, I\'m not breaking the law.', ctx: '高速超速争论', say: '— На спидометре уже сто десять километров в час, ты с ума сошёл?\n— Успокойся, здесь разрешено сто десять, я не нарушаю.' },
  { ru: '— Электрички сегодня ходят? Снег какой валит.\n— Ходят, но интервалы увеличили, придётся помёрзнуть.', zh: '—今天市郊铁路还开吗？雪下得这么大。\n—开，但班次间隔拉长了，得挨会儿冻。', en: '—Are the commuter trains running today in this snow?\n—They are, but intervals have been increased; you\'ll have to freeze a while.', ctx: '暴雪确认车次' },
  { ru: 'Предупреди босса, что задержишься, пусть начинают совещание без тебя.', zh: '提前跟老板说一声你会晚到，让他们先开会，别等你。', en: 'Warn your boss you\'ll be late; have them start the meeting without you.', ctx: '提前打招呼报备' },
  { ru: '— Последняя электричка во сколько? Не хочется ночевать на вокзале.\n— В 23:40, а касса, между прочим, закрывается раньше.\n— Тогда берём билет сейчас и бежим за кофе.', zh: '—末班市郊列车几点？我可不想在火车站过夜。\n—二十三点四十，对了，售票处关得比这早。\n—那咱们现在就买票，再去买咖啡。', en: '—When\'s the last commuter train? I don\'t fancy sleeping at the station.\n—23:40, and the ticket office closes earlier, by the way.\n—Then let\'s get tickets now and run for coffee.', ctx: '赶末班小火车', say: '— Последняя электричка во сколько? Не хочется ночевать на вокзале.\n— В двадцать три сорок, а касса, между прочим, закрывается раньше.\n— Тогда берём билет сейчас и бежим за кофе.' },
  { ru: 'Тише едешь — дальше будешь, не гони, пожалуйста, мне страшно!', zh: '慢点开稳当，求你别飙车，我害怕！', en: 'More haste, less speed — please don\'t race; you\'re scaring me!', ctx: '劝阻开快车' },
]

// ── 购物消费 / Shopping / Покупки ──
const SHOP: Phrase[] = [
  { ru: 'Скажите, пожалуйста, сколько стоит этот кожаный ремень?', zh: '请问这条皮带多少钱？', en: 'Excuse me, how much is this leather belt?', ctx: '询问价格' },
  { ru: '— Можно подешевле? Беру сразу две вещи.\n— Хорошо, сделаю скидку десять процентов, но только сегодня.', zh: '—能便宜点吗？我一次拿两件。\n—好吧，给您让十个百分点，但只限今天。', en: '—Can you do better? I\'ll take two items right now.\n—All right, I\'ll give you ten percent off, but only today.', ctx: '讨价还价' },
  { ru: 'Цена указана на ценнике — 1 490 рублей.', zh: '价格在价签上标着：1490卢布。', en: 'The price is shown on the tag: 1,490 rubles.', ctx: '查看价签', say: 'Цена указана на ценнике — тысяча четыреста девяносто рублей.' },
  { ru: '— У вас действуют скидки по карте покупателя?\n— Да, по карте цена будет на пятнадцать процентов ниже.\n— Тогда давайте оформим карту, она бесплатная?', zh: '—你们这儿顾客卡有折扣吗？\n—有的，持卡价便宜百分之十五。\n—那办一张吧，卡是免费的吗？', en: '—Do you give discounts with a customer card?\n—Yes, with the card the price is fifteen percent lower.\n—Then let\'s get one, is it free?', ctx: '会员折扣' },
  { ru: 'Какой крошечный флакон, а стоит почти 5 000 рублей!', zh: '瓶子这么小，居然要将近5000卢布！', en: 'Such a tiny bottle, yet it costs almost 5,000 rubles!', ctx: '感叹价高', say: 'Какой крошечный флакон, а стоит почти пять тысяч рублей!' },
  { ru: '— Если я найду дешевле в другом магазине, вы снизите цену?\n— Принесите их ценник, и мы продадим ещё дешевле.', zh: '—要是我在别的店找到更便宜的，你们能降价吗？\n—把他们的价签拿来，我们会卖得更便宜。', en: '—If I find it cheaper in another shop, will you match it?\n—Bring their price tag and we\'ll sell it even cheaper.', ctx: '比价议价' },
  { ru: '— Посчитайте всё вместе, пожалуйста.\n— Секунду... выходит восемь тысяч сто двадцать.', zh: '—请把所有东西算在一起。\n—稍等……一共是八千一百二十。', en: '—Can you add it all up together, please?\n—One moment... it comes to eight thousand one hundred twenty.', ctx: '要求核算' },
  { ru: '— Сколько вы просите за этот чайный сервиз?\n— Шесть тысяч, это ручная работа.\n— Четыре тысячи, больше у меня с собой нет.\n— Давайте сойдёмся на пяти тысячах, и я добавлю салфетки в подарок.', zh: '—这套茶具您要价多少？\n—六千，这可是手工的。\n—四千，我身上没带更多了。\n—那就五千成交，我再送您几块餐巾。', en: '—How much are you asking for this tea set?\n—Six thousand, it\'s handmade.\n—Four thousand, I don\'t have more on me.\n—Let\'s meet at five thousand and I\'ll throw in some napkins.', ctx: '市场砍价' },
  { ru: 'Я бы взял этот плед, если бы он стоил хотя бы на тысячу дешевле.', zh: '这条毯子要是能再便宜一千，我就买了。', en: 'I\'d take this blanket if it cost at least a thousand less.', ctx: '条件议价' },
  { ru: '— Когда начинается распродажа зимних курток?\n— Обещают со следующей недели, цены упадут вдвое.', zh: '—冬季外套什么时候开始打折？\n—据说下周起，价格会降一半。', en: '—When does the winter jacket sale start?\n—They say next week, prices will drop by half.', ctx: '等待打折' },
  { ru: 'На эту коллекцию скидка 30%, а на прошлогоднюю — все пятьдесят.', zh: '这个系列打七折，去年款干脆半价。', en: 'This collection is 30% off, and last year\'s line is a full fifty.', ctx: '折扣力度', say: 'На эту коллекцию скидка тридцать процентов, а на прошлогоднюю — все пятьдесят.' },
  { ru: '— Это окончательная цена или торг уместен?\n— Ну для вас могу уступить пару сотен.\n— Триста, и мы договорились?', zh: '—这是最终价还是可以讲价？\n—好吧，给您让个两三百。\n—让三百，咱们就成交？', en: '—Is that the final price or is haggling welcome?\n—Well, for you I can knock off a couple hundred.\n—Three hundred and we\'ve got a deal?', ctx: '讨价还价' },
  { ru: '— Скажите, а доставка входит в эту сумму?\n— Нет, её считают отдельно по километражу.', zh: '—请问这个金额里包含送货吗？\n—不包含，运费按里程另算。', en: '—Tell me, does this price include delivery?\n—No, it\'s calculated separately by distance.', ctx: '价格包含' },
  { ru: '— Берёте ли вы оптом? Нам нужно около двадцати одинаковых кружек.\n— От десяти штук дам оптовую цену, по сто восемьдесят рублей за штуку.', zh: '—你们做批发吗？我们需要大约二十个一样的杯子。\n—十个以上给批发价，每个一百八十卢布。', en: '—Do you sell wholesale? We need about twenty identical mugs.\n—From ten pieces up I\'ll give the wholesale price, 180 rubles each.', ctx: '批发询价' },
  { ru: '— Ничего себе цена! За эти деньги три таких купить можно.\n— Зато смотрите, какая выделка, это же настоящая Италия.', zh: '—这价格可真够意思！这钱能买三个这样的。\n—可您看这做工，这可是正宗意大利货。', en: '—Wow, what a price! You could buy three of these for that money.\n—But look at the craftsmanship, this is genuine Italian make.', ctx: '嫌贵回应' },
  { ru: 'Покажите, пожалуйста, эти джинсы в размере сорок восемь.', zh: '请给我看看48码的这条牛仔裤。', en: 'Please show me these jeans in size forty-eight.', ctx: '询问尺码' },
  { ru: '— Как вам сидит пиджак?\n— В плечах жмёт, а рукава будто коротковаты.', zh: '—西装上衣您穿着怎么样？\n—肩膀处有点紧，袖子好像也偏短。', en: '—How does the jacket fit?\n—It\'s tight across the shoulders and the sleeves feel a bit short.', ctx: '试穿反馈' },
  { ru: 'Мне нужен 46-й размер, не меньше.', zh: '我要46码，不能再小了。', en: 'I need size 46, no smaller.', ctx: '报告尺码', say: 'Мне нужен сорок шестой размер, не меньше.' },
  { ru: '— Где у вас примерочные кабины?\n— Прямо за колонной, проходите.\n— А можно с собой взять два размера для сравнения?', zh: '—试衣间在哪儿？\n—就在柱子后面，您请。\n—我能拿两个尺码进去对比吗？', en: '—Where are your fitting rooms?\n—Right behind the column, go ahead.\n—Can I take two sizes in to compare?', ctx: '去试衣间' },
  { ru: '— Ну как, ботинки не жмут в пальцах?\n— Вроде нет, просто чуть натирают пятку.', zh: '—怎么样，鞋头夹脚吗？\n—好像不夹，就是后跟有点磨。', en: '—Well, do the boots pinch your toes?\n—Not really, they just rub my heel a little.', ctx: '试鞋感受' },
  { ru: '— Какой размер вам принести — S или M?\n— Давайте оба, сравню прямо в зале.', zh: '—给您拿哪个码，S还是M？\n—两个都拿吧，我就在厅里比比。', en: '—Which size should I bring you, S or M?\n—Bring both, I\'ll compare them right here.', ctx: '选择尺码', say: '— Какой размер вам принести — эс или эм?\n— Давайте оба, сравню прямо в зале.' },
  { ru: 'Не знаете, эта модель маломерит или идёт размер в размер?', zh: '请问这款是偏小，还是码数正合适？', en: 'Do you know if this style runs small or true to size?', ctx: '尺码咨询' },
  { ru: '— Юбка застегивается, но дышать трудно.\n— Возьмите на размер больше, ткань почти не тянется.\n— А такой цвет есть в пятидесятом?\n— К сожалению, остался только сорок шестой и сорок восьмой.', zh: '—裙子扣得上，但喘不过气。\n—拿大一码吧，这料子几乎没弹性。\n—这个颜色有50码吗？\n—抱歉，只剩46和48码了。', en: '—The skirt fastens, but I can barely breathe.\n—Take one size up, the fabric barely stretches.\n—Do you have this color in a size fifty?\n—Unfortunately only forty-six and forty-eight are left.', ctx: '换码试穿' },
  { ru: '— На какую ногу сначала примерить?\n— На левую, она у меня чуть полнее.', zh: '—先试哪只脚？\n—左脚，我的左脚稍宽一点。', en: '—Which foot should I try first?\n—The left one, it\'s slightly wider.', ctx: '建议试穿' },
  { ru: '— У вас есть размерная таблица? Боюсь ошибиться с сантиметрами.\n— Вот, смотрите: обхват груди восемьдесят восемь — это сорок четвёртый.', zh: '—你们有尺码表吗？我怕厘米数搞错。\n—您看：胸围八十八对应44码。', en: '—Do you have a size chart? I\'m afraid I\'ll get the centimeters wrong.\n—Here, look: chest eighty-eight is a size forty-four.', ctx: '对照尺码表' },
  { ru: 'Длина стельки у меня 27 сантиметров.', zh: '我的鞋垫长度是27厘米。', en: 'My insole length is 27 centimeters.', ctx: '脚长尺寸', say: 'Длина стельки у меня двадцать семь сантиметров.' },
  { ru: '— Свитер сидит свободно, не мешковато?\n— В самый раз, даже под мышками не тянет.', zh: '—毛衣穿着宽松，不会显垮吧？\n—刚刚好，腋下也不紧绷。', en: '—Does the sweater fit loosely without looking baggy?\n—It\'s just right, it doesn\'t even pull under the arms.', ctx: '确认合身' },
  { ru: '— Можно я ещё похожу по залу в этих кроссовках?\n— Конечно, так и проверяют.\n— Хм, палец почти упирается... наверное, нужен следующий размер.', zh: '—我能穿着这双运动鞋在厅里走走吗？\n—当然，大家都这么试。\n—嗯，脚趾快顶到了……可能得要大一码。', en: '—Can I walk around the store in these trainers?\n—Sure, that\'s how you test them.\n—Hmm, my toe almost touches the end... I probably need the next size up.', ctx: '犹豫尺码' },
  { ru: 'Если бы не был велик в поясе, я бы его оставила.', zh: '要不是腰太肥，我就留下它了。', en: 'If it weren\'t too big at the waist, I\'d keep it.', ctx: '尺码不合' },
  { ru: '— Вы не могли бы принести такой же, но на размер шире?\n— Сейчас посмотрю на складе, подождите минутку.', zh: '—能不能拿一件一样的，但大一码？\n—我去仓库看看，请稍等。', en: '—Could you bring the same one but a size wider?\n—I\'ll check the stockroom, give me a moment.', ctx: '请求换码' },
  { ru: 'У вас есть такая же футболка, только не белая, а тёмно-синяя?', zh: '有同款T恤吗？不要白色，要藏蓝色。', en: 'Do you have the same T-shirt, not white but navy blue?', ctx: '询问颜色' },
  { ru: '— Какой оттенок сейчас в моде — бежевый или фисташковый?\n— Беж смотрится дороже и сочетается почти со всем.', zh: '—现在流行什么色调，米色还是开心果绿？\n—米色显档次，而且几乎百搭。', en: '—Which shade is in fashion now, beige or pistachio?\n—Beige looks more expensive and goes with almost everything.', ctx: '流行颜色' },
  { ru: 'Этот цвет меня полнит, дайте что-нибудь поспокойнее.', zh: '这颜色显胖，给我个素净点的。', en: 'This color makes me look bigger, give me something calmer.', ctx: '颜色显胖' },
  { ru: '— Платье красивое, но вырез слишком глубокий.\n— Есть похожий фасон с закрытым воротником, показать?\n— Да, и желательно без блёсток.', zh: '—裙子很漂亮，但领口太低了。\n—有款类似的，领子不低，要看看吗？\n—好，最好不要亮片。', en: '—The dress is lovely, but the neckline is too low.\n—There\'s a similar style with a high collar, shall I show it?\n—Yes, and preferably without sequins.', ctx: '讨论款式' },
  { ru: '— Вам нравится классика или что-то спортивное?\n— Скорее кэжуал, но без мешковатости.', zh: '—您喜欢经典款还是运动风？\n—偏休闲一点，但不要松松垮垮。', en: '—Do you prefer classics or something sporty?\n—More casual, but not baggy.', ctx: '风格偏好' },
  { ru: '— Тебе не надоела пастель?\n— Наоборот, от неё глаза отдыхают, такая нежная гамма.', zh: '—你不厌倦浅淡色吗？\n—恰恰相反，看着它眼睛都放松，色调多柔和。', en: '—Aren\'t you tired of pastels?\n—On the contrary, they rest the eyes, such a soft palette.', ctx: '赞美色调' },
  { ru: '— Это новая коллекция или прошлый сезон?\n— Новая, завезли только вчера вечером.', zh: '—这是新系列还是往季款？\n—新系列，昨天晚上刚到的货。', en: '—Is this the new collection or last season\'s?\n—It\'s new, it only arrived yesterday evening.', ctx: '新款旧款' },
  { ru: 'Не подскажете, эта куртка однотонная или в мелкую клетку?', zh: '请问这件外套是纯色的还是小格子的？', en: 'Could you tell me if this jacket is plain or in a small check?', ctx: '图案询问' },
  { ru: '— Хочу что-то на каждый день, но не скучное.\n— Примерьте этот плащ прямого кроя.\n— Цвет приятный, а пояс не выглядит старомодно?\n— Наоборот, он как раз подчёркивает талию.', zh: '—想要件日常穿的，但别太乏味。\n—试试这件直筒风衣。\n—颜色不错，腰带会不会显老气？\n—正相反，它刚好能突出腰线。', en: '—I want something for every day, but not boring.\n—Try this straight-cut coat.\n—Nice color, but doesn\'t the belt look old-fashioned?\n—On the contrary, it accentuates the waist.', ctx: '挑选款式' },
  { ru: 'Возьму обе расцветки — полоску и однотонную.', zh: '两种花色我都要——条纹和纯色。', en: 'I\'ll take both colorways, the striped and the plain one.', ctx: '决定颜色' },
  { ru: '— Артикул на этикетке начинается на B, верно?\n— Да, значит, это базовая линейка.', zh: '—标签上的货号以B开头，对吧？\n—对，说明这是基础系列。', en: '—The item code on the label starts with B, right?\n—Yes, which means it\'s the basic line.', ctx: '辨认系列', say: '— Артикул на этикетке начинается на би, верно?\n— Да, значит, это базовая линейка.' },
  { ru: '— Вам какой шарф показать — с витрины?\n— Да, вон тот, с геометрическим узором.', zh: '—给您拿哪条围巾，橱窗里那条吗？\n—对，就是那条几何图案的。', en: '—Which scarf should I show you, the one in the window?\n—Yes, that one with the geometric pattern.', ctx: '指认款式' },
  { ru: '— На солнце эта ткань не выцветает?\n— Нет, она обработана специальной пропиткой.', zh: '—这布料在太阳下不会褪色吗？\n—不会，它经过特殊浸液处理。', en: '—Won\'t this fabric fade in the sun?\n—No, it\'s treated with a special coating.', ctx: '担心褪色' },
  { ru: '— Чёрный слишком официальный, а серый какой-то невзрачный.\n— Тогда посмотрите изумрудный, он освежает.\n— И правда, беру изумрудный.', zh: '—黑色太正式，灰色又有点不起眼。\n—那看看祖母绿，很提气色。\n—也是，就要祖母绿。', en: '—Black is too formal and grey looks somehow dull.\n—Then try emerald, it freshens you up.\n—You\'re right, I\'ll take the emerald.', ctx: '换个颜色' },
  { ru: 'Я бы выбрала красный, если бы он не был таким кричащим.', zh: '要不是红色这么扎眼，我就选它了。', en: 'I\'d choose red if it weren\'t so loud.', ctx: '犹豫颜色' },
  { ru: 'Я расплачусь картой, если можно.', zh: '可以的话我刷卡。', en: 'I\'ll pay by card, if I may.', ctx: '刷卡支付' },
  { ru: '— Вы принимаете наличные? Карта что-то не читается.\n— Да, но мелочью сдачи может не быть.', zh: '—你们收现金吗？卡好像刷不出来。\n—收，不过可能没零钱找。', en: '—Do you take cash? My card won\'t read for some reason.\n—Yes, but I may not have small change.', ctx: '现金支付' },
  { ru: 'Здесь можно оплатить по QR-коду через телефон?', zh: '这儿能用手机扫码支付吗？', en: 'Can I pay by QR code with my phone here?', ctx: '扫码支付', say: 'Здесь можно оплатить по куар коду через телефон?' },
  { ru: '— С вас три тысячи двести.\n— Простите, а терминал поддерживает бесконтактную оплату?\n— Да, просто приложите телефон сюда.', zh: '—一共三千二百。\n—请问，终端支持非接触支付吗？\n—支持，把手机贴这儿就行。', en: '—That\'s three thousand two hundred.\n—Excuse me, does the terminal support contactless payment?\n—Yes, just hold your phone here.', ctx: '非接触支付' },
  { ru: 'Не подскажете, можно ли разбить платёж на несколько месяцев?', zh: '请问能把付款分几个月还吗？', en: 'Could you tell me whether the payment can be split over several months?', ctx: '分期付款' },
  { ru: '— У меня только пятитысячная, найдётся сдача?\n— Сейчас наберу, подождите секундочку.', zh: '—我只有五千的大钞，找得开吗？\n—我这就凑，请稍等一下。', en: '—I only have a five-thousand note, do you have change?\n—I\'ll gather it now, just a second.', ctx: '找零问题' },
  { ru: '— Введите, пожалуйста, код из четырёх цифр.\n— Три неверные попытки, и карта заблокируется, да?', zh: '—请输入四位数字密码。\n—错三次卡就会被锁，是吧？', en: '—Please enter the four-digit code.\n—Three wrong tries and the card gets blocked, right?', ctx: '输入密码' },
  { ru: '— Хочу оформить рассрочку на этот ноутбук.\n— На шесть или двенадцать месяцев?\n— А переплата будет?\n— На полгода — ноль процентов, нужен только паспорт.', zh: '—这台笔记本我想办分期。\n—分六个月还是十二个月？\n—会有额外利息吗？\n—半年期零利率，只需要护照。', en: '—I\'d like to set up an installment plan for this laptop.\n—For six or twelve months?\n—Will there be any overpayment?\n—For six months it\'s zero percent, you only need your passport.', ctx: '办理分期' },
  { ru: 'Оплата прошла, можете оставить чек себе.', zh: '支付成功了，小票您可以留着。', en: 'The payment went through, you can keep the receipt.', ctx: '支付完成' },
  { ru: '— Почему терминал выдаёт ошибку?\n— Видимо, завис интернет, попробуйте ещё раз через минуту.', zh: '—终端为什么报错？\n—看来是网络卡住了，过一分钟再试。', en: '—Why is the terminal showing an error?\n—The internet seems frozen, try again in a minute.', ctx: '刷卡失败' },
  { ru: 'При оплате наличными сделаю скидку 3%.', zh: '付现金的话我给您优惠3%。', en: 'I\'ll give a 3% discount for cash payment.', ctx: '现金折扣', say: 'При оплате наличными сделаю скидку три процента.' },
  { ru: '— Давайте я переведу вам по номеру телефона.\n— Лучше через систему быстрых платежей, так мгновенно и без комиссии.\n— Хорошо, диктуйте номер.', zh: '—我按手机号给您转账吧。\n—最好走快速支付系统，即时到账还免手续费。\n—行，您报号码。', en: '—Let me transfer it to you by phone number.\n—Better through the fast payments system, it\'s instant and free of charge.\n—OK, dictate the number.', ctx: '转账支付' },
  { ru: '— Если оплата не пройдёт, что делать?\n— Рядом банкомат, снимете наличные и вернётесь.', zh: '—要是支付不成功怎么办？\n—旁边就有取款机，取了现金再回来。', en: '—What if the payment doesn\'t go through?\n—There\'s an ATM nearby, withdraw cash and come back.', ctx: '备选方案' },
  { ru: '— Чек нужен в электронном виде или печатный?\n— Скиньте на почту, бумагу экономлю.', zh: '—小票要电子的还是纸质的？\n—发我邮箱吧，我省点纸。', en: '—Do you want the receipt by email or printed?\n—Send it to my email, I save paper.', ctx: '收据形式' },
  { ru: '— Ой, я случайно оплатил дважды!\n— Не волнуйтесь, вижу обе операции, сейчас сделаю отмену.', zh: '—哎呀，我不小心付了两次！\n—别担心，两笔我都看到了，马上撤销一笔。', en: '—Oh no, I accidentally paid twice!\n—Don\'t worry, I see both transactions, I\'ll cancel one now.', ctx: '重复扣款' },
  { ru: 'Я хочу вернуть этот свитер, он мне не подошёл.', zh: '我想退这件毛衣，不合身。', en: 'I\'d like to return this sweater, it doesn\'t fit me.', ctx: '要求退货' },
  { ru: '— У вас сохранился чек и заводская упаковка?\n— Чек есть, а коробку, кажется, выбросила.', zh: '—小票和原包装都保留了吗？\n—小票在，盒子好像扔掉了。', en: '—Have you kept the receipt and the original packaging?\n—I have the receipt, but I think I threw the box away.', ctx: '退货条件' },
  { ru: 'Товар можно обменять в течение 14 дней.', zh: '商品14天之内可以换货。', en: 'The item can be exchanged within 14 days.', ctx: '退货期限', say: 'Товар можно обменять в течение четырнадцати дней.' },
  { ru: '— Чем могу помочь?\n— Дома обнаружила затяжку на рукаве, хочу поменять.\n— Покажите шов... да, это заводской брак, сейчас оформим.', zh: '—有什么可以帮您？\n—回家发现袖子上有个抽丝，想换一件。\n—我看看接缝……没错，是工厂瑕疵，这就给您办。', en: '—How can I help you?\n—At home I found a pulled thread on the sleeve and I\'d like to exchange it.\n—Show me the seam... yes, it\'s a factory defect, we\'ll process it now.', ctx: '质量换货' },
  { ru: 'Скажите, а нижнее бельё подлежит возврату или нет?', zh: '请问内衣能退吗？', en: 'Tell me, can underwear be returned or not?', ctx: '能否退货' },
  { ru: '— Деньги вернутся на карту сразу?\n— В течение трёх-десяти дней, как банк обработает.', zh: '—钱会马上退回卡里吗？\n—银行处理的话，需要三到十天。', en: '—Will the money go back to my card immediately?\n—Within three to ten days, once the bank processes it.', ctx: '退款到账' },
  { ru: '— Что мне заполнить для возврата?\n— Заявление, и подпишите, пожалуйста, внизу.', zh: '—退货我需要填什么？\n—填一张申请，请在下面签名。', en: '—What do I need to fill in for the return?\n—An application form, and please sign at the bottom.', ctx: '填写申请' },
  { ru: '— Мне продали не тот размер, что я просила.\n— Приношу извинения. Сразу поменять или вернём деньги?\n— А нужный размер есть в наличии?\n— Увы, закончился час назад.', zh: '—卖给我的不是我要的尺码。\n—非常抱歉。直接换货还是退款？\n—需要的尺码有货吗？\n—唉，一小时前刚卖完。', en: '—I was sold the wrong size, not the one I asked for.\n—My apologies. Exchange it right away or refund your money?\n—Is the size I need in stock?\n—Alas, it sold out an hour ago.', ctx: '错发处理' },
  { ru: 'Если вещь ношеная, принять назад, к сожалению, не смогу.', zh: '如果衣服穿过，很遗憾我没法收回。', en: 'If the item has been worn, I\'m afraid I can\'t take it back.', ctx: '退货限制' },
  { ru: '— Кто платит за обратную пересылку?\n— При нашей ошибке — мы, вот номер накладной.', zh: '—退回去的运费谁出？\n—是我们出错就我们出，这是运单号。', en: '—Who pays for return shipping?\n—If it\'s our mistake, we do. Here\'s the waybill number.', ctx: '退货运费' },
  { ru: 'Как это «возврату не подлежит»? Вещь вообще не распечатана!', zh: '什么叫「不予退换」？东西我压根没拆封！', en: 'What do you mean "non-returnable"? The item hasn\'t even been opened!', ctx: '退货争议' },
  { ru: '— Можно обменять подарок, если он не понравится?\n— Да, в течение месяца при наличии чека.\n— А если чек подарочный, без указания суммы?', zh: '—礼物要是不喜欢能换吗？\n—能，一个月内凭小票办理。\n—要是礼品小票，上面没写金额呢？', en: '—Can a gift be exchanged if they don\'t like it?\n—Yes, within a month with the receipt.\n—What if it\'s a gift receipt without the amount shown?', ctx: '礼品退换' },
  { ru: '— Какой номер заказа?\n— Секунду... он начинается на 7841.', zh: '—订单号是多少？\n—稍等……开头是7841。', en: '—What\'s the order number?\n—One moment... it starts with 7841.', ctx: '报订单号', say: '— Какой номер заказа?\n— Секунду... он начинается на семь восемь четыре один.' },
  { ru: '— Как долго будет идти экспертиза?\n— До десяти дней, результат пришлём сообщением на телефон.', zh: '—鉴定要多久？\n—最多十天，结果会发短信到手机。', en: '—How long will the examination take?\n—Up to ten days, we\'ll send the result by text message.', ctx: '质量鉴定' },
  { ru: '— Я передумала, можно просто не забирать посылку?\n— Тогда она вернётся к нам, а деньги выплатим обратно.', zh: '—我改主意了，可以直接不去取包裹吗？\n—那包裹会退回我们这儿，货款会退给您。', en: '—I changed my mind, can I simply not pick up the parcel?\n—Then it\'ll come back to us and we\'ll refund the money.', ctx: '拒收包裹' },
  { ru: 'Где у вас лежит свежая зелень — укроп и кинза?', zh: '你们的新鲜香草在哪儿？莳萝和香菜。', en: 'Where do you keep fresh herbs, dill and cilantro?', ctx: '询问位置' },
  { ru: '— Вам взвесить помидоры?\n— Да, килограмма полтора, только спелые.', zh: '—番茄要称吗？\n—要，一斤半左右，要熟的。', en: '—Shall I weigh the tomatoes for you?\n—Yes, about a kilo and a half, ripe ones only.', ctx: '市场称重' },
  { ru: '— Девушка, проходите на свободную кассу!\n— Спасибо, я как раз закончила с покупками.', zh: '—姑娘，请到没人的那个收银台来！\n—谢谢，东西正好挑完了。', en: '—Miss, please come to the open checkout!\n—Thanks, I\'ve just finished my shopping.', ctx: '超市结账' },
  { ru: '— Один пакет или два?\n— Один, и ещё пробейте пачку жвачки.\n— Итого 612 рублей, оплата картой?', zh: '—要一个袋子还是两个？\n—一个，再帮我扫一包口香糖。\n—一共612卢布，刷卡吗？', en: '—One bag or two?\n—One, and ring up a pack of gum too.\n—That\'s 612 rubles total, paying by card?', ctx: '便利店结账', say: '— Один пакет или два?\n— Один, и ещё пробейте пачку жвачки.\n— Итого шестьсот двенадцать рублей, оплата картой?' },
  { ru: 'Эти яблоки у вас местные или привозные?', zh: '你们这些苹果是本地的还是外地运来的？', en: 'Are these apples of yours local or brought in from elsewhere?', ctx: '询问产地' },
  { ru: '— Что-нибудь ещё?\n— Пожалуй, пачку творога и бутылку кефира.', zh: '—还要别的吗？\n—再来一包奶渣和一瓶开菲尔酸奶吧。', en: '—Anything else?\n—Maybe a pack of tvorog and a bottle of kefir.', ctx: '追加商品' },
  { ru: 'Взвесьте 2 кг картошки и кочан капусты.', zh: '称2公斤土豆，再来一颗卷心菜。', en: 'Weigh 2 kg of potatoes and a head of cabbage.', ctx: '市场买菜', say: 'Взвесьте два килограмма картошки и кочан капусты.' },
  { ru: '— Смотрите, какая редиска, утром с грядки!\n— А она не горькая?\n— Попробуйте пучок, свежий редис сладким бывает.\n— Ладно, давайте два пучка и пёрышки лука.', zh: '—您看这小萝卜，早上刚从地里拔的！\n—不苦吗？\n—您尝一根，新鲜水萝卜可甜了。\n—行，来两把，再点小葱。', en: '—Look at these radishes, straight from the bed this morning!\n—Aren\'t they bitter?\n—Try a bunch, fresh radishes can be sweet.\n—All right, give me two bunches and some spring onion.', ctx: '早市挑选' },
  { ru: '— Почему шоколадки лежат прямо у кассы?\n— Хитрость: пока стоишь в очереди — рука сама тянется.', zh: '—巧克力为什么就摆在收银台旁边？\n—小心机：排队等着手就自己伸过去了。', en: '—Why are chocolate bars placed right by the checkout?\n—A trick: while you queue, your hand reaches for them.', ctx: '观察陈列' },
  { ru: '— У вас есть карта магазина? По ней дешевле.\n— Нет, но могу прямо сейчас скачать приложение.', zh: '—您有本店的卡吗？有卡便宜些。\n—没有，不过我可以现在就下载应用。', en: '—Do you have a store card? It\'s cheaper with one.\n—No, but I can download the app right now.', ctx: '办会员卡' },
  { ru: 'Магазин у дома работает 24 часа, очень выручает.', zh: '家门口的店24小时营业，特别方便。', en: 'The corner shop is open 24 hours, it\'s a real lifesaver.', ctx: '便利商店', say: 'Магазин у дома работает двадцать четыре часа, очень выручает.' },
  { ru: '— А огурцы грунтовые или тепличные?\n— Грунтовые, с дачи, берите — не пожалеете.\n— Тогда ещё огурчиков полкило.', zh: '—黄瓜是大地种的还是大棚的？\n—大地的，菜园里摘的，买了不后悔。\n—那再来半斤黄瓜。', en: '—Are the cucumbers field-grown or greenhouse?\n—Field-grown, from a dacha. Take them, you won\'t regret it.\n—Then another half kilo of cucumbers.', ctx: '挑选蔬菜' },
  { ru: '— Яйца положить сверху?\n— Да, отдельно и повыше, чтобы не разбились.', zh: '—鸡蛋放上面吗？\n—对，单独放、放高点，别打碎了。', en: '—Shall I put the eggs on top?\n—Yes, separately and higher up, so they don\'t break.', ctx: '小心装袋' },
  { ru: '— Цена на ценнике одна, а пробили другую!\n— Сейчас проверю... извините, акция ещё не загрузилась, сделаю возврат.', zh: '—价签上是一个价，扫出来却是另一个！\n—我看看……抱歉，促销还没录入，给您退差价。', en: '—The price tag says one thing but I was charged another!\n—Let me check... sorry, the promotion hasn\'t loaded, I\'ll refund the difference.', ctx: '价格纠纷' },
  { ru: 'Если будет скидка на красную рыбу, возьму сразу два куска.', zh: '红鱼要是打折，我马上买两块。', en: 'If red fish goes on sale, I\'ll take two pieces at once.', ctx: '等待促销' },
  { ru: 'Посоветуйте что-нибудь типично русское в подарок друзьям.', zh: '给我推荐点有俄罗斯特色、能送朋友的东西。', en: 'Recommend something typically Russian as a gift for friends.', ctx: '求推荐纪念品' },
  { ru: '— Это настоящая хохлома или штамповка?\n— Смотрите, есть клеймо мастера, ручная роспись.', zh: '—这是真的霍赫洛马彩绘还是机器压的？\n—您看，有匠人的印记，是手绘的。', en: '—Is this real Khokhloma or stamped?\n—Look, there\'s the master\'s mark, it\'s hand-painted.', ctx: '辨别工艺' },
  { ru: '— Сколько кукол в этой матрёшке?\n— Пять, разбирается почти до самой маленькой.', zh: '—这个套娃里有几个娃娃？\n—五个，一路能拆到最小的那个。', en: '—How many dolls are in this matryoshka?\n—Five, it comes apart almost to the tiniest one.', ctx: '挑选套娃' },
  { ru: '— Почём этот расписной платок?\n— Две с половиной тысячи, чистый шёлк.\n— А шерстяной с таким же узором есть?', zh: '—这块花头巾怎么卖？\n—两千五，纯丝的。\n—有同样花纹的羊毛款吗？', en: '—How much is this painted shawl?\n—Two and a half thousand, pure silk.\n—Do you have a wool one in the same pattern?', ctx: '购买头巾' },
  { ru: 'Где можно купить натуральный башкирский мёд?', zh: '哪儿能买到正宗的巴什基尔蜂蜜？', en: 'Where can I buy natural Bashkir honey?', ctx: '寻找特产' },
  { ru: '— Берёте в подарок? Могу упаковать.\n— Да, и положите 2 плитки шоколада с начинкой.', zh: '—买来送人的吗？我可以包装。\n—对，再放两块夹心巧克力。', en: '—Is it a gift? I can wrap it.\n—Yes, and add two bars of filled chocolate.', ctx: '特产巧克力', say: '— Берёте в подарок? Могу упаковать.\n— Да, и положите две плитки шоколада с начинкой.' },
  { ru: 'Такие магнитики на холодильник разлетаются у туристов за день.', zh: '这种冰箱磁贴游客一天就抢光。', en: 'These fridge magnets sell out among tourists in a day.', ctx: '冰箱磁贴' },
  { ru: '— Хочется чего-то небанального, не как в дьюти-фри.\n— Тогда посмотрите финифть: эмаль по металлу, делают в Ростове.\n— Красиво... а это не очень хрупко?\n— В дорогу упакую в стружку, довезёте целым.', zh: '—想要点不俗气的，别像免税店里那种。\n—那看看珐琅：金属胎上烧珐琅，罗斯托夫的工艺。\n—真漂亮……会不会很容易碎？\n—我用刨花给您包好，路上能完整带到。', en: '—I want something less clichéd, not like in duty-free.\n—Then look at finift: enamel on metal, made in Rostov.\n—It\'s beautiful... isn\'t it rather fragile?\n—I\'ll pack it in shavings for the trip, you\'ll get it there in one piece.', ctx: '珐琅首饰' },
  { ru: '— Этот самовар настоящий, старинный?\n— Нет, это сувенирный, он даже воду не кипятит.', zh: '—这个茶炊是真的古董吗？\n—不是，是纪念款，连水都烧不开。', en: '—Is this samovar genuine, an antique?\n—No, it\'s a souvenir one, it doesn\'t even boil water.', ctx: '茶炊纪念品' },
  { ru: 'Возьму 3 баночки варенья из сосновых шишек.', zh: '我要3罐松果果酱。', en: 'I\'ll take 3 jars of pine cone jam.', ctx: '松果果酱', say: 'Возьму три баночки варенья из сосновых шишек.' },
  { ru: '— Из чего этот звонкий свисток?\n— Из обожжённой глины, это филимоновская игрушка.', zh: '—这个声音清脆的小哨是什么做的？\n—烧过的陶泥，是菲利莫诺沃玩具。', en: '—What is this ringing whistle made of?\n—Fired clay, it\'s a Filimonovo toy.', ctx: '泥哨玩具' },
  { ru: '— Почему шкатулка так дорого стоит?\n— Это палехская миниатюра, роспись делается вручную.', zh: '—这小盒子为什么这么贵？\n—这是帕列赫细密画，图案全是手绘的。', en: '—Why does the casket cost so much?\n—It\'s a Palekh miniature, the painting is done by hand.', ctx: '细密画首饰盒' },
  { ru: '— У вас есть янтарь не из прессованной крошки?\n— Вот эти бусы — цельный камень, в нём видны включения.', zh: '—你们有不是压碎料做的琥珀吗？\n—这条项链就是整块石头，里面能看到包裹体。', en: '—Do you have amber that isn\'t pressed dust?\n—These beads are solid stone, you can see inclusions in it.', ctx: '琥珀首饰' },
  { ru: 'Не подскажете, продаются ли где-то рядом оренбургские платки?', zh: '请问附近哪儿有卖奥伦堡围巾的？', en: 'Could you tell me if Orenburg shawls are sold anywhere nearby?', ctx: '奥伦堡围巾' },
  { ru: '— Что везут из вашего города в основном?\n— Печатные пряники, ими славится весь край.\n— Они долго хранятся?\n— Месяца два спокойно, берите в плотной упаковке.', zh: '—大家从你们城市一般带点什么？\n—印花蜜糖饼，整个地区都以此闻名。\n—能放很久吗？\n—两个月没问题，买包装严实的。', en: '—What do people mostly bring from your city?\n—Printed pryaniki, the whole region is famous for them.\n—Do they keep long?\n—Two months easily, take them in tight packaging.', ctx: '印花蜜糖饼' },
  { ru: 'Покажите, пожалуйста, недорогой смартфон с хорошей камерой.', zh: '请给我看看便宜点、摄像头好的手机。', en: 'Please show me an affordable smartphone with a good camera.', ctx: '挑选手机' },
  { ru: '— Сколько держит заряд этот аккумулятор?\n— До 20 часов в режиме视频, проверено.', zh: '—这块电池续航多久？\n—放视频能撑20小时，实测过。', en: '—How long does this battery hold a charge?\n—Up to 20 hours of video, it\'s been tested.', ctx: '电池续航', say: '— Сколько держит заряд этот аккумулятор?\n— До двадцати часов в режиме видео, проверено.' },
  { ru: 'Мне нужен USB-кабель типа C, не микро.', zh: '我要一根C口的USB线，不要micro口。', en: 'I need a USB-C cable, not micro.', ctx: '买数据线', say: 'Мне нужен ю эс би кабель типа це, не микро.' },
  { ru: '— Ноутбук нужен для учёбы или для игр?\n— В основном учиться, иногда хочется и поиграть.\n— Тогда берите модель с шестнадцатью гигабайтами памяти.', zh: '—笔记本主要用来学习还是打游戏？\n—主要学习，偶尔也想玩一玩。\n—那就选16GB内存的型号。', en: '—Do you need the laptop for studying or gaming?\n—Mostly studying, sometimes I\'d like to play too.\n—Then take a model with sixteen gigabytes of memory.', ctx: '选购笔记本' },
  { ru: '— Сколько лет гарантии на эти наушники?\n— Два года сервиса, только чек сохраните.', zh: '—这耳机保修几年？\n—两年售后服务，小票请留好。', en: '—How many years is the warranty on these headphones?\n—Two years of service, just keep the receipt.', ctx: '询问保修' },
  { ru: '— В этой модели есть слот для второй сим-карты?\n— Да, гибридный: либо симка, либо карта памяти.', zh: '—这款有第二个SIM卡槽吗？\n—有，混合槽：要么放SIM卡，要么放存储卡。', en: '—Does this model have a slot for a second SIM card?\n—Yes, it\'s hybrid: either a SIM or a memory card.', ctx: '双卡功能' },
  { ru: 'Возьму модель на 256 ГБ, чтобы хватило на фото.', zh: '我要256GB的型号，放照片够用。', en: 'I\'ll take the 256 GB model, enough for photos.', ctx: '存储容量', say: 'Возьму модель на двести пятьдесят шесть гигабайт, чтобы хватило на фото.' },
  { ru: '— Телефон перестал заряжаться через месяц.\n— Давайте посмотрим... кабель оригинальный?\n— Да, из коробки.\n— Оставьте на диагностику, если брак — поменяем аппарат.', zh: '—手机用了一个月就充不进电了。\n—我看看……线是原装的吗？\n—对，盒里自带的。\n—留下检测吧，如果是瑕疵就给您换机。', en: '—The phone stopped charging after a month.\n—Let\'s have a look... is the cable original?\n—Yes, the one from the box.\n—Leave it for diagnostics; if it\'s a defect, we\'ll replace the device.', ctx: '手机故障' },
  { ru: '— Покажете, как часы подключаются к телефону?\n— Конечно, надевайте на руку, сейчас сопряжём.', zh: '—能演示一下手表怎么连手机吗？\n—当然，戴到手上，我们现在配对。', en: '—Can you show me how the watch connects to the phone?\n—Sure, put it on, we\'ll pair it now.', ctx: '智能手表' },
  { ru: '— Он поддерживает Wi-Fi 6?\n— Да, и Bluetooth пятой версии.', zh: '—它支持Wi-Fi 6吗？\n—支持，蓝牙也是5.0版。', en: '—Does it support Wi-Fi 6?\n—Yes, and Bluetooth version five.', ctx: '无线网络', say: '— Он поддерживает вай фай шесть?\n— Да, и блютуз пятой версии.' },
  { ru: 'Скажите, а можно у вас наклеить защитное стекло?', zh: '请问能在你们这儿贴钢化膜吗？', en: 'Tell me, can I get a protective glass applied here?', ctx: '贴膜服务' },
  { ru: '— Какой у робота-пылесоса радиус действия?\n— Он сам строит карту квартиры и возвращается на базу.\n— А пороги между комнатами он преодолеет?', zh: '—扫地机器人的工作范围多大？\n—它会自己绘制家里的地图，还能自己回充。\n—房间之间的门槛它过得去吗？', en: '—What\'s the range of the robot vacuum?\n—It builds a map of the flat itself and returns to the dock.\n—Can it get over the thresholds between rooms?', ctx: '智能家电' },
  { ru: '— Защищён ли корпус от воды?\n— Да, стандарт IP68, можно на полчаса под воду.', zh: '—机身防水吗？\n—防，IP68等级，可以在水下放半小时。', en: '—Is the body waterproof?\n—Yes, IP68 rated, it can go underwater for half an hour.', ctx: '防水等级', say: '— Защищён ли корпус от воды?\n— Да, стандарт ай пи шестьдесят восемь, можно на полчаса под воду.' },
  { ru: 'Если куплю фотоаппарат сегодня, объектив подарите?', zh: '我今天买相机，镜头送不送？', en: 'If I buy the camera today, will you throw in a lens?', ctx: '索要赠品' },
  { ru: '— Чехол и плёнка идут в комплекте?\n— Увы, только зарядка, аксессуары отдельно.', zh: '—壳和膜是随机附送的吗？\n—可惜只带充电器，配件要单买。', en: '—Do a case and a screen film come in the box?\n—Sadly only the charger, accessories are separate.', ctx: '配件清单' },
  { ru: 'Ищу демисезонное пальто до двадцати тысяч рублей.', zh: '我想找件两万卢布以内的春秋大衣。', en: 'I\'m looking for an in-between-season coat up to twenty thousand rubles.', ctx: '预算购衣' },
  { ru: '— Эти ботинки из натуральной кожи?\n— Да, внутри тоже кожа, не только снаружи.', zh: '—这双靴子是真皮的吗？\n—是，里面也是皮的，不光是外面。', en: '—Are these boots real leather?\n—Yes, leather inside too, not just on the outside.', ctx: '材质询问' },
  { ru: 'Какой из этих рюкзаков держит форму и не промокает?', zh: '这些背包里哪个挺括又防水？', en: 'Which of these backpacks keeps its shape and doesn\'t let water through?', ctx: '挑选背包' },
  { ru: '— Девушка, хотела бы примерить вон те туфли на каблуке.\n— Какой у вас размер?\n— Тридцать восьмой, но нога широкая.', zh: '—姑娘，我想试试那双高跟鞋。\n—您穿多大码？\n—38码，不过脚比较宽。', en: '—Miss, I\'d like to try on those heels over there.\n—What\'s your size?\n—Thirty-eight, but my foot is wide.', ctx: '试高跟鞋' },
  { ru: '— Какую сумочку взять к этому платью?\n— Что-нибудь нейтральное, бежевую или молочную.', zh: '—这条裙子配什么包好？\n—素一点的，米色或奶白色。', en: '—What bag should I take with this dress?\n—Something neutral, beige or cream.', ctx: '搭配包包' },
  { ru: '— Пальто длинное, до колена или ниже?\n— До щиколотки, зато спина точно не мёрзнет.', zh: '—大衣是到膝盖还是更长？\n—到脚踝，不过后背绝对不会冷。', en: '—Is the coat long to the knee or lower?\n—To the ankle, but your back certainly won\'t get cold.', ctx: '衣长讨论' },
  { ru: 'Мне нужен мужской костюм 50-го размера, тёмно-серый.', zh: '我要一套50码的深灰色男士西装。', en: 'I need a men\'s suit in size 50, dark grey.', ctx: '购买西装', say: 'Мне нужен мужской костюм пятидесятого размера, тёмно-серый.' },
  { ru: '— Ремень идёт в комплекте с брюками?\n— Нет, но сегодня на ремни акция: два плюс один.\n— Тогда я покажу модель мужу на фото.\n— Конечно, только примерьте сначала, она маломерит.', zh: '—腰带是跟裤子一套的吗？\n—不是，不过今天腰带搞活动：买二送一。\n—那我拍张照给丈夫看看。\n—行，不过先试试，这款偏小。', en: '—Does a belt come with the trousers?\n—No, but belts are on offer today: two plus one.\n—Then I\'ll show the style to my husband in a photo.\n—Sure, just try it on first, it runs small.', ctx: '搭配腰带' },
  { ru: '— Ремень у этой сумки регулируется?\n— Да, можно носить и на плече, и через плечо, как удобно.', zh: '—这包的带子能调吗？\n—能，可以肩背也可以斜挎，怎么方便怎么来。', en: '—Is the strap on this bag adjustable?\n—Yes, you can wear it on the shoulder or across the body, whatever suits you.', ctx: '挑选单肩包' },
  { ru: '— Вам классические кеды или на платформе?\n— Лучше платформу, я невысокая.', zh: '—您要经典帆布鞋还是厚底的？\n—厚底的吧，我个子不高。', en: '—Do you want classic canvas sneakers or platform ones?\n—Platform is better, I\'m on the short side.', ctx: '帆布鞋款式' },
  { ru: 'Эта куртка на пуху или на искусственном наполнителе?', zh: '这件外套是羽绒的还是人造填充物的？', en: 'Is this jacket down-filled or synthetic-filled?', ctx: '询问填充物' },
  { ru: '— Кроссовки для зала нужны с амортизацией.\n— Возьмите эти, пятка жёстко зафиксирована.\n— А они лёгкие? Я бегаю на дорожке.', zh: '—健身穿的运动鞋需要有缓冲。\n—看看这双，后跟固定得很稳。\n—轻吗？我在跑步机上跑步。', en: '—I need gym trainers with cushioning.\n—Take these, the heel is firmly supported.\n—Are they light? I run on the treadmill.', ctx: '选购运动鞋' },
  { ru: '— Можно эту модель в 37-м размере, бежевую?\n— Есть последняя пара, стояла на витрине.', zh: '—这款有37码米色的吗？\n—有最后一双，一直摆在橱窗里。', en: '—Can I get this style in size 37, beige?\n—There\'s one last pair, it was on display.', ctx: '指定鞋码', say: '— Можно эту модель в тридцать седьмом размере, бежевую?\n— Есть последняя пара, стояла на витрине.' },
  { ru: 'Я бы взяла кожаную сумку, если бы она не была такой тяжёлой.', zh: '这皮包要是没这么沉，我就买了。', en: 'I\'d take the leather bag if it weren\'t so heavy.', ctx: '皮包犹豫' },
  { ru: '— На фурнитуру сумки есть гарантия?\n— Полгода на молнии и замки, приходите с чеком.', zh: '—包的五金件有保修吗？\n—拉链和锁头保修半年，带着小票来。', en: '—Is there a warranty on the bag\'s hardware?\n—Half a year on zips and locks, come with the receipt.', ctx: '包包保修' },
  { ru: 'Где найти стиральный порошок для детских вещей?', zh: '儿童衣物用的洗衣粉在哪儿？', en: 'Where can I find laundry detergent for children\'s clothes?', ctx: '寻找日化' },
  { ru: '— Сыр нарезать ломтиками или одним куском?\n— Ломтиками, граммов триста.', zh: '—奶酪切片还是整块？\n—切片，三百克左右。', en: '—Shall I slice the cheese or give you one piece?\n—Sliced, about three hundred grams.', ctx: '熟食切配' },
  { ru: 'Мне нужна зубная паста без фтора и щётка средней жёсткости.', zh: '我要无氟牙膏和一支中硬毛牙刷。', en: 'I need fluoride-free toothpaste and a medium-hard toothbrush.', ctx: '口腔护理' },
  { ru: '— Докторская колбаса есть в нарезке?\n— Есть, вакуум по 400 граммов.\n— Дайте две упаковки и батон нарезного.', zh: '—医生香肠有切片装吗？\n—有，400克真空装。\n—来两包，再要一条切片面包。', en: '—Do you have sliced Doktorskaya sausage?\n—Yes, vacuum packs of 400 grams.\n—Give me two packs and a sliced loaf.', ctx: '购买熟食', say: '— Докторская колбаса есть в нарезке?\n— Есть, вакуум по четыреста граммов.\n— Дайте две упаковки и батон нарезного.' },
  { ru: '— Хлеб сегодняшний?\n— Утром из печи, ещё тёплый, берите смело.', zh: '—面包是今天的吗？\n—早上刚出炉，还热乎呢，放心买。', en: '—Is the bread from today?\n—Out of the oven this morning, still warm, take it with confidence.', ctx: '新鲜面包' },
  { ru: '— У вас есть мыло без запаха, для чувствительной кожи?\n— Вот, гипоаллергенное, на козьем молоке.', zh: '—有无味、适合敏感肌的香皂吗？\n—这款，低过敏，羊奶做的。', en: '—Do you have unscented soap for sensitive skin?\n—Here, hypoallergenic, made with goat\'s milk.', ctx: '香皂选择' },
  { ru: 'Дайте 10 яиц и пакет молока жирностью 3,2%.', zh: '来10个鸡蛋，再来一袋3.2%脂肪含量的牛奶。', en: 'Give me 10 eggs and a carton of 3.2% milk.', ctx: '蛋奶柜台', say: 'Дайте десять яиц и пакет молока жирностью три целых две десятых процента.' },
  { ru: '— Ищу шампунь от перхоти, чтобы не сушил кожу.\n— Попробуйте мужскую линию с ментолом.\n— А кондиционер той же марки есть?\n— Да, берите парой, на комплект скидка.', zh: '—我想去屑洗发水，但别太干。\n—试试男士薄荷系列。\n—有同品牌的护发素吗？\n—有，一起拿有套装优惠。', en: '—I\'m looking for an anti-dandruff shampoo that won\'t dry my scalp.\n—Try the men\'s line with menthol.\n—Is there a conditioner from the same brand?\n—Yes, take them as a pair, the set is discounted.', ctx: '洗发护发' },
  { ru: '— Рыбу завернуть отдельно?\n— Да, пожалуйста, чтобы по сумке не пахла.', zh: '—鱼要单独包吗？\n—要，麻烦您，免得弄得袋子里有味。', en: '—Shall I wrap the fish separately?\n—Yes, please, so it doesn\'t smell through the bag.', ctx: '分装请求' },
  { ru: '— Салфетки нужны влажные или бумажные?\n— Влажные антибактериальные, в дорогу.', zh: '—要湿纸巾还是干纸巾？\n—抗菌湿巾，路上用。', en: '—Do you need wet wipes or paper tissues?\n—Antibacterial wet wipes, for the trip.', ctx: '纸巾选择' },
  { ru: 'В упаковке 6 рулонов туалетной бумаги, хватит надолго.', zh: '一包有6卷卫生纸，够用很久。', en: 'There are 6 rolls of toilet paper in the pack, it lasts a long time.', ctx: '日用百货', say: 'В упаковке шесть рулонов туалетной бумаги, хватит надолго.' },
  { ru: '— Творог какой жирности?\n— Пять процентов, есть и обезжиренный.\n— Тогда дайте пачку пятипроцентного.', zh: '—奶渣脂肪含量多少？\n—百分之五，也有脱脂的。\n—那来一包5%的。', en: '—What fat content is the tvorog?\n—Five percent, there\'s also fat-free.\n—Then give me a pack of the five-percent one.', ctx: '挑选乳制品' },
  { ru: '— Кофе взять в зёрнах или молотый?\n— В зёрнах, дома есть кофемолка.', zh: '—咖啡要咖啡豆还是咖啡粉？\n—豆子，家里有磨豆机。', en: '—Should I take coffee beans or ground?\n—Beans, I have a grinder at home.', ctx: '咖啡选择' },
  { ru: 'Опять закончилось средство для мытья посуды, надо записать!', zh: '洗洁精又用完了，得记下来！', en: 'We\'re out of dish soap again, I need to note it down!', ctx: '补货提醒' },
  { ru: '— Сколько взять масла — одну бутылку?\n— Берите 1,5 литра, на нём и жарим, и заправляем.', zh: '—油买多少，一瓶吗？\n—拿1.5升的，炒菜、拌菜都用它。', en: '—How much oil should I get, one bottle?\n—Take 1.5 liters, we both fry and dress salads with it.', ctx: '选购食用油', say: '— Сколько взять масла — одну бутылку?\n— Берите полтора литра, на нём и жарим, и заправляем.' },
]

// ── 医疗健康 / Health / Здоровье ──
const HEALTH: Phrase[] = [
  { ru: 'Мне нужно записаться к терапевту на сегодня.', zh: '我想今天预约一位内科医生。', en: 'I need to book an appointment with the GP for today.', ctx: '预约挂号' },
  { ru: '— К какому врачу вы хотите попасть?\n— К хирургу, если можно.', zh: '—您想挂哪位医生的号？\n—如果可以的话，外科医生。', en: '—Which doctor would you like to see?\n—A surgeon, if possible.', ctx: '选择医生' },
  { ru: 'Ближайшее свободное время есть только в четверг.', zh: '最近的空闲时间只有周四了。', en: 'The earliest available slot is only on Thursday.', ctx: '预约时间' },
  { ru: '— На какое число вы записаны?\n— На пятницу, на десять утра.', zh: '—您约的是哪一天？\n—周五，上午十点。', en: '—What day is your appointment?\n—Friday, ten in the morning.', ctx: '确认预约' },
  { ru: '— Доктор принимает по живой очереди?\n— Нет, только по предварительной записи.\n— А можно талон на завтра?', zh: '—医生是按现场排队看诊吗？\n—不，只接受提前预约。\n—那能挂明天的号吗？', en: '—Does the doctor take walk-ins?\n—No, appointments only.\n—Can I get a ticket for tomorrow then?', ctx: '排队就诊' },
  { ru: 'Я звоню, чтобы отменить запись на понедельник.', zh: '我打电话来取消周一的预约。', en: 'I\'m calling to cancel my appointment for Monday.', ctx: '取消预约' },
  { ru: '— Ваш полис и паспорт, пожалуйста.\n— Секунду, сейчас достану из сумки.', zh: '—请出示您的医保卡和护照。\n—稍等，我从包里拿一下。', en: '—Your insurance card and passport, please.\n—One second, I\'ll get them out of my bag.', ctx: '登记证件' },
  { ru: '— Регистратура ещё работает?\n— Да, до восьми вечера, успеете.', zh: '—挂号处还上班吗？\n—上的，到晚八点，您来得及。', en: '—Is the registration desk still open?\n—Yes, until eight p.m., you\'ll make it.', ctx: '门诊时间' },
  { ru: '— Вы прикреплены к нашей поликлинике?\n— Да, я живу в соседнем доме.', zh: '—您的医保关系在我们诊所吗？\n—在，我就住在隔壁楼。', en: '—Are you registered at our clinic?\n—Yes, I live in the building next door.', ctx: '医保绑定' },
  { ru: '— Мне бы попасть к врачу сегодня, очень плохо.\n— Тогда идите в кабинет неотложной помощи, там примут без записи.\n— Спасибо, уже бегу.', zh: '—我想今天看医生，我很不舒服。\n—那去急诊诊室，不用挂号就能看。\n—谢谢，我这就过去。', en: '—I need to see a doctor today, I feel awful.\n—Then go to the urgent care room, they\'ll take you without an appointment.\n—Thanks, I\'m running there now.', ctx: '紧急就诊' },
  { ru: 'Подскажите, а врач принимает по субботам?', zh: '请问医生周六坐诊吗？', en: 'Excuse me, does the doctor see patients on Saturdays?', ctx: '询问出诊' },
  { ru: '— Я могу перенести приём со вторника на среду?\n— Да, в среду есть окно в четыре часа.', zh: '—我能把周二的门诊改到周三吗？\n—可以，周三四点有个空档。', en: '—Can I move my appointment from Tuesday to Wednesday?\n—Yes, there\'s a slot at four on Wednesday.', ctx: '改约时间' },
  { ru: '— Где взять талон к врачу?\n— В терминале у входа, я помогу вам разобраться.', zh: '—在哪取号？\n—入口处的自助机，我帮您操作。', en: '—Where can I get a queue ticket?\n—At the terminal by the entrance, I\'ll help you figure it out.', ctx: '取号机操作' },
  { ru: '— Как ваша фамилия? Я проверю запись.\n— Иванов. Я записан на девять часов.', zh: '—您贵姓？我查一下预约。\n—伊万诺夫，我约的九点。', en: '—What\'s your surname? I\'ll check the appointment.\n—Ivanov. I\'m booked for nine o\'clock.', ctx: '核对预约' },
  { ru: '— Скажите, а запись к узким специалистам только через терапевта?\n— Да, сначала нужен осмотр и направление.\n— Понял. Тогда запишите меня к терапевту.\n— Есть время завтра в одиннадцать, устраивает?', zh: '—请问看专科医生必须先经过内科医生吗？\n—是的，需要先检查并开转诊单。\n—明白了，那帮我约内科医生吧。\n—明天十一点有空，合适吗？', en: '—Tell me, can I see specialists only through a GP?\n—Yes, first you need an exam and a referral.\n—I see. Then book me with the GP.\n—There\'s a slot tomorrow at eleven, does that work?', ctx: '开转诊单' },
  { ru: 'У меня со вчерашнего вечера болит голова.', zh: '我从昨天晚上开始头疼。', en: 'I\'ve had a headache since yesterday evening.', ctx: '头痛不适' },
  { ru: '— Что вас беспокоит?\n— У меня температура 38 градусов, и всё тело ломит.', zh: '—您哪里不舒服？\n—我烧到三十八度，全身酸痛。', en: '—What\'s bothering you?\n—I have a temperature of 38 degrees and my whole body aches.', ctx: '发烧高热', say: '— Что вас беспокоит?\n— У меня температура тридцать восемь градусов, и всё тело ломит.' },
  { ru: 'Кашель не проходит уже неделю, особенно по ночам.', zh: '咳嗽已经一周了还不好，夜里尤其厉害。', en: 'The cough hasn\'t gone away for a week, especially at night.', ctx: '久咳不愈' },
  { ru: '— Где именно болит живот?\n— Вот здесь, справа внизу, когда нажимаю.', zh: '—肚子具体哪里痛？\n—就这儿，右下方，一按就痛。', en: '—Where exactly does your stomach hurt?\n—Right here, lower right side, when I press.', ctx: '腹痛定位' },
  { ru: '— Меня тошнит со вчерашнего дня.\n— Рвота была?\n— Один раз ночью, после ужина.\n— Сейчас постарайтесь больше пить, маленькими глотками.', zh: '—我从昨天开始恶心。\n—吐过吗？\n—夜里吐过一次，在晚饭后。\n—现在要尽量少量多次地喝水。', en: '—I\'ve been feeling nauseous since yesterday.\n—Have you vomited?\n—Once at night, after dinner.\n—Try to drink more now, in small sips.', ctx: '恶心呕吐' },
  { ru: 'Больно глотать, и горло красное.', zh: '吞咽很痛，嗓子也红了。', en: 'It hurts to swallow, and my throat is red.', ctx: '咽痛吞咽' },
  { ru: '— На что у вас аллергия?\n— На пыльцу: сразу слезятся глаза и течёт из носа.', zh: '—您对什么过敏？\n—花粉：立刻眼睛流泪、流鼻涕。', en: '—What are you allergic to?\n—Pollen: my eyes water and my nose runs right away.', ctx: '过敏体质' },
  { ru: 'Голова раскалывается, даже свет раздражает.', zh: '头像裂开一样痛，连光线都让我难受。', en: 'My head is splitting, even the light bothers me.', ctx: '偏头痛发作' },
  { ru: '— Кашель сухой или с мокротой?\n— Сначала был сухой, теперь отходит мокрота.', zh: '—咳嗽是干咳还是有痰？\n—一开始干咳，现在有痰了。', en: '—Is the cough dry or with phlegm?\n—It was dry at first, now phlegm comes up.', ctx: '咳嗽性质' },
  { ru: '— У меня болит живот после каждого приёма пищи.\n— А тошнота или изжога есть?\n— Изжога бывает, да. И ещё немного подташнивает.\n— Понятно, сейчас осмотрим вас.', zh: '—我每次吃完东西肚子就痛。\n—有恶心或者烧心吗？\n—烧心会有，还稍微有点恶心。\n—明白了，我这就给您检查。', en: '—My stomach hurts after every meal.\n—Any nausea or heartburn?\n—I do get heartburn. And I feel a bit nauseous too.\n—I see, let\'s examine you now.', ctx: '餐后腹痛' },
  { ru: 'Температура поднялась до 39, я принял жаропонижающее.', zh: '体温升到三十九度，我吃了退烧药。', en: 'My temperature went up to 39, I took fever medicine.', ctx: '高烧服药', say: 'Температура поднялась до тридцати девяти, я принял жаропонижающее.' },
  { ru: '— Как давно болит горло?\n— Дня три. Сегодня даже голос пропал.', zh: '—嗓子痛多久了？\n—三天左右，今天嗓子都哑了。', en: '—How long has your throat hurt?\n—About three days. Today I even lost my voice.', ctx: '咽痛失声' },
  { ru: '— На что похожа эта сыпь?\n— Не знаю, выступила после морепродуктов, руки чешутся.', zh: '—这疹子是什么情况？\n—不清楚，吃完海鲜后起的，手臂发痒。', en: '—What does this rash look like?\n—I don\'t know, it appeared after seafood, my arms itch.', ctx: '皮疹过敏' },
  { ru: '— У вас кружится голова?\n— Да, когда резко встаю, прямо темнеет в глазах.', zh: '—您头晕吗？\n—是的，猛地站起来时，眼前直接发黑。', en: '—Do you feel dizzy?\n—Yes, when I stand up quickly, everything goes dark.', ctx: '起身眩晕' },
  { ru: '— Меня обсыпало, всё чешется!\n— Что вы ели накануне?\n— Апельсины и шоколад. Раньше такого не было.\n— Похоже на аллергическую реакцию. Я выпишу антигистаминное.', zh: '—我起了一身疹子，痒得不行！\n—您前一天吃了什么？\n—橙子和巧克力，以前没有过。\n—像是过敏反应，我给您开点抗过敏药。', en: '—I\'ve broken out in a rash, everything itches!\n—What did you eat the day before?\n—Oranges and chocolate. It never happened before.\n—It looks like an allergic reaction. I\'ll prescribe an antihistamine.', ctx: '急性过敏' },
  { ru: 'У вас обычная простуда, ничего серьёзного.', zh: '您就是普通感冒，没什么大问题。', en: 'You have a common cold, nothing serious.', ctx: '普通感冒' },
  { ru: '— Это грипп?\n— Пока похоже на вирусную инфекцию, но лучше сдать анализ.', zh: '—是流感吗？\n—目前看像病毒感染，但最好验个血。', en: '—Is it the flu?\n—So far it looks like a viral infection, but better to get tested.', ctx: '疑似流感' },
  { ru: 'Воспаление лёгких нужно исключить, сделаем снимок.', zh: '需要排除肺炎，我们去拍个片子。', en: 'We need to rule out pneumonia, let\'s take an X-ray.', ctx: '排除肺炎' },
  { ru: '— Доктор, это опасно?\n— Не волнуйтесь, начальная стадия, лечение займёт неделю.', zh: '—医生，这危险吗？\n—别担心，是初期，治疗一周就好。', en: '—Doctor, is it dangerous?\n—Don\'t worry, it\'s the early stage, treatment will take a week.', ctx: '安抚病情' },
  { ru: '— Что показывает анализ крови?\n— Небольшое воспаление, повышены лейкоциты.\n— А с горлом что?\n— Ангина. Придётся попить антибиотики.', zh: '—血检结果怎么样？\n—有点炎症，白细胞偏高。\n—那嗓子呢？\n—是扁桃体炎，得吃几天抗生素。', en: '—What does the blood test show?\n—A mild inflammation, white cells are elevated.\n—What about my throat?\n—Tonsillitis. You\'ll need antibiotics.', ctx: '血检结果' },
  { ru: '— Какое у меня давление?\n— Сто сорок на девяносто, многовато.', zh: '—我血压多少？\n—一百四九十，有点高。', en: '—What\'s my blood pressure?\n—One-forty over ninety, a bit high.', ctx: '血压偏高' },
  { ru: '— У меня правда аппендицит?\n— Да, симптомы указывают на острый аппендицит, нужна операция.', zh: '—我真的是阑尾炎吗？\n—是的，症状指向急性阑尾炎，需要手术。', en: '—Do I really have appendicitis?\n—Yes, the symptoms point to acute appendicitis, you need surgery.', ctx: '急性阑尾炎' },
  { ru: 'Это мигрень, а не просто головная боль.', zh: '这是偏头痛，不是普通的头痛。', en: 'It\'s a migraine, not just a headache.', ctx: '偏头痛诊断' },
  { ru: '— От чего у меня сыпь?\n— Скорее всего контактный дерматит. Чем-то новым пользовались?', zh: '—我的疹子是什么引起的？\n—很可能是接触性皮炎，您用过什么新东西吗？', en: '—What\'s causing my rash?\n—Most likely contact dermatitis. Did you use anything new?', ctx: '皮炎病因' },
  { ru: '— Что со мной?\n— У вас кишечная инфекция, отсюда тошнота и слабость.\n— А это надолго?\n— При лечении дня за три-четыре станет легче.', zh: '—我怎么了？\n—您是肠道感染，所以恶心、乏力。\n—这要很久吗？\n—治疗的话三四天就会好转。', en: '—What\'s wrong with me?\n—You have an intestinal infection, hence the nausea and weakness.\n—Will it last long?\n—With treatment you\'ll feel better in three or four days.', ctx: '肠道感染' },
  { ru: 'У вас давление 150 на 95 — это гипертония.', zh: '您血压一百五九十五，这是高血压。', en: 'Your blood pressure is 150 over 95 — that\'s hypertension.', ctx: '高血压', say: 'У вас давление сто пятьдесят на девяносто пять — это гипертония.' },
  { ru: '— Это перелом?\n— Нет, кость цела, просто сильный ушиб.', zh: '—是骨折吗？\n—不是，骨头没事，只是严重挫伤。', en: '—Is it a fracture?\n—No, the bone is intact, just a bad bruise.', ctx: '排除骨折' },
  { ru: 'Анализы у вас хорошие, воспаления нет.', zh: '化验结果不错，没有炎症。', en: 'Your tests are good, there\'s no inflammation.', ctx: '指标正常' },
  { ru: '— Бронхит? Я так и думала.\n— Да, острый бронхит. Постельный режим и обильное питьё.', zh: '—支气管炎？我就猜到了。\n—是的，急性支气管炎。卧床休息，多喝水。', en: '—Bronchitis? I thought so.\n—Yes, acute bronchitis. Bed rest and plenty of fluids.', ctx: '急性支气管炎' },
  { ru: '— Доктор, это точно не сердце?\n— По ЭКГ всё спокойно, боль, скорее всего, из-за остеохондроза.\n— Вы меня прямо успокоили.\n— Но если боль повторится, сразу вызывайте скорую.', zh: '—医生，这真不是心脏问题吗？\n—心电图一切正常，疼痛很可能是颈椎病引起的。\n—您可让我放心了。\n—但如果再痛，立刻叫救护车。', en: '—Doctor, it\'s really not my heart?\n—The ECG is normal, the pain is most likely from osteochondrosis.\n—You\'ve really reassured me.\n—But if the pain returns, call an ambulance immediately.', ctx: '排查心脏病', say: '— Доктор, это точно не сердце?\n— По электрокардиограмме всё спокойно, боль, скорее всего, из-за остеохондроза.\n— Вы меня прямо успокоили.\n— Но если боль повторится, сразу вызывайте скорую.' },
  { ru: 'Принимайте по одной таблетке три раза в день после еды.', zh: '每次一片，一天三次，饭后服用。', en: 'Take one tablet three times a day after meals.', ctx: '服药频次' },
  { ru: '— Это пить до еды или после?\n— За двадцать минут до еды, чтобы лучше помогало.', zh: '—这药饭前吃还是饭后吃？\n—饭前二十分钟，效果更好。', en: '—Should I take this before or after meals?\n—Twenty minutes before meals, so it works better.', ctx: '服药时间' },
  { ru: 'По 2 таблетки 3 раза в день, не больше.', zh: '每次两片，一天三次，不能再多。', en: 'Two tablets, three times a day, no more.', ctx: '每日剂量', say: 'По две таблетки три раза в день, не больше.' },
  { ru: '— А на ночь что принимать?\n— Сироп от кашля, одну чайную ложку перед сном.', zh: '—睡前吃什么？\n—止咳糖浆，睡前一茶匙。', en: '—What should I take at night?\n—Cough syrup, one teaspoon before bed.', ctx: '睡前用药' },
  { ru: '— Сколько дней пить антибиотик?\n— Ровно семь дней, даже если станет лучше.\n— А если забуду выпить?\n— Просто продолжайте по схеме, двойную дозу не принимайте.', zh: '—抗生素吃几天？\n—整整七天，哪怕好转也要吃满。\n—忘了吃怎么办？\n—按原计划继续就行，别吃双份剂量。', en: '—How many days do I take the antibiotic?\n—Exactly seven days, even if you feel better.\n—What if I miss a dose?\n—Just continue the schedule, don\'t take a double dose.', ctx: '抗生素疗程' },
  { ru: 'Капли в нос — по два впрыска в каждую ноздрю.', zh: '滴鼻剂每个鼻孔喷两下。', en: 'Nasal drops — two sprays into each nostril.', ctx: '鼻喷剂用法' },
  { ru: '— Таблетки можно разжёвывать?\n— Нет, глотайте целиком и запивайте водой.', zh: '—药片可以嚼碎吗？\n—不行，整片吞下，用水送服。', en: '—Can I chew the tablets?\n—No, swallow them whole with water.', ctx: '服药方式' },
  { ru: 'Разовая доза — 5 миллилитров, это один мерный стаканчик.', zh: '单次剂量五毫升，就是量杯一杯。', en: 'A single dose is 5 milliliters, that\'s one measuring cup.', ctx: '单次剂量', say: 'Разовая доза — пять миллилитров, это один мерный стаканчик.' },
  { ru: '— Жаропонижающее давать только при высокой температуре?\n— Да, выше тридцати восьми и пяти, не чаще четырёх раз в сутки.', zh: '—退烧药只在高烧时给吗？\n—是的，三十八度五以上，一天不超过四次。', en: '—Should fever medicine be given only at a high temperature?\n—Yes, above 38.5, no more than four times a day.', ctx: '退热指征' },
  { ru: '— Мазь куда наносить?\n— Тонким слоем на поражённое место, два раза в день.\n— Втирать?\n— Слегка, до впитывания, и обязательно мойте руки после.', zh: '—药膏涂在哪里？\n—薄薄涂在患处，一天两次。\n—要揉开吗？\n—轻轻涂到吸收为止，之后一定要洗手。', en: '—Where do I apply the ointment?\n—In a thin layer on the affected area, twice a day.\n—Should I rub it in?\n—Gently, until absorbed, and always wash your hands afterwards.', ctx: '外用药膏' },
  { ru: '— Чем запивать таблетку?\n— Стаканом тёплой воды, чай и кофе не подходят.', zh: '—用什么送服药片？\n—一杯温水，茶和咖啡不行。', en: '—What should I take the tablet with?\n—A glass of warm water; tea and coffee won\'t do.', ctx: '送服饮水' },
  { ru: '— Эти витамины когда лучше пить?\n— Утром, во время завтрака, так они лучше усваиваются.', zh: '—这些维生素什么时候吃比较好？\n—早上吃早饭时，吸收更好。', en: '—When is it best to take these vitamins?\n—In the morning, with breakfast, so they absorb better.', ctx: '维生素服法' },
  { ru: 'Курс лечения — 10 дней, потом обязательный перерыв.', zh: '一个疗程十天，之后必须停药休息。', en: 'The course of treatment is 10 days, then a mandatory break.', ctx: '疗程天数', say: 'Курс лечения — десять дней, потом обязательный перерыв.' },
  { ru: '— Можно вместе с кофе?\n— Нежелательно, кофе снижает эффект лекарства.', zh: '—能配咖啡吃吗？\n—不建议，咖啡会降低药效。', en: '—Can I take it with coffee?\n—Not advisable, coffee reduces the medicine\'s effect.', ctx: '药物相互作用' },
  { ru: '— Я принял две таблетки вместо одной, что делать?\n— Когда это было?\n— Час назад.\n— Не паникуйте, но выпейте воды и оставайтесь дома. Если станет плохо, звоните.', zh: '—我本该吃一片却吃了两片，怎么办？\n—什么时候的事？\n—一小时前。\n—别慌，喝点水，待在家里。要是不舒服就打电话。', en: '—I took two tablets instead of one, what should I do?\n—When was that?\n—An hour ago.\n—Don\'t panic, drink some water and stay home. If you feel worse, call.', ctx: '误服过量' },
  { ru: 'Скажите, у вас есть жаропонижающее для детей?', zh: '请问有儿童退烧药吗？', en: 'Tell me, do you have fever medicine for children?', ctx: '儿童退烧药' },
  { ru: '— Вам рецептурное или без рецепта?\n— Без рецепта, что-нибудь от температуры.', zh: '—您要处方药还是非处方药？\n—非处方的，能退烧的就行。', en: '—Do you need prescription or over-the-counter?\n—Over-the-counter, something for fever.', ctx: '购药咨询' },
  { ru: 'Дайте, пожалуйста, пластырь и перекись водорода.', zh: '请给我创可贴和双氧水。', en: 'Give me a band-aid and hydrogen peroxide, please.', ctx: '购买耗材' },
  { ru: '— Этот антибиотик только по рецепту.\n— Вот, возьмите, врач выписал вчера.', zh: '—这种抗生素必须凭处方。\n—给您，医生昨天开的。', en: '—This antibiotic is prescription only.\n—Here you go, the doctor prescribed it yesterday.', ctx: '处方购药' },
  { ru: '— Мне нужно что-то от боли в горле.\n— Есть спрей и пастилки. Что предпочитаете?\n— Давайте пастилки, спрей я не люблю.\n— Хорошо, брать одну упаковку или две?', zh: '—我需要治嗓子痛的药。\n—有喷雾剂和润喉糖，您想要哪种？\n—要润喉糖吧，我不喜欢喷雾。\n—好的，拿一盒还是两盒？', en: '—I need something for a sore throat.\n—There\'s a spray and lozenges. What do you prefer?\n—Let\'s have lozenges, I don\'t like the spray.\n—Alright, one pack or two?', ctx: '咽痛用药' },
  { ru: 'Есть ли у вас аналог подешевле?', zh: '你们有便宜点的类似药吗？', en: 'Do you have a cheaper equivalent?', ctx: '询问替代药' },
  { ru: '— Как принимать это лекарство?\n— Это написано в инструкции, но лучше уточните у врача.', zh: '—这个药怎么吃？\n—说明书上有写，但最好还是问一下医生。', en: '—How do I take this medicine?\n—It says so in the leaflet, but better to check with your doctor.', ctx: '用药咨询' },
  { ru: '— Порошок от простуды есть?\n— Да, в маленьких пакетиках. Брать упаковку?', zh: '—有感冒冲剂吗？\n—有，小袋装的。拿一盒吗？', en: '—Do you have cold powder?\n—Yes, in small sachets. Shall I get a box?', ctx: '感冒冲剂' },
  { ru: '— У вас аллергия на какие-то препараты?\n— На аспирин, поэтому внимательно смотрю состав.', zh: '—您对什么药物过敏吗？\n—阿司匹林，所以我会仔细看成分。', en: '—Are you allergic to any medications?\n—To aspirin, so I check the ingredients carefully.', ctx: '过敏禁忌' },
  { ru: '— Здравствуйте, мне нужен тонометр.\n— Механический или автоматический?\n— Автоматический, на руку.\n— Есть вот такая модель, очень точная.', zh: '—您好，我要买血压计。\n—机械的还是自动的？\n—自动的，上臂式。\n—有这一款，测量很准。', en: '—Hello, I need a blood pressure monitor.\n—Manual or automatic?\n—Automatic, for the upper arm.\n—We have this model, very accurate.', ctx: '购买器械' },
  { ru: 'Сколько стоит эта упаковка капель?', zh: '这盒滴眼液多少钱？', en: 'How much does this pack of drops cost?', ctx: '询问药价' },
  { ru: '— Лекарство нужно хранить в холодильнике?\n— Да, при температуре от двух до восьми градусов.', zh: '—药要放冰箱保存吗？\n—是的，在两到八度之间。', en: '—Does the medicine need refrigeration?\n—Yes, at a temperature between two and eight degrees.', ctx: '药品储存' },
  { ru: 'Дайте 2 упаковки активированного угля.', zh: '给我两盒活性炭。', en: 'Give me two packs of activated charcoal.', ctx: '活性炭', say: 'Дайте две упаковки активированного угля.' },
  { ru: '— Можно заказать препарат, которого нет в наличии?\n— Да, привезём послезавтра, оставьте номер телефона.', zh: '—没货的药可以预订吗？\n—可以，后天到货，留个电话吧。', en: '—Can I order a medicine that\'s out of stock?\n—Yes, we\'ll get it the day after tomorrow, leave your phone number.', ctx: '缺货预订' },
  { ru: '— У вас есть что-то от изжоги?\n— Вот эти таблетки, очень помогают.\n— А их можно при беременности?\n— Это лучше уточнить у врача, я не могу советовать.', zh: '—有治烧心的药吗？\n—这种药片很管用。\n—孕妇能吃吗？\n—这个最好问医生，我不能给建议。', en: '—Do you have something for heartburn?\n—These tablets help a lot.\n—Can they be taken during pregnancy?\n—Better to ask your doctor, I can\'t advise on that.', ctx: '孕妇用药' },
  { ru: 'Вызовите, пожалуйста, скорее скорую помощь!', zh: '请快叫救护车！', en: 'Please call an ambulance, quickly!', ctx: '呼叫救护车' },
  { ru: '— Что случилось? Говорите!\n— Человеку плохо, он потерял сознание.', zh: '—发生什么事了？请讲！\n—有人情况不好，昏过去了。', en: '—What happened? Speak!\n—Someone\'s in a bad way, he\'s passed out.', ctx: '询问病情' },
  { ru: '— Назовите адрес, мы выезжаем.\n— Улица Ленина, дом двенадцать, третий подъезд.', zh: '—请说地址，我们马上出发。\n—列宁大街十二号楼，三号单元。', en: '—Give me the address, we\'re on our way.\n—Lenin Street, building twelve, third entrance.', ctx: '告知地址' },
  { ru: '— Он дышит?\n— Кажется, да, но очень слабо.', zh: '—他有呼吸吗？\n—好像有，但非常微弱。', en: '—Is he breathing?\n—I think so, but very weakly.', ctx: '检查呼吸' },
  { ru: '— Сильно идёт кровь из раны!\n— Крепко зажмите рану чистой тканью.\n— Она промокает насквозь!\n— Добавьте ещё слой ткани, не убирайте первый. Скорая уже едет.', zh: '—伤口流血很厉害！\n—用干净的布紧紧按住伤口。\n—血把布浸透了！\n—再垫一层布，别拿掉第一层。救护车已经在路上。', en: '—The wound is bleeding heavily!\n—Press the wound firmly with clean cloth.\n—It\'s soaking through!\n—Add another layer, don\'t remove the first. The ambulance is coming.', ctx: '压迫止血' },
  { ru: 'Кажется, у меня сломана рука, она опухла.', zh: '我的手好像骨折了，都肿了。', en: 'I think my arm is broken, it\'s swollen.', ctx: '疑似骨折' },
  { ru: '— Можно шевелить ногой?\n— Нет, не двигайте её, сейчас наложим шину.', zh: '—腿能动吗？\n—不能动，我们马上上夹板。', en: '—Can I move my leg?\n—No, don\'t move it, we\'ll put on a splint now.', ctx: '固定伤肢' },
  { ru: 'Отравление! Ребёнок выпил лекарство из аптечки.', zh: '中毒了！孩子喝了药箱里的药。', en: 'Poisoning! A child drank medicine from the first-aid kit.', ctx: '误服中毒' },
  { ru: '— Сколько вам лет? Есть хронические болезни?\n— Мне шестьдесят, болит сердце, принимаю таблетки.', zh: '—您多大年纪？有慢性病吗？\n—我六十了，心脏不好，一直在吃药。', en: '—How old are you? Any chronic illnesses?\n—I\'m sixty, I have heart trouble and take pills.', ctx: '病史询问' },
  { ru: '— Алло, скорая? Мужчина упал с лестницы!\n— Он в сознании?\n— Да, но жалуется на сильную боль в спине.\n— Не передвигайте его, мы выезжаем.', zh: '—喂，急救中心吗？有个男人从楼梯上摔下来了！\n—他清醒吗？\n—清醒，但说后背剧痛。\n—别挪动他，我们这就来。', en: '—Hello, ambulance? A man fell down the stairs!\n—Is he conscious?\n—Yes, but he complains of severe back pain.\n—Don\'t move him, we\'re on our way.', ctx: '脊柱受伤' },
  { ru: 'У меня открылось кровотечение, помогите!', zh: '我出血了，救命！', en: 'I\'ve started bleeding, help me!', ctx: '急性出血' },
  { ru: '— Ожог большой?\n— Вся ладонь. Обожглась кипятком.', zh: '—烫伤面积大吗？\n—整个手掌，被开水烫的。', en: '—Is the burn large?\n—The whole palm. I scalded it with boiling water.', ctx: '烫伤处理' },
  { ru: 'Пульс частый, больше 100 ударов в минуту.', zh: '脉搏偏快，每分钟超过一百次。', en: 'The pulse is fast, over 100 beats per minute.', ctx: '脉搏异常', say: 'Пульс частый, больше ста ударов в минуту.' },
  { ru: '— Куда теперь? В приёмное отделение?\n— Да, туда, вас осмотрит дежурный врач.', zh: '—现在去哪？去急诊室吗？\n—对，去那儿，值班医生会给您检查。', en: '—Where to now? The admissions department?\n—Yes, there, the doctor on duty will examine you.', ctx: '急诊分诊' },
  { ru: '— Я порезал руку ножом, кровь не останавливается.\n— Рана глубокая?\n— Да, довольно глубокая.\n— Подержите руку выше и зажмите рану. Выезжаем немедленно.', zh: '—我被刀子割伤了手，血流不止。\n—伤口深吗？\n—深，挺深的。\n—把手抬高按住伤口，我们立刻出发。', en: '—I cut my hand with a knife, the bleeding won\'t stop.\n—Is the wound deep?\n—Yes, fairly deep.\n—Keep your hand raised and press the wound. We\'re leaving now.', ctx: '割伤急救' },
  { ru: 'Мне назначили анализ крови натощак.', zh: '医生让我空腹验血。', en: 'I\'ve been told to take a fasting blood test.', ctx: '空腹验血' },
  { ru: '— Кровь из вены или из пальца?\n— Из вены, пройдите в пятый кабинет.', zh: '—抽静脉血还是指尖血？\n—静脉血，请到五号诊室。', en: '—Blood from a vein or the finger?\n—From a vein, go to room five.', ctx: '采血方式' },
  { ru: 'Перед УЗИ нельзя завтракать и пить газировку.', zh: '做超声前不能吃早饭，也不能喝汽水。', en: 'Before the ultrasound you can\'t have breakfast or drink soda.', ctx: '超声准备', say: 'Перед ультразвуковым исследованием нельзя завтракать и пить газировку.' },
  { ru: '— Результаты будут готовы когда?\n— Обычно на следующий день после обеда.', zh: '—结果什么时候能出来？\n—一般第二天下午。', en: '—When will the results be ready?\n—Usually the next day after lunch.', ctx: '取报告时间' },
  { ru: '— Мне нужно на рентген грудной клетки.\n— Снимок делаем на вдохе. Снимите металлические украшения.\n— А серьги тоже?\n— Да, всё металлическое выше пояса. Проходите.', zh: '—我要拍胸片。\n—拍片时要吸气，请摘下金属首饰。\n—耳环也要摘吗？\n—对，腰部以上所有金属物品。请进。', en: '—I need a chest X-ray.\n—We take the shot on an inhale. Remove metal jewelry.\n—Earrings too?\n—Yes, everything metallic above the waist. Come in.', ctx: '胸部X光' },
  { ru: 'ЭКГ делается лёжа и занимает пару минут.', zh: '心电图躺着做，几分钟就好。', en: 'The ECG is done lying down and takes a couple of minutes.', ctx: '心电图检查', say: 'Электрокардиограмма делается лёжа и занимает пару минут.' },
  { ru: '— На кушетку ложиться?\n— Да, оголите запястья, щиколотки и грудь.', zh: '—躺到检查床上吗？\n—对，露出手腕、脚踝和胸口。', en: '—Do I lie on the couch?\n—Yes, bare your wrists, ankles and chest.', ctx: '心电体位' },
  { ru: 'У вас возьмут 4 пробирки крови, не пугайтесь.', zh: '会抽您四管血，别害怕。', en: 'They\'ll take four vials of your blood, don\'t be scared.', ctx: '多管采血', say: 'У вас возьмут четыре пробирки крови, не пугайтесь.' },
  { ru: '— Флюорография у вас когда была?\n— В прошлом году, вот справка с печатью.', zh: '—您上次做胸透是什么时候？\n—去年，这是带印章的证明。', en: '—When did you last have fluorography?\n—Last year, here\'s the stamped certificate.', ctx: '胸片筛查' },
  { ru: '— Расшифруйте, пожалуйста, результат УЗИ.\n— Тут всё в норме, отклонений нет.\n— А вот это пятно?\n— Это особенность строения, не переживайте, но покажите врачу.', zh: '—请帮我解释一下超声结果。\n—一切正常，没有异常。\n—那这个斑点是什么？\n—是结构特点，别担心，但拿给医生看看。', en: '—Please interpret the ultrasound result for me.\n—Everything is normal, no abnormalities.\n—What about this spot?\n—It\'s a structural feature, don\'t worry, but show it to the doctor.', ctx: '超声解读', say: '— Расшифруйте, пожалуйста, результат ультразвукового исследования.\n— Тут всё в норме, отклонений нет.\n— А вот это пятно?\n— Это особенность строения, не переживайте, но покажите врачу.' },
  { ru: 'После анализа крови съешьте что-нибудь сладкое.', zh: '抽完血后吃点甜的。', en: 'Eat something sweet after the blood test.', ctx: '采血后建议' },
  { ru: '— Можно пить воду перед анализом?\n— Можно немного чистой воды, чай и кофе нельзя.', zh: '—化验前能喝水吗？\n—可以喝点白水，茶和咖啡不行。', en: '—Can I drink water before the test?\n—A little plain water is fine, but no tea or coffee.', ctx: '验血前饮水' },
  { ru: '— Рентген точно покажет перелом?\n— Да, на снимке будет видно перелом или трещину.', zh: '—X光一定能看出骨折吗？\n—是的，片子上能看到骨折或骨裂。', en: '—Will the X-ray definitely show a fracture?\n—Yes, the image will show a fracture or a crack.', ctx: '骨折排查' },
  { ru: '— Вас записать на эхокардиографию?\n— Да, врач говорил, надо проверить сердце под нагрузкой.', zh: '—给您预约心脏超声吗？\n—好，医生说要查一下心脏负荷情况。', en: '—Shall I book you for an echocardiogram?\n—Yes, the doctor said to check the heart under stress.', ctx: '心脏负荷超声' },
  { ru: '— Зачем такой большой список анализов?\n— Это стандартная диспансеризация, раз в год положено бесплатно.\n— А по очереди долго?\n— С утра меньше народа, приходите к восьми.', zh: '—为什么要开这么多检查？\n—这是标准体检，每年一次免费。\n—排队要很久吗？\n—早上人少，八点来吧。', en: '—Why such a long list of tests?\n—It\'s a standard check-up, free once a year.\n—Will the queue take long?\n—There are fewer people in the morning, come by eight.', ctx: '年度体检' },
  { ru: 'У меня сильно болит зуб, не могу спать.', zh: '我牙痛得厉害，没法睡觉。', en: 'I have a bad toothache, I can\'t sleep.', ctx: '牙痛失眠' },
  { ru: '— Какой зуб болит?\n— Вон тот, внизу слева, на холодное реагирует.', zh: '—哪颗牙痛？\n—那颗，左下的，遇冷就痛。', en: '—Which tooth hurts?\n—That one, lower left, it reacts to cold.', ctx: '定位患牙' },
  { ru: 'Зуб мудрости режется, и опухла щека.', zh: '智齿在长，脸都肿了。', en: 'A wisdom tooth is cutting through and my cheek is swollen.', ctx: '智齿发炎' },
  { ru: '— Давно были у стоматолога?\n— Года два, наверное. Всё время откладывала.', zh: '—很久没看牙医了吧？\n—大概两年了，一直拖着。', en: '—How long since you saw a dentist?\n—About two years, I suppose. I kept putting it off.', ctx: '久未看牙' },
  { ru: '— Сверлить будете? Я ужасно боюсь.\n— Только маленькую дырочку, поставлю укол, будет не больно.\n— Обещаете?\n— Обещаю. Если что, поднимите руку, сразу остановлюсь.', zh: '—要钻牙吗？我特别害怕。\n—就一个小洞，我先打麻药，不会痛。\n—您保证？\n—保证。要是有感觉就举手，我立刻停。', en: '—Will you drill? I\'m terrified.\n—Just a tiny cavity, I\'ll give you a shot, it won\'t hurt.\n—You promise?\n—I promise. If anything, raise your hand and I\'ll stop at once.', ctx: '害怕钻牙' },
  { ru: '— Сначала поставим пломбу?\n— Да, почистим кариес и поставим световую пломбу.', zh: '—先补牙吗？\n—对，清理蛀牙后用光固化材料补上。', en: '—Do we put in a filling first?\n—Yes, we\'ll clean the decay and put in a light-cured filling.', ctx: '补牙方案' },
  { ru: '— Анестезия отошла? Губы ещё немеют?\n— Да, немеют, это нормально?', zh: '—麻药退了吗？嘴唇还麻吗？\n—还麻，这正常吗？', en: '—Has the anesthesia worn off? Are your lips still numb?\n—Yes, they\'re numb, is that normal?', ctx: '麻药反应' },
  { ru: 'Кровоточат дёсны, когда чищу зубы.', zh: '我刷牙时牙龈出血。', en: 'My gums bleed when I brush my teeth.', ctx: '牙龈出血' },
  { ru: '— Какую пломбу ставим?\n— Лучшую, чтобы цвет совпадал с зубами.', zh: '—补哪种材料？\n—最好的，颜色要和牙齿一致。', en: '—Which filling do we put in?\n—The best one, so the color matches my teeth.', ctx: '补牙材料' },
  { ru: '— Зуб можно сохранить или удалять?\n— Каналы в плохом состоянии, но попробуем полечить.\n— А если не получится?\n— Тогда удалим и поставим имплант, но это крайний вариант.', zh: '—牙能保住还是要拔？\n—根管状态不好，但可以试着治。\n—万一不行呢？\n—那就拔掉种牙，但这是最后的办法。', en: '—Can the tooth be saved or should it come out?\n—The canals are in bad shape, but let\'s try to treat it.\n—And if that doesn\'t work?\n—Then we\'ll remove it and put in an implant, but that\'s the last resort.', ctx: '保牙或拔牙' },
  { ru: 'Не ешьте два часа после установки пломбы.', zh: '补牙后两小时内不要吃东西。', en: 'Don\'t eat for two hours after the filling is placed.', ctx: '术后禁食' },
  { ru: '— Зубы чистить два раза в день?\n— Да, и нитью пользуйтесь каждый вечер.', zh: '—每天刷两次牙吗？\n—对，每晚还要用牙线。', en: '—Should I brush twice a day?\n—Yes, and floss every evening.', ctx: '刷牙用牙线' },
  { ru: 'У меня выпала пломба во время еды.', zh: '我吃饭的时候补料掉了。', en: 'My filling fell out while I was eating.', ctx: '补料脱落' },
  { ru: '— Отбеливание не повредит эмаль?\n— Если делать у врача, эмаль останется целой.', zh: '—美白不会伤牙釉质吗？\n—在医生这里做，牙釉质不会受损。', en: '—Won\'t whitening damage the enamel?\n—If it\'s done at the dentist\'s, the enamel stays intact.', ctx: '牙齿美白' },
  { ru: '— На десне вскочил белый прыщик.\n— Это свищ, под зубом воспаление.\n— Это серьёзно?\n— Нужно лечить канал, иначе воспаление пойдёт дальше. Начнём сегодня?', zh: '—牙龈上长了个白色的小包。\n—这是瘘管，牙根下面有炎症。\n—严重吗？\n—要做根管治疗，不然炎症会扩散。今天就开始吗？', en: '—A white pimple appeared on my gum.\n—It\'s a fistula, there\'s inflammation under the tooth.\n—Is that serious?\n—The root canal needs treatment, otherwise it will spread. Shall we start today?', ctx: '牙龈瘘管' },
  { ru: 'Я плохо вижу доску в школе, буквы расплываются.', zh: '我看不清学校的黑板，字都是花的。', en: 'I can\'t see the board at school, the letters are blurry.', ctx: '视物模糊' },
  { ru: '— Как давно заметили ухудшение?\n— Месяца три, думала, пройдёт.', zh: '—发现视力下降多久了？\n—三个月左右，以为会自己好。', en: '—How long ago did you notice the decline?\n—About three months, I thought it would pass.', ctx: '视力下降时长' },
  { ru: 'Проверьте мне, пожалуйста, сегодня зрение.', zh: '请今天给我检查一下视力。', en: 'Please check my eyesight for me today.', ctx: '验光请求' },
  { ru: '— Буквы читаете до какой строчки?\n— Вот до этой, дальше уже туман.', zh: '—字母能看到第几行？\n—就到这行，再往下就模糊了。', en: '—Which line of letters can you read down to?\n—Down to this one, below that it\'s all foggy.', ctx: '视力表检查' },
  { ru: '— Линза номер один или номер два?\n— Два. В первом буквы мельче.\n— А теперь? Стало лучше или хуже?\n— Лучше! Намного чётче.', zh: '—一号镜片还是二号？\n—二号，一号里字更小。\n—现在呢？清楚了还是更模糊？\n—清楚了！清晰多了。', en: '—Lens number one or number two?\n—Two. In the first one the letters look smaller.\n—And now? Better or worse?\n—Better! Much sharper.', ctx: '试戴镜片' },
  { ru: 'Глаза быстро устают и слезятся от компьютера.', zh: '看电脑眼睛很快就累、流泪。', en: 'My eyes get tired quickly and water from the computer.', ctx: '电脑用眼疲劳' },
  { ru: '— Вы хотите очки или линзы?\n— Начну с очков, линзы пока боюсь.', zh: '—您想配框架眼镜还是隐形眼镜？\n—先配框架吧，暂时不敢用隐形。', en: '—Do you want glasses or contact lenses?\n—I\'ll start with glasses, I\'m not ready for lenses yet.', ctx: '眼镜或隐形' },
  { ru: '— Какую оправу возьмём?\n— Лёгкую пластиковую, в металлической у меня следы на коже.', zh: '—选哪种镜架？\n—轻便的塑料架，金属架会在我皮肤上留印。', en: '—Which frame shall we take?\n—A light plastic one, metal frames leave marks on my skin.', ctx: '选择镜架' },
  { ru: '— Астигматизм есть?\n— Есть небольшой, врач увидел на приёме.', zh: '—有散光吗？\n—有一点，医生检查时发现的。', en: '—Is there astigmatism?\n—A slight one, the doctor found it during the exam.', ctx: '散光确认' },
  { ru: '— Сколько будут готовы очки?\n— Обычно три-четыре дня.\n— А можно поскорее? У меня старые разбились.\n— Тогда сделаем срочно, за два дня, но доплата небольшая.', zh: '—眼镜多久能配好？\n—一般三四天。\n—能快点吗？我旧眼镜打碎了。\n—那走加急，两天取，需要加一点钱。', en: '—How long until the glasses are ready?\n—Usually three or four days.\n—Can it be sooner? My old ones broke.\n—Then we\'ll rush them, in two days, but there\'s a small surcharge.', ctx: '取镜时间' },
  { ru: 'Мне нужны солнцезащитные очки с диоптриями.', zh: '我要配有度数的太阳镜。', en: 'I need prescription sunglasses.', ctx: '度数太阳镜' },
  { ru: '— В линзах глаза сохнут?\n— К вечеру да. Есть капли для увлажнения?', zh: '—戴隐形眼镜眼睛干吗？\n—傍晚会干，有润眼的滴眼液吗？', en: '—Do your eyes get dry in lenses?\n—By evening, yes. Are there moisturizing drops?', ctx: '隐形眼干' },
  { ru: 'Зрение минус 2, выписали очки для постоянного ношения.', zh: '近视二百度，医生让我一直戴着眼镜。', en: 'My vision is minus 2, I was prescribed glasses for constant wear.', ctx: '近视度数', say: 'Зрение минус два, выписали очки для постоянного ношения.' },
  { ru: '— Ребёнку можно линзы?\n— Можно лет с двенадцати, если он сможет сам их надевать.', zh: '—孩子能戴隐形眼镜吗？\n—十二岁以后可以，前提是他自己能戴。', en: '—Can a child wear contact lenses?\n—From about twelve, if the child can put them on alone.', ctx: '儿童隐形' },
  { ru: '— В новых очках кружится голова и пол качается.\n— Сколько дней вы их носите?\n— Со вчерашнего дня.\n— Привыкание занимает неделю. Если не пройдёт, приходите, проверим рецепт.', zh: '—戴新眼镜头晕，感觉地面在晃。\n—您戴几天了？\n—从昨天开始。\n—适应需要一周。如果还不好就过来，我们重新核对度数。', en: '—In the new glasses I feel dizzy and the floor sways.\n—How many days have you worn them?\n—Since yesterday.\n—Adaptation takes a week. If it doesn\'t pass, come in and we\'ll check the prescription.', ctx: '新镜不适' },
  { ru: 'Спите не меньше семи-восьми часов в сутки.', zh: '每天至少睡七到八小时。', en: 'Sleep at least seven to eight hours a day.', ctx: '充足睡眠' },
  { ru: '— Мне обязательно бросать курить?\n— Очень желательно, сердце и лёгкие скажут спасибо.', zh: '—我必须戒烟吗？\n—非常建议戒，心脏和肺都会感谢您。', en: '—Do I really have to quit smoking?\n—It\'s highly advisable, your heart and lungs will thank you.', ctx: '戒烟建议' },
  { ru: 'Больше ходите пешком, хотя бы полчаса в день.', zh: '多走路，每天至少半小时。', en: 'Walk more, at least half an hour a day.', ctx: '坚持步行' },
  { ru: '— Можно мне кофе? Я без него не просыпаюсь.\n— Одна чашка утром не повредит, но не больше.', zh: '—我能喝咖啡吗？不喝我醒不了。\n—早上一杯没问题，但别再多。', en: '—Can I have coffee? I can\'t wake up without it.\n—One cup in the morning won\'t hurt, but no more.', ctx: '限制咖啡' },
  { ru: '— Я постоянно чувствую усталость.\n— А как у вас со сном и питанием?\n— Сплю часов пять, ем на бегу.\n— Вот и причина. Начните с режима, а там посмотрим.', zh: '—我总觉得累。\n—睡眠和饮食怎么样？\n—每天睡五小时，吃饭都凑合。\n—原因就在这。先调整作息，之后再看。', en: '—I constantly feel tired.\n—How are your sleep and diet?\n—I sleep about five hours and eat on the run.\n—There\'s the reason. Start with a routine and we\'ll see.', ctx: '疲劳原因' },
  { ru: 'Пейте чистую воду вместо сладкой газировки.', zh: '喝白水，别喝甜汽水。', en: 'Drink plain water instead of sweet soda.', ctx: '健康饮水' },
  { ru: '— Какой спорт выбрать, если болят колени?\n— Плавание или скандинавская ходьба, без ударной нагрузки.', zh: '—膝盖痛该选什么运动？\n—游泳或北欧式健走，没有冲击性负荷。', en: '—What sport should I choose if my knees hurt?\n—Swimming or Nordic walking, without impact loading.', ctx: '选择运动' },
  { ru: '— Как питаться, чтобы давление не скакало?\n— Больше овощей, меньше соли и жареного.', zh: '—怎么吃血压才不会波动？\n—多吃蔬菜，少吃盐和油炸食品。', en: '—How should I eat so my blood pressure stays steady?\n—More vegetables, less salt and fried food.', ctx: '低盐饮食' },
  { ru: '— Нужно ли мне худеть?\n— Немного сбросить не помешает, давление сразу снизится.', zh: '—我需要减肥吗？\n—减一点没坏处，血压马上就会降。', en: '—Do I need to lose weight?\n—Losing a little won\'t hurt, your pressure will drop right away.', ctx: '控制体重' },
  { ru: '— Доктор, как укрепить иммунитет?\n— Таблеток от всех болезней нет. Сон, движение, еда без фанатизма.\n— А витамины попить?\n— Лучше из продуктов. И поменьше стресса — он бьёт сильнее любой простуды.', zh: '—医生，怎么增强免疫力？\n—没有包治百病的药。睡眠、运动、饮食适度。\n—那吃点维生素呢？\n—最好从食物中获取。再就是少点压力，它比感冒伤人多了。', en: '—Doctor, how can I boost my immunity?\n—There\'s no pill for every illness. Sleep, movement, moderate eating.\n—What about taking vitamins?\n—Better from food. And less stress — it hits harder than any cold.', ctx: '增强免疫' },
  { ru: 'Делайте перерывы каждые сорок минут за компьютером.', zh: '用电脑每四十分钟休息一次。', en: 'Take a break every forty minutes at the computer.', ctx: '用眼休息' },
  { ru: '— Можно немного алкоголя?\n— На время лечения лучше полностью отказаться.', zh: '—能喝点酒吗？\n—治疗期间最好完全不喝。', en: '—Can I have a little alcohol?\n—During treatment it\'s better to give it up completely.', ctx: '禁酒建议' },
  { ru: 'Давление измеряйте 2 раза в день и записывайте.', zh: '每天量两次血压并记录下来。', en: 'Measure your blood pressure twice a day and write it down.', ctx: '监测血压', say: 'Давление измеряйте два раза в день и записывайте.' },
  { ru: '— Что делать, чтобы спина не болела?\n— Следите за осанкой и делайте зарядку для спины.', zh: '—怎样才能不让背痛？\n—注意姿势，做做背部锻炼。', en: '—What can I do so my back doesn\'t hurt?\n—Watch your posture and do back exercises.', ctx: '保护脊柱' },
  { ru: '— Анализы в норме, но я как будто разбитый.\n— Возможно, дело в нервах. Много работаете?\n— Очень, отпуск только зимой.\n— Тогда начните с прогулок и отдыха. Если не поможет, придите снова, поищем причину глубже.', zh: '—化验都正常，可我就是浑身没劲。\n—可能是神经紧张。工作很忙吗？\n—很忙，假期要等到冬天。\n—那就先从散步和休息开始。没用的话再来，我们深入查查原因。', en: '—The tests are normal, but I feel completely worn out.\n—Maybe it\'s nerves. Do you work a lot?\n—Very much, vacation is only in winter.\n—Then start with walks and rest. If that doesn\'t help, come again and we\'ll dig deeper.', ctx: '亚健康调理' },
]

// ── 日常服务 / Services / Услуги ──
const SERVICE: Phrase[] = [
  { ru: 'Мне нужно подстричься, желательно сегодня после обеда.', zh: '我想剪个头发，最好今天下午。', en: 'I need a haircut, preferably this afternoon.', ctx: '预约理发' },
  { ru: '— Вы сейчас свободны? Мне бы подровнять чёлку.\n— Подождите минут десять, мастер сейчас освободится.', zh: '——您现在有空吗？我想修一下刘海。\n——等十来分钟吧，师傅马上就好。', en: '— Are you free now? I\'d like my fringe trimmed.\n— Wait about ten minutes, the stylist will be free soon.', ctx: '等位理发' },
  { ru: '— На какое число хотите записаться?\n— Лучше на завтра, часам к десяти утра.', zh: '——您想约哪天？\n——最好明天上午十点左右。', en: '— What day would you like to book?\n— Tomorrow would be best, around ten in the morning.', ctx: '预约时间' },
  { ru: 'Не подскажете, есть ли у вас мастер, который стрижёт детей?', zh: '请问你们有理儿童发的师傅吗？', en: 'Do you happen to have a stylist who cuts children\'s hair?', ctx: '询问儿童理发' },
  { ru: '— Как вас подстричь?\n— Снимите пару сантиметров, а сверху оставьте подлиннее.', zh: '——想怎么剪？\n——剪掉几厘米，上面留长一点。', en: '— How would you like it cut?\n— Take off a couple of centimetres, but leave the top longer.', ctx: '说明发型' },
  { ru: 'Вымойте мне голову и сделайте укладку феном.', zh: '帮我洗头，再吹个造型。', en: 'Wash my hair and blow-dry it into a style.', ctx: '洗头吹造型' },
  { ru: '— Что будем делать с бородой?\n— Подравняйте, но не сбривайте полностью.\n— Хорошо, контуры сделать чётче?\n— Да, и виски уберите покороче.', zh: '——胡子怎么处理？\n——修齐就行，但别全刮掉。\n——好的，轮廓修分明一点？\n——对，鬓角再剪短些。', en: '— What are we doing with the beard?\n— Trim it even, but don\'t shave it off completely.\n— Alright. Shall I make the edges sharper?\n— Yes, and take the sideburns shorter.', ctx: '修剪胡须' },
  { ru: '— Хочу покрасить волосы. Этот цвет меня сильно старит?\n— Совсем нет, он освежает лицо, берите смело.', zh: '——我想染发。这个颜色会显得我很老吗？\n——完全不会，它很提气色，放心选吧。', en: '— I want to dye my hair. Does this colour make me look much older?\n— Not at all, it brightens your face. Go for it.', ctx: '染发咨询' },
  { ru: '— Сколько стоит мужская стрижка с мытьём?\n— Пятьсот рублей, оплата на кассе.', zh: '——男士剪发加洗头多少钱？\n——五百卢布，在收银台付款。', en: '— How much is a men\'s haircut with a wash?\n— Five hundred rubles, pay at the register.', ctx: '询问价格' },
  { ru: 'Если бы вы работали по воскресеньям, я бы только к вам и ходил!', zh: '要是你们周日也开门，我就只来你们家了！', en: 'If only you were open on Sundays, I\'d come only to you!', ctx: '感叹营业时间' },
  { ru: '— Мне нужен маникюр, гель-лак держится долго?\n— Обычно около двух недель, смотря как работаете руками.', zh: '——我想做美甲，甲油胶能保持很久吗？\n——一般两周左右，看您手用得勤不勤。', en: '— I need a manicure. Does gel polish last long?\n— Usually about two weeks, depending on how much you use your hands.', ctx: '美甲咨询' },
  { ru: '— Девушка, вы на окрашивание?\n— Да, я записана на три часа.\n— Проходите, надевайте халат. Какой оттенок выбрали?\n— Каштановый, как на этом образце.', zh: '——姑娘，您是来染发的吗？\n——对，我约了三点。\n——请进，穿上罩衣。选了哪个色号？\n——栗色的，就像这个样本。', en: '— Are you here for colouring?\n— Yes, I have a three o\'clock appointment.\n— Come in, put on the gown. Which shade did you pick?\n— Chestnut, like on this sample.', ctx: '染发登记' },
  { ru: '— Вас устраивает длина?\n— Сзади ещё немного подровняйте, а то неровно.', zh: '——长度您满意吗？\n——后面再修齐一点，有点不齐。', en: '— Are you happy with the length?\n— Trim the back a little more, it\'s uneven.', ctx: '检查长度' },
  { ru: '— Вам понравилось?\n— В целом да, только уложите чёлку набок.\n— Вот так?\n— Именно, спасибо большое.', zh: '——您觉得满意吗？\n——整体可以，就是把刘海往旁边梳。\n——这样吗？\n——就是这样，太谢谢了。', en: '— Do you like it?\n— Overall yes, just sweep the fringe to the side.\n— Like this?\n— Exactly, thank you so much.', ctx: '调整造型' },
  { ru: 'После стрижки соберите, пожалуйста, волосы с моей одежды.', zh: '剪完请帮我把衣服上的碎发弄掉。', en: 'Please brush the cut hairs off my clothes afterwards.', ctx: '清理碎发' },
  { ru: 'Я хотел бы открыть банковскую карту для ежедневных покупок.', zh: '我想办一张日常消费用的银行卡。', en: 'I\'d like to open a bank card for everyday purchases.', ctx: '申请开户' },
  { ru: '— Какие документы нужны для открытия счёта?\n— Только паспорт, а для кредита ещё и справка о доходах.', zh: '——开户需要什么证件？\n——只要护照；贷款的话还要收入证明。', en: '— What documents do I need to open an account?\n— Just your passport. For a loan you\'d also need proof of income.', ctx: '开户材料' },
  { ru: '— Покажете, как перевести деньги через приложение?\n— С удовольствием, давайте начнём с выбора получателя.', zh: '——能教我怎么用软件转账吗？\n——好的，我们先选择收款人。', en: '— Can you show me how to transfer money through the app?\n— Gladly. Let\'s start by choosing the recipient.', ctx: '教学转账' },
  { ru: 'Заблокируйте мою карту, я потерял её в метро.', zh: '请把我的卡挂失，我在地铁里把它丢了。', en: 'Block my card, please. I lost it on the metro.', ctx: '挂失银行卡' },
  { ru: '— Здравствуйте, хочу обменять тысячу долларов.\n— Паспорт приготовьте, пожалуйста.\n— Вот. Деньги сразу получу?\n— Да, подождите у кассы пять минут.', zh: '——您好，我想换一千美元。\n——请准备好护照。\n——给您。钱能马上拿到吗？\n——可以，请在出纳窗口旁等五分钟。', en: '— Hello, I\'d like to exchange a thousand dollars.\n— Please have your passport ready.\n— Here. Will I get the money right away?\n— Yes, wait by the cashier\'s window for five minutes.', ctx: '兑换外币' },
  { ru: '— Какой сегодня курс доллара к рублю?\n— Покупаем по 90, продаём по 92.', zh: '——今天美元对卢布汇率是多少？\n——买入价九十，卖出价九十二。', en: '— What\'s today\'s dollar-to-ruble rate?\n— We buy at ninety and sell at ninety-two.', ctx: '询问汇率', say: '— Какой сегодня курс доллара к рублю?\n— Покупаем по девяноста, продаём по девяноста двум.' },
  { ru: '— Я забыл код от карты, что делать?\n— Его можно сменить в приложении или в банкомате.', zh: '——我忘了卡的密码，怎么办？\n——可以在软件里或取款机上修改。', en: '— I forgot my card\'s PIN code. What should I do?\n— You can change it in the app or at an ATM.', ctx: '忘记密码' },
  { ru: 'Комиссия за перевод в другой банк составляет один процент.', zh: '转到其他银行的手续费是百分之一。', en: 'The commission for a transfer to another bank is one percent.', ctx: '转账手续费' },
  { ru: '— Можно снять деньги с книжки прямо сейчас?\n— Да, заполните этот бланк и подойдите к окошку.', zh: '——现在能从存折上取钱吗？\n——可以，填好这张单子，到窗口来。', en: '— Can I withdraw money from my savings book right now?\n— Yes, fill out this form and come to the window.', ctx: '柜台取款' },
  { ru: '— Мне пришло сообщение о подозрительном переводе.\n— Когда и на какую сумму?\n— Сегодня ночью, на 15 000 рублей.\n— Сейчас проверим и отменим операцию.', zh: '——我收到一条可疑转账的通知。\n——什么时候、多少钱？\n——今天夜里，一万五千卢布。\n——我们马上查一下并撤销这笔交易。', en: '— I got a message about a suspicious transfer.\n— When was it, and for what amount?\n— Last night, for fifteen thousand rubles.\n— We\'ll check it now and cancel the transaction.', ctx: '可疑转账', say: '— Мне пришло сообщение о подозрительном переводе.\n— Когда и на какую сумму?\n— Сегодня ночью, на пятнадцать тысяч рублей.\n— Сейчас проверим и отменим операцию.' },
  { ru: '— Кредит одобрили?\n— Пока на рассмотрении, ответ придёт по смс в течение дня.', zh: '——贷款批了吗？\n——还在审批，今天之内会发短信通知结果。', en: '— Was the loan approved?\n— Still under review. You\'ll get the answer by text during the day.', ctx: '贷款审批', say: '— Кредит одобрили?\n— Пока на рассмотрении, ответ придёт по эсэмэс в течение дня.' },
  { ru: '— Почему не проходит платёж?\n— На карте недостаточно средств, проверьте баланс.', zh: '——为什么支付不成功？\n——卡里余额不足，请查一下余额。', en: '— Why won\'t the payment go through?\n— There aren\'t enough funds on the card; check your balance.', ctx: '支付失败' },
  { ru: 'Не подскажете, как работает ваша система быстрых платежей?', zh: '请问你们的快速支付系统怎么用？', en: 'Could you tell me how your fast payment system works?', ctx: '快速支付' },
  { ru: '— У меня не получается оплатить коммуналку через терминал.\n— Давайте посмотрим. Какую услугу выбираете?\n— Квартплату, вот квитанция.\n— А, нужен девятизначный код, его-то вы и не ввели.', zh: '——我在终端上交不了物业费。\n——我来看一下。您选的是哪项服务？\n——房租物业费，这是缴费单。\n——啊，需要九位编码，您就是没输这个。', en: '— I can\'t pay my utility bill through the terminal.\n— Let me take a look. Which service are you selecting?\n— Rent and utilities, here\'s the bill.\n— Ah, you need a nine-digit code — that\'s what you didn\'t enter.', ctx: '终端缴费' },
  { ru: '— Ваш вклад можно пополнять?\n— Да, и проценты у нас выше, чем у конкурентов.', zh: '——你们这个存款可以续存吗？\n——可以，而且我们的利息比别家高。', en: '— Can I add to my deposit?\n— Yes, and our interest rates are higher than our competitors\'.', ctx: '咨询存款' },
  { ru: 'Мне нужно отправить эту книгу в Москву заказной бандеролью.', zh: '我想把这本书用挂号印刷品寄到莫斯科。', en: 'I need to send this book to Moscow by registered printed matter.', ctx: '寄印刷品' },
  { ru: '— Сколько идёт посылка до Владивостока?\n— Обычно неделю, а авиапочтой дня три-четыре.', zh: '——包裹寄到海参崴要多久？\n——一般一周，航空的话三四天。', en: '— How long does a parcel to Vladivostok take?\n— Usually a week; by airmail, three or four days.', ctx: '查询时效' },
  { ru: 'Скажите, а вы принимаете посылки в своём пакете, без коробки?', zh: '请问不用纸箱、用我自己的袋子可以寄包裹吗？', en: 'Tell me, do you accept parcels in my own bag, without a box?', ctx: '自带包装' },
  { ru: '— Девушка, мне посылка пришла?\n— Давайте номер извещения, сейчас проверю.', zh: '——姑娘，我的包裹到了吗？\n——给我通知单号，我这就查。', en: '— Has my parcel arrived?\n— Give me the notification number and I\'ll check now.', ctx: '领取包裹' },
  { ru: '— Вот, взвешивайте.\n— Два килограмма триста граммов. Отправляем оценённой?\n— Да, объявленная ценность — тысяча рублей.\n— Тогда заполните таможенную декларацию.', zh: '——给，称吧。\n——两公斤零三百克。按保价寄吗？\n——对，申报价值一千卢布。\n——那请填一张海关申报单。', en: '— Here, weigh it.\n— Two kilograms three hundred grams. Sending it insured?\n— Yes, declared value is one thousand rubles.\n— Then fill out a customs declaration.', ctx: '包裹称重' },
  { ru: 'Положите, пожалуйста, внутрь побольше пупырки, чтобы не разбилось.', zh: '请在里面多放点气泡膜，免得打碎。', en: 'Please put plenty of bubble wrap inside so nothing breaks.', ctx: '易碎包装' },
  { ru: '— Курьер сегодня точно приедет?\n— Он уже в вашем районе, ждите в течение часа.', zh: '——快递员今天肯定会来吗？\n——他已经到您那个片区了，一小时内会到。', en: '— Will the courier definitely come today?\n— He\'s already in your area; expect him within an hour.', ctx: '等待快递' },
  { ru: '— Мне нужно отправить документы за границу.\n— Курьерской службой или обычной почтой?\n— Курьером, так быстрее.\n— Тогда это будет стоить 2 500 рублей, доставка за три дня.', zh: '——我要把文件寄到国外。\n——用快递还是普通邮政？\n——快递，那样快些。\n——那费用是两千五卢布，三天送达。', en: '— I need to send documents abroad.\n— By courier service or regular post?\n— Courier, it\'s faster.\n— Then it\'ll cost two thousand five hundred rubles, delivery in three days.', ctx: '寄文件出国', say: '— Мне нужно отправить документы за границу.\n— Курьерской службой или обычной почтой?\n— Курьером, так быстрее.\n— Тогда это будет стоить две тысячи пятьсот рублей, доставка за три дня.' },
  { ru: '— Почему посылка вернулась обратно?\n— Получатель не забрал её за месяц, вот и вернули.', zh: '——包裹为什么被退回来了？\n——收件人一个月没取，就退回来了。', en: '— Why did the parcel come back?\n— The recipient didn\'t collect it within a month, so it was returned.', ctx: '包裹退回' },
  { ru: 'Распишитесь, пожалуйста, здесь и предъявите паспорт.', zh: '请在这里签字，并出示护照。', en: 'Please sign here and show your passport.', ctx: '签收查验' },
  { ru: '— Можно отследить письмо по трек-номеру на сайте?\n— Да, введите его в строку поиска на главной странице.', zh: '——能在网站上凭单号查信件状态吗？\n——可以，在首页的搜索栏输入单号即可。', en: '— Can I track a letter by its tracking number on the website?\n— Yes, enter it in the search bar on the homepage.', ctx: '物流追踪' },
  { ru: '— У вас есть конверты для документов?\n— Есть плотные, по пятьдесят рублей за штуку.', zh: '——你们有装文件的信封吗？\n——有厚款的，五十卢布一个。', en: '— Do you have envelopes for documents?\n— We have sturdy ones, fifty rubles each.', ctx: '购买信封' },
  { ru: '— Взвесьте ещё раз, мне кажется, весы врут.\n— Да они точные, смотрите: килограмм двести.\n— Странно, дома было меньше.\n— Может, упаковку не учли, она граммов сто весит.', zh: '——请再称一次，我觉得秤不准。\n——秤准着呢，您看：一公斤二百克。\n——奇怪，在家称没这么重。\n——可能您没算包装，包装也有一百来克。', en: '— Weigh it again, I think the scale is off.\n— It\'s accurate, look: one kilogram two hundred.\n— Strange, it weighed less at home.\n— Maybe you didn\'t count the packaging; it\'s around a hundred grams.', ctx: '复称包裹' },
  { ru: '— Я не успеваю забрать посылку, вы работаете в субботу?\n— Да, но отделение закрывается в шесть вечера.', zh: '——我来不及取包裹，你们周六上班吗？\n——上，但网点晚上六点关门。', en: '— I won\'t make it in time to collect my parcel. Are you open on Saturday?\n— Yes, but the branch closes at six in the evening.', ctx: '周六取件' },
  { ru: 'Отправьте, пожалуйста, уведомление о вручении на мой телефон.', zh: '请把签收通知发到我的手机上。', en: 'Please send the delivery confirmation to my phone.', ctx: '签收通知' },
  { ru: 'У меня прорвало трубу на кухне, вода льётся на пол!', zh: '我家厨房水管爆了，水往地上流！', en: 'A pipe burst in my kitchen and water is pouring onto the floor!', ctx: '水管爆裂' },
  { ru: '— Мастер сможет приехать сегодня?\n— Срочный вызов есть, но он дороже на пятьсот рублей.', zh: '——师傅今天能上门吗？\n——有紧急上门，但要加收五百卢布。', en: '— Can a technician come today?\n— There\'s an emergency call-out, but it costs five hundred rubles more.', ctx: '紧急上门' },
  { ru: '— Вы ремонтируете стиральные машины на дому?\n— Да, если поломка несерьёзная, разберёмся на месте.', zh: '——洗衣机你们上门修吗？\n——修，如果故障不严重，当场就能处理。', en: '— Do you repair washing machines at home?\n— Yes, if the fault isn\'t serious, we\'ll sort it on the spot.', ctx: '洗衣机维修' },
  { ru: 'Что может значить, если холодильник стал сильно гудеть?', zh: '冰箱开始嗡嗡响得厉害，可能是什么问题？', en: 'What could it mean if the fridge has started humming loudly?', ctx: '冰箱异响' },
  { ru: '— Розетка искрит, когда включаю чайник.\n— Другие приборы из неё выдернули?\n— Да, конечно, я сразу всё выключил.\n— Ничего не трогайте, электрик приедет к вечеру.', zh: '——我一插电水壶，插座就打火。\n——其他电器都拔下来了吗？\n——当然，我立刻把所有电源都断了。\n——什么都别碰，电工傍晚前到。', en: '— The socket sparks when I plug in the kettle.\n— Did you unplug the other devices from it?\n— Yes, of course, I switched everything off at once.\n— Don\'t touch anything. An electrician will come by evening.', ctx: '插座打火' },
  { ru: '— Ноутбук сильно греется и сам выключается. Чините?\n— Чиним, похоже на систему охлаждения, привозите на диагностику.', zh: '——笔记本很烫还自动关机，能修吗？\n——能修，像是散热系统的问题，您带来检测一下。', en: '— My laptop overheats and shuts down by itself. Can you fix it?\n— We can. It sounds like the cooling system; bring it in for diagnostics.', ctx: '笔记本维修' },
  { ru: '— Сколько будет стоить замена экрана на телефоне?\n— Сам экран плюс работа, примерно восемь тысяч.', zh: '——手机换屏大概多少钱？\n——屏幕加工钱，大约八千。', en: '— How much would a phone screen replacement cost?\n— The screen itself plus labour, around eight thousand.', ctx: '换屏询价' },
  { ru: 'Посмотрите, пожалуйста, замок, ключ в нём застревает.', zh: '请帮忙看看锁，钥匙卡在里面了。', en: 'Please look at the lock; the key gets stuck in it.', ctx: '门锁故障' },
  { ru: '— Гарантия на ремонт есть?\n— Да, полгода, если что — исправим бесплатно.', zh: '——维修有保修吗？\n——有，半年，有问题免费返修。', en: '— Is there a warranty on the repair?\n— Yes, six months. If anything\'s wrong, we\'ll fix it free.', ctx: '维修保修' },
  { ru: '— Кран капает всю ночь, невозможно спать.\n— Прокладку надо менять, это недолго.', zh: '——水龙头滴了一整夜，根本没法睡。\n——得换密封圈，用不了多久。', en: '— The tap dripped all night, impossible to sleep.\n— The washer needs replacing; it won\'t take long.', ctx: '水龙头滴水' },
  { ru: 'Мне нужно повесить люстру и починить дверной звонок.', zh: '我要装一盏吊灯，再修一下门铃。', en: 'I need a chandelier hung and the doorbell fixed.', ctx: '安装吊灯' },
  { ru: '— Мастер опаздывает уже на час!\n— Он застрял в пробке, скоро будет, извините.\n— Ладно, только предупреждайте заранее.\n— Конечно, больше такого не повторится.', zh: '——师傅已经迟到一个小时了！\n——他堵在路上了，马上就到，抱歉。\n——行吧，不过下次要提前说一声。\n——一定，不会再这样了。', en: '— The technician is already an hour late!\n— He\'s stuck in traffic, he\'ll be there soon, sorry.\n— Alright, just warn people in advance.\n— Of course, it won\'t happen again.', ctx: '师傅迟到' },
  { ru: '— Деталь заказывать будем?\n— Да, сколько её ждать?\n— От трёх дней до недели.\n— Хорошо, позвоните, когда привезут.', zh: '——配件要订货吗？\n——要，要等多久？\n——三天到一周。\n——好，货到了请打电话。', en: '— Are we going to order the part?\n— Yes. How long is the wait?\n— Three days to a week.\n— Fine, call when it arrives.', ctx: '订购配件' },
  { ru: '— После вашего ремонта обои в коридоре остались грязными.\n— Не волнуйтесь, завтра заедем и всё отмоем.', zh: '——你们修完以后，走廊的壁纸弄脏了。\n——别担心，我们明天过去把它洗干净。', en: '— After your repair, the wallpaper in the hallway was left dirty.\n— Don\'t worry, we\'ll stop by tomorrow and clean it all off.', ctx: '维修纠纷' },
  { ru: '— Оплата наличными или можно перевести?\n— Как удобно, но только после того, как подпишете акт.', zh: '——付现金还是可以转账？\n——都行，但要等您签完验收单。', en: '— Payment in cash, or can I make a transfer?\n— Whichever you prefer, but only after you sign the completion report.', ctx: '维修付款' },
  { ru: 'Я ищу однокомнатную квартиру рядом с метро, недорого.', zh: '我想在地铁附近找一套不贵的一居室。', en: 'I\'m looking for an inexpensive one-bedroom flat near the metro.', ctx: '找房需求' },
  { ru: '— Сколько стоит залог и когда его возвращают?\n— Месячная плата, вернём при выезде, если всё цело.', zh: '——押金是多少、什么时候退？\n——一个月房租，退房时东西没损坏就退。', en: '— How much is the deposit and when is it returned?\n— One month\'s rent; you\'ll get it back when you leave, if everything\'s intact.', ctx: '押金退还' },
  { ru: 'В эту сумму уже включены свет и вода?', zh: '这个价钱已经包含水电了吗？', en: 'Are electricity and water already included in that amount?', ctx: '费用包含' },
  { ru: '— Можно в квартире с маленькой собакой?\n— Хозяин против животных, извините.', zh: '——可以带小狗住吗？\n——房东不让养宠物，不好意思。', en: '— Would a small dog be allowed in the flat?\n— The landlord won\'t allow pets, sorry.', ctx: '能否养宠' },
  { ru: '— Когда можно посмотреть квартиру?\n— Сегодня вечером после шести устроит?\n— Да, вполне, давайте адрес.\n— Улица Ленина, дом двенадцать, квартира тридцать.', zh: '——什么时候可以看房？\n——今天晚上六点以后行吗？\n——完全可以，给我地址吧。\n——列宁街12号30室。', en: '— When can I view the flat?\n— Would this evening after six work?\n— Yes, perfectly. Give me the address.\n— Twelve Lenina Street, flat thirty.', ctx: '预约看房' },
  { ru: 'Хозяйка требует платить за месяц вперёд, это вообще законно?', zh: '房东要求预付一个月房租，这合法吗？', en: 'The landlady demands a month\'s rent in advance. Is that even legal?', ctx: '预付房租' },
  { ru: '— Стиральная машина в квартире есть?\n— Да, и холодильник новый, его в прошлом году купили.', zh: '——房里有洗衣机吗？\n——有，冰箱还是新的，去年刚买的。', en: '— Is there a washing machine in the flat?\n— Yes, and the fridge is new, bought last year.', ctx: '家电配置' },
  { ru: '— Мебель в квартире чья?\n— Вся хозяйская, своё можно только с её согласия привозить.', zh: '——屋里的家具是谁的？\n——都是房东的，带自己的东西得经过她同意。', en: '— Whose furniture is in the flat?\n— All the landlady\'s. You can bring your own only with her consent.', ctx: '家具归属' },
  { ru: '— Старая мебель вас не смущает?\n— Нисколько, главное, чтобы матрас был удобный.', zh: '——家具旧您介意吗？\n——一点也不，主要床垫舒服就行。', en: '— Doesn\'t the old furniture bother you?\n— Not at all. What matters is a comfortable mattress.', ctx: '家具老旧' },
  { ru: '— Вы договор заключать будете?\n— Обязательно, без договора я платить не стану.\n— Тогда возьмите паспорт, завтра подпишем.\n— А копию договора сразу дадите?', zh: '——您签合同吗？\n——当然签，不签合同我不会付钱。\n——那请带上护照，我们明天签。\n——合同副本当天能给吗？', en: '— Will you be signing a contract?\n— Definitely. I won\'t pay without one.\n— Then bring your passport and we\'ll sign tomorrow.\n— Will I get a copy of the contract right away?', ctx: '签订合同' },
  { ru: '— Соседи сверху шумные?\n— Бабушка живёт, так что тихо, вам повезло.', zh: '——楼上邻居吵不吵？\n——住着一位老奶奶，很安静，您运气不错。', en: '— Are the neighbours upstairs noisy?\n— A grandmother lives there, so it\'s quiet. You\'re in luck.', ctx: '询问邻居' },
  { ru: '— Ребята, с дивана снимайте ножки, так в дверь пройдёт.\n— Хорошо, а коробки на кухню нести?\n— Нет, пока в большую комнату, я потом разберу.\n— Как скажете, покажите только, куда ставить.', zh: '——兄弟们，把沙发腿拆下来，这样就能进门了。\n——好的，箱子搬厨房吗？\n——不，先放大客厅，我回头再整理。\n——听您的，您告诉我们放哪儿就行。', en: '— Guys, take the legs off the sofa, then it\'ll fit through the door.\n— Okay. Shall we carry the boxes to the kitchen?\n— No, into the main room for now, I\'ll sort them later.\n— As you say; just show us where to put things.', ctx: '搬家搬货' },
  { ru: 'Упакуйте, пожалуйста, посуду в отдельные коробки и подпишите их.', zh: '请把餐具单独装箱，并在箱子上写明。', en: 'Please pack the dishes in separate boxes and label them.', ctx: '餐具打包' },
  { ru: '— Откуда выезжаете и куда везём?\n— С третьего этажа на девятый, это в соседнем районе.', zh: '——从哪儿搬、搬到哪儿？\n——从三楼到九楼，就在隔壁街区。', en: '— Where are you moving from and where to?\n— From the third floor to the ninth, in the neighbouring district.', ctx: '搬运路线' },
  { ru: 'Как же надоел этот переезд, спина второй день болит!', zh: '搬家真折腾人，我背都疼了两天了！', en: 'I\'m so fed up with this move; my back has ached for two days!', ctx: '搬家劳累' },
  { ru: 'Мне нужно сдать в химчистку зимнее пальто.', zh: '我想把冬天的大衣送去干洗。', en: 'I need to take my winter coat to the dry cleaner\'s.', ctx: '送洗大衣' },
  { ru: '— Когда будет готово?\n— Через два дня, к четвергу точно успеем.', zh: '——什么时候能取？\n——两天后，星期四肯定好。', en: '— When will it be ready?\n— In two days; it\'ll definitely be done by Thursday.', ctx: '取件时间' },
  { ru: '— Вы выводите пятна от красного вина с шёлка?\n— Постараемся, но стопроцентной гарантии на шёлк не даём.', zh: '——丝绸上的红酒渍你们能去掉吗？\n——我们尽力，但丝绸不敢打百分百保票。', en: '— Can you remove red wine stains from silk?\n— We\'ll try, but we don\'t offer a full guarantee on silk.', ctx: '丝绸去渍' },
  { ru: 'Эта куртка с наполнителем, её можно стирать в машине?', zh: '这件外套有填充物，可以机洗吗？', en: 'This jacket has filling. Can it be machine-washed?', ctx: '羽绒服清洗' },
  { ru: '— Посмотрите, здесь пятно от соуса.\n— Свежее? Тогда, скорее всего, сведём.\n— А если не получится?\n— Вернём деньги за чистку, но такое редко бывает.', zh: '——您看，这儿有个酱汁渍。\n——刚弄的吗？那多半能去掉。\n——要是去不掉呢？\n——退还清洗费，不过这种情况很少见。', en: '— Look, there\'s a sauce stain here.\n— Is it fresh? Then we\'ll most likely get it out.\n— And if you can\'t?\n— We\'ll refund the cleaning, but that rarely happens.', ctx: '酱汁污渍' },
  { ru: 'Сколько стоит выстирать и погладить мужскую рубашку?', zh: '洗一件男式衬衫并熨好要多少钱？', en: 'How much does it cost to wash and iron a men\'s shirt?', ctx: '衬衫洗熨' },
  { ru: '— Вам обычная стирка или деликатная?\n— Деликатная, вещи у меня шерстяные.', zh: '——普通洗还是轻柔洗？\n——轻柔洗，我的都是羊毛衣物。', en: '— Regular wash or delicate?\n— Delicate, my things are woollen.', ctx: '洗涤方式' },
  { ru: '— Пуховик после чистки не сядет?\n— Нет, сушим в специальной машине, будет как новый.', zh: '——羽绒服洗完不会缩水吧？\n——不会，我们用专用机器烘干，跟新的一样。', en: '— Won\'t the down jacket shrink after cleaning?\n— No, we dry it in a special machine; it\'ll be like new.', ctx: '洗后缩水' },
  { ru: '— Свитер повесьте на плечики, ладно?\n— Не стоит, он тогда растянется, лучше сложите.', zh: '——毛衣挂上衣架，行吗？\n——别挂，会拉长变形，最好叠起来。', en: '— Hang the sweater on a hanger, okay?\n— Better not, it\'ll stretch. Fold it instead.', ctx: '毛衣悬挂' },
  { ru: '— Вот ваша квитанция, не теряйте.\n— А если потеряю?\n— Тогда приходите с паспортом.\n— Понял, спасибо, до четверга.', zh: '——这是您的取衣单，别丢了。\n——要是丢了呢？\n——那就带护照来。\n——明白了，谢谢，周四见。', en: '— Here\'s your receipt, don\'t lose it.\n— What if I do?\n— Then come with your passport.\n— Got it, thanks. See you Thursday.', ctx: '遗失凭证' },
  { ru: 'Заберите, пожалуйста, бельё из стирки и сложите в пакет.', zh: '请把洗好的衣物取出来装进袋子。', en: 'Please take the laundry out of the wash and put it in a bag.', ctx: '取出衣物' },
  { ru: '— У вас есть экспресс-чистка за один день?\n— Есть, но это плюс пятьдесят процентов к цене.', zh: '——你们有一天取的加急干洗吗？\n——有，但要加收百分之五十。', en: '— Do you have one-day express cleaning?\n— We do, but it\'s plus fifty percent of the price.', ctx: '加急清洗' },
  { ru: '— После вашей стирки на футболке остались разводы.\n— Давайте посмотрим... Да, это мы виноваты, перестираем.\n— А когда забрать можно?\n— Завтра после обеда, приношу извинения.', zh: '——在你们这儿洗完，T恤上留下了印子。\n——我看看……确实是我们的问题，给您重洗。\n——什么时候能取？\n——明天下午，非常抱歉。', en: '— After your wash, there are streaks left on the T-shirt.\n— Let me see... Yes, that\'s our fault, we\'ll rewash it.\n— When can I pick it up?\n— Tomorrow afternoon. My apologies.', ctx: '洗涤纠纷' },
  { ru: '— Погладьте брюки со стрелками, сможете?\n— Да, это уже входит в стоимость чистки.', zh: '——西裤能熨出裤线吗？\n——可以，这已经包含在干洗费里了。', en: '— Can you press the trousers with creases?\n— Yes, that\'s already included in the cleaning price.', ctx: '熨烫西裤' },
  { ru: '— Шторы можно сдать в чистку вместе с тюлем?\n— Можно, только снимайте с люверсами, они нам не помешают.', zh: '——窗帘能和纱帘一起送来洗吗？\n——可以，带着金属扣眼一起拆下就行，不碍事。', en: '— Can I have the curtains cleaned together with the sheers?\n— You can, just take them down with the grommets; they won\'t bother us.', ctx: '清洗窗帘' },
  { ru: 'Мне нужно сделать регистрацию по месту жительства.', zh: '我要办理居住登记。', en: 'I need to get registration at my place of residence.', ctx: '居住登记' },
  { ru: '— Какие документы нужны для продления визы?\n— Паспорт, миграционная карта и заявление от принимающей стороны.', zh: '——延期签证需要哪些材料？\n——护照、移民卡，还有接待方出具的申请。', en: '— What documents are needed to extend a visa?\n— Your passport, migration card, and an application from the host party.', ctx: '延期材料' },
  { ru: 'Где можно встать на миграционный учёт?', zh: '在哪里可以办理落地签（移民登记）？', en: 'Where can I register for migration records?', ctx: '落地签办理' },
  { ru: '— Моя виза заканчивается через неделю, успею продлить?\n— Если документы готовы, да, лучше не тянуть.', zh: '——我的签证一周后到期，来得及延期吗？\n——材料齐全就来得及，最好别拖。', en: '— My visa expires in a week. Will I have time to extend it?\n— If your documents are ready, yes. Better not delay.', ctx: '签证将到期' },
  { ru: '— Здравствуйте, я потерял миграционную карту.\n— Когда въехали в страну?\n— Месяц назад, вот штамп в паспорте.\n— Пишите заявление, оформим дубликат.', zh: '——您好，我把移民卡弄丢了。\n——您什么时候入境的？\n——一个月前，护照上有章。\n——写份申请，我们给您补办。', en: '— Hello, I lost my migration card.\n— When did you enter the country?\n— A month ago, here\'s the stamp in my passport.\n— Write an application and we\'ll issue a duplicate.', ctx: '补办移民卡' },
  { ru: '— Хозяин обязан прийти со мной на регистрацию?\n— Не обязательно, хватит его паспорта и заявления.', zh: '——房东必须陪我一起来登记吗？\n——不一定，有他的护照和申请就够了。', en: '— Does the landlord have to come with me to the registration?\n— Not necessarily; his passport and application are enough.', ctx: '房东到场' },
  { ru: '— Сколько дней делается регистрация?\n— Три рабочих дня, приходите в четверг.', zh: '——登记要办几天？\n——三个工作日，您周四来。', en: '— How many days does registration take?\n— Three business days. Come on Thursday.', ctx: '登记时长' },
  { ru: '— Это окно занимается визами?\n— Нет, вам в тринадцатый кабинет, по коридору направо.', zh: '——这个窗口办签证吗？\n——不办，您去13号办公室，沿走廊往右。', en: '— Does this window handle visas?\n— No, you need room thirteen, along the corridor to the right.', ctx: '窗口指引' },
  { ru: 'Мне отказали в продлении, хотя все документы были в порядке.', zh: '我材料都齐全，延期却被拒了。', en: 'They refused my extension even though all my documents were in order.', ctx: '延期被拒' },
  { ru: '— Скажите, можно выезжать, пока документы на продлении?\n— Не стоит, потом будут вопросы на границе.', zh: '——请问延期办理期间可以出境吗？\n——最好别去，边检那边会有麻烦。', en: '— Tell me, can I leave the country while my extension is being processed?\n— Better not; you\'ll face questions at the border.', ctx: '延期期间出境' },
  { ru: '— Встаньте, пожалуйста, в очередь по талону.\n— А где взять талон?\n— В автомате у входа, выберите «регистрация».\n— Спасибо, а то я тут впервые.', zh: '——请按叫号单排队等候。\n——号码单在哪儿取？\n——在门口的机器上，选「登记」。\n——谢谢，我头一回来这儿。', en: '— Please join the queue according to your ticket.\n— Where do I get a ticket?\n— From the machine at the entrance; choose "registration".\n— Thanks, it\'s my first time here.', ctx: '取号排队' },
  { ru: '— У меня в паспорте нет перевода печати.\n— Тогда сначала заверьте перевод у нотариуса.', zh: '——我护照里没有印章的翻译件。\n——那请先去公证处公证翻译件。', en: '— There\'s no translation of the stamp in my passport.\n— Then first have the translation certified by a notary.', ctx: '翻译盖章' },
  { ru: 'Продлите мне регистрацию ещё на три месяца, я продлеваю контракт.', zh: '请把我的登记再延长三个月，我在续签合同。', en: 'Extend my registration for another three months; I\'m renewing my contract.', ctx: '延长登记' },
  { ru: '— Штраф за просрочку регистрации большой?\n— От пяти до семи тысяч, смотря на сколько просрочили.\n— А если я заплачу сразу?\n— Всё равно отметка останется, так что больше не нарушайте.', zh: '——登记逾期的罚款重吗？\n——五千到七千不等，看您超了多久。\n——我马上交呢？\n——记录照样会留下，所以以后别再犯了。', en: '— Is the fine for overdue registration large?\n— From five to seven thousand, depending on how late you are.\n— What if I pay right away?\n— The mark stays regardless, so don\'t break the rules again.', ctx: '逾期罚款' },
  { ru: 'Наконец-то поставили штамп, я целую неделю волновался!', zh: '章终于盖好了，我担心了整整一周！', en: 'The stamp is finally in; I worried for a whole week!', ctx: '办妥签章' },
  { ru: 'Мне нужна справка о несудимости для работы за границей.', zh: '我需要一份无犯罪记录证明，用于去国外工作。', en: 'I need a certificate of no criminal record for working abroad.', ctx: '无犯罪证明' },
  { ru: '— Где заверяют копию паспорта?\n— У нотариуса, кабинет на втором этаже.', zh: '——护照复印件在哪儿公证？\n——找公证员，二楼的办公室。', en: '— Where do I get a copy of my passport certified?\n— At the notary\'s, the office on the second floor.', ctx: '护照公证' },
  { ru: '— Как получить справку о составе семьи?\n— Закажите на госуслугах или в паспортном столе.', zh: '——家庭人口组成证明怎么开？\n——在政务服务网站上预约，或去户籍窗口办理。', en: '— How do I get a certificate of family composition?\n— Order it on the state services portal or at the passport office.', ctx: '家庭关系证明' },
  { ru: 'Заявление писать от руки или можно распечатать?', zh: '申请要手写，还是可以打印？', en: 'Should the application be handwritten or can I print it?', ctx: '申请方式' },
  { ru: '— Девушка, мне нужно заверить доверенность.\n— На кого доверенность и для чего?\n— На жену, чтобы она получила мои документы.\n— Тогда оба паспорта с собой есть?', zh: '——姑娘，我要公证一份委托书。\n——委托给谁、做什么用？\n——给我妻子，让她替我领取证件。\n——那您带了两个人的护照吗？', en: '— I need a power of attorney certified.\n— In whose favour, and what for?\n— My wife\'s, so she can collect my documents.\n— Do you have both passports with you then?', ctx: '委托公证' },
  { ru: 'Эта справка действительна только полгода, потом закажете новую.', zh: '这份证明有效期只有半年，之后要重新开。', en: 'This certificate is valid for only six months; you\'ll order a new one later.', ctx: '证明有效期' },
  { ru: '— Можно заказать справку через сайт госуслуг?\n— Да, пришлём на почту или заберёте здесь сами.', zh: '——可以通过政务服务网站开证明吗？\n——可以，我们寄到您邮箱，或者您自己来取。', en: '— Can I order the certificate through the state services website?\n— Yes. We\'ll send it by post or you can collect it here.', ctx: '线上开证明' },
  { ru: '— Вы по записи или в порядке очереди?\n— По записи, на два часа.\n— Покажите талон... проходите.\n— Спасибо, все оригиналы у меня с собой.', zh: '——您是预约的还是排队？\n——预约的，两点。\n——出示一下号码单……请进。\n——谢谢，所有原件我都带了。', en: '— Are you by appointment or in the queue?\n— By appointment, for two o\'clock.\n— Show your ticket... go ahead in.\n— Thank you, I have all the originals with me.', ctx: '预约办事' },
  { ru: '— Поставьте апостиль на диплом, это долго?\n— Недели две, раньше, к сожалению, никак.', zh: '——请在毕业证上办海牙认证，要很久吗？\n——两周左右，很遗憾没法更快。', en: '— Put an apostille on my diploma. Will it take long?\n— About two weeks; sooner is unfortunately impossible.', ctx: '学历认证' },
  { ru: '— Перевод диплома нужен с нотариальным заверением?\n— Да, без него документ за границей не примут.', zh: '——毕业证翻译需要公证吗？\n——需要，没有公证国外不认可。', en: '— Does the diploma translation need notarisation?\n— Yes; without it the document won\'t be accepted abroad.', ctx: '翻译公证' },
  { ru: '— Я два часа простоял, а окно закрылось!\n— Не переживайте, я вас приму, давайте ваши документы.', zh: '——我站着等了两个小时，窗口却关了！\n——别着急，我来给您办，请把材料给我。', en: '— I stood waiting for two hours and the window closed!\n— Don\'t worry, I\'ll take you. Give me your documents.', ctx: '窗口已关' },
  { ru: '— Госпошлину уже оплатили?\n— Да, вот квитанция из банка.', zh: '——规费已经交了吗？\n——交了，这是银行的收据。', en: '— Have you paid the state fee yet?\n— Yes, here\'s the bank receipt.', ctx: '查验缴费' },
  { ru: '— В свидетельстве о рождении опечатка в имени.\n— Тогда нужно внести исправление через ЗАГС.\n— А это долго?\n— Займёт неделю-другую, приходите со свидетельством.', zh: '——出生证上的名字打错了。\n——那需要通过户籍登记处更正。\n——要很久吗？\n——一两周吧，带上出生证来办。', en: '— There\'s a typo in the name on the birth certificate.\n— Then you need the correction made through the civil registry office.\n— Will it take long?\n— A week or two. Come with the certificate.', ctx: '证件更正', say: '— В свидетельстве о рождении опечатка в имени.\n— Тогда нужно внести исправление через отдел записи актов гражданского состояния.\n— А это долго?\n— Займёт неделю или две, приходите со свидетельством.' },
  { ru: '— Нотариус сегодня принимает?\n— Только по записи, свободных окон, увы, нет.', zh: '——公证员今天接待吗？\n——只接待预约的，可惜没有空档了。', en: '— Is the notary seeing clients today?\n— Only by appointment; there are no free slots, alas.', ctx: '预约公证' },
  { ru: 'Продлите, пожалуйста, доверенность ещё на один год.', zh: '请把委托书再延长一年。', en: 'Please extend the power of attorney for another year.', ctx: '续签委托' },
  { ru: 'Мне нужна уборка квартиры после ремонта.', zh: '装修结束后我需要找人打扫公寓。', en: 'I need my flat cleaned after the renovation.', ctx: '装修后保洁' },
  { ru: '— Сколько стоит уборка двухкомнатной квартиры?\n— По тарифу четыре тысячи, окна моем отдельно.', zh: '——两居室打扫一次多少钱？\n——按标准价四千，擦窗户另算。', en: '— How much does cleaning a two-room flat cost?\n— The standard rate is four thousand; we wash windows separately.', ctx: '保洁报价' },
  { ru: 'Вы привозите свои средства для мытья или пользоваться моими?', zh: '清洁剂你们自带，还是用我的？', en: 'Do you bring your own cleaning products or should I use mine?', ctx: '清洁用品' },
  { ru: '— Нужно помыть окна и балкон.\n— Тогда это плюс тысяча рублей, хорошо?', zh: '——需要擦窗户和阳台。\n——那要加一千卢布，可以吗？', en: '— The windows and balcony need washing.\n— Then it\'s plus one thousand rubles, okay?', ctx: '清洗窗户' },
  { ru: '— В какой день вам удобно?\n— Лучше в субботу, утром.\n— К восьми подойдёт?\n— Да, домофон у подъезда, наберите сорок пять.', zh: '——您哪天方便？\n——最好周六上午。\n——八点可以吗？\n——可以，单元门有对讲，请按45。', en: '— What day suits you?\n— Saturday morning would be best.\n— Does eight o\'clock work?\n— Yes, use the intercom at the entrance and dial forty-five.', ctx: '预约时间' },
  { ru: 'Уборщица приходит два раза в неделю, по вторникам и пятницам.', zh: '保洁每周来两次，周二和周五。', en: 'The cleaner comes twice a week, on Tuesdays and Fridays.', ctx: '固定保洁' },
  { ru: '— Холодильник внутри тоже мыть?\n— Да, и микроволновку не забудьте, она вся жирная.', zh: '——冰箱里面也洗吗？\n——洗，微波炉也别忘了，上面全是油。', en: '— Should the fridge be washed inside too?\n— Yes, and don\'t forget the microwave; it\'s all greasy.', ctx: '清洗冰箱' },
  { ru: '— В ванной плесень в углу, сможете убрать?\n— Попробуем специальным средством.\n— А если не отмоется?\n— Тогда уже ремонт нужен, химия не поможет.', zh: '——浴室角落有霉斑，能去掉吗？\n——我们用专用清洁剂试试。\n——万一洗不掉呢？\n——那就得翻新了，清洁剂帮不上忙。', en: '— There\'s mould in the bathroom corner. Can you remove it?\n— We\'ll try with a special product.\n— What if it won\'t wash off?\n— Then renovation is needed; chemicals won\'t help.', ctx: '浴室除霉' },
  { ru: '— Ковёр пылесосим или вывезем на химчистку?\n— Пропылесосьте, пятен на нём вроде бы нет.', zh: '——地毯是吸尘还是送干洗？\n——吸尘吧，上面好像没有污渍。', en: '— Do we vacuum the carpet or take it for dry cleaning?\n— Vacuum it; there don\'t seem to be any stains on it.', ctx: '清洁地毯' },
  { ru: '— Вы бельё гладите?\n— Да, но это отдельная услуга, скажите, сколько вещей.', zh: '——你们熨衣服吗？\n——熨，但这是另收费的项目，请问有多少件。', en: '— Do you iron clothes?\n— Yes, but it\'s a separate service. Tell me how many items.', ctx: '洗衣服务' },
  { ru: '— Мусор после уборки сами вынесете?\n— Да, сложим в мешки и спустим вниз.', zh: '——打扫完的垃圾你们会带走吗？\n——会，我们装进袋子拿下楼。', en: '— Will you take the rubbish out yourselves after cleaning?\n— Yes, we\'ll bag it and carry it downstairs.', ctx: '垃圾清运' },
  { ru: '— После генеральной уборки гарантия есть?\n— А что вы имеете в виду?\n— Если где-то останется грязь, переделаете?\n— Конечно, просто позвоните в течение двух дней.', zh: '——大扫除之后有保障吗？\n——您指的是什么？\n——要是哪儿没干净，会返工吗？\n——当然，两天内打电话就行。', en: '— Is there a guarantee after the deep clean?\n— What do you mean exactly?\n— If dirt is left somewhere, will you redo it?\n— Of course, just call within two days.', ctx: '保洁质保' },
  { ru: '— Не передвигайте тяжёлую мебель, пожалуйста.\n— Не будем, а под кроватью подметём шваброй.', zh: '——请别挪动沉重的家具。\n——不会的，床底下我们用拖把拖。', en: '— Please don\'t move the heavy furniture.\n— We won\'t. We\'ll sweep under the bed with a mop.', ctx: '保护家具' },
  { ru: 'Протрите, пожалуйста, пыль на верхних полках, я туда не достаю.', zh: '请帮我擦一下上层架子的灰，我够不着。', en: 'Please wipe the dust off the top shelves; I can\'t reach there.', ctx: '高处除尘' },
  { ru: 'После уборки в квартире так приятно пахнет чистотой!', zh: '打扫完，屋里满是清新的味道，真舒服！', en: 'After the cleaning the flat smells so nicely fresh!', ctx: '保洁效果' },
  { ru: 'Я бы хотел записаться на приём на следующей неделе.', zh: '我想预约下周办理业务。', en: 'I\'d like to make an appointment for next week.', ctx: '预约办事' },
  { ru: '— На какое число вас записать?\n— Лучше на среду, часам к трём.', zh: '——给您约在哪天？\n——最好周三三点左右。', en: '— What date shall I book you for?\n— Wednesday would be best, around three.', ctx: '选择日期' },
  { ru: '— Скажите, по телефону можно отменить запись?\n— Да, только предупредите хотя бы за час.', zh: '——请问打电话可以取消预约吗？\n——可以，只是请至少提前一小时告知。', en: '— Tell me, can I cancel an appointment by phone?\n— Yes, just let us know at least an hour ahead.', ctx: '取消预约' },
  { ru: 'Будьте добры, подскажите график работы в праздничные дни.', zh: '麻烦问一下节假日的办公时间。', en: 'Could you please tell me the working hours during the holidays?', ctx: '节日时间' },
  { ru: '— Алло, это служба поддержки?\n— Да, слушаю вас, что произошло?\n— Ваш сотрудник не приехал в назначенное время.\n— Приношу извинения, сейчас уточню и перезвоню.', zh: '——喂，是客服中心吗？\n——是的，请讲，发生什么事了？\n——你们的工作人员没在约定时间到。\n——非常抱歉，我马上核实后给您回电。', en: '— Hello, is this customer support?\n— Yes, I\'m listening. What happened?\n— Your employee didn\'t arrive at the appointed time.\n— My apologies. I\'ll check now and call you back.', ctx: '投诉爽约' },
  { ru: '— Я звоню пожаловаться на курьера, он нагрубил.\n— Назовите номер заказа, разберёмся и вам перезвоним.', zh: '——我打电话投诉快递员，他说话很粗鲁。\n——请提供订单号，我们核实后给您回电。', en: '— I\'m calling to complain about the courier; he was rude.\n— Give me the order number and we\'ll look into it and call back.', ctx: '投诉快递员' },
  { ru: '— Есть ли смысл писать жалобу в книге отзывов?\n— Конечно, её обязаны рассмотреть в течение месяца.', zh: '——在意见簿上写投诉有用吗？\n——当然，他们必须在一个月内处理。', en: '— Is there any point writing a complaint in the feedback book?\n— Of course. They\'re required to review it within a month.', ctx: '书面投诉' },
  { ru: 'Если вы не решите вопрос до пятницы, я обращусь в суд.', zh: '如果周五前你们还不解决，我就去法院起诉。', en: 'If you don\'t resolve the matter by Friday, I\'ll go to court.', ctx: '警告起诉' },
  { ru: '— Я третий раз звоню по этому вопросу!\n— Понимаю недовольство, напомните, пожалуйста, суть.\n— Мне до сих пор не вернули деньги за заказ.\n— Ставлю пометку «срочно», с вами свяжется старший менеджер.', zh: '——这个问题我是第三次打电话了！\n——我理解您的不满，请再说说情况。\n——订单退款到现在还没到账。\n——我标为「紧急」，高级经理会联系您。', en: '— This is the third time I\'m calling about this issue!\n— I understand your frustration. Please remind me of the details.\n— I still haven\'t been refunded for the order.\n— I\'ll mark it urgent; a senior manager will contact you.', ctx: '重复投诉' },
  { ru: '— Как к вам проехать от вокзала?\n— На любом трамвае до площади, потом пять минут пешком.', zh: '——从火车站怎么到你们那儿？\n——坐任何一路电车到广场，再步行五分钟。', en: '— How do I get to you from the station?\n— Take any tram to the square, then five minutes on foot.', ctx: '问路指引' },
  { ru: '— Подтверждать запись заранее нужно?\n— Да, позвоните накануне, иначе бронь снимем.', zh: '——需要提前确认预约吗？\n——需要，请前一天来个电话，否则取消预留。', en: '— Do I need to confirm the appointment in advance?\n— Yes, call the day before, otherwise we\'ll release the booking.', ctx: '确认预约' },
  { ru: 'Соедините меня, пожалуйста, с отделом возвратов.', zh: '请帮我转接负责退款的部门。', en: 'Please put me through to the refunds department.', ctx: '转接部门' },
  { ru: '— Жалобу можно оставить онлайн?\n— Да, на сайте есть форма, ответят за десять дней.', zh: '——可以在网上提交投诉吗？\n——可以，网站上有表格，十天内答复。', en: '— Can I file a complaint online?\n— Yes, there\'s a form on the website; you\'ll get an answer in ten days.', ctx: '线上投诉' },
  { ru: '— Здравствуйте, у меня вопрос по оказанной услуге.\n— Слушаю, что именно вас интересует?\n— Мне обещали перезвонить и не перезвонили.\n— Сейчас соединю с ответственным специалистом, оставайтесь на линии.', zh: '——您好，我想咨询一项已办理的业务。\n——请讲，您具体想了解什么？\n——本来答应给我回电，却一直没回。\n——我这就给您接负责的专员，请别挂断。', en: '— Hello, I have a question about a service I received.\n— I\'m listening. What exactly would you like to know?\n— They promised to call back but never did.\n— I\'ll connect you with the specialist in charge; please hold.', ctx: '投诉未回复' },
  { ru: '— Могу я узнать фамилию сотрудника, который со мной говорил?\n— Минутку... это был Соколов, он сегодня ещё на работе.', zh: '——我能问一下刚才接待我的工作人员贵姓吗？\n——稍等……是索科洛夫，他今天还在班上。', en: '— May I know the surname of the employee who spoke with me?\n— One moment... it was Sokolov; he\'s still at work today.', ctx: '查询员工' },
]

// ── 高分子专业 / Polymer / Полимеры ──
const POLYMER: Phrase[] = [
  { ru: 'Радикальная полимеризация стирола идёт очень быстро после добавления инициатора.', zh: '加入引发剂后，苯乙烯的自由基聚合进行得很快。', en: 'Radical polymerization of styrene proceeds very quickly after the initiator is added.', ctx: '自由基聚合' },
  { ru: '— Какой инициатор лучше взять для полимеризации метилметакрилата?\n— Попробуй персульфат калия, он хорошо растворим в воде.', zh: '——甲基丙烯酸甲酯聚合用哪种引发剂比较好？——试试过硫酸钾，它在水中溶解性好。', en: '— Which initiator is better for polymerizing methyl methacrylate? — Try potassium persulfate; it dissolves well in water.', ctx: '选择引发剂' },
  { ru: 'Реакцию поликонденсации ведём при температуре 250 °C в атмосфере азота.', zh: '我们在氮气氛围下于250°C进行缩聚反应。', en: 'We carry out the polycondensation at 250 °C under a nitrogen atmosphere.', ctx: '缩聚反应', say: 'Реакцию поликонденсации ведём при температуре двести пятьдесят градусов Цельсия в атмосфере азота.' },
  { ru: '— Почему молекулярная масса получилась такой низкой?\n— Наверное, конверсия мономера была неполной.\n— Тогда увеличим время реакции и повторим эксперимент.', zh: '——为什么分子量这么低？——可能是单体转化率不完全。——那延长反应时间，再做一次。', en: '— Why did the molecular weight come out so low? — Probably the monomer conversion was incomplete. — Then let us extend the reaction time and repeat the experiment.', ctx: '分子量偏低' },
  { ru: 'Знаете ли вы, чем катионная полимеризация отличается от анионной?', zh: '您知道阳离子聚合和阴离子聚合有什么区别吗？', en: 'Do you know how cationic polymerization differs from anionic polymerization?', ctx: '离子聚合' },
  { ru: '— Эмульсионная полимеризация уже закончилась?\n— Ещё нет, латекс всё ещё мутный, подождём ещё час.', zh: '——乳液聚合结束了吗？——还没有，乳胶还是浑浊的，再等一个小时。', en: '— Is the emulsion polymerization finished? — Not yet, the latex is still cloudy; let us wait another hour.', ctx: '乳液聚合' },
  { ru: 'Охладите реактор, скорость полимеризации слишком высокая!', zh: '快给反应釜降温，聚合速率太高了！', en: 'Cool the reactor down, the polymerization rate is too high!', ctx: '反应放热' },
  { ru: 'Если бы мы добавили больше сшивающего агента, гель получился бы прочнее.', zh: '如果我们多加点交联剂，凝胶就会更结实。', en: 'If we had added more crosslinking agent, the gel would have turned out stronger.', ctx: '交联密度' },
  { ru: '— До какой степени конверсии довели реакцию?\n— До 95 %, дальше вязкость выросла слишком сильно.', zh: '——反应做到多少转化率了？——到95%，再往后黏度升得太高了。', en: '— To what conversion did you run the reaction? — To 95%; beyond that the viscosity rose too much.', ctx: '反应转化率', say: '— До какой степени конверсии довели реакцию? — До девяноста пяти процентов, дальше вязкость выросла слишком сильно.' },
  { ru: 'Суспензионная полимеризация даёт частицы размером около миллиметра.', zh: '悬浮聚合得到的颗粒约一毫米大小。', en: 'Suspension polymerization yields particles about one millimetre in size.', ctx: '悬浮聚合' },
  { ru: '— Слушай, сополимеризация стирола с бутадиеном идёт при комнатной температуре?\n— Нет, обычно нужно градусов пятьдесят.\n— Понял. А инициатор какой?\n— Перекись бензоила, как обычно.', zh: '——哎，苯乙烯和丁二烯的共聚在室温下能进行吗？——不行，一般要五十度左右。——明白了。用什么引发剂？——老样子，过氧化苯甲酰。', en: '— Hey, does the copolymerization of styrene with butadiene proceed at room temperature? — No, it usually needs about fifty degrees. — Got it. And which initiator? — Benzoyl peroxide, as usual.', ctx: '共聚条件' },
  { ru: '— Чем полимеризация отличается от поликонденсации?\n— При поликонденсации выделяется низкомолекулярный продукт, например вода.', zh: '——加聚和缩聚有什么区别？——缩聚会析出小分子产物，比如水。', en: '— How does polymerization differ from polycondensation? — Polycondensation releases a low-molecular by-product, such as water.', ctx: '概念辨析' },
  { ru: 'Завтра будем проводить полимеризацию этилена под высоким давлением.', zh: '明天我们将在高压下进行乙烯聚合。', en: 'Tomorrow we will carry out ethylene polymerization under high pressure.', ctx: '高压聚合' },
  { ru: '— Открой, пожалуйста, подачу азота в реактор.\n— Уже открыл, давление поднимается.', zh: '——请打开反应釜的氮气。——已经开了，压力在上升。', en: '— Please open the nitrogen feed to the reactor. — Already open, the pressure is rising.', ctx: '通入氮气保护' },
  { ru: '— Что вы вчера получили методом перекисной вулканизации?\n— Сшитый полиэтилен, гелевых фракций вышло немало.', zh: '——你们昨天用过氧化物硫化法做出了什么？——交联聚乙烯，凝胶含量不少。', en: '— What did you obtain yesterday by peroxide vulcanization? — Crosslinked polyethylene, with quite a lot of gel fraction.', ctx: '过氧化物交联' },
  { ru: '— Почему латекс коагулировал?\n— Наверное, эмульгатора было мало, вот частицы и слиплись.', zh: '——乳胶为什么凝聚了？——可能是乳化剂太少，颗粒就团聚了。', en: '— Why did the latex coagulate? — Probably there was too little emulsifier, so the particles stuck together.', ctx: '乳胶凝聚' },
  { ru: '— Как понять, что реакция закончилась?\n— Отбери пробу и измерь вязкость.\n— А если вязкость всё ещё растёт?\n— Значит, жди дальше.', zh: '——怎么判断反应结束了？——取样测黏度。——如果黏度还在升呢？——那就继续等。', en: '— How can you tell the reaction is finished? — Take a sample and measure the viscosity. — And if the viscosity is still rising? — Then keep waiting.', ctx: '判断终点' },
  { ru: '— Чем хороша живущая полимеризация?\n— Тем, что позволяет точно контролировать молекулярную массу.', zh: '——活性聚合好在哪里？——好在可以精确控制分子量。', en: '— What is good about living polymerization? — It allows precise control of molecular weight.', ctx: '活性聚合' },
  { ru: '— Добавь передатчик цепи, а то молекулярная масса опять уйдёт вверх.\n— Хорошо, трёх капель хватит?\n— Вполне.', zh: '——加点链转移剂，不然分子量又要偏高了。——好，三滴够吗？——够了。', en: '— Add some chain transfer agent, or the molecular weight will run high again. — Okay, will three drops be enough? — Plenty.', ctx: '链转移剂' },
  { ru: '— Ну и экзотерма! Реактор чуть не ушёл вразнос.\n— Да, мономер надо было дозировать медленнее.', zh: '——这放热太猛了！反应釜差点失控。——是啊，单体应该滴加得再慢一点。', en: '— What an exotherm! The reactor nearly ran away. — Yes, we should have fed the monomer more slowly.', ctx: '放热剧烈' },
  { ru: 'Образцы для испытания на растяжение вырезали в форме лопатки.', zh: '拉伸试验的样品裁成了哑铃形。', en: 'The tensile test specimens were cut in a dumbbell shape.', ctx: '拉伸试样' },
  { ru: '— Какая прочность на разрыв получилась?\n— Около сорока мегапаскалей, вполне прилично для полипропилена.', zh: '——拉伸强度测出来多少？——大约四十兆帕，对聚丙烯来说很不错了。', en: '— What tensile strength did you get? — About forty megapascals, quite decent for polypropylene.', ctx: '拉伸强度' },
  { ru: 'Температура стеклования этого сополимера составляет 105 °C по данным ДСК.', zh: '根据DSC数据，这种共聚物的玻璃化温度是105°C。', en: 'According to DSC data, the glass transition temperature of this copolymer is 105 °C.', ctx: '玻璃化温度', say: 'Температура стеклования этого сополимера составляет сто пять градусов Цельсия по данным дифференциальной сканирующей калориметрии.' },
  { ru: '— Сделай, пожалуйста, ТГА этого образца.\n— С какой скоростью нагрева?\n— Десять градусов в минуту, как всегда.', zh: '——请做一下这个样品的热重分析。——升温速率多少？——每分钟十度，老规矩。', en: '— Please run a TGA on this sample. — At what heating rate? — Ten degrees per minute, as usual.', ctx: '热重分析', say: '— Сделай, пожалуйста, термогравиметрический анализ этого образца. — С какой скоростью нагрева? — Десять градусов в минуту, как всегда.' },
  { ru: 'На ИК-спектре виден сильный пик карбонильной группы.', zh: '红外光谱上可以看到羰基的强吸收峰。', en: 'The IR spectrum shows a strong carbonyl group peak.', ctx: '红外光谱', say: 'На инфракрасном спектре виден сильный пик карбонильной группы.' },
  { ru: '— Смотри, пик при 1700 см⁻¹ — это карбонил?\n— Да, классический пик сложного эфира.', zh: '——你看，1700 cm⁻¹处的峰是羰基吗？——对，是酯类的典型峰。', en: '— Look, is the peak at 1700 cm⁻¹ a carbonyl? — Yes, a classic ester peak.', ctx: '羰基特征峰', say: '— Смотри, пик при тысяча семьсот обратных сантиметрах — это карбонил? — Да, классический пик сложного эфира.' },
  { ru: '— Чем измерить твёрдость этого эластомера?\n— Дюрометром, шкала Шор А.', zh: '——这种弹性体的硬度用什么测？——硬度计，邵氏A标尺。', en: '— What should we use to measure the hardness of this elastomer? — A durometer, Shore A scale.', ctx: '邵氏硬度', say: '— Чем измерить твёрдость этого эластомера? — Дюрометром, шкала Шор а.' },
  { ru: '— Почему ударная вязкость такая низкая?\n— Может, надрез на образце кривой?\n— Точно, я его фрезеровал наспех.\n— Переделай образцы и перепроверь.', zh: '——冲击强度为什么这么低？——会不会是试样缺口切歪了？——对，我当时铣得太仓促了。——重做试样再测一遍。', en: '— Why is the impact strength so low? — Maybe the notch on the specimen is crooked? — Exactly, I milled it in a hurry. — Redo the specimens and recheck.', ctx: '冲击强度偏低' },
  { ru: '— Ты уже записал спектр ЯМР для этого образца?\n— Да, сигналы метиленовых протонов получились чистыми.', zh: '——这个样品的核磁谱你录好了吗？——录好了，亚甲基质子的信号很干净。', en: '— Have you recorded the NMR spectrum for this sample yet? — Yes, the methylene proton signals came out clean.', ctx: '核磁谱图', say: '— Ты уже записал спектр ядерного магнитного резонанса для этого образца? — Да, сигналы метиленовых протонов получились чистыми.' },
  { ru: 'Завтра отгоним образцы на гель-проникающую хроматографию.', zh: '明天我们把样品送去做凝胶渗透色谱。', en: 'Tomorrow we will take the samples for gel permeation chromatography.', ctx: 'GPC测试' },
  { ru: '— Какая дисперсность у этого полимера?\n— Два и три десятых, довольно узкое распределение.', zh: '——这种聚合物的分散系数是多少？——2.3，分布相当窄。', en: '— What is the polydispersity of this polymer? — Two point three, a fairly narrow distribution.', ctx: '分子量分布' },
  { ru: 'Снимок с электронного микроскопа показал равномерное распределение наполнителя.', zh: '电镜照片显示填料分布均匀。', en: 'The electron micrograph showed a uniform distribution of the filler.', ctx: '电镜观察' },
  { ru: '— Что показал рентгеноструктурный анализ?\n— Образец полукристаллический, степень кристалличности около сорока процентов.', zh: '——X射线衍射分析结果如何？——样品是半结晶的，结晶度约40%。', en: '— What did the X-ray diffraction analysis show? — The sample is semicrystalline, with crystallinity around forty percent.', ctx: 'XRD分析' },
  { ru: '— Не забудь откалибровать ДСК перед измерением.\n— Уже откалибровал по индию, всё нормально.', zh: '——测量前别忘了校准DSC。——已经用铟校准过了，一切正常。', en: '— Don\'t forget to calibrate the DSC before measuring. — Already calibrated with indium, all fine.', ctx: '仪器校准', say: '— Не забудь откалибровать дифференциальный сканирующий калориметр перед измерением. — Уже откалибровал по индию, всё нормально.' },
  { ru: 'Если бы образец был толще, пик плавления сместился бы вправо.', zh: '如果样品再厚一些，熔融峰会向右偏移。', en: 'If the sample were thicker, the melting peak would shift to the right.', ctx: '样品厚度影响' },
  { ru: '— Разрушение было хрупким или вязким?\n— Хрупким, излом совершенно ровный.', zh: '——断裂是脆性还是韧性的？——脆性的，断口非常平整。', en: '— Was the fracture brittle or ductile? — Brittle; the fracture surface is perfectly flat.', ctx: '断口形貌' },
  { ru: '— Модуль Юнга посчитал?\n— Посчитал: полторы тысячи мегапаскалей.\n— Многовато для эластомера, не находишь?\n— Согласен, что-то с прибором.', zh: '——杨氏模量算了吗？——算了，一千五百兆帕。——对弹性体来说偏高了吧？——同意，可能是仪器有问题。', en: '— Did you calculate Young\'s modulus? — Yes: fifteen hundred megapascals. — Rather high for an elastomer, don\'t you think? — Agreed, something is wrong with the instrument.', ctx: '弹性模量' },
  { ru: '— Сколько образцов уже разрушилось в испытании на ползучесть?\n— Два из пяти, третий вот-вот сломается.', zh: '——蠕变试验已经断几个样品了？——五个里断两个，第三个也快了。', en: '— How many specimens have already failed in the creep test? — Two out of five; the third is about to break.', ctx: '蠕变试验' },
  { ru: '— Сколько параллельных образцов нужно?\n— Минимум пять, иначе статистика не посчитается.', zh: '——需要多少个平行样？——至少五个，不然统计结果算不出来。', en: '— How many parallel specimens are needed? — At least five, otherwise the statistics won\'t work out.', ctx: '平行样数量' },
  { ru: 'Какой красивый экзотермический пик кристаллизации на этой кривой!', zh: '这条曲线上的结晶放热峰真漂亮！', en: 'What a beautiful exothermic crystallization peak on this curve!', ctx: '结晶放热峰' },
  { ru: '— Реактор уже прогрелся до рабочей температуры?\n— Да, термопара показывает восемьдесят градусов.', zh: '——反应釜已经热到工作温度了吗？——到了，热电偶显示八十度。', en: '— Has the reactor warmed up to the working temperature yet? — Yes, the thermocouple shows eighty degrees.', ctx: '反应釜预热' },
  { ru: 'Термопластавтомат работает в автоматическом режиме.', zh: '注塑机正在自动模式下运行。', en: 'The injection molding machine is running in automatic mode.', ctx: '注塑机运行' },
  { ru: '— Какое давление впрыска поставил?\n— 120 МПа, для этого материала самое то.', zh: '——注射压力设的多少？——120兆帕，对这种材料正合适。', en: '— What injection pressure did you set? — 120 MPa, just right for this material.', ctx: '注塑压力', say: '— Какое давление впрыска поставил? — Сто двадцать мегапаскалей, для этого материала самое то.' },
  { ru: 'Двухшнековый экструдер хорошо перемешивает наполнитель.', zh: '双螺杆挤出机能把填料混合得很好。', en: 'The twin-screw extruder mixes the filler very well.', ctx: '双螺杆挤出机' },
  { ru: '— Почему жгут идёт волнистый?\n— Температура в третьей зоне низковата.\n— Подними на десять градусов.\n— Сейчас, и заодно проверю скорость шнека.', zh: '——料条怎么是波浪形的？——三区温度有点低。——调高十度。——这就调，顺便查一下螺杆转速。', en: '— Why is the strand coming out wavy? — The temperature in the third zone is a bit low. — Raise it by ten degrees. — Right away, and I\'ll check the screw speed too.', ctx: '挤出波动' },
  { ru: '— На каком реометре ты мерил вязкость расплава?\n— На капиллярном, при трёх скоростях сдвига.', zh: '——你用哪种流变仪测的熔体黏度？——毛细管流变仪，测了三个剪切速率。', en: '— Which rheometer did you use to measure the melt viscosity? — A capillary one, at three shear rates.', ctx: '测熔体黏度' },
  { ru: 'Универсальная испытательная машина стоит во второй лаборатории.', zh: '万能试验机在第二实验室。', en: 'The universal testing machine is in the second laboratory.', ctx: '万能试验机' },
  { ru: '— Откалибруй датчик усилия перед испытаниями.\n— Уже, эталонная нагрузка совпадает.', zh: '——试验前把力传感器校准一下。——已经校准了，标准砝码读数一致。', en: '— Calibrate the load cell before the tests. — Already done, the reference load matches.', ctx: '力值校准' },
  { ru: '— Гранулы ещё влажные?\n— Нет, вакуумный шкаф сушил их всю ночь.', zh: '——颗粒还潮吗？——不潮了，真空干燥箱烘了一整夜。', en: '— Are the pellets still moist? — No, the vacuum oven dried them all night.', ctx: '真空干燥' },
  { ru: '— Не работает мешалка в реакторе.\n— Проверь муфту, она вчера уже буксовала.', zh: '——反应釜的搅拌器不转了。——检查一下联轴器，昨天就打滑过。', en: '— The stirrer in the reactor isn\'t working. — Check the coupling; it was already slipping yesterday.', ctx: '搅拌故障' },
  { ru: '— Какую скорость шнека выставил?\n— 200 оборотов в минуту, больше не стоит.', zh: '——螺杆转速设的多少？——每分钟200转，别再高了。', en: '— What screw speed did you set? — 200 revolutions per minute; don\'t go higher.', ctx: '螺杆转速', say: '— Какую скорость шнека выставил? — Двести оборотов в минуту, больше не стоит.' },
  { ru: 'Гидравлический пресс формует образцы для рентгеновских измерений.', zh: '液压机正在压制X射线测试用的试样。', en: 'The hydraulic press is molding specimens for X-ray measurements.', ctx: '液压机成型' },
  { ru: '— Форма опять не заполняется полностью.\n— Повысь температуру расплава.\n— Уже повышал, не помогает.\n— Тогда проверь сопло, может, засорилось.', zh: '——模具又充不满了。——提高熔体温度。——提过了，没用。——那检查一下喷嘴，可能堵了。', en: '— The mold isn\'t filling completely again. — Raise the melt temperature. — I already did, it doesn\'t help. — Then check the nozzle; it might be clogged.', ctx: '缺料问题' },
  { ru: '— Где лежит запасной фильтр для экструдера?\n— В шкафу у гранулятора, возьми сразу два.', zh: '——挤出机的备用滤网放在哪儿？——切粒机旁边的柜子里，直接拿两个吧。', en: '— Where is the spare filter for the extruder? — In the cabinet by the pelletizer; take two at once.', ctx: '备用滤网' },
  { ru: 'Пластограф записывает крутящий момент расплава в реальном времени.', zh: '转矩流变仪实时记录熔体的扭矩。', en: 'The torque rheometer records the melt torque in real time.', ctx: '转矩流变仪' },
  { ru: '— Когда чистили фильеру в последний раз?\n— Позавчера, после партии с мелом.', zh: '——模头上次是什么时候清理的？——前天，做完碳酸钙那批料之后。', en: '— When was the die last cleaned? — The day before yesterday, after the batch with chalk.', ctx: '模头清理' },
  { ru: 'Если бы насос охлаждения работал исправно, цикл был бы заметно короче.', zh: '要是冷却泵正常运转，周期就能明显缩短。', en: 'If the cooling pump worked properly, the cycle would be noticeably shorter.', ctx: '冷却泵故障' },
  { ru: '— Запусти сушилку за час до переработки, ладно?\n— Конечно, поставлю таймер.', zh: '——提前一小时把干燥机开起来，好吗？——没问题，我定个时。', en: '— Start the dryer an hour before processing, okay? — Sure, I\'ll set a timer.', ctx: '提前开干燥' },
  { ru: 'Гранулятор режет жгуты на ровные цилиндрики.', zh: '切粒机把料条切成整齐的圆柱颗粒。', en: 'The pelletizer cuts the strands into uniform cylinders.', ctx: '切粒机工作' },
  { ru: '— Термопара в четвёртой зоне врёт.\n— Откуда знаешь?\n— Пирометр показывает на двадцать градусов меньше.\n— Заменим термопару после смены.', zh: '——四区的热电偶不准了。——你怎么知道？——红外测温仪显示低二十度。——下班后就换掉它。', en: '— The thermocouple in the fourth zone is lying. — How do you know? — The pyrometer reads twenty degrees lower. — We\'ll replace the thermocouple after the shift.', ctx: '热电偶失准' },
  { ru: '— Из чего делают трубы для холодной воды?\n— Чаще всего из полиэтилена низкого давления.', zh: '——冷水管一般用什么材料做？——最常用低压聚乙烯。', en: '— What are cold water pipes made of? — Most often low-pressure polyethylene.', ctx: '聚乙烯管材' },
  { ru: 'Полипропилен плавится примерно при 165 °C.', zh: '聚丙烯大约在165°C熔化。', en: 'Polypropylene melts at approximately 165 °C.', ctx: '聚丙烯熔点', say: 'Полипропилен плавится примерно при ста шестидесяти пяти градусах Цельсия.' },
  { ru: '— Почему от ПВХ при переработке такой запах?\n— Он выделяет хлористый водород, поэтому нужна вытяжка.', zh: '——PVC加工时为什么有这种气味？——它会释放氯化氢，所以必须开通风。', en: '— Why does PVC smell like that during processing? — It releases hydrogen chloride, so ventilation is needed.', ctx: 'PVC分解', say: '— Почему от поливинилхлорида при переработке такой запах? — Он выделяет хлористый водород, поэтому нужна вытяжка.' },
  { ru: '— Почему из полистирола не делают нагруженные детали?\n— Он очень хрупкий, зато прозрачный как стекло.', zh: '——为什么不用聚苯乙烯做受力件？——它太脆了，不过倒像玻璃一样透明。', en: '— Why aren\'t load-bearing parts made of polystyrene? — It is very brittle, though as transparent as glass.', ctx: '聚苯乙烯' },
  { ru: '— Для корпуса прибора какой пластик возьмём?\n— АБС: ударопрочный и легко окрашивается.\n— А по цене?\n— Приемлемо.', zh: '——仪器外壳用什么塑料？——ABS：抗冲击而且容易上色。——价格呢？——可以接受。', en: '— Which plastic shall we use for the instrument housing? — ABS: impact-resistant and easy to paint. — And the price? — Acceptable.', ctx: '选外壳料', say: '— Для корпуса прибора какой пластик возьмём? — Акрилонитрилбутадиенстирол: ударопрочный и легко окрашивается. — А по цене? — Приемлемо.' },
  { ru: '— Полиамид впитывает влагу, это критично?\n— Да, перед литьём его обязательно сушат.', zh: '——尼龙会吸湿，这要紧吗？——要紧，注塑前必须烘干。', en: '— Polyamide absorbs moisture; is that critical? — Yes, it must be dried before molding.', ctx: '尼龙吸湿' },
  { ru: 'Поликарбонат выдерживает удары, которые ломают обычное стекло.', zh: '聚碳酸酯能承受足以打碎普通玻璃的冲击。', en: 'Polycarbonate withstands impacts that would break ordinary glass.', ctx: '聚碳酸酯' },
  { ru: '— Какая плотность у этого полиэтилена?\n— 0,95 г/см³, это полиэтилен высокой плотности.', zh: '——这种聚乙烯的密度是多少？——0.95克每立方厘米，是高密度聚乙烯。', en: '— What is the density of this polyethylene? — 0.95 g/cm³; it is high-density polyethylene.', ctx: '聚乙烯密度', say: '— Какая плотность у этого полиэтилена? — Ноль целых девяносто пять сотых грамма на кубический сантиметр, это полиэтилен высокой плотности.' },
  { ru: 'Полиуретан бывает как жёстким пенопластом, так и эластичным каучуком.', zh: '聚氨酯既可以是硬质泡沫，也可以是弹性橡胶。', en: 'Polyurethane can be either a rigid foam or an elastic rubber.', ctx: '聚氨酯形态' },
  { ru: '— Бутылки делают из ПЭТ, верно?\n— Да, и его легко перерабатывать вторично.', zh: '——瓶子是用PET做的，对吧？——对，而且PET很容易回收再利用。', en: '— Bottles are made of PET, right? — Yes, and it is easy to recycle.', ctx: 'PET瓶', say: '— Бутылки делают из полиэтилентерефталата, верно? — Да, и его легко перерабатывать вторично.' },
  { ru: '— Этот каучук на какой основе?\n— Бутадиен-стирольный, по-моему.\n— Проверь по паспорту, от этого режим вулканизации зависит.', zh: '——这种生胶是什么体系的？——我记得是丁苯橡胶。——查一下合格证，硫化工艺取决于这个。', en: '— What is this rubber based on? — Butadiene-styrene, I believe. — Check the certificate; the vulcanization regime depends on it.', ctx: '橡胶牌号' },
  { ru: 'Эпоксидная смола после отверждения становится очень твёрдой.', zh: '环氧树脂固化后会变得非常坚硬。', en: 'Epoxy resin becomes very hard after curing.', ctx: '环氧树脂' },
  { ru: '— Сколько отвердителя добавлять в эпоксидку?\n— По инструкции, десять частей на сто частей смолы.', zh: '——环氧树脂里加多少固化剂？——按说明书，一百份树脂加十份。', en: '— How much hardener should be added to the epoxy? — Per the instructions, ten parts per hundred parts of resin.', ctx: '固化剂配比' },
  { ru: 'Углеродное волокно в пять раз легче стали при сопоставимой прочности.', zh: '碳纤维在强度相当的情况下比钢轻五倍。', en: 'Carbon fiber is five times lighter than steel at comparable strength.', ctx: '碳纤维性能' },
  { ru: '— Если бы нужен был прозрачный и термостойкий материал, что бы ты выбрал?\n— Пожалуй, поликарбонат.', zh: '——如果需要一种既透明又耐热的材料，你会选什么？——大概是聚碳酸酯。', en: '— If you needed a transparent and heat-resistant material, what would you choose? — Probably polycarbonate.', ctx: '选材假设' },
  { ru: 'Фторопласт ни к чему не прилипает и выдерживает высокие температуры.', zh: '氟塑料什么都不粘，而且耐高温。', en: 'Fluoroplastic sticks to nothing and withstands high temperatures.', ctx: '氟塑料特性' },
  { ru: '— Это вторичный полипропилен или первичный?\n— Вторичный, видишь, оттенок сероватый.', zh: '——这是再生聚丙烯还是新料？——再生的，你看，颜色偏灰。', en: '— Is this recycled or virgin polypropylene? — Recycled; see, the tint is grayish.', ctx: '回料识别' },
  { ru: '— Чем армировать эту деталь?\n— Стекловолокном, процентов тридцать.\n— А углеродным не лучше?\n— Лучше, но в разы дороже.', zh: '——这个零件用什么增强？——玻璃纤维，百分之三十左右。——碳纤维不更好吗？——更好，但贵好几倍。', en: '— What should we reinforce this part with? — Glass fiber, about thirty percent. — Wouldn\'t carbon fiber be better? — Better, but several times more expensive.', ctx: '增强纤维' },
  { ru: 'Какая чистая гранула у этого первичного полиэтилена!', zh: '这种新料聚乙烯的颗粒真干净！', en: 'What clean pellets this virgin polyethylene has!', ctx: '原料外观' },
  { ru: '— Силиконовая резина переносит мороз?\n— Да, она остаётся эластичной и при минус пятидесяти.', zh: '——硅橡胶耐冻吗？——耐，零下五十度仍有弹性。', en: '— Does silicone rubber tolerate frost? — Yes, it stays elastic even at minus fifty.', ctx: '硅橡胶耐低温' },
  { ru: '— На семинаре ты выступаешь первым, готов?\n— Почти, осталось проверить слайды.', zh: '——组会上你第一个发言，准备好了吗？——差不多了，就差再过一遍幻灯片。', en: '— You\'re presenting first at the seminar; are you ready? — Almost, I just need to check the slides.', ctx: '组会汇报' },
  { ru: 'Руководитель посоветовал добавить сравнение с литературными данными.', zh: '导师建议加入与文献数据的对比。', en: 'My supervisor suggested adding a comparison with literature data.', ctx: '导师建议' },
  { ru: '— Ты читал вчерашнюю статью в журнале «Полимер»?\n— Ту, про регулируемую радикальную полимеризацию?\n— Да, там отличная методика, возьмём на заметку.', zh: '——你看昨天《聚合物》杂志上的文章了吗？——讲可控自由基聚合那篇？——对，里面的方法很好，我们借鉴一下。', en: '— Have you read yesterday\'s article in the Polymer journal? — The one about controlled radical polymerization? — Yes, the methodology there is excellent; let\'s take note of it.', ctx: '阅读文献' },
  { ru: 'Правильно ли я понимаю, что вы предлагаете изменить схему синтеза?', zh: '我理解得对吗，您是建议改变合成路线？', en: 'Do I understand correctly that you are proposing to change the synthesis scheme?', ctx: '确认理解' },
  { ru: '— Когда у тебя предзащита?\n— В следующий четверг, уже волнуюсь.', zh: '——你什么时候预答辩？——下周四，已经开始紧张了。', en: '— When is your pre-defense? — Next Thursday; I\'m already nervous.', ctx: '预答辩时间' },
  { ru: '— Мне непонятен этот вывод авторов.\n— Смотри, они опираются на данные вискозиметрии, вот вся логика.', zh: '——我看不懂作者的这个结论。——你看，他们是基于黏度测量的数据，逻辑就在这里。', en: '— I don\'t understand this conclusion of the authors. — Look, they rely on viscometry data; that\'s the whole logic.', ctx: '讨论论文' },
  { ru: 'Если бы у меня было больше времени, я бы повторил этот эксперимент трижды.', zh: '要是有更多时间，我就把这个实验重复三遍。', en: 'If I had more time, I would repeat this experiment three times.', ctx: '时间不够' },
  { ru: '— Профессор, можно задать вопрос?\n— Конечно, слушаю.\n— Почему вы выбрали именно этот растворитель?\n— Хороший вопрос: он полярный и легко отгоняется.', zh: '——教授，可以问个问题吗？——当然，请讲。——您为什么偏偏选了这个溶剂？——问得好：它是极性的，而且容易蒸掉。', en: '— Professor, may I ask a question? — Of course, go ahead. — Why did you choose this particular solvent? — Good question: it is polar and evaporates easily.', ctx: '请教导师' },
  { ru: '— Над чем ты сейчас работаешь?\n— Над модификацией полипропилена малеиновым ангидридом.', zh: '——你现在在研究什么？——马来酸酐改性聚丙烯。', en: '— What are you working on now? — Modification of polypropylene with maleic anhydride.', ctx: '研究方向' },
  { ru: '— Как продвигается твоя диссертация?\n— Медленно, но экспериментальная часть почти закрыта.', zh: '——你的学位论文进展如何？——比较慢，不过实验部分基本完成了。', en: '— How is your dissertation coming along? — Slowly, but the experimental part is almost done.', ctx: '论文进展' },
  { ru: '— Не согласен с твоей интерпретацией спектра.\n— Аргументируй.\n— Смотри: этот пик не может быть карбонилом, положение не то.', zh: '——我不同意你对谱图的解读。——说出理由。——你看：这个峰不可能是羰基，位置不对。', en: '— I disagree with your interpretation of the spectrum. — Give your arguments. — Look: this peak cannot be a carbonyl; the position is wrong.', ctx: '学术争论' },
  { ru: 'На конференции я представлю постер о наших последних результатах.', zh: '我将在会议上用海报展示我们的最新成果。', en: 'At the conference I will present a poster about our latest results.', ctx: '学术会议' },
  { ru: '— Твой доклад займёт сколько минут?\n— Двенадцать плюс три на вопросы.', zh: '——你的报告多长时间？——十二分钟，外加三分钟提问。', en: '— How many minutes will your talk take? — Twelve, plus three for questions.', ctx: '报告时长' },
  { ru: '— Кстати, ты в курсе, что завтрашний семинар перенесли?\n— Нет, спасибо, что предупредил!', zh: '——对了，你知道明天的研讨会改期了吗？——不知道，谢谢你提醒！', en: '— By the way, did you know tomorrow\'s seminar was rescheduled? — No, thanks for warning me!', ctx: '会议改期' },
  { ru: 'После магистратуры я планирую поступить в аспирантуру.', zh: '硕士毕业后我打算读博。', en: 'After my master\'s degree I plan to enter a PhD program.', ctx: '继续深造' },
  { ru: '— Посмотри мою презентацию, если будет минутка.\n— Давай после обеда, сейчас совещание.', zh: '——有空帮我看看演示文稿吧。——午饭后看，现在有个会。', en: '— Look through my presentation if you have a minute. — After lunch; there\'s a meeting now.', ctx: '请人把关' },
  { ru: 'Какой каверзный вопрос задал оппонент, я даже растерялся!', zh: '答辩委员提了个刁钻的问题，我都慌了！', en: 'The opponent asked such a tricky question that I was completely taken aback!', ctx: '答辩提问' },
  { ru: '— Эти данные противоречат прошлой серии.\n— Точно, я и забыл.\n— Разберись до завтра, ладно?', zh: '——这些数据和上一批矛盾。——确实，我都忘了。——明天之前弄清楚，好吗？', en: '— These data contradict the previous series. — Right, I forgot about that. — Sort it out by tomorrow, okay?', ctx: '数据矛盾' },
  { ru: '— С кем из лаборатории ты советуешься по хроматографии?\n— С Ирой, она в этом лучший специалист.', zh: '——色谱方面的问题你向实验室谁请教？——伊拉，她是这方面最厉害的专家。', en: '— Whom in the lab do you consult about chromatography? — Ira; she is the best specialist in that.', ctx: '请教对象' },
  { ru: 'Научный руководитель хвалит меня за аккуратность, но ругает за медлительность.', zh: '导师夸我做事仔细，但批评我动作太慢。', en: 'My supervisor praises me for being thorough but scolds me for being slow.', ctx: '导师评价' },
  { ru: '— Какую температуру держим в первой зоне?\n— 160 °C, как в регламенте.', zh: '——一区温度保持多少？——160°C，按工艺规程来。', en: '— What temperature do we keep in the first zone? — 160 °C, as per the regulations.', ctx: '各区温度', say: '— Какую температуру держим в первой зоне? — Сто шестьдесят градусов Цельсия, как в регламенте.' },
  { ru: 'Катализатор вводят в самом конце, перед розливом.', zh: '催化剂在最后、浇注之前加入。', en: 'The catalyst is introduced at the very end, before casting.', ctx: '催化剂加入' },
  { ru: '— Соотношение мономеров один к одному?\n— Нет, избыток диола процентов пять.', zh: '——单体比例是一比一吗？——不是，二醇过量百分之五左右。', en: '— Is the monomer ratio one to one? — No, there is about five percent excess of the diol.', ctx: '单体配比' },
  { ru: 'Давление в автоклаве поднялось до 30 атмосфер.', zh: '高压釜内的压力升到了30个大气压。', en: 'The pressure in the autoclave rose to 30 atmospheres.', ctx: '釜内压力', say: 'Давление в автоклаве поднялось до тридцати атмосфер.' },
  { ru: '— Конверсия опять низкая.\n— Увеличь дозу инициатора.\n— Так молекулярная масса упадёт!\n— Немного, зато конверсия вырастет.', zh: '——转化率又偏低。——加大引发剂用量。——那样分子量会降的！——会降一点，但转化率能上去。', en: '— The conversion is low again. — Increase the initiator dose. — But the molecular weight will drop! — Slightly, but the conversion will rise.', ctx: '提高转化率' },
  { ru: '— Какое время выдержки при этой температуре?\n— Два часа, потом медленное охлаждение.', zh: '——这个温度下保温多久？——两个小时，然后缓慢冷却。', en: '— What is the holding time at this temperature? — Two hours, then slow cooling.', ctx: '保温时间' },
  { ru: 'Молекулярно-массовое распределение стало шире после второго прогона.', zh: '第二次加工后分子量分布变宽了。', en: 'The molecular weight distribution became broader after the second pass.', ctx: '分子量分布' },
  { ru: '— Зачем добавлять пластификатор?\n— Чтобы снизить температуру стеклования и повысить гибкость.', zh: '——为什么要加增塑剂？——为了降低玻璃化温度、提高柔韧性。', en: '— Why add a plasticizer? — To lower the glass transition temperature and increase flexibility.', ctx: '增塑剂作用' },
  { ru: 'Если бы скорость перемешивания была выше, эмульсия получилась бы стабильнее.', zh: '如果搅拌速度再高一些，乳液会更稳定。', en: 'If the stirring speed were higher, the emulsion would turn out more stable.', ctx: '搅拌速度' },
  { ru: '— Подними температуру на пять градусов, посмотрим, что изменится.\n— Хорошо, зафиксирую в журнале.', zh: '——把温度提高五度，看看有什么变化。——好，我在记录本上记下来。', en: '— Raise the temperature by five degrees; let\'s see what changes. — Okay, I\'ll record it in the logbook.', ctx: '微调温度' },
  { ru: '— Почему показатель текучести расплава вырос?\n— Возможно, материал частично деструктировал.\n— Из-за перегрева?\n— Скорее всего, вторая зона была горячее нормы.', zh: '——熔体流动速率为什么升高了？——可能材料发生了部分降解。——因为过热？——很可能，二区温度超标了。', en: '— Why did the melt flow index increase? — Possibly the material partially degraded. — Because of overheating? — Most likely; the second zone was hotter than normal.', ctx: '熔指升高' },
  { ru: 'Наполнитель вводят порциями, чтобы не было комков.', zh: '填料要分批加入，以免结块。', en: 'The filler is added in portions to avoid lumps.', ctx: '填料加入' },
  { ru: '— Какова концентрация катализатора?\n— 0,1 % от массы мономера, не больше.', zh: '——催化剂浓度是多少？——单体质量的0.1%，不能再多。', en: '— What is the catalyst concentration? — 0.1% of the monomer mass, no more.', ctx: '催化剂浓度', say: '— Какова концентрация катализатора? — Одна десятая процента от массы мономера, не больше.' },
  { ru: '— Отслеживай кислотное число каждые полчаса.\n— Понял, буду отбирать пробы.', zh: '——每半小时跟踪一次酸值。——明白，我会按时取样。', en: '— Track the acid number every half hour. — Understood, I\'ll take samples.', ctx: '跟踪酸值' },
  { ru: '— От чего зависит размер частиц суспензии?\n— В том числе от степени разбавления системы.', zh: '——悬浮颗粒的粒径受什么影响？——体系稀释度就是其中之一。', en: '— What affects the particle size of the suspension? — Among other things, the dilution of the system.', ctx: '体系稀释度' },
  { ru: '— Какой режим сушки для этих гранул?\n— Четыре часа при восьмидесяти градусах.\n— А остаточная влажность какая?\n— Не выше двух сотых процента.', zh: '——这些颗粒的干燥工艺是什么？——八十度烘四小时。——残余水分要求多少？——不超过万分之二。', en: '— What is the drying regime for these pellets? — Four hours at eighty degrees. — And the residual moisture? — No higher than two hundredths of a percent.', ctx: '干燥工艺' },
  { ru: 'Как резко выросла вязкость, похоже, началась сшивка!', zh: '黏度怎么突然飙升了，看来是开始交联了！', en: 'How sharply the viscosity rose — looks like crosslinking has begun!', ctx: '黏度突增' },
  { ru: '— Снизь скорость подачи мономера вдвое.\n— Сделано, температура сразу стабилизировалась.', zh: '——把单体进料速度减半。——已调，温度立刻稳定了。', en: '— Halve the monomer feed rate. — Done; the temperature stabilized immediately.', ctx: '控制进料' },
  { ru: 'Рецептура предусматривает стабилизатор и антиоксидант.', zh: '配方中包含稳定剂和抗氧剂。', en: 'The formulation includes a stabilizer and an antioxidant.', ctx: '配方组成' },
  { ru: '— Почему у этой партии цвет желтее?\n— Возможно, переработка шла при повышенной температуре.', zh: '——这批料颜色为什么偏黄？——可能是加工时温度偏高了。', en: '— Why is the color of this batch more yellow? — Possibly the processing ran at an elevated temperature.', ctx: '颜色发黄' },
  { ru: 'Работайте со стиролом только под вытяжным шкафом!', zh: '苯乙烯操作必须在通风橱内进行！', en: 'Work with styrene only under the fume hood!', ctx: '通风橱操作' },
  { ru: '— Где твои защитные очки?\n— В шкафчике, сейчас надену, извини.', zh: '——你的护目镜呢？——在柜子里，我马上戴上，抱歉。', en: '— Where are your safety goggles? — In the locker; I\'ll put them on right now, sorry.', ctx: '佩戴护目镜' },
  { ru: '— Вентиляцию перед работой проверил?\n— Да, тяга отличная, можно начинать.', zh: '——开工前检查通风了吗？——查了，抽力很好，可以开始。', en: '— Did you check the ventilation before starting? — Yes, the draft is excellent; we can begin.', ctx: '检查通风' },
  { ru: '— Какая концентрация паров растворителя допустима?\n— Не выше 50 мг/м³, по санитарным нормам.', zh: '——溶剂蒸气的允许浓度是多少？——按卫生标准，不超过50毫克每立方米。', en: '— What concentration of solvent vapor is permissible? — No higher than 50 mg/m³, according to sanitary norms.', ctx: '溶剂浓度限值', say: '— Какая концентрация паров растворителя допустима? — Не выше пятидесяти миллиграммов на кубический метр, по санитарным нормам.' },
  { ru: '— Куда сливать отработанный ацетон?\n— В канистру для органических отходов.\n— А в раковину нельзя?\n— Ни в коем случае!', zh: '——废丙酮倒在哪里？——倒有机废液桶。——不能倒水槽吗？——绝对不行！', en: '— Where should I pour the used acetone? — Into the canister for organic waste. — Can it go down the sink? — Absolutely not!', ctx: '废液处理' },
  { ru: 'Нитриловые перчатки защищают лучше латексных при работе с растворителями.', zh: '接触溶剂时，丁腈手套比乳胶手套防护更好。', en: 'Nitrile gloves protect better than latex ones when working with solvents.', ctx: '手套选择' },
  { ru: '— Что делать, если кислота попала на кожу?\n— Немедленно промыть большим количеством воды и сообщить руководителю.', zh: '——酸溅到皮肤上怎么办？——立即用大量清水冲洗，并报告负责人。', en: '— What should you do if acid gets on your skin? — Rinse immediately with plenty of water and inform the supervisor.', ctx: '酸液灼伤' },
  { ru: 'Если бы он работал без халата, ожог был бы серьёзнее.', zh: '要是他没穿实验服，烫伤会更严重。', en: 'If he had worked without a lab coat, the burn would have been more serious.', ctx: '实验服防护' },
  { ru: '— Включи вытяжку, здесь пахнет амином.\n— Уже включил, и окно открыл.', zh: '——打开排风，这里有胺的味道。——已经开了，窗户也打开了。', en: '— Turn on the exhaust; it smells of amine here. — Already on, and I opened the window too.', ctx: '胺味泄漏' },
  { ru: '— Эти реактивы почему на солнце стоят?\n— Переставлю сейчас.\n— Перекиси вообще в холодильник убери, они светочувствительны.', zh: '——这些试剂怎么放在太阳底下？——我马上挪走。——过氧化物直接放冰箱，它们怕光。', en: '— Why are these reagents sitting in the sun? — I\'ll move them right away. — Put the peroxides in the fridge altogether; they are light-sensitive.', ctx: '试剂存放' },
  { ru: 'Аптечка и средства пожаротушения находятся у выхода.', zh: '急救箱和灭火器材在出口旁边。', en: 'The first-aid kit and fire extinguishers are by the exit.', ctx: '应急物品' },
  { ru: '— Ты прошёл инструктаж по технике безопасности?\n— Да, вчера расписался в журнале.', zh: '——你参加安全培训了吗？——参加了，昨天在记录本上签了字。', en: '— Have you completed the safety briefing? — Yes, I signed the logbook yesterday.', ctx: '安全培训' },
  { ru: 'Какая густая пена, похоже, что-то вскипело в колбе!', zh: '好浓的泡沫，看来烧瓶里有东西暴沸了！', en: 'What thick foam — looks like something boiled over in the flask!', ctx: '意外沸腾' },
  { ru: '— Работаешь с гидридом натрия? Надень фартук и маску.\n— Конечно, и перчатки двойные надену.', zh: '——要用氢化钠吗？穿上围裙、戴好口罩。——当然，手套我也戴双层的。', en: '— Working with sodium hydride? Put on an apron and a mask. — Of course, and I\'ll wear double gloves too.', ctx: '危险品操作' },
  { ru: '— Где хранятся органические растворители?\n— В металлическом шкафу под замком, вот ключ.', zh: '——有机溶剂存放在哪里？——带锁的金属柜里，钥匙在这儿。', en: '— Where are organic solvents stored? — In a locked metal cabinet; here is the key.', ctx: '溶剂储存' },
  { ru: '— Почему сработала пожарная сигнализация?\n— Кто-то грел эфир на открытой горелке.\n— Это же недопустимо!\n— Согласен, уже разбираемся.', zh: '——火警为什么响了？——有人在明火上加热乙醚。——这绝对不允许！——同意，我们正在处理。', en: '— Why did the fire alarm go off? — Someone was heating ether over an open burner. — That\'s unacceptable! — Agreed, we\'re already dealing with it.', ctx: '火警误报' },
  { ru: '— Утилизируем эти просроченные реактивы как обычные отходы?\n— Нет, только через специализированную службу.', zh: '——这些过期试剂按普通垃圾处理吗？——不行，必须交给专门的处理机构。', en: '— Shall we dispose of these expired reagents as ordinary waste? — No, only through a specialized service.', ctx: '过期试剂' },
  { ru: 'При розливе ртути нужно немедленно эвакуироваться и вызвать дежурного.', zh: '发生汞泄漏要立即撤离并通知值班人员。', en: 'In case of a mercury spill, evacuate immediately and call the duty officer.', ctx: '汞泄漏应急' },
  { ru: '— Взял ли ты респиратор для работы с порошком?\n— Взял, ещё и очки закрытого типа.', zh: '——操作粉末时带呼吸器了吗？——带了，还配了密闭式护目镜。', en: '— Did you take a respirator for working with the powder? — Yes, and closed-type goggles as well.', ctx: '防尘呼吸器' },
  { ru: 'Завтра утром проведут проверку состояния охраны труда в лаборатории.', zh: '明天上午要检查实验室的安全生产状况。', en: 'Tomorrow morning there will be an occupational safety inspection in the laboratory.', ctx: '安全检查' },
  { ru: '— Линия номер три уже вышла на режим?\n— Да, качество гранул стабильное.', zh: '——三号生产线已经进入正常状态了吗？——是的，颗粒质量很稳定。', en: '— Has line number three reached its operating regime yet? — Yes, the pellet quality is stable.', ctx: '生产线状态' },
  { ru: 'Сегодняшняя смена выпускает полипропилен марки 030.', zh: '今天这个班生产030牌号的聚丙烯。', en: 'Today\'s shift is producing polypropylene grade 030.', ctx: '今日产品牌号', say: 'Сегодняшняя смена выпускает полипропилен марки ноль тридцать.' },
  { ru: '— Почему остановили линию?\n— Датчик давления на фильере зашкаливал.\n— Поменяли?\n— Да, сейчас запускаем обратно.', zh: '——为什么停线了？——模头压力传感器超量程了。——换了吗？——换了，现在重新启动。', en: '— Why was the line stopped? — The pressure sensor at the die went off scale. — Was it replaced? — Yes, we\'re restarting now.', ctx: '停机排查' },
  { ru: '— Рецептуру на эту партию кто утвердил?\n— Главный технолог, подпись в журнале.', zh: '——这批料的配方是谁批准的？——总工艺师，记录本上有签字。', en: '— Who approved the formulation for this batch? — The chief technologist; the signature is in the logbook.', ctx: '配方审批' },
  { ru: 'Каждую партию сопровождает паспорт качества.', zh: '每批产品都附有质量合格证。', en: 'Every batch is accompanied by a quality certificate.', ctx: '批次合格证' },
  { ru: '— Сколько тонн мы должны выдать за смену?\n— 12 тонн, план напряжённый.', zh: '——我们这个班要产出多少吨？——12吨，任务很紧。', en: '— How many tons are we supposed to produce per shift? — 12 tons; the plan is tight.', ctx: '当班产量', say: '— Сколько тонн мы должны выдать за смену? — Двенадцать тонн, план напряжённый.' },
  { ru: '— ОТК забраковало вторую партию. В чём причина?\n— Посторонние включения в гранулах, проверяем фильтры.', zh: '——质检科把第二批判为不合格，什么原因？——颗粒里有杂质，我们正在查滤网。', en: '— Quality control rejected the second batch. What\'s the reason? — Foreign inclusions in the pellets; we\'re checking the filters.', ctx: '质检退货', say: '— Отдел технического контроля забраковал вторую партию. В чём причина? — Посторонние включения в гранулах, проверяем фильтры.' },
  { ru: 'Сырьё на участок подаётся пневмотранспортом из силосов.', zh: '原料通过气力输送从料仓送到工段。', en: 'Raw material is fed to the section by pneumatic transport from the silos.', ctx: '原料输送' },
  { ru: '— Гранулятор опять дребезжит.\n— Ножи затупились, наверное.\n— Вызову слесаря.\n— И заодно пусть посмотрит подшипники.', zh: '——切粒机又哐当响了。——大概是刀片钝了。——我去叫钳工。——顺便让他看看轴承。', en: '— The pelletizer is rattling again. — The knives have probably gone dull. — I\'ll call the fitter. — And let him check the bearings while he\'s at it.', ctx: '切粒机异响' },
  { ru: '— Переходи на новую рецептуру с понедельника.\n— Принял, инструктаж по изменениям будет?', zh: '——周一开始切换到新配方。——收到，会有变更培训吗？', en: '— Switch to the new formulation starting Monday. — Understood; will there be a briefing on the changes?', ctx: '切换配方' },
  { ru: 'Если бы сырьё пришло вовремя, мы бы не сорвали график отгрузки.', zh: '要是原料按时到货，我们就不会耽误发货进度了。', en: 'If the raw material had arrived on time, we wouldn\'t have disrupted the shipping schedule.', ctx: '原料延误' },
  { ru: '— Какой зазор между валками каландра стоит?\n— Полмиллиметра, по технологической карте.', zh: '——压延机的辊间隙设的是多少？——半毫米，按工艺卡来的。', en: '— What gap is set between the calender rolls? — Half a millimetre, per the process card.', ctx: '压延辊间隙' },
  { ru: 'Опять обрыв жгута, третий раз за смену!', zh: '料条又断了，这班都第三次了！', en: 'The strand broke again — the third time this shift!', ctx: '料条断裂' },
  { ru: '— Кто сегодня отвечает за смену?\n— Мастер Петров, он же ведёт журнал.', zh: '——今天谁负责这个班？——彼得罗夫班长，记录本也是他在管。', en: '— Who is in charge of the shift today? — Foreman Petrov; he also keeps the logbook.', ctx: '当班负责人' },
  { ru: '— Насос подачи расплава гудит странно.\n— Давление на входе какое?\n— Пониженное.\n— Значит, заборный фильтр забился, чисти.', zh: '——熔体泵声音不对劲。——入口压力多少？——偏低。——那就是进料滤网堵了，清理一下。', en: '— The melt pump is humming strangely. — What\'s the inlet pressure? — Low. — Then the intake filter is clogged; clean it.', ctx: '熔体泵异响' },
  { ru: 'Упаковочный участок работает в три смены без выходных.', zh: '包装工段三班倒，没有休息日。', en: 'The packaging section works in three shifts, without days off.', ctx: '包装车间' },
  { ru: '— Склад готовой продукции переполнен.\n— Знаю, отгрузка задерживается из-за вагонов.', zh: '——成品库已经堆满了。——知道，车皮不够，发货耽搁了。', en: '— The finished goods warehouse is overfilled. — I know; shipment is delayed because of the railcars.', ctx: '成品积压' },
  { ru: '— Проведи замер влажности сырья из каждого мешка.\n— Сделаю, результат занесу в накладную.', zh: '——每袋原料都测一下含水率。——好的，结果我记到送货单上。', en: '— Measure the moisture of the raw material from each bag. — Will do; I\'ll enter the results into the delivery note.', ctx: '原料含水' },
  { ru: 'На следующей неделе линия встанет на плановое обслуживание.', zh: '下周生产线将停机进行计划检修。', en: 'Next week the line will be stopped for scheduled maintenance.', ctx: '计划检修' },
  { ru: '— Ночная смена оставила замечания в журнале.\n— Что пишут?\n— Перепады напряжения на нагревателях.\n— Передам электрикам, спасибо.', zh: '——夜班在记录本上留了意见。——写了什么？——加热器电压波动。——我转达给电工，谢谢。', en: '— The night shift left remarks in the logbook. — What do they say? — Voltage fluctuations on the heaters. — I\'ll pass that to the electricians, thanks.', ctx: '交接班记录' },
  { ru: '— Записал массу навески в журнал?\n— Да, три целых две сотых грамма.', zh: '——称样量记到记录本上了吗？——记了，3.02克。', en: '— Did you record the sample weight in the logbook? — Yes, three point zero two grams.', ctx: '记录称量' },
  { ru: 'Сегодняшний эксперимент не воспроизводится, уже третья попытка.', zh: '今天的实验重复不出来，已经是第三次尝试了。', en: 'Today\'s experiment won\'t reproduce — this is already the third attempt.', ctx: '无法复现' },
  { ru: '— Почему данные так сильно разбросаны?\n— Возможно, датчик температуры шумит.\n— Проверь его на эталоне.\n— Проверил: отклонение в полтора градуса, вот и причина.', zh: '——数据为什么这么离散？——可能温度传感器有噪声。——用标准件校一下。——校了：偏差一点五度，原因找到了。', en: '— Why are the data so scattered? — Possibly the temperature sensor is noisy. — Check it against a reference. — I did: a deviation of one and a half degrees; that\'s the reason.', ctx: '数据离散' },
  { ru: '— Какую погрешность ты заложил в расчёт?\n— Плюс-минус два процента, по паспорту прибора.', zh: '——你在计算里取了多少误差？——正负百分之二，按仪器说明书。', en: '— What error did you assume in the calculation? — Plus or minus two percent, per the instrument\'s certificate.', ctx: '误差估算' },
  { ru: 'Какая странная аномалия на кривой, такого раньше не было!', zh: '曲线上这个异常好奇怪，以前从没出现过！', en: 'What a strange anomaly on the curve — this never happened before!', ctx: '曲线异常' },
  { ru: '— Отчёт за прошлую неделю готов?\n— Почти, осталось оформить графики.', zh: '——上周的报告写好了吗？——差不多了，就差把图表排好。', en: '— Is last week\'s report ready? — Almost; I just need to format the graphs.', ctx: '周报进度' },
  { ru: 'Если бы я записал условия опыта сразу, не пришлось бы потом гадать.', zh: '要是我当时就把实验条件记下来，之后就不用猜了。', en: 'If I had recorded the experimental conditions right away, I wouldn\'t have to guess later.', ctx: '及时记录' },
  { ru: '— Эти результаты сильно отличаются от вчерашних.\n— Условия те же?\n— Вроде да.\n— Тогда проверь калибровку весов.', zh: '——这些结果和昨天的差很多。——条件一样吗？——好像一样。——那检查一下天平校准。', en: '— These results differ a lot from yesterday\'s. — Were the conditions the same? — Seems so. — Then check the balance calibration.', ctx: '结果不一致' },
  { ru: '— Как ты различаешь все эти образцы?\n— Каждый получил уникальный номер, вот реестр.', zh: '——你怎么区分这些样品？——每个都有唯一编号，这是登记表。', en: '— How do you tell all these samples apart? — Each has a unique number; here is the register.', ctx: '样品编号' },
  { ru: '— Случайно удалил файл с измерениями, что делать?\n— Спокойно, на сервере есть автоматическая копия.', zh: '——我不小心把测量文件删了，怎么办？——别慌，服务器上有自动备份。', en: '— I accidentally deleted the measurement file; what should I do? — Stay calm, there\'s an automatic backup on the server.', ctx: '误删数据' },
  { ru: '— Заполни протокол испытаний до конца смены.\n— Обязательно, а подпись чью ставить?', zh: '——下班前把试验记录填好。——一定，签字签谁的？', en: '— Fill in the test protocol before the end of the shift. — Sure; whose signature should go on it?', ctx: '填写记录' },
  { ru: 'Среднее значение из 5 измерений равно 42,3 МПа.', zh: '5次测量的平均值是42.3兆帕。', en: 'The average of 5 measurements is 42.3 MPa.', ctx: '均值计算', say: 'Среднее значение из пяти измерений равно сорока двум целым трём десятым мегапаскаля.' },
  { ru: '— Видел мой журнал с записями за март?\n— На стеллаже лежал.\n— Спасибо, нашёл. Кстати, там ошибка в дате.', zh: '——看到我的三月份记录本了吗？——在架子上放着。——谢谢，找到了。对了，里面有个日期写错了。', en: '— Have you seen my logbook with the March entries? — It was on the shelf. — Thanks, found it. By the way, there\'s a wrong date in it.', ctx: '找实验本' },
  { ru: '— Почему ты выбросил эту точку из статистики?\n— Она выпадает за три сигмы, явный промах.', zh: '——你为什么把这个数据点从统计里剔掉了？——它超出三倍标准差，明显是异常值。', en: '— Why did you exclude this point from the statistics? — It falls beyond three sigma; an obvious outlier.', ctx: '剔除异常值' },
  { ru: 'Фотографии изломов хранятся в общей папке лаборатории.', zh: '断口照片存放在实验室的共享文件夹里。', en: 'The fracture photos are stored in the laboratory\'s shared folder.', ctx: '照片存档' },
  { ru: '— Повтори измерение ещё дважды для верности.\n— Уже повторил, значения сошлись.', zh: '——保险起见再重复测两次。——已经测过了，数值吻合。', en: '— Repeat the measurement twice more to be sure. — Already did; the values agree.', ctx: '重复测量' },
  { ru: 'В лабораторном журнале нельзя оставлять пустые страницы.', zh: '实验记录本里不允许留空白页。', en: 'Blank pages are not allowed in the laboratory logbook.', ctx: '记录规范' },
  { ru: '— Ты подписал протокол у руководителя?\n— Он вернул с замечаниями.\n— Какими?\n— Просит указать влажность воздуха при испытаниях.', zh: '——你找负责人签记录了吗？——他退回来了，附了意见。——什么意见？——要求注明试验时的空气湿度。', en: '— Did you get the protocol signed by the supervisor? — He returned it with comments. — What comments? — He asks to state the air humidity during the tests.', ctx: '签字退回' },
  { ru: '— Во сколько начался отжиг образцов?\n— В девять утра, отметка есть в журнале.', zh: '——样品退火是几点开始的？——上午九点，记录本上有标注。', en: '— What time did the annealing of the samples start? — At nine in the morning; there\'s a note in the logbook.', ctx: '退火时间' },
  { ru: 'Завтра перепишу черновик отчёта начисто и передам на проверку.', zh: '明天我把报告草稿誊写清楚，然后交上去审核。', en: 'Tomorrow I will rewrite the draft report cleanly and submit it for review.', ctx: '誊写报告' },
  { ru: 'Раздел «Экспериментальная часть» должен быть воспроизводимым.', zh: '“实验部分”这一章必须写得可以复现。', en: 'The Experimental section must be reproducible.', ctx: '实验部分' },
  { ru: '— Как оформить ссылку на эту статью?\n— По ГОСТу, посмотри примеры в методичке.', zh: '——这篇文章的引用格式怎么写？——按国标来，参考手册里有示例。', en: '— How should I format the reference to this article? — According to GOST; see the examples in the handbook.', ctx: '引用格式', say: '— Как оформить ссылку на эту статью? — По госту, посмотри примеры в методичке.' },
  { ru: '— Рецензент просит добавить данные по дисперсности.\n— У нас они есть?\n— Да, из ГПХ, вставлю таблицей.', zh: '——审稿人要求补充分散系数的数据。——我们有吗？——有，GPC测的，我做成表格插进去。', en: '— The reviewer asks to add polydispersity data. — Do we have them? — Yes, from GPC; I\'ll insert them as a table.', ctx: '审稿意见', say: '— Рецензент просит добавить данные по дисперсности. — У нас они есть? — Да, из гель-проникающей хроматографии, вставлю таблицей.' },
  { ru: '— На каком языке писать подписи к рисункам?\n— На двух: русском и английском.', zh: '——图注用什么语言写？——两种：俄语和英语。', en: '— In which language should the figure captions be written? — In two: Russian and English.', ctx: '图注语言' },
  { ru: '— Этот абзац лучше перенести во введение.\n— Согласен, там он логичнее смотрится.', zh: '——这一段最好移到引言里去。——同意，放在那里更合逻辑。', en: '— This paragraph is better moved to the introduction. — Agreed, it looks more logical there.', ctx: '调整段落' },
  { ru: '— Сколько ключевых слов требует журнал?\n— От пяти до семи, не больше.', zh: '——期刊要求几个关键词？——五到七个，不能再多。', en: '— How many keywords does the journal require? — Five to seven, no more.', ctx: '关键词数量' },
  { ru: 'Если бы я раньше начал писать статью, сейчас бы не мучился со сроками.', zh: '要是我早点动笔写论文，现在就不用为期限发愁了。', en: 'If I had started writing the article earlier, I wouldn\'t be struggling with deadlines now.', ctx: '写作拖延' },
  { ru: '— Таблица два не сходится с текстом.\n— Где именно?\n— Во второй строке значения перепутаны.\n— Точно, исправлю сегодня же.', zh: '——表二和正文对不上。——具体哪里？——第二行的数值弄错了。——确实，我今天就更正。', en: '— Table two doesn\'t match the text. — Where exactly? — The values in the second row are mixed up. — Right, I\'ll fix it today.', ctx: '图表核对' },
  { ru: 'Аннотация должна отражать цель, методы и главный результат.', zh: '摘要必须体现目的、方法和主要结果。', en: 'The abstract must reflect the aim, the methods, and the main result.', ctx: '摘要写法' },
  { ru: '— Ты ответил на все замечания рецензента?\n— На все, письмо с пояснениями приложил.', zh: '——审稿人的意见你都回复了吗？——都回复了，还附了说明信。', en: '— Have you answered all the reviewer\'s comments? — All of them; I attached an explanatory letter.', ctx: '回复审稿' },
  { ru: '— Какой шрифт использовать для формул?\n— Основной текстовый, курсив для переменных.', zh: '——公式用什么字体？——正文主字体，变量用斜体。', en: '— Which font should be used for formulas? — The main text font, italics for variables.', ctx: '公式排版' },
  { ru: 'Список литературы я сформировал автоматически через менеджер ссылок.', zh: '参考文献列表我用文献管理软件自动生成了。', en: 'I generated the reference list automatically with a citation manager.', ctx: '文献管理' },
  { ru: '— График лучше сделать цветным или чёрно-белым?\n— Чёрно-белым: журнал печатный.\n— А маркеры различимы будут?\n— Сделаю разные формы маркеров.', zh: '——图做成彩色的还是黑白的？——黑白的，期刊是纸版的。——那数据点还能区分吗？——我用不同形状的标记。', en: '— Should the graph be color or black-and-white? — Black-and-white: the journal is printed. — Will the markers be distinguishable? — I\'ll use different marker shapes.', ctx: '图表配色' },
  { ru: '— Проверь, пожалуйста, мой английский в аннотации.\n— Давай, кину правки к вечеру.', zh: '——帮我看看摘要的英文吧。——好，晚上前把修改发你。', en: '— Please check my English in the abstract. — Sure, I\'ll send you the edits by evening.', ctx: '语言润色' },
  { ru: 'Наконец-то статья принята, два года работы не зря!', zh: '论文终于录用了，两年的功夫没白费！', en: 'The article is finally accepted — two years of work were not in vain!', ctx: '论文录用' },
  { ru: '— В каком журнале планируешь публиковаться?\n— В «Высокомолекулярных соединениях», профиль подходит.', zh: '——你打算投哪个期刊？——《高分子化合物》，方向对口。', en: '— Which journal are you planning to publish in? — In Vysokomolekulyarnye Soedineniya; the scope fits.', ctx: '目标期刊' },
  { ru: 'Введение переписал трижды, но результатом доволен.', zh: '引言我改了三遍，不过对结果很满意。', en: 'I rewrote the introduction three times, but I\'m pleased with the result.', ctx: '反复修改' },
  { ru: '— Процент оригинальности проверил?\n— Да, система показывает восемьдесят девять процентов.', zh: '——查重率看过了吗？——看了，系统显示原创度百分之八十九。', en: '— Have you checked the originality percentage? — Yes, the system shows eighty-nine percent.', ctx: '查重结果' },
  { ru: '— Кто будет соавтором статьи?\n— Руководитель и лаборант, делавший измерения.\n— Порядок авторов обсудили?\n— Да, по вкладу в работу.', zh: '——论文的共同作者都有谁？——导师和做测试的实验员。——署名顺序商量了吗？——商量了，按贡献排。', en: '— Who will be the co-authors of the article? — The supervisor and the lab assistant who did the measurements. — Did you discuss the author order? — Yes, by contribution to the work.', ctx: '署名顺序' },
  { ru: 'После доработки отправлю рукопись в редакцию не позднее пятницы.', zh: '修改完之后，我周五前就把稿件投给编辑部。', en: 'After the revision I will send the manuscript to the editorial office no later than Friday.', ctx: '投稿计划' },
]

// ── 职场工作 / Workplace / Работа ──
const WORK: Phrase[] = [
  { ru: 'Меня зовут Анна, я работала маркетологом 3 года в e-commerce.', zh: '我叫安娜，在电商行业做了3年营销。', en: 'My name is Anna, and I worked as a marketer for 3 years in e-commerce.', ctx: '求职面试', say: 'Меня зовут Анна, я работала маркетологом три года в электронной коммерции.' },
  { ru: '— Какие у вас ожидания по зарплате?\n— Я рассчитываю на 120 тысяч рублей до вычета налогов.', zh: '——您对薪资有什么期望？\n——我期望税前12万卢布。', en: '— What are your salary expectations?\n— I expect 120 thousand rubles before tax.', ctx: '求职面试', say: '— Какие у вас ожидания по зарплате?\n— Я рассчитываю на сто двадцать тысяч рублей до вычета налогов.' },
  { ru: '— Расскажите о вашем опыте управления командой.\n— Я руководил отделом из 8 человек, внедрил agile.', zh: '——请谈谈您的团队管理经验。\n——我管理过8人团队，引入了敏捷方法。', en: '— Tell me about your team management experience.\n— I led an 8-person department and introduced agile.', ctx: '求职面试', say: '— Расскажите о вашем опыте управления командой.\n— Я руководил отделом из восьми человек, внедрил эджайл.' },
  { ru: '— Почему вы уволились с предыдущего места?\n— Компания сократила бюджет, и мой проект заморозили.\n— Понимаю, к сожалению, такое сейчас нередко случается.', zh: '——您为什么从上一家公司离职？\n——公司削减了预算，我的项目被冻结了。\n——理解，很遗憾，这种情况现在并不少见。', en: '— Why did you leave your previous job?\n— The company cut the budget and froze my project.\n— I understand; unfortunately, that happens often these days.', ctx: '求职面试' },
  { ru: '— Когда вы можете выйти на работу?\n— Через две недели после подписания договора.', zh: '——您什么时候可以入职？\n——签合同后两周。', en: '— When can you start?\n— Two weeks after signing the contract.', ctx: '求职面试' },
  { ru: 'Мои ключевые компетенции — аналитика, переговоры и запуск продуктов с нуля.', zh: '我的核心能力是分析、谈判和从零开始推出产品。', en: 'My key competencies are analytics, negotiation, and launching products from scratch.', ctx: '求职面试' },
  { ru: '— Готовы ли вы к командировкам?\n— Да, до 20% рабочего времени.', zh: '——您能接受出差吗？\n——可以，占工作时间20%以内。', en: '— Are you open to business trips?\n— Yes, up to 20% of working time.', ctx: '求职面试', say: '— Готовы ли вы к командировкам?\n— Да, до двадцати процентов рабочего времени.' },
  { ru: '— Есть ли у вас вопросы к нам?\n— Какие KPI ставят на испытательный срок?', zh: '——您有什么问题要问我们吗？\n——试用期的KPI是什么？', en: '— Do you have any questions for us?\n— What KPIs are set for the probation period?', ctx: '求职面试', say: '— Есть ли у вас вопросы к нам?\n— Какие кэй-пи-ай ставят на испытательный срок?' },
  { ru: '— Расскажите о вашем самом сложном проекте.\n— Это был миграция данных за 72 часа без остановки сервиса.', zh: '——请谈谈您做过最复杂的项目。\n——是一次72小时内不停服的数据迁移。', en: '— Tell me about your most complex project.\n— It was a data migration within 72 hours without service downtime.', ctx: '求职面试', say: '— Расскажите о вашем самом сложном проекте.\n— Это была миграция данных за семьдесят два часа без остановки сервиса.' },
  { ru: '— Как вы справляетесь с дедлайнами?\n— Декомпозирую задачи и ставлю промежуточные контрольные точки.\n— Разумный подход, у нас он тоже приветствуется.', zh: '——您如何应对截止日期？\n——我会分解任务并设置中间检查点。\n——合理的做法，我们公司也提倡这样。', en: '— How do you handle deadlines?\n— I decompose tasks and set intermediate checkpoints.\n— A sensible approach; we encourage it here too.', ctx: '求职面试' },
  { ru: '— Почему именно наша компания?\n— Мне нравится ваша экспертиза в B2B и корпоративная культура.', zh: '——为什么选我们公司？\n——我欣赏你们在B2B领域的专业度和企业文化。', en: '— Why our company specifically?\n— I appreciate your B2B expertise and corporate culture.', ctx: '求职面试', say: '— Почему именно наша компания?\n— Мне нравится ваша экспертиза в би-ту-би и корпоративная культура.' },
  { ru: '— Можете привести пример конфликта в команде?\n— Два разработчика спорили о стеке, я организовал proof of concept.', zh: '——能举一个团队冲突的例子吗？\n——两位开发者为技术栈争执，我组织了概念验证。', en: '— Can you give an example of a team conflict?\n— Two developers argued about the stack, and I organized a proof of concept.', ctx: '求职面试', say: '— Можете привести пример конфликта в команде?\n— Два разработчика спорили о стеке, я организовал пруф оф концепт.' },
  { ru: 'Меня привлекает возможность работать в международной среде и развивать soft skills.', zh: '我向往在国际环境中工作并提升软技能的机会。', en: 'I am attracted by the opportunity to work in an international environment and develop soft skills.', ctx: '求职面试', say: 'Меня привлекает возможность работать в международной среде и развивать софт скиллс.' },
  { ru: '— Что для вас важнее: зарплата или рост?\n— На данном этапе — рост, но стабильный доход тоже нужен.', zh: '——对您来说薪资和成长哪个更重要？\n——现阶段是成长，但稳定收入也必要。', en: '— What matters more to you: salary or growth?\n— At this stage, growth, but stable income is also needed.', ctx: '求职面试' },
  { ru: '— Где вы видите себя через 5 лет?\n— В роли директора по продукту с глубокой экспертизой в AI.', zh: '——您设想过自己5年后是什么样子吗？\n——我希望成为具备深厚AI专业知识的产品总监。', en: '— Where do you see yourself in 5 years?\n— As a director of product with deep AI expertise.', ctx: '求职面试', say: '— Где вы видите себя через пять лет?\n— В роли директора по продукту с глубокой экспертизой в эй-ай.' },
  { ru: 'Я уже отметился в системе, сегодня в офисе с 8:45.', zh: '我已经在系统里打卡了，今天8:45到办公室。', en: 'I already checked in the system; I’m in the office from 8:45 today.', ctx: '办公日常', say: 'Я уже отметился в системе, сегодня в офисе с восемь сорок пять.' },
  { ru: '— Ты уже отправил ежедневный отчёт?\n— Да, в Slack-канале #daily с тегом @lead.', zh: '——你发日报了吗？\n——发了，在#daily频道里@了主管。', en: '— Have you sent the daily report yet?\n— Yes, in the #daily Slack channel with @lead.', ctx: '办公日常', say: '— Ты уже отправил ежедневный отчёт?\n— Да, в Слак-канале дейли с тегом эт-лид.' },
  { ru: '— Перезвони клиенту до обеда, пожалуйста.\n— Хорошо, уточню детали по договору.\n— И сразу напиши мне, что он ответил.', zh: '——请在午饭前给客户回个电话。\n——好的，我会确认合同细节。\n——然后马上告诉我他怎么回复的。', en: '— Please call the client back before lunch.\n— Okay, I’ll clarify the contract details.\n— And write to me right away about what he says.', ctx: '办公日常' },
  { ru: 'Проверь почту: пришло письмо от бухгалтерии с актами за сентябрь.', zh: '看一下邮箱：会计部发来9月账单了。', en: 'Check your email: a letter from accounting with September invoices has arrived.', ctx: '办公日常' },
  { ru: '— Забронируй переговорку на 14:00 на час.\n— Забронировал, но только до 14:50.', zh: '——帮我订一间会议室，下午2点用一小时。\n——订好了，但只到2:50。', en: '— Book a meeting room for 14:00 for an hour.\n— Booked, but only until 14:50.', ctx: '办公日常', say: '— Забронируй переговорку на четырнадцать ноль-ноль на час.\n— Забронировал, но только до четырнадцати пятидесяти.' },
  { ru: 'В календаре конфликт: у тебя одновременно созвон и ревью кода.', zh: '日程冲突了：你的电话会和代码评审撞时间了。', en: 'There’s a calendar conflict: your call and code review overlap.', ctx: '办公日常' },
  { ru: '— Ты видел обновление в Confluence?\n— Да, добавили требования к новому модулю.\n— Тогда созвонимся завтра и обсудим детали.', zh: '——你看到Confluence的更新了吗？\n——看到了，增加了新模块的需求。\n——那明天通个电话讨论一下细节。', en: '— Did you see the Confluence update?\n— Yes, they added requirements for the new module.\n— Then let’s have a call tomorrow and discuss the details.', ctx: '办公日常', say: '— Ты видел обновление в Конфлюенс?\n— Да, добавили требования к новому модулю.\n— Тогда созвонимся завтра и обсудим детали.' },
  { ru: 'Поставь задачу в Jira с приоритетом medium и назначь на backend-команду.', zh: '在Jira里建个中等优先级的任务，指派给后端团队。', en: 'Create a Jira task with medium priority and assign it to the backend team.', ctx: '办公日常', say: 'Поставь задачу в Джира с приоритетом медиум и назначь на бэкенд-команду.' },
  { ru: '— Ты уже заполнил табель за октябрь?\n— Нет, там ошибка в отпуске с 4 по 8 числа.', zh: '——你填好10月的考勤表了吗？\n——没，4号到8号的请假数据有误。', en: '— Have you filled out the October timesheet?\n— No, there’s an error in my leave from the 4th to the 8th.', ctx: '办公日常', say: '— Ты уже заполнил табель за октябрь?\n— Нет, там ошибка в отпуске с четвёртого по восьмое числа.' },
  { ru: '— Перешли мне логи с сервера staging.\n— Отправил в личку, архивом zip.', zh: '——把staging服务器的日志转发给我。\n——私聊发你了，zip压缩包。', en: '— Forward me the logs from the staging server.\n— Sent in DM as a zip archive.', ctx: '办公日常', say: '— Перешли мне логи с сервера стейджинг.\n— Отправил в личку, архивом зип.' },
  { ru: 'Скоро обед: пойдём в столовую или закажем доставку?', zh: '快午饭了：去食堂还是叫外卖？', en: 'Lunch is soon: shall we go to the canteen or order delivery?', ctx: '办公日常' },
  { ru: '— Ты записал на видео демонстрацию?\n— Да, залил на корпоративный диск, ссылку скину.', zh: '——你把演示录屏了吗？\n——录了，上传到企业网盘了，链接马上发。', en: '— Did you record the demo?\n— Yes, uploaded it to the corporate drive; I’ll send the link.', ctx: '办公日常' },
  { ru: 'Печать сломалась, придётся сохранить в PDF и отправить через ЭДО.', zh: '打印机坏了，只能存成PDF通过电子文档系统发送。', en: 'The printer is broken; I’ll have to save as PDF and send via EDI.', ctx: '办公日常', say: 'Печать сломалась, придётся сохранить в ПДФ и отправить через э-д-о.' },
  { ru: '— У тебя есть доступ к CRM?\n— Пока нет, жду выдачу прав от IT.', zh: '——你有CRM权限吗？\n——还没有，在等IT开权限。', en: '— Do you have access to the CRM?\n— Not yet, waiting for IT to grant permissions.', ctx: '办公日常', say: '— У тебя есть доступ к си-эр-эм?\n— Пока нет, жду выдачу прав от ай-ти.' },
  { ru: '— Осталось подписать документы у директора?\n— Да, зайду к нему после трёх.', zh: '——就差找领导签字了吗？\n——对，我三点以后去找他。', en: '— Is the director’s signature all that’s left?\n— Yes, I’ll go see him after three.', ctx: '办公日常' },
  { ru: 'Давайте начнём без опоздавших; к 10:15 подключатся из филиала в Самаре.', zh: '我们先开始，不等迟到的人；10:15萨马拉分部的同事会加入。', en: 'Let’s start without those who are late; the Samara branch will join by 10:15.', ctx: '会议讨论', say: 'Давайте начнём без опоздавших; к десяти пятнадцати подключатся из филиала в Самаре.' },
  { ru: '— Кто будет модерировать обсуждение?\n— Я возьму на себя, но прошу таймить выступления.', zh: '——谁来主持讨论？\n——我来，但请大家控制发言时间。', en: '— Who will moderate the discussion?\n— I’ll take it, but please time the speeches.', ctx: '会议讨论' },
  { ru: '— У меня вопрос по слайду 7: откуда взялась цифра 18%?\n— Это данные отдела аналитики за Q3.', zh: '——我对第7页幻灯片有疑问：18%这个数字是怎么来的？\n——这是分析部Q3的数据。', en: '— I have a question about slide 7: where did the 18% figure come from?\n— It’s from the analytics department’s Q3 data.', ctx: '会议讨论', say: '— У меня вопрос по слайду семь: откуда взялась цифра восемнадцать процентов?\n— Это данные отдела аналитики за кью-три.' },
  { ru: '— Я не согласен с оценкой сроков.\n— Обоснуй: какие риски ты видишь?\n— Интеграция с внешней системой может занять вдвое больше времени.', zh: '——我不同意这个工期评估。\n——请说明理由：你看到了哪些风险？\n——和外部系统的对接可能要多花一倍的时间。', en: '— I disagree with the timeline estimate.\n— Justify it: what risks do you see?\n— Integration with the external system may take twice as long.', ctx: '会议讨论' },
  { ru: 'Подведём итоги: мы сдвинули дедлайн на неделю и сократили scope MVP.', zh: '总结一下：我们把截止日期延后一周，并缩减了MVP范围。', en: 'Let’s summarize: we pushed the deadline back by a week and reduced the MVP scope.', ctx: '会议讨论', say: 'Подведём итоги: мы сдвинули дедлайн на неделю и сократили скоуп эм-ви-пи.' },
  { ru: '— Кто возьмёт action item по интеграции?\n— Записал в протокол, ответственный Иванов.', zh: '——谁负责对接这个行动项？\n——已经记在会议纪要里了，负责人是伊万诺夫。', en: '— Who will take the action item on integration?\n— Recorded in the minutes; Ivanov is responsible.', ctx: '会议讨论', say: '— Кто возьмёт экшн айтем по интеграции?\n— Записал в протокол, ответственный Иванов.' },
  { ru: 'Давайте обсудим это offline, чтобы не тянуть созвон.', zh: '我们线下再讨论这个吧，别让电话会拖太久。', en: 'Let’s discuss this offline so we don’t drag out the call.', ctx: '会议讨论', say: 'Давайте обсудим это офлайн, чтобы не тянуть созвон.' },
  { ru: '— Есть ли возражения против предложенного плана?\n— Пока нет, но прошу зафиксировать риски.', zh: '——对提出的计划有异议吗？\n——暂时没有，但请把风险记录下来。', en: '— Are there any objections to the proposed plan?\n— Not for now, but please record the risks.', ctx: '会议讨论' },
  { ru: '— Можешь поделиться экраном?\n— Секунду, у меня два монитора, выберу нужный.', zh: '——你能共享一下屏幕吗？\n——稍等，我有两个显示器，我选一下。', en: '— Can you share your screen?\n— One moment, I have two monitors; I’ll pick the right one.', ctx: '会议讨论' },
  { ru: 'В следующем созвоне представим результаты A/B-теста и решим о масштабировании.', zh: '下次电话会我们会展示A/B测试结果，并决定是否扩大推广。', en: 'In the next call we’ll present the A/B test results and decide on scaling.', ctx: '会议讨论', say: 'В следующем созвоне представим результаты эй-би-теста и решим о масштабировании.' },
  { ru: '— Какие метрики будем отслеживать?\n— CAC, LTV и churn за первые 30 дней.', zh: '——我们要追踪哪些指标？\n——获客成本、用户生命周期价值和前30天流失率。', en: '— What metrics will we track?\n— CAC, LTV, and churn for the first 30 days.', ctx: '会议讨论', say: '— Какие метрики будем отслеживать?\n— си-эй-си, эл-тэ-ви и чёрн за первые тридцать дней.' },
  { ru: '— Почему мы отказались от варианта B?\n— Там выше capex и сложнее поддержка.', zh: '——为什么放弃了B方案？\n——资本支出更高，维护也更复杂。', en: '— Why did we drop option B?\n— Higher capex and more complex maintenance.', ctx: '会议讨论', say: '— Почему мы отказались от варианта би?\n— Там выше кейпекс и сложнее поддержка.' },
  { ru: '— Ты готов выступить с докладом на ретро?\n— Да, но мне нужен доступ к дашборду.', zh: '——你准备在复盘会上发言吗？\n——是的，但我需要访问仪表盘权限。', en: '— Are you ready to speak at the retro?\n— Yes, but I need access to the dashboard.', ctx: '会议讨论' },
  { ru: '— Давай перенесём демо на пятницу.\n— Неудобно: в пятницу я в отпуске до 15:00.', zh: '——我们把演示改到周五吧。\n——不太方便：周五我休假到下午3点。', en: '— Let’s move the demo to Friday.\n— Inconvenient: I’m on leave until 15:00 on Friday.', ctx: '会议讨论', say: '— Давай перенесём демо на пятницу.\n— Неудобно: в пятницу я в отпуске до пятнадцати ноль-ноль.' },
  { ru: 'Согласуем финальную версию road map до конца дня и разошлём stakeholders.', zh: '今天下班前确定最终版路线图，然后发给各利益相关方。', en: 'Let’s agree on the final road map version by end of day and send it to stakeholders.', ctx: '会议讨论', say: 'Согласуем финальную версию роад мэп до конца дня и разошлём стейкхолдерс.' },
  { ru: '— Можешь помочь с формулой в Excel?\n— Конечно, скинь файл, посмотрю вечером.', zh: '——你能帮我看看Excel里的公式吗？\n——当然，把文件发我，晚上帮你看。', en: '— Can you help with a formula in Excel?\n— Sure, send the file and I’ll look in the evening.', ctx: '同事关系', say: '— Можешь помочь с формулой в Эксель?\n— Конечно, скинь файл, посмотрю вечером.' },
  { ru: '— Ты не против, если я сяду рядом? Хочу обсудить задачу.\n— Да, давай, сейчас как раз перерыв.', zh: '——你介意我坐旁边吗？想讨论个任务。\n——不介意，正好现在休息。', en: '— Do you mind if I sit next to you? I want to discuss a task.\n— No, let’s do it; it’s break time right now.', ctx: '同事关系' },
  { ru: '— Ты слышал, что Петров уходит в другой отдел?\n— Да, жалко, с ним было легко работать.\n— Ничего, он хотя бы остаётся в компании.', zh: '——你听说彼得罗夫要调去别的部门了吗？\n——听说了，挺可惜的，跟他共事很轻松。\n——没事，至少他还留在公司里。', en: '— Did you hear Petrov is moving to another department?\n— Yes, it’s a shame; he was easy to work with.\n— Well, at least he’s staying in the company.', ctx: '同事关系' },
  { ru: 'Пойдём на обед вместе? Сегодня в столовой борщ и котлеты.', zh: '一起去吃午饭吗？今天食堂有红菜汤和肉饼。', en: 'Shall we go to lunch together? Today the canteen has borscht and cutlets.', ctx: '同事关系' },
  { ru: '— Спасибо, что подменил меня на созвоне!\n— Без проблем, всё записал.', zh: '——谢谢你替我参加了电话会！\n——没问题，我都记下来了。', en: '— Thanks for covering me on the call!\n— No problem, I took notes.', ctx: '同事关系' },
  { ru: 'Мы отлично сработались на этом проекте.', zh: '我们在这个项目上配合得非常默契。', en: 'We worked together perfectly on this project.', ctx: '同事关系' },
  { ru: '— Как тебе новый руководитель?\n— Требовательный, но справедливый.', zh: '——你觉得新来的主管怎么样？\n——要求高，但很公正。', en: '— How do you like the new manager?\n— Demanding, but fair.', ctx: '同事关系' },
  { ru: '— Ты сегодня сам не свой, что случилось?\n— Поспорил с коллегой из-за приоритетов.\n— Бывает, главное — не копить обиды.', zh: '——你今天心神不宁的，出什么事了？\n——因为优先级的事跟同事争执了几句。\n——常有的事，关键是别往心里去。', en: '— You’re not yourself today, what happened?\n— I argued with a colleague over priorities.\n— It happens; the main thing is not to hold a grudge.', ctx: '同事关系' },
  { ru: '— Не мог бы ты посмотреть мой код до релиза?\n— Да, пришли pull request, гляну после обеда.', zh: '——发布前你能帮我看一下代码吗？\n——行，把pull request发我，午饭后我看。', en: '— Could you review my code before the release?\n— Sure, send me the pull request, I’ll look after lunch.', ctx: '同事关系', say: '— Не мог бы ты посмотреть мой код до релиза?\n— Да, пришли пул реквест, гляну после обеда.' },
  { ru: '— С днём рождения! Это подарок от всей команды.\n— Как приятно! Спасибо, коллеги!\n— Заслужил!', zh: '——生日快乐！这是全团队送的礼物。\n——太暖心了！谢谢大家！\n——你应得的！', en: '— Happy birthday! This gift is from the whole team.\n— How touching! Thanks, everyone!\n— You deserve it!', ctx: '同事关系' },
  { ru: '— Ты не против, если я включу кондиционер?\n— Включай, только не направляй на меня.', zh: '——我开空调你不介意吧？\n——开吧，只是别对着我吹。', en: '— Do you mind if I turn on the air conditioner?\n— Go ahead, just don’t point it at me.', ctx: '同事关系' },
  { ru: '— Кто съел мой йогурт из холодильника?\n— Прости, я взял по ошибке, куплю тебе новый.\n— Ладно, только в следующий раз подпиши свой.', zh: '——谁吃了我冰箱里的酸奶？\n——抱歉，我拿错了，给你买杯新的。\n——好吧，下次记得在自己的上面写名字。', en: '— Who ate my yogurt from the fridge?\n— Sorry, I took it by mistake; I’ll buy you a new one.\n— Fine, just label yours next time.', ctx: '同事关系' },
  { ru: 'Если понадобится помощь с отчётностью, обращайся.', zh: '如果报表方面需要帮忙，随时来找我。', en: 'If you need help with reporting, just come to me.', ctx: '同事关系' },
  { ru: '— Хватит сплетничать, давайте работать!\n— Согласна, что-то мы совсем отвлеклись.', zh: '——别八卦了，干活吧！\n——说得对，我们确实聊过头了。', en: '— Enough gossiping, let’s work!\n— Agreed, we got too distracted.', ctx: '同事关系' },
  { ru: 'В нашей команде принято помогать друг другу без лишних просьб.', zh: '我们团队的习惯是不用开口就互相帮忙。', en: 'In our team it’s customary to help each other without being asked.', ctx: '同事关系' },
  { ru: 'План по продажам выполнен на 112%.', zh: '销售计划完成了112%。', en: 'The sales plan was fulfilled at 112%.', ctx: '汇报述职', say: 'План по продажам выполнен на сто двенадцать процентов.' },
  { ru: '— Как продвигается квартальный проект?\n— Идём по графику, рисков не вижу.', zh: '——季度项目进展如何？\n——按计划推进，我看不到风险。', en: '— How is the quarterly project progressing?\n— We’re on schedule, I see no risks.', ctx: '汇报述职' },
  { ru: '— Почему упали показатели в октябре?\n— Сезонный спад плюс ушёл ключевой клиент.\n— Понятно, готовь план возврата клиента.', zh: '——为什么十月的指标下滑了？\n——季节性淡季，加上走了一个大客户。\n——明白了，准备一份客户挽回方案。', en: '— Why did the numbers drop in October?\n— A seasonal dip plus we lost a key client.\n— Understood; prepare a plan to win the client back.', ctx: '汇报述职' },
  { ru: 'Докладываю: все задачи спринта закрыты досрочно.', zh: '汇报一下：本次迭代的任务全部提前完成。', en: 'Reporting: all sprint tasks were closed ahead of schedule.', ctx: '汇报述职' },
  { ru: '— Какие главные трудности сейчас?\n— Не хватает людей и бюджета на продвижение.', zh: '——目前最大的困难是什么？\n——缺人手，也缺推广预算。', en: '— What are the main difficulties right now?\n— We’re short on people and marketing budget.', ctx: '汇报述职' },
  { ru: '— Какие цели ставишь на следующий квартал?\n— Запустить новый продукт и удержать базу клиентов.\n— Амбициозно, но реально.', zh: '——下个季度你定什么目标？\n——上线新产品，同时守住现有客户群。\n——有野心，但可行。', en: '— What goals are you setting for next quarter?\n— Launch the new product and retain the client base.\n— Ambitious, but realistic.', ctx: '汇报述职' },
  { ru: 'Мне удалось сократить издержки, не увольняя сотрудников.', zh: '我做到了不裁员也降低了成本。', en: 'I managed to cut costs without laying off employees.', ctx: '汇报述职' },
  { ru: '— Покажи цифры за последний месяц.\n— Вот дашборд, рост виден невооружённым глазом.', zh: '——给我看看上个月的数据。\n——这是看板，增长一目了然。', en: '— Show me last month’s numbers.\n— Here’s the dashboard; the growth is obvious.', ctx: '汇报述职' },
  { ru: 'Результаты говорят сами за себя!', zh: '结果自己会说话！', en: 'The results speak for themselves!', ctx: '汇报述职' },
  { ru: '— Отчёт готов?\n— Почти, осталась пара графиков.\n— К понедельнику он должен лежать у меня на столе.', zh: '——报告写好了吗？\n——快了，还差两张图表。\n——周一之前必须放到我桌上。', en: '— Is the report ready?\n— Almost, a couple of charts left.\n— It must be on my desk by Monday.', ctx: '汇报述职' },
  { ru: '— Что бы ты сделал иначе?\n— Начал бы тестировать гипотезы раньше.', zh: '——如果重来一次，你会怎么做？\n——我会更早开始验证假设。', en: '— What would you have done differently?\n— I would have started testing hypotheses earlier.', ctx: '汇报述职' },
  { ru: 'Честно говоря, часть целей была завышена изначально.', zh: '说实话，有一部分目标从一开始就定高了。', en: 'Honestly, some of the goals were inflated from the start.', ctx: '汇报述职' },
  { ru: '— Прошу учесть мои результаты при пересмотре оклада.\n— Хорошо, внесу это в повестку.', zh: '——请在调薪时考虑我的业绩。\n——好的，我会把这件事列入议程。', en: '— Please take my results into account at the salary review.\n— Okay, I’ll put it on the agenda.', ctx: '汇报述职' },
  { ru: '— Конверсия выросла с 3% до 5% за квартал.\n— Отличная динамика, продолжай в том же духе!', zh: '——转化率一个季度从3%涨到了5%。\n——势头很好，继续保持！', en: '— Conversion grew from 3% to 5% over the quarter.\n— Great dynamics, keep it up!', ctx: '汇报述职', say: '— Конверсия выросла с трёх до пяти процентов за квартал.\n— Отличная динамика, продолжай в том же духе!' },
  { ru: 'В следующем году сфокусируюсь на удержании клиентов.', zh: '明年我会把重点放在客户留存上。', en: 'Next year I’ll focus on client retention.', ctx: '汇报述职' },
  { ru: 'Я решил уволиться по собственному желанию.', zh: '我决定主动辞职。', en: 'I’ve decided to resign of my own accord.', ctx: '离职交接' },
  { ru: '— Почему ты уходишь?\n— Нашёл место ближе к дому, да и задачи интереснее.', zh: '——你为什么要走？\n——找了个离家近的岗位，工作也更有意思。', en: '— Why are you leaving?\n— I found a place closer to home, and the work is more interesting.', ctx: '离职交接' },
  { ru: '— Прошу считать это официальным заявлением об увольнении.\n— Принято, жаль, что вы уходите.', zh: '——请把这当作我的正式辞职申请。\n——收到，很遗憾你要离开。', en: '— Please consider this my official letter of resignation.\n— Received; it’s a pity you’re leaving.', ctx: '离职交接' },
  { ru: '— Кто заменит тебя?\n— Маша справится, я ей всё покажу за две недели.\n— Отлично, доверяю твоему выбору.', zh: '——谁来接替你？\n——玛莎能胜任，这两周我把一切都教给她。\n——很好，我相信你的判断。', en: '— Who will replace you?\n— Masha can handle it; I’ll show her everything in two weeks.\n— Great, I trust your judgment.', ctx: '离职交接' },
  { ru: 'Отработаю положенные две недели и спокойно уйду.', zh: '我会做满规定的两周交接期，然后平静离开。', en: 'I’ll work the required two weeks and leave quietly.', ctx: '离职交接' },
  { ru: '— Передай, пожалуйста, доступы к серверам.\n— Уже собрал всё в один документ, вот ссылка.', zh: '——请把服务器权限交接一下。\n——我都整理在一个文档里了，这是链接。', en: '— Please hand over the server access.\n— I’ve already put everything in one document; here’s the link.', ctx: '离职交接' },
  { ru: '— Жаль, что ты нас покидаешь!\n— Мне тоже, но так надо.', zh: '——真舍不得你走！\n——我也是，但没办法。', en: '— It’s a shame you’re leaving us!\n— I feel the same, but it has to be.', ctx: '离职交接' },
  { ru: '— Куда переходишь, если не секрет?\n— В стартап, друзья позвали.\n— Рискованно, но уважаю такое решение.', zh: '——方便透露你去哪儿吗？\n——去一家创业公司，朋友拉我去的。\n——有点冒险，但我佩服这个决定。', en: '— Where are you moving to, if it’s not a secret?\n— To a startup; friends invited me.\n— Risky, but I respect the decision.', ctx: '离职交接' },
  { ru: 'Все дела переданы, папки разобраны, почта перенаправлена.', zh: '所有工作已交接，文件已整理，邮件已转接。', en: 'All duties are handed over, folders sorted, mail forwarded.', ctx: '离职交接' },
  { ru: '— Не забудь сдать пропуск в конце дня.\n— Помню, уже договорился с охраной.', zh: '——下班前别忘了交门禁卡。\n——记得，已经跟保安说好了。', en: '— Don’t forget to return your badge at the end of the day.\n— I remember; I’ve already arranged it with security.', ctx: '离职交接' },
  { ru: '— Спасибо вам всем за эти годы!\n— Это тебе спасибо, ты многому нас научил.', zh: '——谢谢大家这些年的关照！\n——该我们谢你，你教会了我们很多。', en: '— Thank you all for these years!\n— Thank you — you taught us a lot.', ctx: '离职交接' },
  { ru: '— Сегодня твой последний день, как настроение?\n— Грустно и радостно одновременно.\n— Заглядывай к нам на чай!', zh: '——今天是你的最后一天，心情如何？\n——又难过又开心。\n——常回来坐坐！', en: '— Today is your last day, how do you feel?\n— Sad and happy at the same time.\n— Drop by for tea sometime!', ctx: '离职交接' },
  { ru: '— Останешься на связи?\n— Конечно! Пишите, всегда помогу советом.', zh: '——以后会保持联系吗？\n——当然！随时留言，我一定给建议。', en: '— Will you stay in touch?\n— Of course! Write anytime, I’ll always help with advice.', ctx: '离职交接' },
  { ru: 'Если бы не семейные обстоятельства, я бы остался.', zh: '要不是家庭原因，我会留下来的。', en: 'If it weren’t for family circumstances, I would have stayed.', ctx: '离职交接' },
  { ru: '— Мой преемник уже в курсе всех текущих задач.\n— Значит, переход будет гладким.', zh: '——我的继任者已经了解所有在办事项。\n——那交接会很顺利。', en: '— My successor is already up to speed on all current tasks.\n— Then the transition will be smooth.', ctx: '离职交接' },
  { ru: 'Меня слышно? Кажется, микрофон барахлит.', zh: '听得到我吗？麦克风好像出问题了。', en: 'Can you hear me? My microphone seems to be acting up.', ctx: '远程办公' },
  { ru: '— У тебя сейчас который час?\n— Вечер, разница с тобой пять часов.', zh: '——你那边现在几点？\n——晚上了，跟你差五个小时。', en: '— What time is it at your place now?\n— Evening; I’m five hours behind you.', ctx: '远程办公' },
  { ru: '— Ты мой экран видишь?\n— Вижу, но презентация не развёрнута.\n— Секунду, сейчас исправлю.', zh: '——你能看到我的屏幕吗？\n——能，但幻灯片没有全屏。\n——稍等，我马上弄好。', en: '— Can you see my screen?\n— Yes, but the presentation isn’t fullscreen.\n— One second, I’ll fix it now.', ctx: '远程办公' },
  { ru: '— Почему тебя не было на созвоне?\n— Интернет упал, подключался с телефона.', zh: '——你怎么没参加电话会？\n——网断了，我在用手机接入。', en: '— Why weren’t you on the call?\n— My internet went down; I was joining from my phone.', ctx: '远程办公' },
  { ru: '— Связь ужасная, ты пропадаешь.\n— Перезвоню через минуту, перейду к окну.\n— Так гораздо лучше слышно.', zh: '——信号太差，你声音断断续续的。\n——我走到窗边，一分钟后给你回拨。\n——现在清楚多了。', en: '— The connection is terrible, you’re breaking up.\n— I’ll call back in a minute from the window.\n— Much clearer now.', ctx: '远程办公' },
  { ru: '— Включи камеру, пожалуйста.\n— Секунду, только приведу себя в порядок.', zh: '——请打开摄像头。\n——稍等，我先整理一下仪容。', en: '— Please turn on your camera.\n— One moment, let me make myself presentable.', ctx: '远程办公' },
  { ru: 'Давайте общаться асинхронно, чтобы не будить коллег в других часовых поясах.', zh: '我们改成异步沟通吧，免得吵醒其他时区的同事。', en: 'Let’s communicate asynchronously so we don’t wake colleagues in other time zones.', ctx: '远程办公' },
  { ru: '— Во сколько завтра стендап?\n— Как обычно, в 10:00 по Москве.\n— Тогда я подключусь пораньше.', zh: '——明天站会几点？\n——老时间，莫斯科时间十点。\n——那我提前上线。', en: '— What time is standup tomorrow?\n— As usual, 10:00 Moscow time.\n— Then I’ll join a bit earlier.', ctx: '远程办公', say: '— Во сколько завтра стендап?\n— Как обычно, в десять ноль-ноль по Москве.\n— Тогда я подключусь пораньше.' },
  { ru: '— Если ответ не горит, пиши в чат, а не звони.\n— Понял, буду писать.', zh: '——不急的事就发消息，别打电话。\n——明白，我以后发消息。', en: '— If it’s not urgent, write in the chat instead of calling.\n— Got it, I’ll write.', ctx: '远程办公' },
  { ru: '— Ты часто работаешь из дома?\n— Три дня в неделю, остальное — из офиса.', zh: '——你经常在家办公吗？\n——一周三天，其余时间去公司。', en: '— Do you often work from home?\n— Three days a week, the rest from the office.', ctx: '远程办公' },
  { ru: 'VPN снова отключился, не могу зайти на сервер тестирования.', zh: 'VPN又断了，我连不上测试服务器。', en: 'The VPN disconnected again; I can’t access the test server.', ctx: '远程办公', say: 'Ви-пи-эн снова отключился, не могу зайти на сервер тестирования.' },
  { ru: '— Включи режим «не беспокоить», я записываю скринкаст.\n— Хорошо, напишу, когда освободишься.', zh: '——开启勿扰模式，我在录屏。\n——好，等你忙完我再发消息。', en: '— Turn on Do Not Disturb, I’m recording a screencast.\n— Okay, I’ll message you when you’re free.', ctx: '远程办公' },
  { ru: 'Теперь вся документация хранится в облаке, и я могу работать из любого места.', zh: '现在所有文档都在云端，我可以从任何地方办公。', en: 'Now all documentation is in the cloud, and I can work from anywhere.', ctx: '远程办公' },
  { ru: '— Почему ты не отвечал на письма сегодня утром?\n— Я был в ко-воркинге, не видел уведомлений.', zh: '——为什么你今早没回邮件？\n——我在共享办公空间，没看到通知。', en: '— Why didn’t you reply to emails this morning?\n— I was in a coworking space and didn’t see notifications.', ctx: '远程办公' },
  { ru: '— Какой Wi-Fi в твоём доме по скорости?\n— Загрузка около 100 Мбит/с, нормально для видеозвонков.', zh: '——你家Wi-Fi速度怎么样？\n——下载大概100兆，视频通话没问题。', en: '— How fast is your home Wi-Fi?\n— Download is about 100 Mbps, fine for video calls.', ctx: '远程办公', say: '— Какой Вай-Фай в твоём доме по скорости?\n— Загрузка около ста мегабит в секунду, нормально для видеозвонков.' },
  { ru: '— Ваш рейс прибыл?\n— Да, вылет был из Шереметьево, приземлились вовремя.', zh: '——您航班到了吗？\n——到了，从谢列梅捷沃出发，准时降落。', en: '— Has your flight arrived?\n— Yes, the flight was from Sheremetyevo and landed on time.', ctx: '商务接待' },
  { ru: '— Добро пожаловать! Как прошёл перелёт?\n— Спасибо, довольно комфортно, несмотря на задержку.', zh: '——欢迎光临！旅途还顺利吗？\n——谢谢，虽然晚点但还算舒适。', en: '— Welcome! How was the flight?\n— Thanks, quite comfortable despite the delay.', ctx: '商务接待' },
  { ru: '— Это наш производственный цех, площадь 2 000 м².\n— Впечатляет, сколько здесь сотрудников?\n— Сейчас около 120.', zh: '——这是我们的生产车间，面积2000平方米。\n——真壮观，这里有多少人？\n——现在大约120人。', en: '— This is our production floor, area 2,000 m².\n— Impressive; how many employees are here?\n— About 120 now.', ctx: '商务接待', say: '— Это наш производственный цех, площадь две тысячи квадратных метров.\n— Впечатляет, сколько здесь сотрудников?\n— Сейчас около ста двадцати.' },
  { ru: '— Готовы ли вы к подписанию соглашения?\n— Да, юристы всё сверили, можно начинать.', zh: '——您准备好签署协议了吗？\n——准备好了，律师都核对过了，可以开始。', en: '— Are you ready to sign the agreement?\n— Yes, the lawyers have checked everything; we can start.', ctx: '商务接待' },
  { ru: '— Завтра проводим вас в аэропорт.\n— Не стоит, я сам доберусь на такси.\n— Как хотите, но мы останемся на связи.', zh: '——明天我们送您去机场。\n——不用麻烦了，我自己打车去。\n——随您，但我们会保持联系。', en: '— Tomorrow we’ll escort you to the airport.\n— No need; I’ll get there by taxi myself.\n— As you wish, but we’ll stay in touch.', ctx: '商务接待' },
  { ru: 'Позвольте предложить вам место рядом с директором.', zh: '请允许我安排您坐在总监旁边。', en: 'Allow me to offer you a seat next to the director.', ctx: '商务接待' },
  { ru: '— Сколько человек будет на ужине?\n— Десять, включая вашу делегацию и наших партнёров.\n— Замечательно, накроем стол.', zh: '——晚宴一共几位？\n——十位，包括贵方代表团和我方合作伙伴。\n——太好了，我们这就安排。', en: '— How many people will there be at dinner?\n— Ten, including your delegation and our partners.\n— Wonderful, we’ll set the table.', ctx: '商务接待' },
  { ru: 'Экскурсия займёт примерно полчаса, после — трансфер в гостиницу.', zh: '参观大约需要半小时，之后送您去酒店。', en: 'The tour will take about half an hour, then a transfer to the hotel.', ctx: '商务接待' },
  { ru: '— Есть ли культурные особенности, о которых стоит помнить?\n— Да, не начинайте переговоры до обмена визитками.', zh: '——有什么文化细节需要注意吗？\n——有，交换名片前不要进入正题。', en: '— Are there cultural nuances to keep in mind?\n— Yes, don’t start negotiations before exchanging business cards.', ctx: '商务接待' },
  { ru: '— На счёт, пожалуйста!\n— Это наш банкет, вам не стоит платить.', zh: '——买单！\n——这是我们做东，不用您破费。', en: '— Check, please!\n— This is our banquet; you don’t need to pay.', ctx: '商务接待' },
  { ru: '— Как вам наш город?\n— Очень зелёный и удобный для бизнеса.', zh: '——您觉得我们城市怎么样？\n——很绿化，也很适合做生意。', en: '— What do you think of our city?\n— Very green and business-friendly.', ctx: '商务接待' },
  { ru: '— Я привёз вам сувениры из нашей страны.\n— Спасибо, это очень мило с вашей стороны!\n— Надеюсь, вам понравится.', zh: '——我给您带了我国的纪念品。\n——谢谢，您太有心了！\n——希望您喜欢。', en: '— I brought you souvenirs from my country.\n— Thank you, that’s very kind of you!\n— I hope you like them.', ctx: '商务接待' },
  { ru: 'Давайте отметим успешное партнёрство бокалом шампанского!', zh: '让我们用一杯香槟庆祝合作成功！', en: 'Let’s celebrate our successful partnership with a glass of champagne!', ctx: '商务接待' },
  { ru: 'Договор подписан в двух экземплярах, один — вам.', zh: '协议一式两份，这份是您的。', en: 'The contract is signed in two copies; one is yours.', ctx: '商务接待' },
  { ru: '— Проводим вас до самолёта, не беспокойтесь о трансфере.\n— Спасибо, с вами всё так просто.', zh: '——我们会送您到登机口，交通的事不用担心。\n——谢谢，跟你们合作一切都这么顺利。', en: '— We’ll see you off to the plane; don’t worry about the transfer.\n— Thanks, everything is so easy with you.', ctx: '商务接待' },
  { ru: 'Я устал от ежедневных переработок.', zh: '我厌倦了每天加班。', en: 'I’m tired of overtime every single day.', ctx: '工作压力' },
  { ru: '— Сколько часов ты вчера просидел?\n— До 22:00, и я снова на ногах в 7:00.', zh: '——你昨晚坐到几点？\n——晚上10点，然后早上7点又要爬起来。', en: '— How many hours did you sit yesterday?\n— Until 22:00, and I’m on my feet again at 7:00.', ctx: '工作压力', say: '— Сколько часов ты вчера просидел?\n— До двадцати двух ноль-ноль, и я снова на ногах в семь ноль-ноль.' },
  { ru: '— Ты в порядке? Выглядишь измотанным.\n— Просто не выспался, ничего серьёзного.', zh: '——你还好吗？看起来精疲力竭。\n——就是没睡好，没什么大碍。', en: '— Are you okay? You look exhausted.\n— Just didn’t sleep well; nothing serious.', ctx: '工作压力' },
  { ru: '— Можно взять отгул в пятницу?\n— Ты уже использовал все отпускные дни.', zh: '——周五能调休一天吗？\n——你已经用完所有年假了。', en: '— Can I take a day off on Friday?\n— You’ve already used all your vacation days.', ctx: '工作压力' },
  { ru: '— Почему ты снова на работе в выходной?\n— Дедлайн горит, иначе срываем сдачу.\n— Не забывай про отдых, работа не убежит.', zh: '——你怎么又在周末来上班了？\n——截止日期火烧眉毛，不赶完就交不上了。\n——别忘了休息，工作跑不了。', en: '— Why are you at work on a weekend again?\n— The deadline is burning; otherwise we’ll miss delivery.\n— Don’t forget to rest; work isn’t going anywhere.', ctx: '工作压力' },
  { ru: '— Мне нужен отпуск, я на грани выгорания.\n— Согласуй с руководителем и уходи в ближайшую пятницу.', zh: '——我需要休假，快撑不住了。\n——去跟主管协调一下，这周五就走。', en: '— I need a vacation; I’m on the verge of burnout.\n— Coordinate with your manager and leave this Friday.', ctx: '工作压力' },
  { ru: '— Сколько у тебя осталось рабочих часов в этом месяце?\n— Переработал уже на 15 часов.', zh: '——这个月你还有多少工时？\n——已经加班15小时了。', en: '— How many working hours do you have left this month?\n— I’ve already worked 15 hours overtime.', ctx: '工作压力', say: '— Сколько у тебя осталось рабочих часов в этом месяце?\n— Переработал уже на пятнадцать часов.' },
  { ru: '— Что ты делаешь для баланса работы и жизни?\n— Бегаю по утрам и не проверяю почту после 21:00.', zh: '——你怎么平衡工作和生活？\n——早上跑步，晚上9点后不看邮件。', en: '— What do you do for work-life balance?\n— I run in the mornings and don’t check email after 21:00.', ctx: '工作压力', say: '— Что ты делаешь для баланса работы и жизни?\n— Бегаю по утрам и не проверяю почту после двадцати одного ноль-ноль.' },
  { ru: '— Сколько выходных тебе одобрили?\n— Три дня, но с условием быть на связи.', zh: '——批了你几天假？\n——三天，但条件是要保持联系。', en: '— How many days off did they approve?\n— Three days, but with the condition of staying reachable.', ctx: '工作压力' },
  { ru: 'Не могу поверить, что у меня мигрень из-за стресса на работе.', zh: '真不敢相信我因为工作压力大到偏头痛。', en: 'I can’t believe I have a migraine from work stress.', ctx: '工作压力' },
  { ru: '— Давай раз в неделю ходить на йогу вместе.\n— Хорошая идея, надо сбросить напряжение.', zh: '——我们每周一起去练瑜伽吧。\n——好主意，得释放一下压力。', en: '— Let’s do yoga together once a week.\n— Good idea; we need to release the tension.', ctx: '工作压力' },
  { ru: '— Тебе одобрили удалёнку на время болезни?\n— Да, но придётся оформить больничный.', zh: '——你生病期间获批远程办公了吗？\n——批了，但得办病假条。', en: '— Did they approve remote work while you’re sick?\n— Yes, but I’ll have to file a sick leave.', ctx: '工作压力' },
  { ru: 'Я уже забыл, когда последний раз уходил с работы до заката.', zh: '我已经忘了上次在天黑前下班是什么时候了。', en: 'I’ve already forgotten the last time I left work before sunset.', ctx: '工作压力' },
  { ru: '— Возьмите выходной, вы его заслужили.\n— Спасибо, так и сделаю.', zh: '——放一天假吧，这是你应得的。\n——谢谢，就这么办。', en: '— Take a day off; you’ve earned it.\n— Thanks, I will.', ctx: '工作压力' },
  { ru: 'Новые правила: запрещается отвечать на рабочие письма после 20:00.', zh: '新规定：晚上8点后禁止回复工作邮件。', en: 'New rule: replying to work emails after 20:00 is prohibited.', ctx: '工作压力', say: 'Новые правила: запрещается отвечать на рабочие письма после двадцати ноль-ноль.' },
  { ru: '— Я получил повышение!\n— Поздравляю! Какой теперь грейд?\n— Senior, с зарплатой на 30% выше.', zh: '——我升职了！\n——恭喜！现在是什么级别？\n——高级，工资涨了30%。', en: '— I got promoted!\n— Congratulations! What’s your new grade?\n— Senior, with a salary 30% higher.', ctx: '职业发展', say: '— Я получил повышение!\n— Поздравляю! Какой теперь грейд?\n— Синьор, с зарплатой на тридцать процентов выше.' },
  { ru: '— Почему ты решил сменить направление?\n— Хочу перейти из маркетинга в data science.\n— Амбициозно, но с нуля будет сложно.', zh: '——你为什么决定转型？\n——我想从营销转到数据科学。\n——有野心，但从零开始不容易。', en: '— Why did you decide to change direction?\n— I want to move from marketing to data science.\n— Ambitious, but starting from scratch will be hard.', ctx: '职业发展', say: '— Почему ты решил сменить направление?\n— Хочу перейти из маркетинга в дата сайенс.\n— Амбициозно, но с нуля будет сложно.' },
  { ru: '— Какие курсы ты сейчас проходишь?\n— Изучаю Python и SQL для аналитики.', zh: '——你现在在上什么课？\n——在学Python和SQL，为了做数据分析。', en: '— What courses are you taking now?\n— I’m learning Python and SQL for analytics.', ctx: '职业发展', say: '— Какие курсы ты сейчас проходишь?\n— Изучаю Пайтон и эс-кю-эл для аналитики.' },
  { ru: '— Кто твой ментор?\n— Старший инженер с 12-летним опытом в отрасли.\n— Повезло, у него много чему поучиться.', zh: '——你的导师是谁？\n——一位在行业里干了12年的高级工程师。\n——运气不错，他能教你的很多。', en: '— Who is your mentor?\n— A senior engineer with 12 years in the industry.\n— Lucky; he has a lot to teach you.', ctx: '职业发展', say: '— Кто твой ментор?\n— Старший инженер с двенадцатилетним опытом в отрасли.\n— Повезло, у него много чему поучиться.' },
  { ru: '— Куда ты хочешь расти в этой компании?\n— В идеале — стать руководителем подразделения за 3 года.', zh: '——你在这家公司想往哪发展？\n——理想情况下，3年内成为部门负责人。', en: '— Where do you want to grow in this company?\n— Ideally, become a department head in 3 years.', ctx: '职业发展', say: '— Куда ты хочешь расти в этой компании?\n— В идеале — стать руководителем подразделения за три года.' },
  { ru: 'Прохожу сертификацию AWS, экзамен через месяц.', zh: '我正在考AWS认证，一个月后考试。', en: 'I’m taking the AWS certification; the exam is in a month.', ctx: '职业发展', say: 'Прохожу сертификацию эй-дабл-ю-эс, экзамен через месяц.' },
  { ru: '— Тебе одобрили бюджет на конференцию?\n— Да, но покрывают только билет и отель.', zh: '——你的参会预算批下来了吗？\n——批了，但只报销机票和酒店。', en: '— Did they approve your conference budget?\n— Yes, but they only cover the ticket and hotel.', ctx: '职业发展' },
  { ru: '— Какой самый полезный навык, который ты приобрёл за год?\n— Умение вести переговоры на английском.', zh: '——过去一年你学到的最有用的技能是什么？\n——用英语谈判的能力。', en: '— What’s the most useful skill you gained this year?\n— The ability to negotiate in English.', ctx: '职业发展' },
  { ru: 'Мой план — освоить управление продуктом и вырасти до VP.', zh: '我的计划是掌握产品管理，做到副总裁级别。', en: 'My plan is to master product management and grow to VP.', ctx: '职业发展', say: 'Мой план — освоить управление продуктом и вырасти до ви-пи.' },
  { ru: '— Предлагаю встречаться с ментором раз в месяц.\n— Хорошо, главное — готовить заранее вопросы.', zh: '——我建议每个月和导师见一次。\n——可以，关键是提前准备好问题。', en: '— I suggest meeting with the mentor once a month.\n— Fine; the main thing is to prepare questions in advance.', ctx: '职业发展' },
  { ru: '— Ты получил повышение или это перевод?\n— Формально перевод, но зарплата выросла.', zh: '——你这是晋升还是调动？\n——名义上是调动，但薪水涨了。', en: '— Did you get promoted or is it a transfer?\n— Formally a transfer, but the salary increased.', ctx: '职业发展' },
  { ru: '— Сколько времени занимает твой commute?\n— Два часа в один конец, из-за этого и ушёл в удалёнку.', zh: '——你通勤要多久？\n——单程两小时，这就是我为什么转远程了。', en: '— How long is your commute?\n— Two hours one way; that’s why I switched to remote.', ctx: '职业发展', say: '— Сколько времени занимает твой коммьют?\n— Два часа в один конец, из-за этого и ушёл в удалёнку.' },
  { ru: '— Какие книги посоветуешь по leadership?\n— «Hard Things about Hard Things» и «Radical Candor».', zh: '——关于领导力有什么书推荐？\n——《创业维艰》和《绝对坦率》。', en: '— What books on leadership do you recommend?\n— “Hard Things about Hard Things” and “Radical Candor.”', ctx: '职业发展', say: '— Какие книги посоветуешь по лидерству?\n— «Хард тингз эбаут хард тингз» и «Рэдикал кандор».' },
  { ru: '— Насколько сложен был переход из backend в frontend?\n— Пришлось освоить React и TypeScript за полгода.', zh: '——从后端转前端难吗？\n——得在半年内学会React和TypeScript。', en: '— How difficult was the switch from backend to frontend?\n— I had to pick up React and TypeScript in half a year.', ctx: '职业发展', say: '— Насколько сложен был переход из бэкенд во фронтенд?\n— Пришлось освоить Реакт и Тайпскрипт за полгода.' },
  { ru: '— Планируешь ли ты MBA?\n— Думаю, но только если компания оплатит половину.', zh: '——你打算读MBA吗？\n——在考虑，但前提是公司报销一半。', en: '— Are you planning to do an MBA?\n— Thinking about it, but only if the company pays half.', ctx: '职业发展', say: '— Планируешь ли ты эм-би-эй?\n— Думаю, но только если компания оплатит половину.' },
]

// ── 情感表达 / Emotions / Эмоции ──
const EMOTION: Phrase[] = [
  { ru: 'Ура! Наконец-то наступили каникулы, и мы завтра едем на море!', zh: '万岁！终于放假了，我们明天去海边！', en: 'Hooray! The holidays have finally begun and tomorrow we\'re off to the sea!', ctx: '放假去海边' },
  { ru: 'Я так счастлива, что просто хочется обнять весь мир.', zh: '我太幸福了，简直想拥抱整个世界。', en: 'I\'m so happy I just want to hug the whole world.', ctx: '感到无比幸福' },
  { ru: 'Ты уже слышал, что нас выбрали для стажировки в Париже?', zh: '你听说了吗，我们被选上去巴黎实习了？', en: 'Have you heard that we\'ve been chosen for the internship in Paris?', ctx: '得知实习录取' },
  { ru: 'Вот это новость! Не могу в это поверить!', zh: '这消息太棒了！我简直不敢相信！', en: 'What news! I can\'t believe it!', ctx: '听到好消息' },
  { ru: 'Моей сестре сегодня исполнилось 18 лет, и она прыгает от радости.', zh: '我妹妹今天满18岁，高兴得蹦了起来。', en: 'My sister turned 18 today and she\'s jumping for joy.', ctx: '妹妹十八岁生日', say: 'Моей сестре сегодня исполнилось восемнадцать лет, и она прыгает от радости.' },
  { ru: '— Представляешь, мне повысили зарплату!\n— Да ладно! Поздравляю, ты это заслужила.', zh: '—你猜怎么着，我涨工资了！—不会吧！恭喜你，这是你应得的。', en: '—Imagine, I got a raise! —No way! Congratulations, you earned it.', ctx: '涨工资喜讯' },
  { ru: '— Ну как, понравился тебе сюрприз?\n— Ещё как! Я даже расплакалась от радости.', zh: '—怎么样，喜欢这个惊喜吗？—太喜欢了！我都高兴哭了。', en: '—Well, did you like the surprise? —Did I ever! I even cried with joy.', ctx: '惊喜派对反应' },
  { ru: '— Мы выиграли грант на полмиллиона!\n— Не может быть! Это же победа, ребята!', zh: '—我们赢得了五十万拨款！—不可能！这可是胜利啊，伙计们！', en: '—We won a grant for half a million! —No way! That\'s a victory, guys!', ctx: '团队赢得拨款' },
  { ru: '— Смотри, какая радуга над рекой!\n— Какая красота! Давай скорее фотографировать.', zh: '—看，河面上的彩虹多美！—太美了！我们快拍照吧。', en: '—Look at that rainbow over the river! —How beautiful! Let\'s take photos quickly.', ctx: '看见彩虹' },
  { ru: '— Если бы ты только видел его лицо, когда он получил подарок!\n— Наверное, он был на седьмом небе?', zh: '—你真该看看他收到礼物时的表情！—他肯定乐坏了吧？', en: '—If only you\'d seen his face when he got the present! —I bet he was on cloud nine, wasn\'t he?', ctx: '聊礼物惊喜' },
  { ru: '— Слушай, я только что узнала: я беременна!\n— Правда? Вот это счастье! Поздравляю вас обоих!', zh: '—听我说，我刚知道：我怀孕了！—真的吗？太幸福了！恭喜你们俩！', en: '—Listen, I just found out: I\'m pregnant! —Really? That\'s such wonderful news! Congratulations to you both!', ctx: '宣布怀孕' },
  { ru: '— Узнал ли ты уже результаты конкурса?\n— Да! Я занял первое место, сам до сих пор не верю.', zh: '—你知道比赛结果了吗？—知道了！我拿了第一名，自己到现在都不敢相信。', en: '—Have you found out the competition results yet? —Yes! I took first place, I still can\'t believe it myself.', ctx: '比赛出结果' },
  { ru: '— Мама, я поступил!\n— Как? Правда поступил?\n— Да, вот письмо из университета!\n— Дай я тебя обниму, сынок, я так тобой горжусь!', zh: '—妈，我考上了！—什么？真的考上了？—真的，这是大学的录取通知！—让妈抱抱你，儿子，我真为你骄傲！', en: '—Mom, I got in! —What? You really got in? —Yes, here\'s the letter from the university! —Let me hug you, son, I\'m so proud of you!', ctx: '收到录取通知' },
  { ru: '— Он сделал мне предложение!\n— Серьёзно? Когда?\n— Вчера вечером, на крыше, с кольцом и цветами!', zh: '—他向我求婚了！—真的吗？什么时候？—昨天晚上，在屋顶，还带着戒指和鲜花！', en: '—He proposed! —Seriously? When? —Last night, on the rooftop, with a ring and flowers!', ctx: '被求婚惊喜' },
  { ru: '— Алло, это ты? Не узнал?\n— Нет, не узнаю... Неужели Катя?\n— Она самая! Я вернулась из экспедиции, встречай меня в 19:00 на вокзале!', zh: '—喂，是你吗？猜不出？—猜不出……难道是卡佳？—正是！我考察回来了，晚上七点来火车站接我！', en: '—Hello, is that you? Don\'t you recognize me? —No, I don\'t... Can it be Katya? —It is! I\'m back from the expedition, meet me at the station at 7 PM!', ctx: '老友归来', say: '— Алло, это ты? Не узнал?\n— Нет, не узнаю... Неужели Катя?\n— Она самая! Я вернулась из экспедиции, встречай меня в девятнадцать часов на вокзале!' },
  { ru: 'Мне так грустно сегодня, что даже любимый чай не радует.', zh: '我今天特别难过，连最喜欢的茶都让人高兴不起来。', en: 'I feel so sad today that even my favorite tea doesn\'t cheer me up.', ctx: '莫名心情低落' },
  { ru: 'Он уехал, и в квартире вдруг стало тихо и пусто.', zh: '他走了，屋里一下子变得又安静又空荡。', en: 'He left, and the apartment suddenly felt quiet and empty.', ctx: '离别后的空落' },
  { ru: 'Как же больно терять тех, кого любишь!', zh: '失去所爱的人是多么痛苦啊！', en: 'How painful it is to lose those you love!', ctx: '失去挚爱之痛' },
  { ru: 'Почему хорошие дни всегда пролетают так быстро?', zh: '为什么美好的日子总是过得这么快？', en: 'Why do good days always fly by so fast?', ctx: '好时光易逝' },
  { ru: 'Я не плачу, просто что-то попало в глаз.', zh: '我没哭，就是眼睛里进东西了。', en: 'I\'m not crying, something just got in my eye.', ctx: '强忍眼泪' },
  { ru: '— Ты чего такая печальная?\n— Бабушка заболела, и я очень за неё переживаю.', zh: '—你怎么这么难过？—奶奶病了，我特别担心她。', en: '—Why are you so sad? —Grandma is sick and I\'m really worried about her.', ctx: '担心生病的奶奶' },
  { ru: '— Мы расстались.\n— Вот как... Мне очень жаль, держись там.', zh: '—我们分手了。—这样啊……我很遗憾，你要撑住。', en: '—We broke up. —I see... I\'m so sorry, hang in there.', ctx: '告诉朋友分手' },
  { ru: '— Слушай, не хочешь поговорить о том, что случилось?\n— Не сейчас. Мне надо побыть одному.', zh: '—听我说，不想聊聊发生了什么吗？—现在不想，我想一个人待会儿。', en: '—Listen, don\'t you want to talk about what happened? —Not now. I need to be alone.', ctx: '想独自消化' },
  { ru: '— Я провалил экзамен, который готовил полгода.\n— Ну ничего, бывает. Ты же сможешь пересдать, верно?', zh: '—准备了半年的考试我没通过。—没事的，这种事难免。你可以重考，对吧？', en: '—I failed the exam I prepared for six months. —Well, it happens. You can retake it, right?', ctx: '考试失利诉苦' },
  { ru: '— Неужели ты даже не скучаешь по нашим вечерам?\n— Скучаю, просто не хочу это показывать.', zh: '—难道你一点都不想念我们一起的夜晚吗？—想念，只是不想表现出来。', en: '—Don\'t you even miss our evenings together? —I do, I just don\'t want to show it.', ctx: '旧情难忘' },
  { ru: '— Этот фильм всегда заставляет меня реветь.\n— Меня тоже, особенно концовка.', zh: '—这部电影总让我哭。—我也是，尤其是结局。', en: '—This movie always makes me bawl. —Me too, especially the ending.', ctx: '看电影落泪' },
  { ru: '— Кажется, дождь сегодня целый день, как назло.\n— Да, под такую погоду только и взгрустнётся.', zh: '—这雨好像故意似的下了一整天。—是啊，这种天气就容易伤感。', en: '—It seems to have been raining all day, as if on purpose. —Yeah, weather like this just makes you sad.', ctx: '阴雨天伤怀' },
  { ru: '— Почему ты плачешь? Кто тебя обидел?\n— Никто... просто всё сразу навалилось.\n— Иди сюда, давай обниму. Хочешь, останусь сегодня у тебя?', zh: '—你怎么哭了？谁欺负你了？—没人……就是所有事一下子压过来。—过来，让我抱抱你。要不我今晚陪你？', en: '—Why are you crying? Who hurt you? —No one... it\'s just all piled up at once. —Come here, let me give you a hug. Want me to stay at yours tonight?', ctx: '崩溃被安慰' },
  { ru: '— Ты читал сообщение? Собаку усыпили.\n— Читал... Бедный Бим, он прожил у нас 12 лет.\n— Я до сих пор не могу заходить в комнату, где стояла его подстилка.\n— Понимаю. Давай завтра съездим к тебе вместе.', zh: '—你看到消息了吗？狗被安乐死了。—看到了……可怜的比姆，它在我们家住了12年。—我到现在都不敢走进放它垫子的房间。—我理解。明天我陪你回去一趟吧。', en: '—Did you read the message? They put the dog to sleep. —I did... Poor Bim, he lived with us for 12 years. —I still can\'t go into the room where his mat was. —I understand. Let me come over with you tomorrow.', ctx: '宠物离世', say: '— Ты читал сообщение? Собаку усыпили.\n— Читал... Бедный Бим, он прожил у нас двенадцать лет.\n— Я до сих пор не могу заходить в комнату, где стояла его подстилка.\n— Понимаю. Давай завтра съездим к тебе вместе.' },
  { ru: '— Алло, папа... маме ночью вызвали скорую.\n— Что с ней? Она в больнице?\n— Да, сердце. Мне так страшно, приезжай скорее.', zh: '—喂，爸……妈夜里叫了急救车。—她怎么了？住院了吗？—嗯，心脏的问题。我好害怕，你快回来。', en: '—Dad... they called an ambulance for Mom last night. —What\'s wrong with her? Is she in hospital? —Yes, her heart. I\'m so scared, come quickly.', ctx: '母亲突发急病' },
  { ru: 'Меня бесит, когда люди опаздывают и даже не пишут.', zh: '我最烦别人迟到还连个消息都不发。', en: 'It infuriates me when people are late and don\'t even text.', ctx: '厌恶迟到不告知' },
  { ru: 'Это уже слишком! Я больше не намерен это терпеть!', zh: '这太过分了！我不打算再忍了！', en: 'This is too much! I\'m not going to put up with it anymore!', ctx: '忍无可忍' },
  { ru: 'Сколько можно повторять одно и то же?', zh: '同一件事还要说多少遍？', en: 'How many times must I repeat the same thing?', ctx: '反复叮嘱无效' },
  { ru: 'Если он ещё раз меня перебьёт, я просто выйду из комнаты.', zh: '他要是再打断我一次，我就直接走出房间。', en: 'If he interrupts me once more, I\'ll just walk out of the room.', ctx: '被打断的怒火' },
  { ru: 'Я в ярости: мою идею выдали за свою на совещании.', zh: '我气坏了：我的点子在会上被人据为己有。', en: 'I\'m furious: my idea was passed off as someone else\'s at the meeting.', ctx: '功劳被窃取' },
  { ru: '— Ты почему на меня кричишь?\n— Потому что ты опять всё сделал по-своему!', zh: '—你冲我喊什么？—因为你又自作主张了！', en: '—Why are you yelling at me? —Because you did everything your own way again!', ctx: '争吵质问' },
  { ru: '— Слушай, этот тип занял наше место.\n— Вот нахал! Пойди разберись с ним сам.', zh: '喂，那家伙占了我们的位置。—真无耻！你自己去找他理论。', en: '—Listen, that guy took our seats. —What a cheek! Go sort it out with him yourself.', ctx: '位置被占' },
  { ru: '— Ну что, опять сломал мой ноутбук?\n— Я не виноват, он сам выключился!', zh: '—怎么，又把我笔记本弄坏了？—不怪我，它自己关机的！', en: '—So, did you break my laptop again? —It\'s not my fault, it turned itself off!', ctx: '弄坏东西抵赖' },
  { ru: '— Как ты могла прочитать мой дневник?\n— Я случайно, честное слово!', zh: '—你怎么能看我的日记？—我是不小心的，我发誓！', en: '—How could you read my diary? —It was an accident, I swear!', ctx: '隐私被侵犯' },
  { ru: '— Отдаёшь ли ты себе отчёт в том, что наделал?\n— Отдаю, и мне уже стыдно.', zh: '—你明白自己闯了什么祸吗？—明白，我已经很惭愧了。', en: '—Do you realize what you\'ve done? —I do, and I\'m already ashamed.', ctx: '质问闯祸者' },
  { ru: '— Официант уже полчаса нас не замечает.\n— Это просто возмутительно! Позови менеджера.', zh: '—服务员半小时都不理我们。—太不像话了！把经理叫来。', en: '—The waiter has been ignoring us for half an hour. —That\'s outrageous! Call the manager.', ctx: '餐厅服务差' },
  { ru: '— Смотри, кто-то поцарапал нашу машину и уехал.\n— Чёрт возьми! Ну что за люди такие!', zh: '—看，有人刮了我们的车就跑了。—该死！怎么有这种人！', en: '—Look, someone scratched our car and drove off. —Damn it! What is wrong with people!', ctx: '车被刮蹭逃逸' },
  { ru: '— Где ты был? Я звонила тебе десять раз!\n— Ну не кричи, телефон сел...\n— Не смей со мной так разговаривать!\n— Прости, я виноват, давай без скандала.', zh: '—你去哪儿了？我给你打了十个电话！—别喊，手机没电了……—你竟敢这么跟我说话！—对不起，是我的错，咱别吵了。', en: '—Where were you? I called you ten times! —Don\'t shout, the phone died... —Don\'t you dare talk to me like that! —Sorry, it\'s my fault, let\'s not have a scene.', ctx: '深夜未归争吵' },
  { ru: '— Мне отказали без всяких объяснений.\n— Это несправедливо, ты лучший кандидат!\n— Вот именно, и взяли какого-то племянника директора.', zh: '—他们没给任何理由就拒绝了我。—这不公平，你才是最合适的人选！—可不是嘛，结果录用了老板的什么侄子。', en: '—They turned me down without any explanation. —That\'s unfair, you\'re the best candidate! —Exactly, and they hired some nephew of the director\'s.', ctx: '求职遭遇不公' },
  { ru: '— Опять ты трогал мои документы?\n— Я только переложил их на стол.\n— Я их час искала! Не смей больше ничего трогать в моём кабинете!', zh: '—你又动我文件了？—我只是把它们放到桌上了。—我找了一个小时！以后不许再碰我办公室里的任何东西！', en: '—Did you touch my documents again? —I only moved them onto the desk. —I spent an hour looking for them! Don\'t you dare touch anything in my office again!', ctx: '文件被乱动' },
  { ru: 'Я так волнуюсь перед собеседованием, что ночью почти не спал.', zh: '面试前我紧张得一夜几乎没睡着。', en: 'I\'m so nervous about the interview that I barely slept last night.', ctx: '面试前夜失眠' },
  { ru: 'Сердце колотится, будто вот-вот выпрыгнет из груди.', zh: '心怦怦直跳，好像马上要从胸口蹦出来。', en: 'My heart is pounding as if it\'s about to jump out of my chest.', ctx: '心跳加速紧张' },
  { ru: 'А вдруг я забуду все слова, когда выйду на сцену?', zh: '万一上台后我把台词全忘了怎么办？', en: 'What if I forget all my lines once I get on stage?', ctx: '担心上台忘词' },
  { ru: 'Не могу найти себе места: результаты будут только завтра.', zh: '我坐立不安：结果明天才出来。', en: 'I can\'t sit still: the results won\'t be out until tomorrow.', ctx: '等结果坐立难安' },
  { ru: 'До вылета осталось 2 ч, а я ещё не собрала чемодан.', zh: '离起飞只剩2小时，我还没收拾行李。', en: 'There are only 2 hours left before the flight and I haven\'t packed yet.', ctx: '赶飞机来不及', say: 'До вылета осталось два часа, а я ещё не собрала чемодан.' },
  { ru: '— Ты вся дрожишь. Что случилось?\n— Мне сейчас звонили из больницы, просили приехать.', zh: '—你浑身在发抖，怎么了？—医院刚给我打电话，让我去一趟。', en: '—You\'re trembling. What happened? —They just called from the hospital and asked me to come in.', ctx: '接到医院电话' },
  { ru: '— Ну как ты, готов к докладу?\n— Честно? Руки трясутся, хоть бы план не подвёл.', zh: '—怎么样，报告准备好了吗？—说实话？手都在抖，但愿讲稿别出问题。', en: '—How are you, ready for the presentation? —Honestly? My hands are shaking, I just hope my notes don\'t let me down.', ctx: '演讲前互相打气' },
  { ru: '— Не мни ты так салфетку, все ногти сгрызла уже.\n— Не могу, жду звонка от врача.', zh: '—别再揉餐巾了，指甲都快咬光了。—忍不住，我在等医生电话。', en: '—Stop crumpling that napkin, you\'ve bitten all your nails. —I can\'t help it, I\'m waiting for the doctor\'s call.', ctx: '等医生来电' },
  { ru: '— Как думаешь, заметят ли они мою ошибку в отчёте?\n— Если заметишь ты, заметят и они. Лучше исправь сразу.', zh: '—你觉得他们会发现我报告里的错误吗？—你自己都发现了，他们也会。最好马上改掉。', en: '—Do you think they\'ll notice my mistake in the report? —If you noticed it, they will. Better fix it now.', ctx: '担心错误被发现' },
  { ru: '— Если пробки не рассосутся, мы опоздаем на свадьбу.\n— Тогда давай свернём на кольцевую, так надёжнее.', zh: '—堵车再不缓解，我们参加婚礼就要迟到了。—那我们绕到环路吧，那样更稳。', en: '—If the traffic doesn\'t clear, we\'ll be late for the wedding. —Then let\'s take the ring road, it\'s safer.', ctx: '堵车怕迟到' },
  { ru: '— У меня бабочки в животе перед первым свиданием.\n— Да ты в зеркало на себя посмотри: красотка же!', zh: '—第一次约会前我心里七上八下的。—你照照镜子：多漂亮啊！', en: '—I have butterflies in my stomach before my first date. —Just look at yourself in the mirror: you\'re gorgeous!', ctx: '初次约会紧张' },
  { ru: '— Слушай, я, кажется, потеряла паспорт.\n— Только не это! Проверь ещё раз сумку и карманы.', zh: '—听我说，我好像把护照弄丢了。—可别！再检查一遍包和口袋。', en: '—Listen, I think I lost my passport. —Not that! Check your bag and pockets again.', ctx: '找不到护照' },
  { ru: '— Мама, не волнуйся так, это всего лишь контрольная.\n— Как это всего лишь? От неё зависит оценка за четверть!\n— Я всё выучил, честное пионерское.\n— Ладно, ладно... просто я не меньше тебя переживаю.', zh: '—妈，别这么紧张，不就是个小测验嘛。—什么叫不就是？这可关系到整个季度的成绩！—我都复习好了，我发誓。—好吧……只是我不比你少操心。', en: '—Mom, don\'t worry so much, it\'s just a quiz. —What do you mean "just"? The term grade depends on it! —I\'ve learned everything, cross my heart. —Okay, okay... I\'m just as nervous as you are.', ctx: '孩子考试家长紧张' },
  { ru: '— Ты видел, как на меня посмотрел шеф?\n— По-моему, он просто задумался.\n— А мне кажется, он всё знает про тот отчёт.', zh: '—你看到老板怎么看我了吗？—我觉得他只是在想事情。—可我觉得他知道那份报告的事了。', en: '—Did you see how the boss looked at me? —I think he was just lost in thought. —I have a feeling he knows all about that report.', ctx: '上班疑神疑鬼' },
  { ru: '— Отправила ему SMS два часа назад, а он молчит.\n— Может, он на совещании, без телефона.\n— Если до 21:00 не ответит, я точно сойду с ума.', zh: '—我两小时前就给他发了短信，他一直没回。—也许他在开会，手机不在身边。—九点前再不回，我真要疯了。', en: '—I sent him an SMS two hours ago and he\'s still silent. —Maybe he\'s in a meeting without his phone. —If he doesn\'t reply by 9 PM, I\'ll definitely lose my mind.', ctx: '等不到回复焦虑', say: '— Отправила ему эсэмэску два часа назад, а он молчит.\n— Может, он на совещании, без телефона.\n— Если до девяти вечера не ответит, я точно сойду с ума.' },
  { ru: 'Ты? Вот так встреча! Какими судьбами тебя занесло сюда?', zh: '你？真没想到会在这儿碰见！什么风把你吹来的？', en: 'You? What a meeting! What on earth brings you here?', ctx: '意外遇见故人' },
  { ru: 'Вот уж не ожидал встретить тебя в этом городе.', zh: '真没想到会在这座城市遇见你。', en: 'I never expected to run into you in this city.', ctx: '异地偶遇' },
  { ru: 'Откуда у тебя мой номер, мы же сто лет не виделись?', zh: '你怎么会有我的号码，我们不是一百年没见了吗？', en: 'How did you get my number, we haven\'t seen each other in ages, right?', ctx: '接到意外来电' },
  { ru: 'Надо же, как ты изменился за эти годы!', zh: '天哪，这些年你变化真大！', en: 'Wow, how you\'ve changed over the years!', ctx: '感叹对方变化' },
  { ru: 'Ему всего 22, а он уже защитил кандидатскую!', zh: '他才22岁就已经通过副博士答辩了！', en: 'He\'s only 22 and he\'s already defended his candidate\'s dissertation!', ctx: '年纪轻轻成就高', say: 'Ему всего двадцать два, а он уже защитил кандидатскую!' },
  { ru: '— Угадай, кого я сейчас видела?\n— Понятия не имею, говори же!', zh: '—你猜我刚才看见谁了？—完全猜不到，快说呀！', en: '—Guess who I just saw? —I have no idea, tell me!', ctx: '卖关子猜人' },
  { ru: '— Представляешь, наша школа закрывается.\n— Да ты что! Не может такого быть!', zh: '—你猜怎么着，我们学校要关了。—你说什么！不可能吧！', en: '—Imagine, our school is closing. —What! That can\'t be!', ctx: '听闻学校关闭' },
  { ru: '— Смотри, это же сам президент в очереди за кофе!\n— Не выдумывай... хотя и правда похож!', zh: '—看，那不是总统本人在排队买咖啡吗！—别瞎说了……不过还真像！', en: '—Look, isn\'t that the president himself queuing for coffee! —Don\'t make things up... though he really does look like him!', ctx: '街头撞见名人' },
  { ru: '— Ты слышала новость? Лена выходит замуж!\n— Какая Лена? Та, что клялась никогда не выходить замуж?', zh: '—你听说了吗？莲娜要结婚了！—哪个莲娜？那个发誓永不结婚的？', en: '—Did you hear the news? Lena is getting married! —Which Lena? The one who swore she\'d never marry?', ctx: '不婚朋友闪婚' },
  { ru: '— Правда ли, что цены на проезд поднимут вдвое?\n— К сожалению, правда, я сам читал постановление.', zh: '—车票要翻倍是真的吗？—很遗憾，是真的，我亲自看过文件。', en: '—Is it true that fares will double? —Unfortunately it\'s true, I read the decree myself.', ctx: '听闻涨价传闻' },
  { ru: '— Ну и сюрприз ты нам устроил!\n— Я хотел, чтобы у вас отвисла челюсть.', zh: '—你可真给了我们一个大惊喜！—我就是想让你们惊掉下巴。', en: '—What a surprise you gave us! —I wanted your jaws to drop.', ctx: '精心设计惊喜' },
  { ru: '— В холодильнике мышь повесилась, а ты знал?\n— Знал, просто не успел заехать в магазин.', zh: '—冰箱里空得能跑老鼠，你知道吗？—知道，只是没来得及去超市。', en: '—The fridge is bare, did you know? —I did, I just didn\'t have time to stop at the store.', ctx: '发现冰箱空空' },
  { ru: '— Алло, дедушка, это я!\n— Какой такой я? Ты же в Сибири!\n— Я в аэропорту, прилетел на юбилей!\n— Вот так номер... мать, бросай пироги, внук приехал!', zh: '—喂，爷爷，是我！—哪个我？你不是在西伯利亚吗！—我在机场，回来过寿了！—真没想到……老太婆，别忙活馅饼了，孙子回来啦！', en: '—Grandpa, it\'s me! —Me who? You\'re in Siberia! —I\'m at the airport, I flew in for your birthday! —Well, I never... old girl, drop the pies, our grandson is here!', ctx: '悄悄回家祝寿' },
  { ru: '— Закрой глаза и протяни руку.\n— Что это? Коробочка?.. Неужели кольцо?\n— С днём рождения, родная, открой.', zh: '—闭上眼睛，伸出手。—这是什么？小盒子？……难道是戒指？—生日快乐，亲爱的，打开吧。', en: '—Close your eyes and hold out your hand. —What is it? A little box?.. Can it be a ring? —Happy birthday, darling, open it.', ctx: '生日礼物揭秘' },
  { ru: '— Ты видел счёт за электричество?\n— Нет, а что там?\n— 8000 рублей! Мы же столько не нажигаем!', zh: '—你看到电费账单了吗？—没有，怎么了？—八千卢布！我们哪用得了这么多！', en: '—Did you see the electricity bill? —No, what\'s it say? —8,000 rubles! We don\'t use that much!', ctx: '电费高得离谱', say: '— Ты видел счёт за электричество?\n— Нет, а что там?\n— Восемь тысяч рублей! Мы же столько не нажигаем!' },
  { ru: 'Я с детства боюсь темноты и до сих пор сплю с ночником.', zh: '我从小怕黑，到现在还开着夜灯睡觉。', en: 'I\'ve been afraid of the dark since childhood and still sleep with a nightlight.', ctx: '怕黑开夜灯' },
  { ru: 'Мне было так страшно, что кровь застыла в жилах!', zh: '我当时吓得血液都要凝固了！', en: 'I was so scared that the blood froze in my veins!', ctx: '吓得血液凝固' },
  { ru: 'Ты разве не боишься высоты, стоя у самого края?', zh: '你站在边上，难道不怕高吗？', en: 'Aren\'t you afraid of heights, standing right at the edge?', ctx: '高处腿软' },
  { ru: 'Когда молния ударила рядом, я буквально онемел от ужаса.', zh: '闪电劈到旁边时，我简直吓呆了。', en: 'When lightning struck nearby, I literally froze with terror.', ctx: '雷电惊吓' },
  { ru: 'На меня залаяла собака, и я со всех ног бежала 3 км до дома.', zh: '一条狗冲我叫，我拼命跑了3公里才到家。', en: 'A dog barked at me and I ran the 3 km home as fast as I could.', ctx: '被恶狗追', say: 'На меня залаяла собака, и я со всех ног бежала три километра до дома.' },
  { ru: '— Ты почему прячешься за моей спиной?\n— Там паук, огромный, убери его, пожалуйста!', zh: '—你躲我背后干什么？—那儿有只蜘蛛，超大的，求你把它弄走！', en: '—Why are you hiding behind my back? —There\'s a spider, a huge one, please get rid of it!', ctx: '怕蜘蛛求救' },
  { ru: '— Не подходи ближе, здесь край обрыва!\n— Я и не двигаюсь, у меня колени подкашиваются.', zh: '—别再靠近了，这边是悬崖！—我没动，我膝盖都软了。', en: '—Don\'t come any closer, this is the edge of the cliff! —I\'m not moving, my knees are giving way.', ctx: '悬崖边恐惧' },
  { ru: '— Ну как фильм, страшный?\n— Я полночи не спала, везде мерещились тени.', zh: '—电影怎么样，恐怖吗？—我半宿没睡着，到处都觉得有影子。', en: '—So, was the movie scary? —I didn\'t sleep half the night, I kept seeing shadows everywhere.', ctx: '看完恐怖片' },
  { ru: '— Смотри, к нам бежит разъярённый бык!\n— Бежим скорее к забору, он нас догоняет!', zh: '—看，一头愤怒的牛朝我们冲过来了！—快往栅栏跑，它要追上了！', en: '—Look, an angry bull is charging at us! —Run for the fence, it\'s catching up!', ctx: '野外遇公牛' },
  { ru: '— Боялся ли ты когда-нибудь по-настоящему, до дрожи?\n— Боялся, однажды в горах ночью, в грозу.', zh: '—你有没有真正害怕过，怕到发抖？—有过，有一次夜里在山上遇到暴风雨。', en: '—Have you ever been truly afraid, trembling with fear? —I have, once at night in the mountains during a storm.', ctx: '讲述恐惧经历' },
  { ru: '— Врач сказал, что нужна операция.\n— Не бойся, сейчас такие операции делают постоянно.', zh: '—医生说需要做手术。—别怕，现在这种手术很常见。', en: '—The doctor said I need surgery. —Don\'t be afraid, they do operations like this all the time now.', ctx: '害怕做手术' },
  { ru: '— Слушай, мне кажется, за нами кто-то идёт.\n— Не оглядывайся, прибавь шаг, впереди магазин.', zh: '—听我说，好像有人在跟着我们。—别回头，走快点，前面有家商店。', en: '—Listen, I think someone\'s following us. —Don\'t look back, walk faster, there\'s a shop ahead.', ctx: '夜里被跟踪' },
  { ru: '— Что это был за звук в подвале?\n— Я ничего не слышал.\n— Вот, опять! Как будто кто-то скребётся.\n— Ладно, возьмём фонарик и спустимся вместе.', zh: '—地下室是什么声音？—我什么也没听见。—听，又来了！好像有什么在抓挠。—好吧，拿上手电，我们一起下去。', en: '—What was that sound in the basement? —I didn\'t hear anything. —There it is again! Like something scratching. —All right, let\'s grab a flashlight and go down together.', ctx: '半夜怪声' },
  { ru: '— Самолёт так трясёт, мне страшно летать.\n— Это всего лишь воздушная яма, держи мою руку.\n— А если турбулентность не кончится?', zh: '—飞机晃得好厉害，我害怕坐飞机。—这只是气流颠簸，抓住我的手。—要是颠簸一直不停怎么办？', en: '—The plane is shaking so much, I\'m terrified of flying. —It\'s just an air pocket, hold my hand. —What if the turbulence doesn\'t stop?', ctx: '遇气流颠簸' },
  { ru: '— Мама, под моей кроватью кто-то есть!\n— Никого там нет, это тени от штор.\n— А ты проверь, пожалуйста, я боюсь закрыть глаза.', zh: '—妈妈，我床底下有人！—什么人都没有，那是窗帘的影子。—那你检查一下嘛，我不敢闭眼。', en: '—Mom, there\'s someone under my bed! —There\'s no one there, it\'s the shadows from the curtains. —Please check anyway, I\'m afraid to close my eyes.', ctx: '孩子怕床底' },
  { ru: 'Жаль, конечно, но, видимо, не судьба.', zh: '当然可惜，但看来是没这个缘分。', en: 'It\'s a shame, of course, but I guess it wasn\'t meant to be.', ctx: '宽慰自己随缘' },
  { ru: 'Опять отменили концерт! Ну сколько можно!', zh: '演唱会又取消了！还有完没完！', en: 'They canceled the concert again! Enough already!', ctx: '活动再度取消' },
  { ru: 'Что поделать, если обещания у него расходятся с делом?', zh: '他总是说一套做一套，又有什么办法呢？', en: 'What can you do when his promises don\'t match his actions?', ctx: '对方光说不练' },
  { ru: 'Я пытался объяснить, но он и слушать не стал.', zh: '我试着解释，可他根本不听。', en: 'I tried to explain, but he wouldn\'t even listen.', ctx: '解释无人听' },
  { ru: 'Заказ так и не пришёл, хотя на сайте статус OK уже 5 дней.', zh: '货一直没到，可网站上五天前就显示状态正常。', en: 'The order never arrived, even though the site has shown status OK for 5 days.', ctx: '网购迟迟不到', say: 'Заказ так и не пришёл, хотя на сайте статус окей уже пять дней.' },
  { ru: '— Ты идёшь завтра на матч?\n— Какой матч, билеты раскупили за час.', zh: '—你明天去看比赛吗？—看什么，票一小时就抢光了。', en: '—Are you going to the match tomorrow? —What match, the tickets sold out in an hour.', ctx: '门票售罄' },
  { ru: '— Ну что, взяли тебя на работу?\n— Увы, выбрали кандидата с опытом.', zh: '—怎么样，被录用了吗？—唉，他们选了有经验的。', en: '—So, did you get the job? —Alas, they picked a candidate with experience.', ctx: '求职又被拒' },
  { ru: '— Погода просто ужас, пикник накрылся.\n— Значит, остаёмся дома, что уж тут поделаешь.', zh: '—天气糟透了，野餐泡汤了。—那就待在家里吧，还能怎么办。', en: '—The weather is awful, the picnic is off. —Then we\'ll stay home, nothing to be done about it.', ctx: '野餐因雨取消' },
  { ru: '— Он опять забыл про годовщину.\n— Не расстраивайся, для него все даты — тёмный лес.', zh: '—他又把纪念日忘了。—别难过，他对日期一窍不通。', en: '—He forgot our anniversary again. —Don\'t be upset, all dates are a mystery to him.', ctx: '纪念日被遗忘' },
  { ru: '— Стоило ли вообще ждать чего-то хорошего?\n— Стоило, просто в этот раз не повезло.', zh: '—当初值得抱什么希望吗？—值得，只是这次运气不好。', en: '—Was it even worth hoping for something good? —It was, it just didn\'t work out this time.', ctx: '怀疑期待是否值得' },
  { ru: '— Я верила ему, а он взял и не пришёл.\n— Ну, значит, он не тот, кого ты заслуживаешь.', zh: '—我那么相信他，他却干脆没来。—那就说明他配不上你。', en: '—I trusted him, and he just didn\'t show up. —Well, then he\'s not the one you deserve.', ctx: '信任被辜负' },
  { ru: '— Поезд ушёл, следующий только вечером.\n— Что ж, придётся торчать на вокзале полдня.', zh: '—火车开走了，下一班要到晚上。—唉，只能在车站耗半天了。', en: '—The train has left, the next one isn\'t until evening. —Well, I\'ll have to hang around the station half the day.', ctx: '错过火车' },
  { ru: '— Ты почему ещё не спишь?\n— Жду результатов розыгрыша...\n— Ну и?\n— Ничего не выиграла, как всегда.', zh: '—你怎么还没睡？—等抽奖结果呢……—结果呢？—什么都没中，跟往常一样。', en: '—Why aren\'t you asleep yet? —I\'m waiting for the raffle results... —Well? —I didn\'t win anything, as usual.', ctx: '抽奖再次落空' },
  { ru: '— Шеф опять зарезал мой проект.\n— Третий раз за месяц?\n— Третий. Кажется, мне пора искать новую работу.', zh: '—老板又毙了我的项目。—这个月第三次了？—第三次。看来我该找新工作了。', en: '—The boss killed my project again. —Third time this month? —Third. I think it\'s time I looked for a new job.', ctx: '项目反复被否' },
  { ru: '— Мы копили на машину 3 года.\n— И что, опять всё потратили на ремонт?\n— Увы, прорвало трубу, пришлось.', zh: '—我们攒了三年钱买车。—怎么，又全花在修房子上了？—唉，水管爆了，没办法。', en: '—We saved for a car for 3 years. —And what, it all went on repairs again? —Alas, a pipe burst, we had to.', ctx: '积蓄又被花光', say: '— Мы копили на машину три года.\n— И что, опять всё потратили на ремонт?\n— Увы, прорвало трубу, пришлось.' },
  { ru: 'Не переживай, всё образуется, вот увидишь.', zh: '别担心，一切都会好的，你看着吧。', en: 'Don\'t worry, everything will work out, you\'ll see.', ctx: '劝慰一切会好' },
  { ru: 'Ты справишься, я в тебя верю!', zh: '你一定行，我相信你！', en: 'You\'ll manage, I believe in you!', ctx: '给朋友打气' },
  { ru: 'На твоём месте я бы не сдавался: остался всего один шаг.', zh: '换作我就不会放弃：只差一步了。', en: 'If I were you I wouldn\'t give up: there\'s only one step left.', ctx: '劝人再坚持' },
  { ru: 'Кто не ошибается? Зато какой у тебя теперь опыт!', zh: '谁不犯错呢？至少你现在收获了经验！', en: 'Who doesn\'t make mistakes? But think of the experience you\'ve gained!', ctx: '犯错后开导' },
  { ru: 'Выпей чаю, согрейся и поспи, утро вечера мудренее.', zh: '喝杯茶，暖暖身子睡一觉，早晨比晚上清醒。', en: 'Have some tea, warm up and get some sleep; the morning is wiser than the evening.', ctx: '劝人好好休息' },
  { ru: '— У меня руки опускаются.\n— Не смей так говорить! Вспомни, сколько ты уже прошёл.', zh: '—我都想放弃了。—不许这么说！想想你已经走过了多少路。', en: '—I feel like giving up. —Don\'t you dare say that! Remember how far you\'ve come.', ctx: '泄气时被拉住' },
  { ru: '— Я, кажется, всё испортила.\n— Ну какая ерунда, давай вместе подумаем, как исправить.', zh: '—我好像把一切都搞砸了。—什么话，我们一起想办法补救。', en: '—I think I\'ve ruined everything. —Nonsense, let\'s think together how to fix it.', ctx: '出错后被安抚' },
  { ru: '— Слушай, это не конец света, правда.\n— Тебе легко говорить.', zh: '—听我说，这真不是世界末日。—你说得倒轻巧。', en: '—Listen, it\'s not the end of the world, really. —Easy for you to say.', ctx: '劝解一时难接受' },
  { ru: '— Если устанешь, просто сделай паузу, ладно?\n— Спасибо, что позволяешь мне не быть сильной всегда.', zh: '—累了就歇一歇，好吗？—谢谢你允许我不必永远坚强。', en: '—If you get tired, just take a break, okay? —Thanks for letting me not be strong all the time.', ctx: '允许对方示弱' },
  { ru: '— Разве одна неудача может перечеркнуть все твои победы?\n— Нет, если подумать, не может.', zh: '—一次失败难道就能抹去你所有的成功吗？—仔细想想，不能。', en: '—Can one failure cancel out all your victories? —No, when I think about it, it can\'t.', ctx: '帮人重建信心' },
  { ru: '— Поплачь, если хочется, я не уйду.\n— Спасибо, мне от одних этих слов уже легче.', zh: '—想哭就哭吧，我不会走。—谢谢，光听这句话我就好受多了。', en: '—Cry if you want, I won\'t leave. —Thanks, those words alone already make me feel better.', ctx: '默默陪伴' },
  { ru: '— Дыши глубже: вдох, выдох. Ну как?\n— Кажется, сердце понемногу успокаивается.', zh: '—深呼吸：吸气，呼气。好点没？—好像心跳慢慢平复了。', en: '—Breathe deeply: in, out. How do you feel? —I think my heart is slowly calming down.', ctx: '引导平复情绪' },
  { ru: '— Я не смогу, зал слишком большой.\n— Сможешь, ты же месяц репетировала.\n— А если забуду текст?\n— Тогда посмотришь на меня в первом ряду, и я подскажу.', zh: '—我不行的，厅太大了。—你行的，你都排练一个月了。—要是忘词呢？—那你就看第一排的我，我给你提示。', en: '—I can\'t, the hall is too big. —You can, you rehearsed for a month. —What if I forget my lines? —Then look at me in the front row and I\'ll prompt you.', ctx: '上台前给勇气' },
  { ru: '— Меня сократили, я не знаю, что делать.\n— Для начала поживёшь у меня, идёт?\n— Мне неловко тебя обременять.\n— Брось, друзья для того и нужны.', zh: '—我被裁员了，不知道该怎么办。—先住我这儿，行吗？—给你添麻烦我过意不去。—说什么呢，朋友就是干这个用的。', en: '—I was laid off, I don\'t know what to do. —First you\'ll stay at my place, okay? —I feel awkward imposing on you. —Come on, that\'s what friends are for.', ctx: '失业被收留' },
  { ru: '— После операции он так и не вышел из депрессии.\n— Ему нужны не советы, а просто ваше присутствие.\n— Ты думаешь, этого достаточно?', zh: '—手术后他一直没走出抑郁。—他需要的不是建议，而是你们在身边。—你觉得这就够了吗？', en: '—He never came out of his depression after the operation. —He doesn\'t need advice, just your presence. —Do you think that\'s enough?', ctx: '陪伴抑郁病人' },
  { ru: 'Прости, я был неправ и очень об этом жалею.', zh: '对不起，是我错了，我非常后悔。', en: 'I\'m sorry, I was wrong and I deeply regret it.', ctx: '主动承认错误' },
  { ru: 'Как же мне стыдно за вчерашнее!', zh: '昨天的事我真是太惭愧了！', en: 'I\'m so ashamed of what happened yesterday!', ctx: '为昨天羞愧' },
  { ru: 'Можно мне загладить вину и пригласить тебя на ужин?', zh: '我能不能将功补过，请你吃顿晚饭？', en: 'Can I make it up to you and invite you to dinner?', ctx: '请求弥补过错' },
  { ru: 'Я не должен был так говорить, это вырвалось случайно.', zh: '我不该那么说，那是随口说漏的。', en: 'I shouldn\'t have said that, it just slipped out.', ctx: '解释失言' },
  { ru: 'Опаздываю на 15 минут, не сердись, пожалуйста!', zh: '我会迟到15分钟，请别生气！', en: 'I\'ll be 15 minutes late, please don\'t be angry!', ctx: '迟到先道歉', say: 'Опаздываю на пятнадцать минут, не сердись, пожалуйста!' },
  { ru: '— Я перед тобой виноват.\n— Передо мной? За что?', zh: '—我对不起你。—对不起我？为什么？', en: '—I\'ve wronged you. —Wronged me? What for?', ctx: '突然道歉' },
  { ru: '— Прости, что накричала.\n— Да я и не обиделся, всё нормально.', zh: '—对不起，我冲你嚷嚷了。—我没往心里去，没事的。', en: '—Sorry for snapping at you. —I wasn\'t offended, it\'s fine.', ctx: '发脾气后道歉' },
  { ru: '— Ну что, так и будем молчать?\n— А что сказать, ты меня сильно обидел.', zh: '—怎么，我们就一直冷战吗？—说什么呢，你把我伤得很深。', en: '—So, are we just going to keep silent? —What is there to say, you hurt me badly.', ctx: '冷战中破冰' },
  { ru: '— Слушай, давай забудем всё, как будто не было.\n— Хорошо, но пообещай, что больше так не сделаешь.', zh: '—听我说，让我们忘了这一切，就当没发生过。—好，但你要保证以后不再这样。', en: '—Listen, let\'s forget everything, as if it never happened. —Okay, but promise you won\'t do it again.', ctx: '答应和好' },
  { ru: '— Неужели ты не примешь мои извинения?\n— Приму, просто мне нужно время остыть.', zh: '—你难道不肯接受我的道歉吗？—接受，只是我需要时间消气。', en: '—Won\'t you accept my apology? —I will, I just need time to cool down.', ctx: '道歉需要时间' },
  { ru: '— Я был дураком, честно.\n— Был, но дураки мне тоже нравятся.', zh: '—说实话，我就是个傻瓜。—是傻瓜，可傻瓜我也喜欢。', en: '—I was a fool, honestly. —You were, but I like fools too.', ctx: '撒娇式和好' },
  { ru: '— Мир?\n— Мир. Но в следующий раз я тебе не спущу.', zh: '—和好吧？—和好。但下次我可饶不了你。', en: '—Truce? —Truce. But next time I won\'t let you off so easy.', ctx: '握手言和' },
  { ru: '— Почему ты не берёшь трубку?\n— Мне было больно, не хотела говорить.\n— Я понимаю, и всё же — прости меня.\n— Ладно... приходи вечером, поговорим.', zh: '—你为什么不接电话？—我当时很难受，不想说话。—我理解，但还是请你原谅我。—好吧……晚上过来，我们谈谈。', en: '—Why didn\'t you answer the phone? —I was hurt, I didn\'t want to talk. —I understand, but even so — forgive me. —All right... come over tonight and we\'ll talk.', ctx: '闹别扭后和解' },
  { ru: '— Это я разбил твою чашку, извини.\n— Ту самую, бабушкину?\n— Я уже заказал похожую, но понимаю, что это не то.', zh: '—是我打碎了你的杯子，对不起。—奶奶留下的那个？—我已经订了个相似的，但我知道那不一样。', en: '—I broke your cup, I\'m sorry. —The one from Grandma? —I\'ve already ordered a similar one, but I know it\'s not the same.', ctx: '打碎遗物道歉' },
  { ru: '— Ты простишь меня когда-нибудь?\n— Я уже почти простила.\n— Правда? Тогда давай начнём всё сначала?', zh: '—你有一天会原谅我吗？—我差不多已经原谅了。—真的吗？那我们重新开始好吗？', en: '—Will you ever forgive me? —I\'ve almost forgiven you already. —Really? Then shall we start all over?', ctx: '请求重新开始' },
  { ru: 'Спасибо тебе за всё, ты даже не представляешь, как много для меня сделал.', zh: '谢谢你所做的一切，你不知道你帮了我多大的忙。', en: 'Thank you for everything, you have no idea how much you\'ve done for me.', ctx: '由衷感谢帮助' },
  { ru: 'Как же мне повезло с такими друзьями!', zh: '有你们这样的朋友，我真是太幸运了！', en: 'How lucky I am to have friends like you!', ctx: '庆幸有好朋友' },
  { ru: 'Я тронут до глубины души твоим поступком.', zh: '你的所作所为让我深受感动。', en: 'I\'m deeply moved by what you did.', ctx: '被善举打动' },
  { ru: 'Чем я могу отплатить тебе за такую доброту?', zh: '你对我这么好，我该怎么报答你？', en: 'How can I ever repay you for such kindness?', ctx: '思考如何报答' },
  { ru: 'Благодаря тебе я сдал на права с 1-го раза!', zh: '多亏你，我驾照一次就考过了！', en: 'Thanks to you I passed my driving test on the first try!', ctx: '感谢陪练帮助', say: 'Благодаря тебе я сдал на права с первого раза!' },
  { ru: '— Я принесла тебе суп, ты же болеешь.\n— Ну зачем ты, мне даже неловко...', zh: '—你生病了，我给你带了汤。—哎呀，何必呢，我都不好意思了……', en: '—I brought you some soup, you\'re sick after all. —Oh, you shouldn\'t have, I feel awkward...', ctx: '生病被照顾' },
  { ru: '— Спасибо, что выслушал меня вчера.\n— Да брось, для меня это важно не меньше.', zh: '—谢谢你昨天听我倾诉。—说什么呢，这对我同样重要。', en: '—Thanks for listening to me yesterday. —Come on, it matters just as much to me.', ctx: '感谢倾听' },
  { ru: '— Слушай, я нашёл тебе редкую книгу, держи.\n— Не верю глазам! Я искал её год, спасибо!', zh: '—听着，我给你弄到一本稀有的书，拿着。—简直不敢相信！我找了它一年，谢谢！', en: '—Listen, I found that rare book for you, here. —I can\'t believe my eyes! I\'ve been looking for it for a year, thanks!', ctx: '收到梦寐以求的书' },
  { ru: '— Это тебе, маленький знак благодарности.\n— Вот это да! Ты меня совсем разбаловал.', zh: '—这是给你的，一点谢意。—天哪！你都把我宠坏了。', en: '—This is for you, a small token of gratitude. —Wow! You\'ve completely spoiled me.', ctx: '收到感谢礼物' },
  { ru: '— Неужели ты помнишь, что я люблю ромашки?\n— Конечно, я же запоминаю такие вещи.', zh: '—你居然记得我喜欢洋甘菊？—当然，这种事我都记得。', en: '—You actually remembered I love daisies? —Of course, I remember things like that.', ctx: '被记住喜好' },
  { ru: '— Ты для меня как родная, правда.\n— От таких слов и расплакаться недолго.', zh: '—你对我来说就像亲人一样。—这话听得人都要哭了。', en: '—You\'re like family to me, truly. —Words like that could make me cry.', ctx: '情同家人' },
  { ru: '— Спасибо, что верил в меня, когда я сам не верил.\n— Я просто знал, что у тебя получится.', zh: '—谢谢你在我都不相信自己的时候相信我。—我只是知道你能行。', en: '—Thanks for believing in me when I didn\'t believe in myself. —I just knew you\'d make it.', ctx: '感谢一路信任' },
  { ru: '— Мы всей семьёй хотим тебя поблагодарить.\n— Да не за что, правда.\n— Ты ночами сидел с моим отцом в больнице...\n— Он бы сделал для меня то же самое.', zh: '—我们全家都想谢谢你。—真的不用谢。—你夜里在医院陪我父亲……—换作他也会为我这么做的。', en: '—Our whole family wants to thank you. —There\'s really no need. —You sat with my father in the hospital at night... —He would have done the same for me.', ctx: '全家感谢恩人' },
  { ru: '— Почему ты решил помочь совершенно чужому человеку?\n— Когда-то мне тоже помогли, просто так.\n— Значит, теперь и мой черёд?', zh: '—你为什么决定帮助一个完全陌生的人？—曾经也有人这样无私地帮过我。—那现在轮到我了？', en: '—Why did you decide to help a complete stranger? —Someone once helped me too, just like that. —So now it\'s my turn?', ctx: '善意的传递' },
  { ru: '— Мама, спасибо тебе за жизнь и за всё-всё.\n— Ты что, сынок, расплакался?\n— Просто я только сейчас понял, чем ты для меня пожертвовала.', zh: '—妈，谢谢你给我生命，谢谢你的一切。—怎么了儿子，哭了？—我只是现在才明白，你为我牺牲了多少。', en: '—Mom, thank you for my life and for everything. —What is it, son, are you crying? —I just realized now how much you sacrificed for me.', ctx: '对母亲的感恩' },
]

// ── 天气自然 / Weather / Погода ──
const WEATHER: Phrase[] = [
  { ru: 'С утра небо ясное, ни одного облака не видно.', zh: '早晨天空晴朗，一片云都看不到。', en: 'The sky has been clear since morning, not a single cloud in sight.', ctx: '晨起晴空' },
  { ru: '— Ты не знаешь, после обеда распогодится?\n— Обещают, что тучи к вечеру разойдутся.', zh: '—你知道下午会转晴吗？—预报说傍晚云就散了。', en: '—Do you know if it will clear up after lunch? —They say the clouds will part by evening.', ctx: '询问午后天气' },
  { ru: '— Смотри, какая на улице серость!\n— Да, целый день небо как будто ватой затянуло.', zh: '—看外面多阴沉啊！—是啊，一整天天空都像被棉花遮住了。', en: '—Look how grey it is outside! —Yeah, the sky has looked covered in cotton wool all day.', ctx: '阴沉天空' },
  { ru: '— Дождь ещё идёт?\n— Идёт, но совсем слабый.\n— Тогда можно и без зонта.', zh: '—雨还在下吗？—在下，但很小。—那可以不带伞了。', en: '—Is it still raining? —It is, but very lightly. —Then I can skip the umbrella.', ctx: '雨势渐小' },
  { ru: 'Не люблю выходить из дома в такую морось.', zh: '我不喜欢在这种毛毛雨天出门。', en: 'I hate leaving the house in this kind of drizzle.', ctx: '讨厌毛毛雨' },
  { ru: '— Откуда ты весь такой промокший?\n— Попал под ливень, пока шёл от метро.', zh: '—你怎么浑身都湿透了？—从地铁站走过来时赶上了暴雨。', en: '—How did you get soaked? —I got caught in a downpour walking from the metro.', ctx: '半路遇暴雨' },
  { ru: '— Кажется, дождь начинается.\n— И не говори, небо совсем почернело.\n— Бельё на балконе!\n— Успею снять, не переживай.', zh: '—好像开始下雨了。—可不是嘛，天全黑了。—阳台上还晾着衣服呢！—我来得及收，别担心。', en: '—I think it is starting to rain. —Tell me about it, the sky has gone completely black. —The laundry is on the balcony! —I will get it in time, do not worry.', ctx: '急雨收衣' },
  { ru: '— Возьмёшь завтра зонт?\n— Конечно, весь день обещают проливные дожди.', zh: '—你明天带伞吗？—当然，预报说全天有大雨。', en: '—Are you taking an umbrella tomorrow? —Sure, heavy rain is forecast all day.', ctx: '明日带伞' },
  { ru: 'После короткого дождя асфальт блестит и пахнет свежестью.', zh: '一阵小雨过后，柏油路面发亮，空气清新。', en: 'After a short rain, the asphalt glistens and smells fresh.', ctx: '雨后街道' },
  { ru: '— Ну и погодка сегодня, да?\n— Да уж, с утра солнце, а сейчас вон как льёт.', zh: '—今天这天气可真够呛，是吧？—可不是，早上还出太阳，这会儿就下成这样。', en: '—Some weather today, huh? —Tell me about it, sunny this morning and now it is pouring.', ctx: '天气多变' },
  { ru: '— Дождь кончился?\n— Вроде да, только капли с крыш падают.\n— Значит, можно выходить.', zh: '—雨停了吗？—好像停了，只有屋檐还在滴水。—那就可以出门了。', en: '—Has the rain stopped? —Seems so, only drips are falling from the roofs. —Then we can head out.', ctx: '雨后出门' },
  { ru: '— Будет ли завтра солнце?\n— Синоптики говорят, да, целый день без туч.', zh: '—明天会出太阳吗？—预报员说会，一整天都没云。', en: '—Will there be sun tomorrow? —Forecasters say yes, no clouds all day.', ctx: '盼望晴天' },
  { ru: 'За окном то моросит, то снова выглядывает солнце.', zh: '窗外一会儿飘毛毛雨，一会儿又出太阳。', en: 'Outside it drizzles one minute and the sun comes out the next.', ctx: '时雨时晴' },
  { ru: '— Почему ты так любишь пасмурные дни?\n— Не жарко и гулять приятно.', zh: '—你为什么这么喜欢阴天？—不热，散步很舒服。', en: '—Why do you like overcast days so much? —It is not hot and walking is pleasant.', ctx: '偏爱阴天' },
  { ru: '— Лужи уже высохли?\n— Почти, ветер за полчаса всё подсушил.', zh: '—水洼已经干了吗？—差不多了，风半小时就全吹干了。', en: '—Have the puddles dried yet? —Almost, the wind dried everything in half an hour.', ctx: '积水渐干' },
  { ru: 'За ночь намело столько снега, что дверь еле открылась.', zh: '一夜下了好多雪，门都差点打不开。', en: 'So much snow fell overnight that the door barely opened.', ctx: '一夜大雪' },
  { ru: '— Ты видел, какой ночью был снегопад?\n— Конечно, всё во дворе по колено засыпало.', zh: '—你看到昨晚雪下得多大了吗？—当然，院子里的雪都没到膝盖了。', en: '—Did you see how hard it snowed last night? —Sure, the whole yard was buried knee-deep.', ctx: '夜雪齐膝' },
  { ru: '— Ветер просто с ног сбивает, правда?\n— Ещё какой, я капюшон так и не смог опустить.', zh: '—风大得快把人吹倒了，对吧？—可不是嘛，我连帽子都一直放不下来。', en: '—The wind is practically knocking people over, is not it? —Totally, I never managed to keep my hood down.', ctx: '狂风大作' },
  { ru: 'Град был размером с перепелиное яйцо и побил все помидоры.', zh: '冰雹有鹌鹑蛋那么大，把西红柿全砸坏了。', en: 'The hailstones were the size of quail eggs and destroyed all the tomatoes.', ctx: '冰雹砸菜' },
  { ru: '— Слышишь, как по подоконнику стучит?\n— Это град, лучше отойди от окна.', zh: '—你听到窗台被敲得直响吗？—是冰雹，最好离窗户远点。', en: '—Do you hear that tapping on the windowsill? —It is hail, better stay away from the window.', ctx: '冰雹敲窗' },
  { ru: '— Метель до утра утихнет?\n— Вряд ли, говорят, только к полудню ослабнет.\n— Значит, машину из сугроба не достать.', zh: '—暴风雪天亮前会停吗？—够呛，听说要到中午才减弱。—那车没法从雪堆里开出来了。', en: '—Will the blizzard ease before morning? —Doubt it, they say it will not weaken until noon. —Then the car stays in the snowdrift.', ctx: '暴风雪困车' },
  { ru: 'Снег идёт крупными хлопьями и совсем не тает на рукаве.', zh: '雪下得鹅毛般大，落在袖子上一点都不化。', en: 'Snow is falling in big flakes and does not melt at all on my sleeve.', ctx: '鹅毛大雪' },
  { ru: '— Дороги уже почистили?\n— Какое там, коммунальные службы только до нас доехали.', zh: '—路已经扫了吗？—哪有，环卫队伍刚到我们这儿。', en: '—Have the roads been plowed yet? —Not even close, the crews only just reached us.', ctx: '道路除雪' },
  { ru: '— Замёрз?\n— Очень, пальцы на ногах вообще не чувствую.\n— Иди скорее горячий чай пить.\n— Сейчас, только ботинки отряхну.', zh: '—冻坏了吧？—冻坏了，脚趾头都没知觉了。—快过来喝口热茶。—等一下，我先把鞋上的雪抖掉。', en: '—Frozen? —Completely, I cannot feel my toes at all. —Come and have some hot tea. —In a second, just let me brush the snow off my boots.', ctx: '踏雪归来' },
  { ru: 'Колючий ветер несёт снег прямо в лицо, и дорогу почти не видно.', zh: '刺骨的风雪直往脸上扑，路几乎看不清。', en: 'Biting wind blows snow straight into my face, and the road is barely visible.', ctx: '风雪迷眼' },
  { ru: '— Ты случайно не знаешь, завтра будет гололёд?\n— Обещают, так что осторожнее на спусках.', zh: '—你知道明天会不会路面结冰？—预报说会，下坡时小心点。', en: '—Do you happen to know if it will be icy tomorrow? —They say so, so be careful on slopes.', ctx: '路面结冰' },
  { ru: '— Сосульки видел под крышей?\n— Ага, огромные, того и гляди кому-нибудь на голову упадут.', zh: '—你看到屋檐下的冰锥了吗？—看到了，特别大，随时会砸到谁的头上。', en: '—Did you see the icicles under the roof? —Yeah, huge ones, they could fall on someone\'s head any moment.', ctx: '檐下冰锥' },
  { ru: 'В пургу лучше вообще никуда не выезжать за город.', zh: '下大暴雪的时候最好哪儿也别去，更别出城。', en: 'In a blizzard it is best not to drive anywhere out of town at all.', ctx: '暴雪勿远行' },
  { ru: '— Снеговика уже слепили?\n— А как же, с морковкой и старым ведром вместо шляпы.', zh: '—雪人已经堆好了吗？—当然，有胡萝卜，还有旧桶当帽子。', en: '—Did you build the snowman yet? —We sure did, with a carrot and an old bucket for a hat.', ctx: '院中堆雪人' },
  { ru: '— Смотри, опять снег повалил!\n— Неужели? Только же всё расчистили.\n— Ветром, наверное, тучу нагнало.\n— Похоже, зиму так просто не переждать.', zh: '—看，又下大雪了！—不会吧，刚把雪清完。—估计是风又把云吹来了。—看样子这冬天没那么容易熬过去。', en: '—Look, it is snowing heavily again! —No way, we just cleared everything. —The wind must have blown a cloud over. —Looks like winter will not let up that easily.', ctx: '再降大雪' },
  { ru: 'Сегодня такая жара, что даже в тени трудно дышать.', zh: '今天太热了，连在阴凉处都喘不过气。', en: 'It is so hot today that it is hard to breathe even in the shade.', ctx: '酷暑难当' },
  { ru: '— Ты не замёрзла в этой лёгкой кофте?\n— Совсем нет, мне даже как-то тепло.', zh: '—你穿这么薄的上衣不冷吗？—一点也不，我甚至觉得有点热。', en: '—Are not you cold in that light cardigan? —Not at all, I actually feel kind of warm.', ctx: '衣着单薄' },
  { ru: '— Ну как там на улице?\n— Пекло настоящее, асфальт, кажется, вот-вот поплывёт.', zh: '—外面怎么样？—简直是烤炉，柏油路都快被晒化了。', en: '—What is it like outside? —A real scorcher, the asphalt looks about to melt.', ctx: '户外酷热' },
  { ru: '— Можно я окно открою?\n— Лучше не надо, там ещё жарче, чем в комнате.\n— Тогда включай вентилятор.', zh: '—我可以开窗户吗？—最好别，外面比屋里还热。—那就开风扇吧。', en: '—Can I open the window? —Better not, it is even hotter out there than in here. —Then turn on the fan.', ctx: '室内闷热' },
  { ru: 'К вечеру жара спала до 21 градуса, и на улицах появился народ.', zh: '到傍晚暑热降到21度，街上的人也多了。', en: 'The heat eased to 21 degrees by evening, and people came out into the streets.', ctx: '傍晚暑消', say: 'К вечеру жара спала до двадцати одного градуса, и на улицах появился народ.' },
  { ru: '— Ты чего так тепло оделся?\n— Так по радио обещали резкое похолодание.', zh: '—你怎么穿这么多？—广播里说要大幅降温啊。', en: '—Why are you dressed so warmly? —The radio promised a sudden cold snap.', ctx: '骤降添衣' },
  { ru: '— Холодно?\n— Не то слово, руки к рулю примерзают.\n— Тогда прогрей машину подольше.', zh: '—冷吗？—岂止是冷，手都快冻在方向盘上了。—那就把车多预热一会儿。', en: '—Cold? —That is an understatement, my hands are freezing to the wheel. —Then warm up the car a bit longer.', ctx: '清晨严寒' },
  { ru: '— А тебе не жарко в свитере?\n— Жарко, но в конторе кондиционер работает на всю мощность.', zh: '—你穿毛衣不热吗？—热，但办公室空调开得特别足。', en: '—Are not you hot in that sweater? —I am, but the AC at the office is cranked up full blast.', ctx: '室内冷气' },
  { ru: 'Лёгкий ветерок делает такую жару почти приятной.', zh: '微风让这样的大热天几乎变得舒服起来。', en: 'A light breeze makes this heat almost pleasant.', ctx: '微风解暑' },
  { ru: '— Вода в реке ещё холодная?\n— Бодрит, но купаться уже вполне можно.', zh: '—河水还凉吗？—挺提神的，不过已经完全可以游泳了。', en: '—Is the river water still cold? —It is bracing, but perfectly swimmable now.', ctx: '河水温度' },
  { ru: '— Ты где так обгорел?\n— Весь день на даче провёл, а крем забыл.\n— Теперь неделю будешь как рак красный.', zh: '—你在哪儿晒成这样？—在别墅待了一整天，忘了涂防晒霜。—这下得当一个星期红人了。', en: '—Where did you get that sunburn? —I spent all day at the dacha and forgot the sunscreen. —Now you will be red as a lobster for a week.', ctx: '暴晒晒伤' },
  { ru: '— Прохладно сегодня, не находишь?\n— Ещё бы, я с утра даже отопление включил.', zh: '—今天挺凉的，你不觉得吗？—可不是，我早上都把暖气开了。', en: '—It is chilly today, do not you think? —No kidding, I even turned the heating on this morning.', ctx: '秋凉乍起' },
  { ru: 'От жары спасает только морс со льдом и сквозняк.', zh: '能解暑的只有加冰的果汁饮料和穿堂风。', en: 'The only things saving me from the heat are iced berry drink and a draft.', ctx: '消暑办法' },
  { ru: '— Были ли ночью заморозки?\n— Были, до минус 1 градуса, трава утром вся белая стояла.', zh: '—夜里有霜冻吗？—有，低至零下1度，早上草全是白的。', en: '—Was there frost last night? —Yes, down to minus 1 degree, the grass was all white in the morning.', ctx: '夜间霜冻', say: '— Были ли ночью заморозки?\n— Были, до минус одного градуса, трава утром вся белая стояла.' },
  { ru: '— Почему кот целый день на балконе спит?\n— Греется на солнышке, ему-то хорошо.', zh: '—猫怎么整天在阳台上睡？—在晒太阳取暖，它可舒服了。', en: '—Why does the cat sleep on the balcony all day? —Soaking up the sun, it has got the right idea.', ctx: '猫晒太阳' },
  { ru: 'Утром около +7 °C, а к полудню воздух прогреется до 16 °C.', zh: '早上约7摄氏度，到中午会升到16度。', en: 'Around 7°C in the morning, warming to 16°C by midday.', ctx: '早晚温差', say: 'Утром около плюс семи градусов, а к полудню воздух прогреется до шестнадцати градусов.' },
  { ru: '— Ты прогноз на выходные смотрела?\n— Ага, обещают солнце и почти безветренную погоду.', zh: '—你看周末的天气预报了吗？—看了，说是晴天，几乎没风。', en: '—Did you see the weekend forecast? —Uh-huh, sun and almost no wind.', ctx: '周末预报' },
  { ru: '— Синоптики опять всё перепутали?\n— А то! Обещали дождь, а на дворе ни облачка.', zh: '—预报员又搞错了？—可不是！说有雨，结果外面一片云都没有。', en: '—Did the forecasters mess up again? —Did they ever! Rain was forecast and there is not a cloud outside.', ctx: '预报失准' },
  { ru: 'По радио сказали, что ветер усилится до штормового к ночи.', zh: '广播说入夜后风力会增强到风暴级。', en: 'The radio said the wind would pick up to gale force by night.', ctx: '夜间大风预警' },
  { ru: '— Какая завтра максимальная температура?\n— Днём 23 градуса, но из-за влажности будет душно.', zh: '—明天最高气温多少？—白天23度，但湿度大，会很闷。', en: '—What is tomorrow\'s high? —23 degrees in the daytime, though humidity will make it stuffy.', ctx: '明日最高温', say: '— Какая завтра максимальная температура?\n— Днём двадцать три градуса, но из-за влажности будет душно.' },
  { ru: '— Вероятность дождя точно есть?\n— Приложение показывает 90 % после шести вечера.\n— Тогда встретимся пораньше.', zh: '—确定有可能下雨吗？—软件显示晚上六点后降水概率90%。—那我们早点见面。', en: '—Is rain really likely? —The app shows 90 percent after six p.m. —Then let\'s meet earlier.', ctx: '降水概率', say: '— Вероятность дождя точно есть?\n— Приложение показывает девяносто процентов после шести вечера.\n— Тогда встретимся пораньше.' },
  { ru: 'За сутки выпало 18 мм осадков, это почти половина месячной нормы.', zh: '一昼夜降水18毫米，几乎是月降水量的一半。', en: '18 mm of precipitation fell in 24 hours, almost half the monthly norm.', ctx: '单日降水量', say: 'За сутки выпало восемнадцать миллиметров осадков, это почти половина месячной нормы.' },
  { ru: '— А что говорят про следующую неделю?\n— Что будет бабье лето, тёплые сухие деньки вернутся.', zh: '—下周天气怎么说？—会有小阳春，温暖干燥的日子要回来了。', en: '—What do they say about next week? —Indian summer is coming, warm dry days will return.', ctx: '下周回暖' },
  { ru: '— Ты уже видела сегодняшнюю сводку?\n— Нет ещё, а что там?\n— Штормовое предупреждение объявили на завтра.\n— Значит, велосипед отменяется.', zh: '—你看今天的天气通报了吗？—还没，怎么了？—明天发布了风暴预警。—那骑行就取消吧。', en: '—Have you seen today\'s weather bulletin? —Not yet, what does it say? —They issued a storm warning for tomorrow. —So the bike trip is off.', ctx: '风暴预警' },
  { ru: 'В горах ожидается до минус 12 °C и сильный снег.', zh: '山区预计低至零下12摄氏度，并有大雪。', en: 'Up to minus 12°C and heavy snow are expected in the mountains.', ctx: '山区低温', say: 'В горах ожидается до минус двенадцати градусов и сильный снег.' },
  { ru: '— Откуда ты прогноз обычно узнаёшь?\n— Да в телефоне гляну утром, мне хватает.', zh: '—你平时从哪儿看天气预报？—早上在手机上看一眼就够了。', en: '—Where do you usually get the forecast? —I just check my phone in the morning, that is enough.', ctx: '看预报习惯' },
  { ru: '— Не подскажешь, во сколько завтра рассвет?\n— Если не ошибаюсь, в районе половины шестого.', zh: '—请问明天几点日出？—没记错的话，五点半左右。', en: '—Do you know what time sunrise is tomorrow? —If I am not mistaken, around half past five.', ctx: '查询日出时间' },
  { ru: 'В прогнозе написано, что всю неделю будет держаться ясная погода.', zh: '预报说整个星期都会是晴天。', en: 'The forecast says clear weather will hold all week.', ctx: '一周晴朗' },
  { ru: '— Какой ветер обещают на завтра?\n— Северный, порывистый, до пятнадцати метров в секунду.', zh: '—明天预报什么风？—偏北风，有阵风，可达每秒十五米。', en: '—What wind is forecast for tomorrow? —Northerly, gusty, up to fifteen meters per second.', ctx: '风力预报' },
  { ru: '— Передавали, что ночью подморозит?\n— Да, до минус 3, а днём опять плюс 9.\n— Дороги, наверное, каток будут.\n— Вот именно, выезжай пораньше.', zh: '—广播说夜里上冻吗？—对，低至零下3度，白天又回到零上9度。—路上估计跟冰场一样。—就是，早点出门。', en: '—Did they say it would freeze overnight? —Yes, down to minus 3, plus 9 again in the daytime. —The roads will be like a skating rink. —Exactly, so leave early.', ctx: '昼夜温差大', say: '— Передавали, что ночью подморозит?\n— Да, до минус трёх, а днём опять плюс девять.\n— Дороги, наверное, каток будут.\n— Вот именно, выезжай пораньше.' },
  { ru: 'Весна в этом году поздняя, и снег сошёл только в апреле.', zh: '今年春天来得晚，雪到四月才化完。', en: 'Spring is late this year, and the snow only melted in April.', ctx: '今春来迟' },
  { ru: '— Ты уже чувствуешь, что весной запахло?\n— А то, сосульки вон с крыш текут, и птицы поют.', zh: '—你闻到春天的气息了吗？—当然，屋檐上的冰锥在滴水，鸟儿也在唱。', en: '—Can you smell spring in the air? —Definitely, the icicles are dripping and the birds are singing.', ctx: '春天气息' },
  { ru: '— Какое твоё любимое время года?\n— Осень, люблю шуршать жёлтыми листьями в парке.', zh: '—你最喜欢哪个季节？—秋天，我喜欢在公园里踩着黄叶沙沙响。', en: '—What is your favorite season? —Autumn, I love rustling through yellow leaves in the park.', ctx: '最爱秋天' },
  { ru: '— Лето уже кончилось?\n— По календарю да, но жара ещё стоит.\n— Значит, купаться не поздно.', zh: '—夏天已经过了吗？—日历上是过了，但暑热还在。—那去游泳还不晚。', en: '—Is summer over already? —By the calendar, yes, but the heat is still here. —Then it is not too late to swim.', ctx: '夏末余暑' },
  { ru: 'Дни стали заметно короче, и темнеет уже к семи.', zh: '白天明显变短，七点左右天就黑了。', en: 'The days have gotten noticeably shorter, and it is dark by seven.', ctx: '昼短夜长' },
  { ru: '— Почему ты так радуешься зиме?\n— Так Новый год, каникулы и можно на коньках кататься.', zh: '—你为什么这么盼着冬天？—有新年、假期，还能滑冰啊。', en: '—Why are you so happy about winter? —New Year, holidays, and ice skating.', ctx: '期待冬日' },
  { ru: '— Смотри, первые листочки проклюнулись!\n— И правда, а вчера ещё ветки голые были.\n— Значит, точно потеплело.\n— Давно пора, я уже устал от курток.', zh: '—看，第一批小叶子冒出来了！—真的，昨天树枝还是光秃秃的。—看来天真的暖了。—早该暖了，我穿外套都穿烦了。', en: '—Look, the first leaves have sprouted! —They have, just yesterday the branches were bare. —So it really has warmed up. —About time, I am sick of jackets.', ctx: '新芽初绽' },
  { ru: '— В августе ночи уже холодные?\n— Ближе к концу месяца да, спасает только тонкое одеяло.', zh: '—八月的夜晚已经凉了吗？—快到月底时会凉，只有薄被能救场。', en: '—Are August nights cold already? —Toward the end of the month, yes, only a thin blanket saves me.', ctx: '八月夜凉' },
  { ru: 'Осенью в нашем городе часто моросит и дует пронизывающий ветер.', zh: '秋天我们城里常下毛毛雨，还刮刺骨的风。', en: 'In autumn it often drizzles in our city and a piercing wind blows.', ctx: '秋雨秋风' },
  { ru: '— Когда у вас начинается сезон дождей?\n— Обычно в конце мая и длится почти весь июнь.', zh: '—你们这儿雨季什么时候开始？—一般在五月底，几乎持续整个六月。', en: '—When does your rainy season start? —Usually at the end of May and lasts nearly all of June.', ctx: '雨季来临' },
  { ru: '— Первый снег, ура!\n— Рано радуешься, он, скорее всего, к обеду растает.\n— Всё равно зима уже близко.', zh: '—第一场雪，太棒了！—高兴太早了，这雪多半中午就化。—反正冬天已经近了。', en: '—First snow, hooray! —Do not celebrate yet, it will probably melt by lunch. —Winter is close anyway.', ctx: '初雪飘落' },
  { ru: '— Лето в этом году выдалось жаркое?\n— Не то слово, два месяца подряд стояло пекло.', zh: '—今年夏天很热吗？—岂止热，连续两个月都是烤人的天气。', en: '—Was this summer a hot one? —That is an understatement, scorching heat lasted two months straight.', ctx: '酷暑之夏' },
  { ru: 'Зимой рассветает поздно, и в восьмом часу ещё совсем темно.', zh: '冬天天亮得晚，七点多钟外面还全黑着。', en: 'In winter it gets light late, and it is still completely dark past seven.', ctx: '冬日迟明' },
  { ru: '— Ты уже переобулся по сезону?\n— Вчера переобул, в летних кедах теперь ноги мёрзнут.', zh: '—你按季节换鞋了吗？—昨天换的，现在穿夏天的帆布鞋脚冷。', en: '—Have you switched to seasonal shoes yet? —Yesterday, my feet freeze in summer sneakers now.', ctx: '换季穿鞋' },
  { ru: '— А весна у вас тёплая?\n— Когда как, в марте бывает и снег, и первая гроза.', zh: '—你们那儿春天暖和吗？—不一定，三月里有时下雪，有时又有第一声春雷。', en: '—Is spring warm where you are? —It varies, in March there can be snow and the first thunderstorm.', ctx: '春寒多变' },
  { ru: 'Скорость ветра в эпицентре урагана достигала 42 м/с.', zh: '飓风中心的风速达到每秒42米。', en: 'Wind speeds in the eye of the hurricane reached 42 m/s.', ctx: '飓风风速', say: 'Скорость ветра в эпицентре урагана достигала сорока двух метров в секунду.' },
  { ru: '— Ты когда-нибудь видел настоящую бурю на море?\n— Один раз попал: волны через пирс перехлёстывали.', zh: '—你见过真正的海上风暴吗？—赶上过一次，浪都漫过码头了。', en: '—Have you ever seen a real storm at sea? —I got caught in one once, waves washed right over the pier.', ctx: '海上风暴' },
  { ru: '— Из-за чего отменили рейс?\n— Над аэропортом грозовой фронт, самолёты не принимают.', zh: '—航班为什么取消了？—机场上空有雷暴锋面，飞机无法降落。', en: '—Why was the flight canceled? —There is a thunderstorm front over the airport, planes cannot land.', ctx: '雷雨停航' },
  { ru: 'Засуха держится уже четвёртый месяц, и колхозы подсчитывают убытки.', zh: '干旱已经持续到第四个月，农场都在计算损失。', en: 'The drought has lasted four months now, and farms are counting their losses.', ctx: '连月干旱' },
  { ru: '— Как ты добрался в такой ливень?\n— Вброд практически, некоторые улицы полностью затопило.', zh: '—这么大的雨你怎么到的？—几乎是蹚水来的，有些街道全被淹了。', en: '—How did you get here in such a downpour? —Practically wading, some streets were completely flooded.', ctx: '暴雨淹街' },
  { ru: '— Молнию видел?\n— Видел, прямо в соседний дом ударила.\n— Страшно-то как, хорошо, что никто не пострадал.', zh: '—看到闪电了吗？—看到了，直接劈中了隔壁的房子。—太吓人了，好在没人受伤。', en: '—Did you see the lightning? —I did, it struck the house next door. —How scary, good thing nobody was hurt.', ctx: '惊雷落雷' },
  { ru: 'Из-за аномальной жары в области ввели режим чрезвычайной ситуации.', zh: '由于异常高温，该州进入了紧急状态。', en: 'A state of emergency was declared in the region due to abnormal heat.', ctx: '异常高温' },
  { ru: '— Дорогу сильно замело?\n— Настолько, что фуры стоят уже несколько часов.', zh: '—路被雪封得厉害吗？—厉害得很，大货车已经堵了好几个小时。', en: '—Was the road badly snowed in? —So badly that trucks have been stuck for hours.', ctx: '大雪封路' },
  { ru: '— Вода прибывает?\n— Очень быстро, ещё час назад причал был виден.\n— Тогда надо вещи со второго этажа выносить.\n— Я уже позвонил в службу спасения.', zh: '—水在涨吗？—涨得很快，一小时前还能看到码头。—那得把东西往三楼搬了。—我已经给救援部门打了电话。', en: '—Is the water rising? —Fast, the pier was still visible an hour ago. —Then we need to move things from the second floor. —I have already called the rescue service.', ctx: '洪水上涨' },
  { ru: 'Ледяной дождь за одну ночь превратил город в сплошной каток.', zh: '冻雨一夜之间把整座城市变成了大冰场。', en: 'Freezing rain turned the city into one giant skating rink overnight.', ctx: '冻雨成冰' },
  { ru: '— От жары даже рельсы покоробило, правда?\n— Правда, несколько электричек шли с опозданием.', zh: '—热得连铁轨都变形了，真的吗？—真的，好几趟市郊列车都晚点了。', en: '—Did the heat even warp the rails? —It did, several commuter trains ran late.', ctx: '高温烤弯铁轨' },
  { ru: '— А град часто у вас бывает?\n— Раз в пару лет, но если случается, то сразу с куриное яйцо.', zh: '—你们这儿常下冰雹吗？—几年一次，可一旦下，就有鸡蛋那么大。', en: '—Do you get hail often? —Once every couple of years, but when we do, it is the size of a chicken egg.', ctx: '罕见冰雹' },
  { ru: 'После урагана полгорода осталось без света и повалило десятки деревьев.', zh: '飓风过后，半个城市停电，还刮倒了几十棵树。', en: 'After the hurricane, half the city lost power and dozens of trees were blown down.', ctx: '风灾过后' },
  { ru: '— Холод собачий, ты как вообще?\n— Еле держусь, автобус жду уже 20 минут.', zh: '—冻死了，你还好吗？—快撑不住了，公交已经等了20分钟。', en: '—It is brass monkeys out here, how are you? —Barely, I have been waiting 20 minutes for the bus.', ctx: '酷寒等车', say: '— Холод собачий, ты как вообще?\n— Еле держусь, автобус жду уже двадцать минут.' },
  { ru: '— Говорят, такой жары сто лет не было?\n— В новостях сказали, что это рекорд за 130 лет.\n— Ничего себе, а ночью хоть спадает?\n— Спадает, но в квартире всё равно двадцать восемь.', zh: '—听说这么热的天一百年没遇到了？—新闻说这是130年来的最高纪录。—我的天，夜里总会凉些吧？—会凉，但屋里还是二十八度。', en: '—They say there has not been heat like this in a century? —The news said it is a 130-year record. —Wow, does it at least cool down at night? —It does, but it is still twenty-eight in the apartment.', ctx: '百年高温纪录', say: '— Говорят, такой жары сто лет не было?\n— В новостях сказали, что это рекорд за сто тридцать лет.\n— Ничего себе, а ночью хоть спадает?\n— Спадает, но в квартире всё равно двадцать восемь.' },
  { ru: 'Выходя из дома, всегда проверяй, не забыл ли ты зонт.', zh: '出门时一定要检查自己有没有忘带伞。', en: 'Always check that you have not forgotten your umbrella before leaving home.', ctx: '出门查伞' },
  { ru: '— Тебе дать запасной зонт?\n— Дай, пожалуй, мой вчера ветром вывернуло.', zh: '—给你一把备用伞好吗？—给我吧，我那把昨天被风吹翻了。', en: '—Want me to give you a spare umbrella? —Yes please, mine got turned inside out by the wind yesterday.', ctx: '雨天借伞' },
  { ru: '— Что мне надеть, если днём потеплеет?\n— Возьми куртку на молнии, снимешь, если что.', zh: '—白天要是变热我穿什么好？—穿件拉链外套，热了可以脱。', en: '—What should I wear if it warms up during the day? —Take a zip jacket, you can take it off if needed.', ctx: '灵活穿衣' },
  { ru: '— Ты шапку взяла?\n— Зачем, на улице совсем не холодно.\n— К вечеру резко похолодает, я прогноз видела.', zh: '—你带帽子了吗？—带帽子干嘛，外面一点也不冷。—傍晚会骤冷，我看了预报的。', en: '—Did you take a hat? —Why, it is not cold outside at all. —It will turn sharply cold by evening, I saw the forecast.', ctx: '提醒带帽' },
  { ru: 'Перед дальней дорогой лучше заранее посмотреть прогноз по всему маршруту.', zh: '长途出行前，最好提前查看沿途的天气预报。', en: 'Before a long trip, better check the forecast along the whole route in advance.', ctx: '远行看天' },
  { ru: '— Дождевик брать или зонта хватит?\n— Бери дождевик, ветер такой, что зонт бесполезен.', zh: '—带雨衣还是带伞就行？—带雨衣，风这么大，伞根本没用。', en: '—Should I take a raincoat or is an umbrella enough? —Take the raincoat, with this wind an umbrella is useless.', ctx: '雨衣还是伞' },
  { ru: '— Я побежал, опаздываю!\n— Стоп, а резиновые сапоги?\n— Да они тяжёлые, в кедах быстрее.\n— Промокнешь же, потом не говори, что я не предупреждала.', zh: '—我跑着去了，要迟到了！—等等，雨靴呢？—雨靴太重，穿帆布鞋快。—会湿透的，到时候别说我没提醒你。', en: '—I am running, I am late! —Wait, what about rubber boots? —They are heavy, sneakers are faster. —You will get soaked, do not say I did not warn you.', ctx: '拒穿雨靴' },
  { ru: '— Почему у тебя всегда в сумке зонт?\n— Привычка: живу в городе, где дождь начинается внезапно.', zh: '—你包里怎么总放着伞？—习惯，我住的城市雨总是说下就下。', en: '—Why do you always have an umbrella in your bag? —Habit, I live in a city where rain starts suddenly.', ctx: '随身带伞' },
  { ru: 'Собираясь в горы, обязательно возьми тёплые носки и непромокаемую куртку.', zh: '去山里时一定要带上保暖袜和防水外套。', en: 'When heading to the mountains, be sure to take warm socks and a waterproof jacket.', ctx: '登山装备' },
  { ru: '— Перчатки положить?\n— Положи, утром обещают минусовую температуру.', zh: '—手套要放进去吗？—放上吧，预报说早上零下。', en: '—Should I pack gloves? —Do, below-zero temperatures are forecast for the morning.', ctx: '备好手套' },
  { ru: '— Ты почему в шортах?\n— Так солнце же было с утра!\n— Собирайся быстрее и переодевайся, на небе уже тучи.', zh: '—你怎么穿短裤？—早上明明有太阳啊！—快点换衣服，天上已经乌云密布了。', en: '—Why are you in shorts? —But it was sunny this morning! —Hurry up and change, there are already clouds in the sky.', ctx: '突变催换装' },
  { ru: '— Зонт раскрыть?\n— Раскрой, а то капюшон промокает уже.', zh: '—把伞打开吗？—打开吧，帽子都已经湿了。', en: '—Should I open the umbrella? —Do, the hood is already soaked.', ctx: '共撑一伞' },
  { ru: 'В сильный мороз обязательно заматывай шею шарфом до самого носа.', zh: '严寒时一定要用围巾把脖子围到鼻子那儿。', en: 'In severe frost, always wrap a scarf around your neck right up to your nose.', ctx: '严寒保暖' },
  { ru: '— Купальник брать на всякий случай?\n— Бери, вдруг распогодится и к морю выберемся.', zh: '—泳衣要不要带上以防万一？—带上吧，万一放晴还能去海边。', en: '—Should I pack a swimsuit just in case? —Do, maybe it will clear and we will get to the sea.', ctx: '海边备泳衣' },
  { ru: '— Сколько слоёв одежды на тебе?\n— Три: майка, свитер и куртка, на улице -8 всё-таки.', zh: '—你穿了几层？—三层：背心、毛衣、外套，外面毕竟零下8度。', en: '—How many layers have you got on? —Three: undershirt, sweater, jacket, it is minus 8 outside after all.', ctx: '层层保暖', say: '— Сколько слоёв одежды на тебе?\n— Три: майка, свитер и куртка, на улице минус восемь всё-таки.' },
  { ru: 'Землетрясение магнитудой шесть баллов ощущалось даже в соседних областях.', zh: '六级地震连邻近的州都有震感。', en: 'The magnitude-six earthquake was felt even in neighboring regions.', ctx: '地震波及' },
  { ru: '— Почему в этом регионе так много наводнений?\n— Он стоит в низине, и реки весной выходят из берегов.', zh: '—为什么这个地区这么多洪水？—这里地势低洼，春天河水会漫出河岸。', en: '—Why are there so many floods in this region? —It sits in a lowland, and rivers overflow in spring.', ctx: '低洼水患' },
  { ru: '— Ты слышала, что к побережью движется цунами?\n— Слышала, жителей уже эвакуируют вглубь острова.', zh: '—你听说海啸正朝海岸移动了吗？—听说了，居民已经在往岛内疏散。', en: '—Did you hear a tsunami is moving toward the coast? —I did, residents are already being evacuated inland.', ctx: '海啸预警' },
  { ru: 'Снежная лавина сошла со склона прямо на участок горной трассы.', zh: '一场雪崩从山坡冲下，直接埋住了一段山路。', en: 'An avalanche came down the slope right onto a section of the mountain road.', ctx: '雪崩阻路' },
  { ru: '— Из-за чего в лесу торфяники горят?\n— Жара и отсутствие дождей сделали своё дело.', zh: '—森林里的泥炭地为什么起火？—高温少雨造成的。', en: '—Why are the peat bogs burning in the forest? —The heat and lack of rain did their work.', ctx: '泥炭自燃' },
  { ru: '— Чувствуешь запах гари?\n— Чувствую, наверное, где-то далеко тайга горит.\n— Тогда завтра окна лучше держать закрытыми.', zh: '—你闻到烧焦味了吗？—闻到了，估计是远处的原始林在烧。—那明天窗户最好都关着。', en: '—Can you smell smoke? —I can, probably the taiga is burning somewhere far away. —Then we had better keep the windows shut tomorrow.', ctx: '林火烟味' },
  { ru: 'После нескольких ливней сошёл сель и засыпал единственную дорогу в село.', zh: '几场暴雨后发生了泥石流，埋住了进村唯一的路。', en: 'After several downpours, a mudslide came down and buried the only road into the village.', ctx: '泥石流封村' },
  { ru: '— Вас тоже эвакуировали?\n— Да, ночью полиция ходила по дворам и будила всех.', zh: '—你们也被疏散了吗？—嗯，夜里警察挨家挨户把大家叫醒。', en: '—Were you evacuated too? —Yes, police went yard to yard at night waking everyone.', ctx: '夜半疏散' },
  { ru: '— Ураган ночью ожидается?\n— Ожидается, МЧС советует запастись водой и свечами.\n— А фонарик работает?\n— Сейчас проверю батарейки.', zh: '—夜里会有飓风吗？—会，紧急情况部建议储备水和蜡烛。—手电筒能用吗？—我现在检查电池。', en: '—Is the hurricane expected tonight? —It is, the Emergency Ministry advises stocking water and candles. —Does the flashlight work? —I will check the batteries now.', ctx: '备战飓风' },
  { ru: 'Засуха превратила колодцы в сухие ямы, и воду привозят машинами.', zh: '干旱把水井变成了干坑，水只能靠车辆运送。', en: 'The drought turned wells into dry pits, and water is brought in by trucks.', ctx: '旱灾缺水' },
  { ru: '— Как дома уцелели во время урагана?\n— Повезло, только шифер с крыш посрывало.', zh: '—飓风时房子是怎么保住的？—算走运，只是屋顶的石板瓦被掀了。', en: '—How did the houses survive the hurricane? —We were lucky, only slate was torn off the roofs.', ctx: '房屋受损' },
  { ru: '— А оползень часто тут случается?\n— После сильных дождей склон каждый раз понемногу ползёт.', zh: '—这儿常发生滑坡吗？—大雨过后，山坡每次都会往下滑一点。', en: '—Do landslides happen here often? —After heavy rains, the slope creeps a little every time.', ctx: '山体滑坡' },
  { ru: 'Извержение вулкана закрыло пеплом половину неба над островом.', zh: '火山喷发的火山灰遮住了岛上半边天空。', en: 'The volcanic eruption covered half the sky over the island with ash.', ctx: '火山喷发' },
  { ru: '— Откуда столько беженцев в районе?\n— Из посёлков у реки, там всё водой с крышами накрыло.', zh: '—这地区怎么这么多灾民？—都是河边村镇来的，那儿连房顶都被水淹没了。', en: '—Where did so many displaced people in the area come from? —From riverside villages, the water covered everything including roofs.', ctx: '洪水灾民' },
  { ru: '— Толчки ночью повторялись?\n— Повторялись, около 3 часов, сила 4 балла.\n— Вещи на всякий случай собрал?\n— Собрал, документы и вода у двери стоят.', zh: '—夜里又有余震吗？—有，3点左右，4级。—东西以防万一收好了吗？—收好了，证件和水都放在门边。', en: '—Did the tremors repeat at night? —They did, around 3 o\'clock, magnitude 4. —Packed your things just in case? —I did, documents and water are by the door.', ctx: '夜间余震', say: '— Толчки ночью повторялись?\n— Повторялись, около трёх часов, сила четыре балла.\n— Вещи на всякий случай собрал?\n— Собрал, документы и вода у двери стоят.' },
  { ru: 'Сегодня рассвет был такого нежного розового цвета, что я даже остановился.', zh: '今天的黎明是那么柔和的粉红色，我不由得停下了脚步。', en: 'Today\'s dawn was such a soft pink that I even stopped to watch.', ctx: '粉色黎明' },
  { ru: '— Ты когда-нибудь встречал рассвет на крыше?\n— Один раз было дело, замёрзли, но красотища невероятная.', zh: '—你在屋顶看过日出吗？—有过一次，冻坏了，但美得不可思议。', en: '—Have you ever watched the sunrise from a rooftop? —Once, we froze, but it was unbelievably beautiful.', ctx: '屋顶看日出' },
  { ru: '— Во сколько завтра заходит солнце?\n— Если верить таблице, в четверть седьмого вечера.', zh: '—明天太阳几点落山？—查表的话，傍晚六点一刻。', en: '—What time does the sun set tomorrow? —According to the chart, at a quarter past six in the evening.', ctx: '查询日落' },
  { ru: '— Смотри, радуга!\n— Какая яркая, и все семь цветов хорошо видно.\n— Это потому, что дождь ещё не кончился, а солнце уже вышло.', zh: '—看，彩虹！—好鲜艳，七种颜色都看得清清楚楚。—那是因为雨还没停，太阳就出来了。', en: '—Look, a rainbow! —So bright, and all seven colors are clearly visible. —That is because the rain has not stopped while the sun is already out.', ctx: '雨后彩虹' },
  { ru: 'Закат над морем длится всего несколько минут, но запоминается надолго.', zh: '海上日落只持续几分钟，却能让人记很久。', en: 'A sunset over the sea lasts only a few minutes but stays in your memory for ages.', ctx: '海上日落' },
  { ru: '— Почему луна сегодня такая огромная?\n— Это полнолуние, да и висит она низко над горизонтом.', zh: '—今天月亮怎么这么大？—今天是满月，而且低低地挂在地平线上方。', en: '—Why is the moon so huge tonight? —It is a full moon, and it is hanging low above the horizon.', ctx: '满月低垂' },
  { ru: '— Ты видел падающую звезду?\n— Где? Я только посмотрел, а её уже нет.\n— Вон ещё одна, загадывай желание скорее!\n— Успел, кажется.', zh: '—你看到流星了吗？—哪儿？我刚抬头，它就没了。—那儿又有一颗，快许愿！—好像赶上了。', en: '—Did you see that shooting star? —Where? I just looked and it was already gone. —There is another one, make a wish quick! —I think I made it in time.', ctx: '流星许愿' },
  { ru: '— А северное сияние у вас видно?\n— Очень редко, но в прошлом году небо две ночи подряд зелёным горело.', zh: '—你们那儿能看到极光吗？—极少，但去年有两晚天空一直发绿光。', en: '—Can you see the northern lights where you live? —Very rarely, but last year the sky glowed green two nights in a row.', ctx: '极光偶现' },
  { ru: 'После дождя в небе повисла двойная радуга, и весь двор выбежал смотреть.', zh: '雨后天空挂着一道双彩虹，全院的人都跑出来看。', en: 'After the rain a double rainbow hung in the sky, and the whole yard ran out to see it.', ctx: '双虹当空' },
  { ru: '— Ты знал, что солнце в декабре восходит почти в девять?\n— Знал, поэтому зимой по дороге на работу всегда темно.', zh: '—你知道十二月太阳快九点才升起吗？—知道，所以冬天上班路上天总是黑的。', en: '—Did you know the sun rises at almost nine in December? —I did, that is why it is always dark on my winter commute.', ctx: '冬日迟升' },
  { ru: '— Облака сегодня перистые, да?\n— Ага, тонкие, как пух, высоко-высоко.\n— Говорят, такая дымка к перемене погоды.', zh: '—今天是卷云吧？—嗯，像绒毛一样薄薄的，高高的。—听说这种云丝预示天气要变。', en: '—Those are cirrus clouds today, right? —Uh-huh, thin as down, way up high. —They say such haze means the weather is changing.', ctx: '卷云识天' },
  { ru: '— Почему закат бывает красным?\n— Свет идёт под углом, и часть лучей рассеивается в воздухе.', zh: '—日落为什么是红色的？—光线斜照过来，一部分光在空气中散射了。', en: '—Why are sunsets red? —The light comes at an angle, and some rays scatter in the air.', ctx: '落日为何红' },
  { ru: 'В ясную ночь за городом видно Млечный Путь от края до края неба.', zh: '晴朗的夜晚，在郊外能看到横跨整个天空的银河。', en: 'On a clear night outside the city, the Milky Way spans the sky from edge to edge.', ctx: '郊外星空' },
  { ru: '— Смотрел вчера лунное затмение?\n— Смотрел, луна на четверть часа стала тёмно-красной.', zh: '—你看昨天的月食了吗？—看了，月亮有一刻钟变成了深红色。', en: '—Did you watch yesterday\'s lunar eclipse? —I did, the moon turned dark red for fifteen minutes.', ctx: '观看月食' },
  { ru: '— Во сколько сегодня максимальная высота солнца?\n— Около 12:30, но можно просто в полдень выйти.', zh: '—今天太阳最高是几点？—十二点半左右，不过中午出去也行。', en: '—When is the sun highest today? —Around 12:30, but going out at noon works too.', ctx: '正午太阳', say: '— Во сколько сегодня максимальная высота солнца?\n— Около половины первого, но можно просто в полдень выйти.' },
  { ru: 'Климат в Петербурге сырой и ветреный, а зимы часто бывают бесснежными.', zh: '圣彼得堡气候潮湿多风，冬天常常没有雪。', en: 'The climate in Petersburg is damp and windy, and winters are often snowless.', ctx: '彼得堡气候' },
  { ru: '— Ты бы смог жить в стране, где круглый год лето?\n— Вряд ли, я люблю снег и нормальную зиму.', zh: '—你能住在一年到头都是夏天的国家吗？—够呛，我喜欢雪和像样的冬天。', en: '—Could you live in a country where it is summer all year? —Doubt it, I love snow and a proper winter.', ctx: '常年如夏' },
  { ru: '— Чем климат Москвы отличается от питерского?\n— В Москве суше, морозы крепче, а дождей заметно меньше.', zh: '—莫斯科的气候和圣彼得堡有什么不同？—莫斯科更干燥，严寒更厉害，雨明显更少。', en: '—How does Moscow\'s climate differ from Petersburg\'s? —Moscow is drier, the frosts are harder, and there is noticeably less rain.', ctx: '双城气候对比' },
  { ru: 'На юге страны зима мягкая, и море застывает лишь у самого берега.', zh: '该国南方冬天温和，海水只在岸边结冰。', en: 'In the south of the country winter is mild, and the sea freezes only right by the shore.', ctx: '南方暖冬' },
  { ru: '— Тебе не тяжело дался переезд из тепла в холод?\n— Первое время да, потом привыкаешь и даже начинаешь любить.', zh: '—从暖和的地方搬到冷地方，不难受吗？—一开始难受，后来习惯了，甚至喜欢上了。', en: '—Was not moving from a warm climate to a cold one hard? —At first, then you get used to it and even start to like it.', ctx: '迁徙适应' },
  { ru: '— Как думаешь, климат действительно меняется?\n— Похоже на то, зимы стали заметно мягче, чем двадцать лет назад.\n— А у нас, наоборот, снега всё больше.', zh: '—你觉得气候真的在变吗？—看样子是的，冬天比二十年前明显暖和了。—我们那儿反而雪越来越多。', en: '—Do you think the climate is really changing? —Seems so, winters have gotten noticeably milder than twenty years ago. —Where we are, there is more and more snow instead.', ctx: '气候变化' },
  { ru: 'В приморских городах высокая влажность, и жара переносится тяжелее.', zh: '海滨城市湿度大，热天更难熬。', en: 'Coastal cities have high humidity, and the heat is harder to bear.', ctx: '海滨湿热' },
  { ru: '— Почему в пустыне день жаркий, а ночью холодно?\n— Песок быстро остывает, а влаги в воздухе почти нет.', zh: '—为什么沙漠白天热、夜里冷？—沙子凉得快，空气里又几乎没有水分。', en: '—Why is the desert hot by day and cold at night? —Sand cools fast and there is almost no moisture in the air.', ctx: '沙漠温差' },
  { ru: '— Тебе какой климат больше подходит?\n— Сухой и тёплый, как в горах.\n— А я люблю грозы и летние ливни.\n— Значит, нам в отпуск ехать в разные места.', zh: '—你更适合什么样的气候？—干燥温暖的，像山里那种。—我喜欢雷雨和夏天的暴雨。—那我们度假得去不同的地方了。', en: '—What climate suits you best? —Dry and warm, like in the mountains. —I love thunderstorms and summer downpours. —Then we should vacation in different places.', ctx: '各爱气候' },
  { ru: 'Город стоит в котловине, поэтому зимой над ним неделями висит смог.', zh: '城市坐落在盆地里，所以冬天雾霾常一连几周不散。', en: 'The city sits in a basin, so smog hangs over it for weeks in winter.', ctx: '盆地雾霾' },
  { ru: '— А в Сочи снег вообще бывает?\n— В городе редко, а в горах полным-полно, там лыжный сезон.', zh: '—索契到底下不下雪？—城里很少，山里却很多，正是滑雪季。', en: '—Does it ever snow in Sochi? —Rarely in town, but plenty in the mountains, it is ski season.', ctx: '索契雪景' },
  { ru: '— Правда, что в твоём городе летом белые ночи?\n— Чистые белые — только за полярным кругом, но светло допоздна — факт.', zh: '—你住的城市夏天真有白夜吗？—真正的白夜只在北极圈内，但天到很晚还亮是真的。', en: '—Is it true your city has white nights in summer? —True white nights are only above the Arctic Circle, but it is light late, that is a fact.', ctx: '白夜现象' },
  { ru: 'За Полярным кругом зимой солнце не показывается почти два месяца.', zh: '在北极圈内，冬天太阳将近两个月不露面。', en: 'Above the Arctic Circle the sun does not appear for almost two months in winter.', ctx: '北极极夜' },
  { ru: '— Как ты переносишь резкую смену климата?\n— Плохо, акклиматизация у меня занимает целую неделю.', zh: '—你怎么适应气候的剧烈变化？—不太好，我得花整整一周来适应当地气候。', en: '—How do you handle abrupt climate changes? —Badly, acclimatization takes me a whole week.', ctx: '水土不服' },
  { ru: '— В твоём городе сколько градусов сейчас?\n— Плюс 22, сухо и солнечно.\n— А у нас всего 8 и дождь с утра.\n— Ну, в следующий раз приезжай к нам греться.', zh: '—你的城市现在多少度？—零上22度，干燥晴朗。—我们这儿才8度，一早就下雨。—那下次来我们这儿取暖吧。', en: '—How many degrees is it in your city now? —Plus 22, dry and sunny. —Here it is only 8 and raining since morning. —Well, come to ours to warm up next time.', ctx: '城市气温对比', say: '— В твоём городе сколько градусов сейчас?\n— Плюс двадцать два, сухо и солнечно.\n— А у нас всего восемь и дождь с утра.\n— Ну, в следующий раз приезжай к нам греться.' },
]

// ── 科技网络 / Tech / Технологии ──
const TECH: Phrase[] = [
  { ru: 'Опять мой телефон разрядился за полдня!\n— Сколько лет твоему аккумулятору? Похоже, пора менять.', zh: '我手机半天又没电了！\n— 你这电池用几年了？看样子该换了。', en: 'My phone died again after half a day!\n— How old is your battery? Looks like it\'s time to replace it.', ctx: '电池不耐用' },
  { ru: 'Поставь, пожалуйста, телефон на зарядку, он почти сел.\n— Сейчас, только кабель найду.', zh: '麻烦把手机充下电，快没电了。\n— 马上，我找下充电线。', en: 'Please put the phone on charge, it\'s almost dead.\n— In a sec, just let me find the cable.', ctx: '帮忙充电' },
  { ru: 'Не знаешь, ловит ли здесь связь? У меня вообще не грузит.', zh: '你知道这儿有信号吗？我这儿完全加载不出来。', en: 'Do you know if there\'s reception here? Nothing loads on my phone at all.', ctx: '询问信号' },
  { ru: 'Как же медленно работает интернет на этом тарифе!\n— Так смени тариф, в чём проблема?\n— Хотела бы, да номер менять не хочется, а со своим номером там дороже.', zh: '这套餐的网速怎么这么慢啊！\n— 那就换套餐啊，有什么问题？\n— 我倒想换，可不想换号码，携号转网过去反而更贵。', en: 'Why is the internet so slow on this plan!\n— Then switch plans, what\'s the problem?\n— I\'d love to, but I don\'t want a new number, and keeping mine costs more there.', ctx: '套餐网速慢' },
  { ru: 'Опять абонентскую плату подняли!\n— Да? А я и не заметил, надо посмотреть в приложении.', zh: '他们又涨月费了！\n— 是吗？我都没注意，得去应用里看看。', en: 'They raised the monthly fee again!\n— Really? I didn\'t even notice, I should check in the app.', ctx: '话费涨价' },
  { ru: 'Переведи, пожалуйста, деньги на телефон, а то не могу позвонить.', zh: '帮我给手机充点话费吧，不然电话都打不出去了。', en: 'Put some credit on my phone, please, otherwise I can\'t make calls.', ctx: '请求充值' },
  { ru: 'У тебя какая связь: «Билайн» или МТС?\n— «Мегафон», и пока не жалуюсь.', zh: '你用的是哪家运营商，Beeline还是MTS？\n— MegaFon，目前我还挺满意。', en: 'Which operator do you have, Beeline or MTS?\n— MegaFon, and so far I\'ve no complaints.', ctx: '运营商选择' },
  { ru: 'Если будешь в торговом центре, купи мне новое зарядное устройство.', zh: '你要是去商场，帮我买个新充电器吧。', en: 'If you\'re going to the mall, buy me a new charger.', ctx: '代买充电器' },
  { ru: 'Можно твою зарядку? Моя куда-то делась.\n— Бери, только верни потом, она у меня одна.', zh: '能用下你的充电器吗？我的不知道去哪了。\n— 拿吧，不过记得还，我只有这一个。', en: 'Can I use your charger? Mine\'s gone missing.\n— Take it, just bring it back, it\'s my only one.', ctx: '借充电器' },
  { ru: 'В метро связь постоянно пропадает, невозможно ничего посмотреть.', zh: '地铁里信号老是断，什么都看不了。', en: 'In the subway the signal keeps dropping, you can\'t watch anything.', ctx: '地铁没信号' },
  { ru: 'Сколько у тебя гигабайт интернета в месяц?\n— Двадцать, и мне хватает с запасом.', zh: '你每月有多少G流量？\n— 20G，对我来说绰绰有余。', en: 'How many gigabytes a month do you get?\n— Twenty, and that\'s more than enough for me.', ctx: '流量有多少' },
  { ru: 'Алло, тебя плохо слышно, ты где?\n— В лифте еду, сейчас выйду, перезвони через минуту.\n— Хорошо, жду.', zh: '喂，听不清你说话，你在哪？\n— 我在电梯里，马上出来，过一分钟再打过来。\n— 好，我等你。', en: 'Hello, I can barely hear you, where are you?\n— I\'m in the elevator, getting out now, call back in a minute.\n— OK, I\'ll wait.', ctx: '通话听不清' },
  { ru: 'Какой тариф лучше выбрать для интернета на даче?', zh: '在乡下上网，选什么套餐比较好？', en: 'What plan is best to choose for internet at the dacha?', ctx: '郊外选套餐' },
  { ru: 'Мне пришло сообщение, что кончаются гигабайты.\n— А у меня ещё 5 ГБ осталось, могу раздать.', zh: '我收到短信说流量快用完了。\n— 我还剩5个G，可以开热点分给你。', en: 'I got a text saying my data is running low.\n— I still have 5 GB left, I can share it with you.', ctx: '流量快用完', say: 'Мне пришло сообщение, что кончаются гигабайты.\n— А у меня ещё пять гигабайт осталось, могу раздать.' },
  { ru: 'Ой, телефон опять завис!\n— А ты пробовал перезагрузить?\n— Пробовал, не помогает.\n— Тогда подожди, сам выключится, когда сядет.', zh: '哎呀，手机又卡死了！\n— 你试过重启吗？\n— 试了，没用。\n— 那就等着吧，等没电了它自己就关机了。', en: 'Ugh, my phone froze again!\n— Have you tried restarting it?\n— I have, it doesn\'t help.\n— Then wait, it\'ll turn off by itself when the battery dies.', ctx: '手机卡死了' },
  { ru: 'Ноутбук сильно греется и шумит, даже когда я просто печатаю.\n— Поставь его на подставку, а лучше почисти от пыли, наверняка он забит.', zh: '我笔记本特别烫、风扇特别响，哪怕只是打打字。\n— 把它垫到支架上，最好除下尘，里面肯定堵满了。', en: 'My laptop runs really hot and loud even when I\'m just typing.\n— Put it on a stand; better yet, clean the dust out, it must be clogged.', ctx: '电脑发烫' },
  { ru: 'Компьютер вообще не включается, что делать?\n— Проверь, воткнут ли кабель питания в розетку.', zh: '电脑完全开不了机，怎么办？\n— 检查一下电源线有没有插到插座上。', en: 'The computer won\'t turn on at all, what should I do?\n— Check whether the power cable is plugged into the socket.', ctx: '开不了机' },
  { ru: 'Экран стал каким-то тёмным, хотя яркость на максимуме.', zh: '屏幕变得暗暗的，可亮度已经调到最高了。', en: 'The screen has gone dark somehow, even though the brightness is at maximum.', ctx: '屏幕变暗' },
  { ru: 'Ты можешь посмотреть мой ноутбук? Он тормозит ужасно.\n— Давай посмотрю, наверное, вирус нахватал.', zh: '你能帮我看看笔记本吗？卡得要命。\n— 我看看，估计是染上病毒了。', en: 'Can you take a look at my laptop? It\'s terribly sluggish.\n— Let me see, probably picked up a virus.', ctx: '电脑卡顿' },
  { ru: 'Наконец-то мастер починил компьютер, я уже неделю без него страдал!', zh: '师傅总算把电脑修好了，我离开它熬了一个星期！', en: 'The technician finally fixed the computer; I suffered a whole week without it!', ctx: '电脑修好' },
  { ru: 'Сколько будет стоить замена клавиатуры?\n— Трудно сказать, надо сначала сделать диагностику.', zh: '换个键盘要多少钱？\n— 不好说，得先做个检测。', en: 'How much would replacing the keyboard cost?\n— Hard to say, we need diagnostics first.', ctx: '维修报价' },
  { ru: 'Если ноутбук не перестанет шуметь, отнесу его в сервис.', zh: '笔记本要是还一直响，我就把它送去维修。', en: 'If the laptop doesn\'t stop humming, I\'ll take it in for service.', ctx: '打算送修' },
  { ru: 'У меня пропала папка с документами!\n— Спокойно, возможно, ты её случайно удалил, загляни в корзину.\n— Точно, вот она! Спасибо, ты меня спас.', zh: '我装文件的文件夹不见了！\n— 别急，可能是你不小心删了，看看回收站。\n— 真的，在这儿！谢谢，你救了我。', en: 'My documents folder has disappeared!\n— Easy, maybe you deleted it by accident; check the recycle bin.\n— Right, here it is! Thanks, you saved me.', ctx: '文件不见了' },
  { ru: 'Из колонок идёт какой-то странный треск.\n— Попробуй подключить наушники, проверим, в чём дело.', zh: '喇叭里有种奇怪的噼啪声。\n— 插上耳机试试，看看问题出在哪。', en: 'There\'s a strange crackling coming from the speakers.\n— Try plugging in headphones, we\'ll see what the issue is.', ctx: '喇叭有异响' },
  { ru: 'При загрузке система выдаёт синий экран и сразу перезагружается.', zh: '开机时系统出现蓝屏，然后立刻重启。', en: 'On boot the system shows a blue screen and immediately restarts.', ctx: '蓝屏重启' },
  { ru: 'Сколько времени займёт ремонт?\n— Дня два, не больше, завтра вечером уже заберёте.', zh: '维修要花多长时间？\n— 两天左右，不超过，明天晚上您就能取。', en: 'How long will the repair take?\n— Two days at most; you can pick it up tomorrow evening.', ctx: '维修多久' },
  { ru: 'Сохраняй работу почаще, а то зависнет — потом пожалеешь.', zh: '多保存几次，不然一卡死你就该后悔了。', en: 'Save your work often, otherwise if it freezes you\'ll regret it.', ctx: '记得存盘' },
  { ru: 'Клавиша «энтер» совсем перестала нажиматься.\n— Ты ничего на клавиатуру не проливал? Чаю, например?', zh: '回车键完全按不动了。\n— 你没往键盘上洒过什么吧？比如茶？', en: 'The Enter key has stopped pressing completely.\n— You didn\'t spill anything on the keyboard? Tea, for instance?', ctx: '按键失灵' },
  { ru: 'Мастер говорит, нужно менять жёсткий диск.\n— И сколько это будет стоить?\n— Половину цены нового ноутбука.\n— Тогда, может, проще купить новый?', zh: '师傅说得换硬盘。\n— 那要多少钱？\n— 新笔记本一半的价钱。\n— 那或许直接买个新的更省事？', en: 'The technician says the hard drive needs replacing.\n— And how much will that cost?\n— Half the price of a new laptop.\n— Then maybe buying a new one is simpler?', ctx: '修还是换' },
  { ru: 'Зарядка почему-то не идёт, хотя штекер вставлен до щелчка.', zh: '不知道为什么就是充不进电，虽然插头已经插到底了。', en: 'It\'s not charging for some reason, even though the plug is pushed in until it clicks.', ctx: '充不进电' },
  { ru: 'Ты не знаешь пароль от Wi-Fi?\n— Сейчас гляну на наклейке сзади роутера.', zh: '你知道Wi-Fi密码吗？\n— 我看下路由器后面的标签。', en: 'Do you know the Wi-Fi password?\n— I\'ll check the sticker on the back of the router.', ctx: '无线网密码', say: 'Ты не знаешь пароль от вай-фая?\n— Сейчас гляну на наклейке сзади роутера.' },
  { ru: 'Вечером интернет ужасно тупит, даже видео нормально не посмотреть.\n— Это у всех так, район перегружен, тут ничего не поделаешь.', zh: '晚上网速卡得要命，连正常画质的视频都看不了。\n— 大家都这样，这片区域过载了，没办法。', en: 'The internet is terribly slow in the evening, can\'t even watch a video in normal quality.\n— It\'s the same for everyone, the area is overloaded, nothing you can do.', ctx: '晚高峰卡顿' },
  { ru: 'Опять интернет отвалился, у тебя тоже?\n— У меня работает, наверное, дело в твоём телефоне.', zh: '网又断了，你那边也断了吗？\n— 我这儿能用，估计是你手机的问题。', en: 'The internet dropped again, is yours down too?\n— Mine works, probably it\'s your phone.', ctx: '突然断网' },
  { ru: 'Никто не знает, закончились ли ремонтные работы у провайдера?\n— Я час назад звонил, сказали, ещё пару часов.\n— Замечательно, значит, опять весь вечер без интернета.', zh: '有没有人知道运营商的维修结束了没？\n— 我一小时前打过电话，说还要两个小时。\n— 太好了，意味着今晚又一整晚没网。', en: 'Does anyone know if the provider\'s repairs are finished?\n— I called an hour ago, they said another couple of hours.\n— Wonderful, so another whole evening without internet.', ctx: '等维修恢复' },
  { ru: 'Какая у тебя скорость по Wi-Fi?\n— Сто мегабит, но по факту гораздо меньше.', zh: '你Wi-Fi的网速是多少？\n— 100兆，但实际要慢得多。', en: 'What\'s your Wi-Fi speed?\n— A hundred megabits, but in reality much less.', ctx: '网速多少', say: 'Какая у тебя скорость по вай-фаю?\n— Сто мегабит, но по факту гораздо меньше.' },
  { ru: 'Роутер стоит в другой комнате, поэтому в спальне сигнал совсем слабый.', zh: '路由器在另一个房间，所以卧室的信号特别弱。', en: 'The router is in another room, so the signal in the bedroom is really weak.', ctx: '房间信号弱' },
  { ru: 'Помоги настроить вай-фай, а то я в этом ничего не понимаю.\n— Ладно, показывай, где у тебя роутер.', zh: '帮我设置下无线网，这方面我一窍不通。\n— 行，给我看看路由器在哪。', en: 'Help me set up the Wi-Fi, I don\'t understand any of this.\n— OK, show me where your router is.', ctx: '帮忙设网络' },
  { ru: 'За городом я подключаю ноутбук к телефону, другого варианта нет.', zh: '在郊外我把笔记本连到手机上，没别的办法。', en: 'Out of town I connect my laptop to my phone; there\'s no other option.', ctx: '手机热点' },
  { ru: 'Ты пробовал выключить роутер и снова включить?\n— Смеёшься? Я это уже раз десять сделал.', zh: '你试过把路由器关掉再打开吗？\n— 开玩笑吗？这我都做了十来遍了。', en: 'Have you tried turning the router off and on again?\n— Are you kidding? I\'ve done that about ten times already.', ctx: '重启路由器' },
  { ru: 'Как же бесит, когда видео останавливается на самом интересном месте!', zh: '视频偏在最精彩的地方卡住，太让人抓狂了！', en: 'It\'s so maddening when the video stops at the best part!', ctx: '视频卡住' },
  { ru: 'Почему скорость такая низкая? Я же плачу за 500 Мбит!\n— По кабелю так и будет, а по вай-фаю всегда медленнее.', zh: '为什么速度这么低？我可是付了500兆的钱！\n— 插网线是那样，无线网总会慢些。', en: 'Why is the speed so low? I pay for 500 Mbps!\n— That\'s over a cable; Wi-Fi is always slower.', ctx: '网速不达标', say: 'Почему скорость такая низкая? Я же плачу за пятьсот мегабит!\n— По кабелю так и будет, а по вай-фаю всегда медленнее.' },
  { ru: 'Если связь не появится через пять минут, позвоню провайдеру и устрою им скандал.', zh: '再过五分钟还没网，我就给运营商打电话，跟他们大闹一场。', en: 'If the connection doesn\'t come back in five minutes, I\'ll call the provider and give them an earful.', ctx: '要投诉运营商' },
  { ru: 'Можно к вам подключиться? Мой интернет совсем не работает.\n— Конечно, сейчас продиктую пароль.\n— Записываю: большими буквами, внимательно.', zh: '能连下你们的网吗？我的完全用不了。\n— 当然，我把密码念给你。\n— 我记一下，大写字母，听仔细了。', en: 'Can I connect to your network? Mine isn\'t working at all.\n— Sure, I\'ll dictate the password.\n— I\'m writing: capital letters, pay attention.', ctx: '借无线网' },
  { ru: 'Здесь вообще есть бесплатный вай-фай?\n— Должен быть, только сначала надо зарегистрироваться.', zh: '这儿到底有没有免费无线网？\n— 应该有，只是得先注册。', en: 'Is there even free Wi-Fi here?\n— There should be, you just have to register first.', ctx: '免费无线网' },
  { ru: 'Страница грузится уже минут пять, наверное, опять что-то с сервером.', zh: '页面已经加载了五分钟左右，估计又是服务器出问题了。', en: 'The page has been loading for about five minutes; probably the server is acting up again.', ctx: '页面加载慢' },
  { ru: 'Ты установил то приложение для изучения языков?\n— Установил, но так ни разу и не открыл, честно говоря.', zh: '你装那个学语言的应用了吗？\n— 装是装了，但说实话一次都没打开过。', en: 'Did you install that language-learning app?\n— I did, but I never opened it even once, honestly.', ctx: '装了没用' },
  { ru: 'Приложение опять просит обновление, которое весит целый гигабайт.\n— И не говори, делают их с каждым разом всё тяжелее.', zh: '这应用又要更新，足有一个G大。\n— 可不是嘛，它们一次比一次臃肿。', en: 'The app is asking for another update, a whole gigabyte.\n— Tell me about it, they get heavier every time.', ctx: '更新包太大' },
  { ru: 'Я забыл пароль от почты, что теперь делать?\n— Нажми «восстановить пароль», тебе пришлют ссылку на телефон.', zh: '我忘了邮箱密码，现在怎么办？\n— 点“找回密码”，会给你手机发个链接。', en: 'I forgot my email password, what now?\n— Press "reset password", they\'ll text a link to your phone.', ctx: '忘记密码' },
  { ru: 'Почему после обновления всё выглядит по-другому и так неудобно?', zh: '为什么更新之后一切都变样了，还这么别扭？', en: 'Why does everything look different after the update, and so awkward?', ctx: '更新变难用' },
  { ru: 'Опять эта программа вылетела прямо посередине работы!', zh: '这破软件又在我干活干到一半时闪退了！', en: 'That program crashed again right in the middle of my work!', ctx: '软件闪退' },
  { ru: 'Сколько места занимает эта игра?\n— Около 40 ГБ, так что освободи память заранее.', zh: '这游戏占多少空间？\n— 大概40G，所以提前腾点内存。', en: 'How much space does this game take?\n— Around 40 GB, so free up memory beforehand.', ctx: '占多少空间', say: 'Сколько места занимает эта игра?\n— Около сорока гигабайт, так что освободи память заранее.' },
  { ru: 'После обновления телефон стал разряжаться заметно быстрее.', zh: '更新之后手机耗电明显变快了。', en: 'After the update the phone started draining noticeably faster.', ctx: '更新后耗电' },
  { ru: 'Можно создать второй аккаунт на один номер?\n— Можно, но только если первый к нему не привязан.', zh: '一个手机号能注册第二个账号吗？\n— 可以，只要第一个账号没绑这个号。', en: 'Can I create a second account with one phone number?\n— You can, as long as the first account isn\'t linked to it.', ctx: '注册账号' },
  { ru: 'Установи обновление вечером, когда подключишься к вай-фаю, а то трафик сожрёт.', zh: '晚上连上无线网再装更新，不然会把流量吃光。', en: 'Install the update in the evening when you\'re on Wi-Fi, otherwise it\'ll eat all your data.', ctx: '联网再更新' },
  { ru: 'Приложение не скачивается, пишет «ошибка».\n— А памяти точно хватает? Иногда дело именно в этом.', zh: '应用下不下来，显示“错误”。\n— 内存确定够吗？有时候原因就在这儿。', en: 'The app won\'t download, it says "error".\n— Are you sure there\'s enough storage? Sometimes that\'s exactly it.', ctx: '下载失败' },
  { ru: 'Если бы не реклама через каждые пять минут, приложение было бы идеальным.', zh: '要不是每隔五分钟就有广告，这应用就完美了。', en: 'If it weren\'t for ads every five minutes, the app would be perfect.', ctx: '广告太多' },
  { ru: 'Меня заблокировали в аккаунте, представляешь?\n— За что? Ты что-то нарушил?\n— Да ничего я не нарушал! Наверное, кто-то пожаловался по ошибке.', zh: '我账号被封了，你能信吗？\n— 为什么封？你违规了？\n— 我什么都没违！估计是有人误举报了。', en: 'I got blocked from my account, can you believe it?\n— What for? Did you violate something?\n— I didn\'t violate anything! Someone must have reported me by mistake.', ctx: '账号被封' },
  { ru: 'Ты прошёл эту проверку «я не робот»?\n— Со второго раза только, на этих картинках вечно ничего не понять.', zh: '你过了那个烦人的“我不是机器人”验证吗？\n— 第二次才过，那些图片永远看不懂。', en: 'Did you pass that annoying "I\'m not a robot" check?\n— Only the second time, you can never make out those pictures.', ctx: '人机验证' },
  { ru: 'Новая версия, кажется, стала чуть шустрее работать.', zh: '新版本似乎运行得快了一点。', en: 'The new version seems to run a bit faster.', ctx: '新版本体验' },
  { ru: 'Удали это приложение, оно всё равно тебе не нужно.\n— Жалко как-то, вдруг пригодится.\n— Полгода уже «пригодится», удаляй давай.', zh: '把这应用删了，你反正用不着。\n— 有点舍不得，万一用得上呢。\n— 都“万一”半年了，删了吧。', en: 'Delete this app, you don\'t need it anyway.\n— It feels wasteful somehow, what if it comes in handy.\n— You\'ve been saying "maybe" for six months, go on, delete it.', ctx: '删掉应用' },
  { ru: 'Напиши ей в телеграме, она там обычно быстро отвечает.\n— Уже написал, жду, но она, кажется, не в сети.', zh: '在Telegram给她写吧，她在那儿通常回得快。\n— 已经发了，等着呢，但她好像不在线。', en: 'Write to her on Telegram, she usually answers quickly there.\n— I already did, waiting, but she seems offline.', ctx: '发消息联系' },
  { ru: 'Ты видел, что он вчера написал в истории?\n— Нет, а что там такое?', zh: '你看到他昨天动态里发的了吗？\n— 没有，写什么了？', en: 'Did you see what he posted in his story yesterday?\n— No, what was it?', ctx: '看他动态' },
  { ru: 'Он опять не отвечает, хотя был в сети десять минут назад.\n— Ну, может, просто занят, не накручивай себя.', zh: '他又不回消息，虽然十分钟前还在线。\n— 也许只是在忙，别自己吓自己。', en: 'He\'s not answering again, even though he was online ten minutes ago.\n— Well, maybe he\'s just busy; don\'t wind yourself up.', ctx: '不回消息' },
  { ru: 'Скинь, пожалуйста, наше фото в общий чат.\n— Сейчас скину, только найду его в галерее.', zh: '把我们的照片发到群聊里吧。\n— 马上发，先在相册里找找。', en: 'Send our photo to the group chat, please.\n— I will in a sec, just let me find it in the gallery.', ctx: '照片发群' },
  { ru: 'Ты не помнишь, отключил ли я уведомления в этом чате?', zh: '你记不记得我有没有把这个群的通知关掉？', en: 'Do you remember whether I turned off notifications for this chat?', ctx: '消息通知' },
  { ru: 'Почему ты удалил меня из друзей?\n— Я? Да я вообще туда неделю не заходил!', zh: '你为什么把我从好友里删了？\n— 我？我都一个星期没登过了！', en: 'Why did you unfriend me?\n— Me? I haven\'t even logged in for a week!', ctx: '被删好友' },
  { ru: 'В родительском чате опять сто непрочитанных сообщений.\n— И ты их все читаешь?\n— Ещё чего, просто отключаю звук и раз в день просматриваю по диагонали.', zh: '家长群里又有上百条未读消息。\n— 你还都看啊？\n— 怎么可能，我关掉声音，一天扫一眼而已。', en: 'The parent chat has a hundred unread messages again.\n— And you read them all?\n— As if! I just mute it and skim once a day.', ctx: '群消息太多' },
  { ru: 'Представляешь, мне написал какой-то незнакомец.\n— И что ему надо?\n— Да ерунду какую-то, деньги предлагал вложить, сразу заблокировала.', zh: '你猜怎么着，有个陌生人给我写消息。\n— 他想要什么？\n— 一些废话，说让我投钱，我立刻拉黑了。', en: 'Guess what, some stranger messaged me.\n— And what does he want?\n— Some nonsense, offering to invest money, I blocked him at once.', ctx: '陌生人私信' },
  { ru: 'Не выкладывай это фото, пожалуйста, я там плохо получилась.', zh: '请别发这张照片，我拍得好难看。', en: 'Please don\'t post that photo, I look awful in it.', ctx: '别发照片' },
  { ru: 'Кто-то поставил лайк нашей фотке трёхлетней давности.\n— Ну всё, теперь полночи будем гадать, кто это был.', zh: '有人给我们三年前的照片点了赞。\n— 得，这下要猜半宿是谁了。', en: 'Someone liked our photo from three years ago.\n— Great, now we\'ll spend half the night guessing who.', ctx: '旧照被赞' },
  { ru: 'Как я рада, что наконец отписалась от всех этих скучных блогеров!', zh: '终于取关了所有这些无聊的博主，真高兴！', en: 'I\'m so glad I finally unfollowed all those boring bloggers!', ctx: '取消关注' },
  { ru: 'Ты будешь вести прямой эфир сегодня?\n— Не знаю, если народ соберётся, то почему бы и нет.', zh: '你今天做直播吗？\n— 不知道，要是人凑齐了，那为什么不呢。', en: 'Are you streaming live today?\n— Not sure, if people gather, then why not.', ctx: '今天直播' },
  { ru: 'Она выставила такую подпись к фото, что все сразу обиделись.', zh: '她给照片配了那么段文字，结果大家立刻都生气了。', en: 'She posted such a caption with the photo that everyone got offended right away.', ctx: '配文惹祸' },
  { ru: 'Смотри, какой смешной ролик мне прислали!\n— Не могу открыть, у меня тут связь никакая.', zh: '看，别人给我发了个多好笑的视频！\n— 打不开，我这儿信号很差。', en: 'Look what a funny video someone sent me!\n— I can\'t open it, the connection here is terrible.', ctx: '分享视频' },
  { ru: 'Ты почему вчера не ответил?\n— Я спать лёг рано, телефон на беззвучном стоял.\n— А я уже думала, что ты обиделся.\n— Да на что тут обижаться, ерунда какая.', zh: '你昨天为什么不回？\n— 我睡得早，手机开着静音。\n— 我都以为你生气了。\n— 这有什么好生气的，莫名其妙。', en: 'Why didn\'t you reply yesterday?\n— I went to bed early, my phone was on silent.\n— I already thought you were offended.\n— What\'s there to be offended about, nonsense.', ctx: '没回的误会' },
  { ru: 'Заказывать одежду в интернете удобно, но с размером вечно угадывать приходится.\n— А ты таблицу мерок смотри и отзывы читай, мне помогает.', zh: '在网上订衣服很方便，但尺码总得靠猜。\n— 你看尺码表、读评价，这招对我管用。', en: 'Ordering clothes online is convenient, but you always have to guess the size.\n— Check the size chart and read the reviews; it helps me.', ctx: '网购尺码' },
  { ru: 'Ты оплатил заказ? А то его отменят скоро.\n— Пытаюсь, но карта почему-то не проходит.', zh: '你给订单付款了吗？不然很快就取消了。\n— 我在试，但卡不知道为什么刷不过。', en: 'Have you paid for the order? It\'ll be cancelled soon.\n— I\'m trying, but the card keeps getting declined for some reason.', ctx: '支付失败' },
  { ru: 'Как думаешь, на этой площадке вообще безопасно покупать?', zh: '你觉得在这个平台上买东西到底安全吗？', en: 'Do you think it\'s actually safe to buy things on this site?', ctx: '网购靠谱吗' },
  { ru: 'Когда придёт мой заказ? Уже неделя прошла.\n— По треку посмотри, он, кажется, на сортировке завис.', zh: '我的订单什么时候到？都已经一星期了。\n— 看下物流，它好像卡在分拣点了。', en: 'When will my order arrive? It\'s already been a week.\n— Check the tracking, it seems stuck at the sorting facility.', ctx: '查询物流' },
  { ru: 'Когда вернётся кэшбэк за этот заказ?\n— Написано, через пять дней.\n— Вечно у них так: тратишь сразу, а возврата ждёшь неделями.', zh: '这单的返现什么时候回来？\n— 写着五天后。\n— 他们老是这样：钱立刻花掉，退款却要等好几周。', en: 'When will the cashback for this order come back?\n— It says in five days.\n— They\'re always like this: you spend instantly but wait weeks for a return.', ctx: '等待返现' },
  { ru: 'Зачем тебе столько заказов с маркетплейса?\n— Так по акции же было, почти даром!', zh: '你要这么多电商订单干嘛？\n— 因为搞活动啊，几乎白给！', en: 'Why do you have so many marketplace orders?\n— They were on sale, practically for free!', ctx: '打折囤货' },
  { ru: 'Продавец просит перевести деньги на личную карту.\n— Не переводи ни в коем случае, это почти всегда обман.\n— Так он говорит, что так дешевле выйдет.\n— Ага, а потом ни денег, ни товара.', zh: '卖家让我把钱转到他个人卡上。\n— 千万别转，这几乎总是骗局。\n— 可他说那样更便宜。\n— 是啊，然后钱和货都没了。', en: 'The seller asks me to transfer money to his personal card.\n— Don\'t transfer it under any circumstances, it\'s almost always a scam.\n— But he says it\'ll be cheaper that way.\n— Right, and then there\'s neither money nor goods.', ctx: '私下转账' },
  { ru: 'Мне пришёл не тот размер, что делать?\n— Открой спор, приложи фотографии, вернут деньги.\n— А долго их ждать?\n— Обычно несколько дней, не переживай.', zh: '给我发来的尺码不对，怎么办？\n— 发起纠纷，附上照片，会退钱的。\n— 要等很久吗？\n— 一般几天，别担心。', en: 'They sent me the wrong size, what should I do?\n— Open a dispute, attach photos, you\'ll get a refund.\n— Will I have to wait long?\n— Usually a few days, don\'t worry.', ctx: '申请退换' },
  { ru: 'Ты привязал карту к телефону?\n— Давно уже, в магазине просто прикладываю и всё.', zh: '你把卡绑到手机上了吗？\n— 早就绑了，在店里一贴就行。', en: 'Have you linked your card to your phone?\n— Ages ago; in a shop I just tap it and that\'s it.', ctx: '手机支付' },
  { ru: 'Хочу заказать наушники, но отзывы какие-то противоречивые, не решу никак.', zh: '我想订耳机，但评价褒贬不一，怎么也下不了决心。', en: 'I want to order headphones, but the reviews are mixed and I just can\'t decide.', ctx: '看评价下单' },
  { ru: 'Какая скидка на этот телефон?\n— Двадцать процентов, но только до конца недели.', zh: '这款手机折扣多少？\n— 百分之二十，不过只到本周末。', en: 'What\'s the discount on this phone?\n— Twenty percent, but only until the end of the week.', ctx: '折扣多少' },
  { ru: 'Опять цены на маркетплейсе подскочили, вчера было вдвое дешевле!', zh: '电商上的价格又涨了，昨天还便宜一半呢！', en: 'Prices on the marketplace jumped again; yesterday it was half the price!', ctx: '突然涨价' },
  { ru: 'Ты забрал посылку из постамата?\n— Забрал, но коробка была помятая, хорошо хоть всё цело.', zh: '你从自提柜取包裹了吗？\n— 取了，但盒子皱巴巴的，好在东西都完好。', en: 'Did you pick up the parcel from the locker?\n— I did, but the box was crumpled; luckily everything is intact.', ctx: '自提包裹' },
  { ru: 'Если доставят раньше срока, успею подарить на день рождения.', zh: '要是能提前送到，还赶得上送生日礼物。', en: 'If it\'s delivered ahead of schedule, I\'ll make it in time for a birthday present.', ctx: '盼着到货' },
  { ru: 'Тут есть оплата частями?\n— Есть, первый платёж всего 1 рубль, остальное потом.', zh: '这里可以分期付款吗？\n— 可以，首付只要1卢布，其余的以后付。', en: 'Can I pay in installments here?\n— Yes, the first payment is only 1 ruble, the rest later.', ctx: '分期付款', say: 'Тут есть оплата частями?\n— Есть, первый платёж всего один рубль, остальное потом.' },
  { ru: 'Смотри, нейросеть нарисовала картину, от настоящей не отличить!\n— И вправду, я бы ни за что не догадался, что это машина.', zh: '你看，神经网络画了幅画，跟真的没区别！\n— 确实，我怎么也猜不到这是机器画的。', en: 'Look, the neural network made a painting indistinguishable from a real one!\n— Indeed, I\'d never have guessed it was a machine.', ctx: '智能绘画' },
  { ru: 'Ты вообще пользуешься AI в работе?\n— Ещё бы, он за меня половину текстов пишет.', zh: '你在工作里用AI吗？\n— 那还用说，一半的文字都是它替我写的。', en: 'Do you use AI at work?\n— Sure, it writes half my texts for me.', ctx: '用AI办公', say: 'Ты вообще пользуешься эй-ай в работе?\n— Ещё бы, он за меня половину текстов пишет.' },
  { ru: 'Боюсь, скоро искусственный интеллект оставит нас без работы.\n— Да брось, он же не умеет того, что умеют люди.\n— Пока не умеет, а через десять лет кто его знает.', zh: '我担心人工智能很快会让我们失业。\n— 得了吧，它又不会人会的本事。\n— 暂时不会，十年后谁知道呢。', en: 'I\'m afraid artificial intelligence will soon leave us without jobs.\n— Come on, it can\'t do what people can.\n— Not yet, but who knows ten years from now.', ctx: '失业焦虑' },
  { ru: 'Попроси чат-бота перевести этот договор, сэкономим время.\n— Давай, только потом я всё равно проверю каждое слово.', zh: '让聊天机器人翻译这份合同，能省时间。\n— 行吧，不过之后我还是会逐词核对。', en: 'Ask the chatbot to translate this contract, we\'ll save time.\n— OK, but I\'ll still check every word afterwards.', ctx: '机器翻译' },
  { ru: 'Неужели этот голос записал не человек, а нейросеть — вообще не отличить!', zh: '这声音居然不是人录的，而是神经网络——根本分辨不出！', en: 'To think this voice was recorded not by a person but by a neural network—you can\'t tell at all!', ctx: '合成语音' },
  { ru: 'Какую модель лучше взять для работы с картинками?\n— Я слышал, новая модель рисует заметно лучше старых.', zh: '处理图片用哪个模型更好？\n— 我听说新模型比老模型画得明显好。', en: 'Which model is better to use for images?\n— I heard the new one draws noticeably better than the old ones.', ctx: '模型怎么选' },
  { ru: 'Если бы нейросеть умела чувствовать, это было бы уже страшновато.', zh: '要是神经网络能感知，那可就有点吓人了。', en: 'If a neural network could feel, that would already be a bit scary.', ctx: '畅想未来' },
  { ru: 'Смотри, робот-пылесос сам построил карту квартиры!\n— А мой вчера сожрал провод и чуть не сгорел.', zh: '你看，扫地机器人自己建了家里的地图！\n— 我家那个昨天吞了根电线，差点烧掉。', en: 'Look, the robot vacuum mapped the apartment by itself!\n— Mine ate a cable yesterday and almost burned out.', ctx: '扫地机器人' },
  { ru: 'Как думаешь, бот по-настоящему понимает то, что говорит?\n— Вряд ли, он просто подбирает слова по порядку.\n— А со стороны и не скажешь, отвечает-то вполне осмысленно.', zh: '你觉得机器人真正理解自己说的话吗？\n— 未必，它只是按顺序选词。\n— 但从外面看不出来，回答得还挺有道理。', en: 'Do you think the bot truly understands what it says?\n— Hardly, it just selects words in order.\n— You couldn\'t tell from outside; it answers quite sensibly.', ctx: '它真懂吗' },
  { ru: 'Я вчера весь вечер болтал с нейросетью.\n— И о чём можно с ней говорить так долго?\n— Да обо всём! Она и шутит, и советы даёт, иногда даже слишком умно.', zh: '我昨天整晚都在跟神经网络聊天。\n— 跟它有什么好聊这么久的？\n— 什么都行！它会开玩笑、给建议，有时候聪明得过头。', en: 'I chatted with a neural network all evening yesterday.\n— What can you even discuss with it for so long?\n— Everything! It jokes and gives advice, sometimes too cleverly.', ctx: '陪聊机器人' },
  { ru: 'На уроке детям показывали, как нейросеть распознаёт лица на фотографиях.', zh: '课上给孩子们演示神经网络如何识别照片上的人脸。', en: 'In class the kids were shown how a neural network recognizes faces in photos.', ctx: '人脸识别' },
  { ru: 'Представляешь, скоро такси будут возить без водителя?\n— Давно пора, только бы безопасно было.', zh: '你能想象吗，很快出租车就没有司机了？\n— 早该如此，只要安全就好。', en: 'Can you imagine, soon taxis will run without drivers?\n— About time, as long as it\'s safe.', ctx: '无人驾驶' },
  { ru: 'В новом телефоне есть функция перевода разговора прямо в реальном времени.', zh: '新手机有实时翻译对话的功能。', en: 'The new phone has a feature that translates a conversation in real time.', ctx: '实时翻译' },
  { ru: 'А эта штука сама сочиняет музыку?\n— Сочиняет, и довольно неплохо, я бы даже не догадался.', zh: '这玩意儿能自己作曲？\n— 能，而且相当不错，我都想不到。', en: 'Can this thing compose music by itself?\n— It can, and quite well; I\'d never have guessed.', ctx: '智能作曲' },
  { ru: 'Читала, что искусственный интеллект теперь ставит диагнозы лучше врачей.\n— Не верю я в это, машина есть машина.\n— Так исследования же показывают.\n— Исследования исследованиями, а лечиться я лучше у живого доктора буду.', zh: '我读到，人工智能现在诊断比医生还准。\n— 我不信这个，机器终归是机器。\n— 可研究表明是这样啊。\n— 研究归研究，我还是找活生生的医生看病。', en: 'I read that artificial intelligence now diagnoses better than doctors.\n— I don\'t believe it, a machine is a machine.\n— But the studies show it.\n— Studies or not, I\'d rather be treated by a living doctor.', ctx: '机器看病' },
  { ru: 'Хочу электронную книгу, говорят, глаза от неё меньше устают.\n— Я сама пользуюсь, бери с экраном нового типа, не пожалеешь.', zh: '我想要个电子书阅读器，据说眼睛不那么累。\n— 我自己也在用，买新屏幕类型的，你不会后悔。', en: 'I want an e-reader; they say your eyes get less tired.\n— I use one myself; take it with the new type of screen and you won\'t regret it.', ctx: '选阅读器' },
  { ru: 'Посоветуй ноутбук для работы, я в них совсем запутался.\n— Бюджет какой? От этого всё и зависит.', zh: '给我推荐个办公笔记本吧，我完全挑晕了。\n— 预算多少？一切都取决于这个。', en: 'Recommend a laptop for work, I\'m completely confused by them.\n— What\'s the budget? Everything depends on that.', ctx: '推荐笔记本' },
  { ru: 'Какой марки телевизор сейчас считается самым надёжным?\n— Сейчас всё на одном заводе делают, разница небольшая.\n— Так что же, брать самый дешёвый?\n— Ну зачем самый, бери средний по цене известной марки.', zh: '现在什么牌子的电视算最可靠？\n— 如今都在一家工厂生产，差别不大。\n— 那是不是买最便宜的？\n— 干嘛买最便宜的，买知名牌子的中等价位。', en: 'Which TV brand is considered the most reliable now?\n— They\'re all made in the same factories nowadays, the difference is small.\n— So should I take the cheapest?\n— Why the cheapest? Take a mid-priced one from a known brand.', ctx: '选购电视' },
  { ru: 'Сколько ты отдал за свои умные часы?\n— 15 000 рублей, но по скидке, без неё было бы двадцать.', zh: '你买智能手表花了多少？\n— 15000卢布，不过是打折，没折扣要两万。', en: 'How much did you pay for your smartwatch?\n— 15,000 rubles, but on sale; without it, it\'d be twenty thousand.', ctx: '手表价格', say: 'Сколько ты отдал за свои умные часы?\n— Пятнадцать тысяч рублей, но по скидке, без неё было бы двадцать.' },
  { ru: 'Не вижу смысла переплачивать за флагман, если пользуешься только мессенджерами.', zh: '如果只用聊天软件，我看没必要为旗舰多花钱。', en: 'If you only use messengers, I see no point in overpaying for a flagship.', ctx: '旗舰值不值' },
  { ru: 'Что лучше взять: фотоаппарат или телефон с хорошей камерой?\n— Сейчас телефоны так снимают, что камера почти и не нужна.', zh: '买什么更好：照相机还是拍照好的手机？\n— 现在手机拍照好到几乎不需要相机。', en: 'What\'s better to buy: a camera or a phone with a good camera?\n— Phones shoot so well now that a camera is barely needed.', ctx: '相机还是手机' },
  { ru: 'Я читаю отзывы на независимых форумах, там честнее пишут.', zh: '我在独立论坛上看评价，那里写得更诚实。', en: 'I read reviews on independent forums; they write more honestly there.', ctx: '去哪看评测' },
  { ru: 'Смотри, какие наушники я присмотрел.\n— Красивые, а шумоподавление есть?\n— Есть, и батарею держат чуть ли не сутки, завтра закажу.', zh: '看，我看上了这款耳机。\n— 挺好看，有降噪吗？\n— 有，而且电池差不多能撑一天，我明天就订。', en: 'Look at the headphones I\'ve picked out.\n— They\'re nice; do they have noise cancellation?\n— They do, and the battery lasts almost a day. I\'ll order them tomorrow.', ctx: '选购耳机' },
  { ru: 'Ты за новый телефон или за подержанный?\n— Лучше новый со скидкой, чем чужой, с чужими болячками.', zh: '你选新手机还是二手的？\n— 宁愿打折买新机，也不要别人带隐患的旧机。', en: 'Do you go for a new phone or a used one?\n— Better a new one on sale than someone else\'s old one with hidden issues.', ctx: '新机二手' },
  { ru: 'Что скажешь про эту модель?\n— Железо отличное, но слабое место — батарея, через год придётся менять.\n— Для меня это критично, я в разъездах постоянно.\n— Тогда смотри другую, что тут ещё сказать.', zh: '你觉得这款怎么样？\n— 配置很棒，但短板是电池，一年后就得换。\n— 这对我来说很关键，我总在出差。\n— 那就看别的吧，还能说什么。', en: 'What do you say about this model?\n— The hardware is great, but its weak point is the battery; you\'ll have to replace it in a year.\n— That\'s critical for me, I\'m always travelling.\n— Then look at another one, what else is there to say.', ctx: '机型短板' },
  { ru: 'А планшет тебе зачем, если ноутбук есть?\n— Фильмы в кровати смотреть удобнее, вот и весь ответ.', zh: '有笔记本了你要平板干嘛？\n— 躺床上看电影更方便，这就是全部理由。', en: 'Why do you need a tablet if you have a laptop?\n— Watching movies in bed is more convenient, that\'s the whole answer.', ctx: '要买平板' },
  { ru: 'Какие же тонкие стали ноутбуки, журнал и то толще бывает!', zh: '现在的笔记本多薄啊，有的杂志都比它厚！', en: 'How thin laptops have become; even a magazine can be thicker!', ctx: '感叹轻薄' },
  { ru: 'Говорят, эта колонка звучит как большая.\n— Верить надо ушам, а не обзорам, пойди да послушай в магазине.', zh: '据说这个音箱声音像大的一样。\n— 要信耳朵而不是评测，去店里听听。', en: 'They say this speaker sounds like a big one.\n— You should trust your ears, not reviews; go listen in the shop.', ctx: '选购音箱' },
  { ru: 'Взял бы подержанный фотоаппарат, если бы понимал, на что смотреть при покупке.', zh: '如果我懂买的时候该看什么，我就会买二手照相机。', en: 'I\'d buy a used camera if I understood what to look for when buying.', ctx: '二手相机' },
  { ru: 'Как думаешь, стоит менять телефон или ещё год походит?\n— А что с ним не так?\n— Батарея садится быстро, а так всё работает.\n— Тогда поменяй батарею и ходи себе дальше.', zh: '你觉得该换手机还是再用一年？\n— 它有什么问题？\n— 电池掉得快，其他都正常。\n— 那就换块电池继续用。', en: 'Do you think I should change phones or keep it another year?\n— What\'s wrong with it?\n— The battery drains fast, otherwise everything works.\n— Then replace the battery and keep using it.', ctx: '换电池吗' },
  { ru: 'Придумай пароль подлиннее, а то взломают за две минуты.\n— А как запомнить-то такой? У меня и простые-то все вылетают из головы.', zh: '想个长点的密码，不然两分钟就被破解。\n— 可那种密码怎么记？我连简单的都记不住。', en: 'Come up with a longer password, otherwise it\'ll be cracked in two minutes.\n— But how do you remember one like that? I can\'t even keep the simple ones straight.', ctx: '设强密码' },
  { ru: 'Мне звонят и говорят, что я якобы оформил кредит.\n— Клади трубку сразу, это мошенники, сто процентов.', zh: '有人给我打电话说我好像办了笔贷款。\n— 立刻挂断，这是骗子，百分之百。', en: 'They\'re calling me saying I apparently took out a loan.\n— Hang up right away, it\'s scammers, a hundred percent.', ctx: '诈骗电话' },
  { ru: 'Ты делаешь резервные копии фотографий?\n— Конечно, после того как раз всё потеряла, теперь дую на воду.', zh: '你给照片做备份吗？\n— 当然，自从丢过一次所有东西，现在我格外谨慎。', en: 'Do you back up your photos?\n— Of course; after losing everything once, now I\'m extra careful.', ctx: '备份照片' },
  { ru: 'Смотри, мне прислали ссылку на какой-то выигрыш!\n— Не вздумай нажимать, просто удали сообщение.', zh: '看，有人给我发了个中奖链接！\n— 千万别点，直接把消息删掉。', en: 'Look, someone sent me a prize link!\n— Don\'t you dare click; just delete the message.', ctx: '钓鱼链接' },
  { ru: 'Везде нужен свой пароль, а я их и так уже не помню.', zh: '处处都要有不同的密码，我反正已经记不住了。', en: 'Every place needs its own password, and I can\'t remember them all as it is.', ctx: '密码太多' },
  { ru: 'Когда ты последний раз менял пароль от почты?\n— Да года три назад, наверное, а что?', zh: '你上次换邮箱密码是什么时候？\n— 大概三年前吧，怎么了？', en: 'When did you last change your email password?\n— About three years ago, I guess; why?', ctx: '该换密码' },
  { ru: 'Какой кошмар, у знакомого украли все деньги с карты!', zh: '太可怕了，一个熟人卡上所有的钱都被偷走了！', en: 'How awful; someone I know had all the money stolen from their card!', ctx: '卡被盗刷' },
  { ru: 'Почему нельзя подключаться к открытому вай-фаю?\n— Через него у тебя могут увести пароли, вот почему.', zh: '为什么不能连开放的无线网？\n— 因为通过它你的密码可能被盗，就这原因。', en: 'Why can\'t I connect to open Wi-Fi?\n— Because your passwords can be stolen through it, that\'s why.', ctx: '公共网风险' },
  { ru: 'Если бы я вовремя сделал резервную копию, не потерял бы фотографии за десять лет.', zh: '我要是及时做了备份，就不会丢掉十年的照片。', en: 'If I had made a backup in time, I wouldn\'t have lost ten years of photos.', ctx: '后悔没备份' },
  { ru: 'Меня просят продиктовать код из СМС, это нормально?\n— Нет! Никому никогда не говори этот код.\n— Всё, поняла, уже положила трубку.', zh: '他们要我念短信里的验证码，这正常吗？\n— 不正常！这个码永远别告诉任何人。\n— 好，我懂了，已经挂断了。', en: 'They\'re asking me to read out the code from the SMS; is that normal?\n— No! Never tell that code to anyone.\n— OK, I understand; I\'ve already hung up.', ctx: '验证码骗局' },
  { ru: 'Я храню важные файлы в облаке и на внешнем диске, так надёжнее.', zh: '我把重要文件存在云端和一块外接硬盘上，这样更可靠。', en: 'I keep important files in the cloud and on an external drive; it\'s more reliable that way.', ctx: '双重备份' },
  { ru: 'Ты заклеиваешь камеру на ноутбуке?\n— А как же, после того как узнал, что за людьми следят.', zh: '你把笔记本的摄像头贴起来吗？\n— 当然，在得知有人被监视之后。', en: 'Do you tape over your laptop camera?\n— Of course, after learning that people get watched.', ctx: '摄像头隐私' },
  { ru: 'Опять этот код из сообщения вводить, надоело!\n— Зато без него мошенникам было бы гораздо проще.\n— Согласна, но когда спешишь, эта двухфакторная аутентификация просто бесит.', zh: '又要输短信里的码，烦透了！\n— 但没它骗子就容易多了。\n— 同意，可赶时间的时候，这种双重验证真让人恼火。', en: 'Entering the code from a message again, I\'m fed up!\n— But without it scammers would have a much easier time.\n— Agreed, but when you\'re in a hurry, this two-factor authentication is simply infuriating.', ctx: '双重验证' },
  { ru: 'Представляешь, моя подруга перевела мошенникам все сбережения.\n— Как так вышло? Она же всегда такая осторожная.', zh: '你能信吗，我朋友把所有积蓄都转给了骗子。\n— 怎么会这样？她一向那么谨慎。', en: 'Can you believe it, my friend transferred all her savings to scammers.\n— How did that happen? She\'s always been so careful.', ctx: '被骗积蓄' },
  { ru: 'Ты включил облачное копирование?\n— Не понимаю я этих настроек, покажи как-нибудь.\n— Тут пяти минут делов: заходишь сюда, нажимаешь вот сюда.\n— Ой, правда просто! Спасибо, теперь все фото в безопасности.', zh: '你开云备份了吗？\n— 我搞不懂这些设置，找时间教教我。\n— 这花不了五分钟：进这里，点这个。\n— 哎呀，真简单！谢谢，现在照片都安全了。', en: 'Did you turn on cloud backup?\n— I don\'t understand these settings; show me sometime.\n— It\'s a five-minute job: go here, press this.\n— Oh, it really is simple! Thanks, now all the photos are safe.', ctx: '教开云备份' },
  { ru: 'Раньше мы как-то жили без гаджетов и не жаловались.\n— Жили, конечно, только и скучали, бывало, неделями ждали письма.', zh: '以前我们没有数码产品也照样生活，也没抱怨。\n— 当然生活，可也会无聊，有时等一封信要好几星期。', en: 'We used to live without gadgets and didn\'t complain.\n— We did, of course, but we were bored too; sometimes we waited weeks for a letter.', ctx: '今昔对比' },
  { ru: 'Ты читал про новую презентацию?\n— Читал, а показали, как обычно, то же самое, только дороже.', zh: '你读了关于那场新发布会的消息吗？\n— 读了，可跟往常一样，展示的还是那套，只是更贵。', en: 'Did you read about the new presentation?\n— I did; as usual they showed the same thing, only more expensive.', ctx: '发布会吐槽' },
  { ru: 'Как считаешь, технологии делают нас ближе или, наоборот, разделяют?', zh: '你认为技术让我们更亲近，还是相反，让我们疏远？', en: 'Do you think technology brings us closer or, conversely, drives us apart?', ctx: '科技与关系' },
  { ru: 'Мой дедушка в восемьдесят лет спокойно пользуется смартфоном.\n— Мой тоже, даже продукты с доставкой на дом заказывает.', zh: '我爷爷八十岁了，智能手机用得很从容。\n— 我爷爷也是，甚至会订送货上门的食品。', en: 'My grandfather uses a smartphone confidently at eighty.\n— Mine too; he even orders groceries with home delivery.', ctx: '老人用手机' },
  { ru: 'Гаджеты реально экономят время?\n— Если не залипать в них сутками, то да.\n— Вот в этом и загвоздка: откроешь на минутку, очнулся через два часа.', zh: '数码产品真的能省时间吗？\n— 只要别整天泡在里面，就能。\n— 症结就在这儿：打开一分钟，两小时后才回过神。', en: 'Do gadgets really save time?\n— If you don\'t get stuck in them all day, yes.\n— That\'s the catch: you open it for a minute and come to your senses two hours later.', ctx: '科技双刃剑' },
  { ru: 'Говорят, скоро все перейдут на электромобили.\n— Не скоро, у нас зарядок-то почти нет, какая бы техника ни была.', zh: '听说很快大家都会改用电动汽车。\n— 没那么快，我们这儿充电桩几乎没有，不管技术多好。', en: 'They say everyone will soon switch to electric cars.\n— Not soon; we barely have any charging stations, however good the technology.', ctx: '电动车讨论' },
  { ru: 'До чего техника дошла: можно увидеть человека с другого конца света вживую!', zh: '技术发展到了什么地步：可以实时看到地球另一端的人！', en: 'What technology has come to: you can see a person from the other side of the world live!', ctx: '赞叹科技' },
  { ru: 'Тебе не кажется, что мы слишком зависим от телефонов?\n— Кажется, я без него даже дорогу найти не могу.\n— Вот именно, раньше маршруты в голове держали, а теперь всё в телефоне.', zh: '你不觉得我们太依赖手机了吗？\n— 觉得，没它我连路都找不到。\n— 就是，以前路线都记在脑子里，现在全在手机里。', en: 'Don\'t you think we\'re too dependent on phones?\n— I do; without it I can\'t even find the way.\n— Exactly; we used to keep routes in our heads, now everything\'s in the phone.', ctx: '依赖手机' },
  { ru: 'Как тебе новый флагман?\n— Красивый, спору нет, но ценник конский, пусть сами себе его оставят.', zh: '新旗舰你觉得怎么样？\n— 漂亮，没说的，但价格吓人，让他们自己留着吧。', en: 'What do you think of the new flagship?\n— It\'s beautiful, no argument, but the price is outrageous; let them keep it.', ctx: '评价旗舰' },
  { ru: 'А какие технологии ты считаешь лучшими?\n— Те, которых не замечаешь: просто работают, и всё.', zh: '你认为哪些技术最好？\n— 那些你注意不到的：就只管工作，如此而已。', en: 'Which technologies do you think are the best?\n— The ones you don\'t notice: they just work, that\'s all.', ctx: '什么是好科技' },
  { ru: 'Видел новость про очередной скачок цен на технику?\n— Видел, теперь точно до зимы ничего покупать не буду.', zh: '你看到电子产品又一次涨价的新闻了吗？\n— 看到了，现在我肯定入冬前什么都不买。', en: 'Did you see the news about another spike in gadget prices?\n— I did; now I\'m definitely not buying anything before winter.', ctx: '涨价新闻' },
  { ru: 'Без интернета я бы, наверное, больше читал и раньше ложился спать.', zh: '要是没有互联网，我大概会多读书、更早睡觉。', en: 'Without the internet I\'d probably read more and go to bed earlier.', ctx: '没网的假设' },
  { ru: 'Дети сейчас вообще не вылезают из планшетов.\n— Так мы сами им их суём, лишь бы не мешали, честно-то говоря.', zh: '现在的孩子根本离不开平板。\n— 还不是我们自己塞给他们，只求不碍事，说实话。', en: 'Kids today practically never leave their tablets.\n— We\'re the ones who hand them over, just so they won\'t bother us, to be honest.', ctx: '孩子与屏幕' },
  { ru: 'Смотрела документалку про влияние соцсетей на мозг?\n— Нет, а что там говорят?\n— Что внимание у людей стало как у золотой рыбки, и это, похоже, правда.', zh: '你看那部关于社交媒体影响大脑的纪录片了吗？\n— 没有，里面讲什么？\n— 说人的注意力变得像金鱼一样，而这似乎是真的。', en: 'Did you watch the documentary about social media\'s effect on the brain?\n— No, what does it say?\n— That people\'s attention span has become like a goldfish\'s, and it appears to be true.', ctx: '注意力变短' },
  { ru: 'Знаешь, о чём я жалею?\n— О чём?\n— Что в детстве у нас не было всех этих игрушек и гаджетов.\n— Да брось, зато у нас было настоящее детство, во дворе до темноты.', zh: '你知道我后悔什么吗？\n— 什么？\n— 遗憾我们小时候没有所有这些玩具和数码产品。\n— 得了吧，我们反而拥有真正的童年，在院子里玩到天黑。', en: 'Do you know what I regret?\n— What?\n— That in childhood we didn\'t have all these toys and gadgets.\n— Oh come on; instead we had a real childhood, out in the yard until dark.', ctx: '童年与科技' },
]

// ── 谚语熟语 / Proverbs / Пословицы ──
const PROVERB: Phrase[] = [
  { ru: 'Век живи, век учись.\n— Бабушка, ты в семьдесят лет пошла на курсы?\n— Век живи, век учись!', zh: '活到老，学到老。\n— 奶奶，您七十岁还去上培训班？\n— 活到老，学到老！', en: 'Live and learn.\n— Granny, you started courses at seventy?\n— Live and learn!', ctx: '劝人不断学习' },
  { ru: 'Ученье — свет, а неученье — тьма.', zh: '学习是光明，无知是黑暗。', en: 'Learning is light, and ignorance is darkness.', ctx: '谈学习的价值' },
  { ru: 'Повторение — мать учения.\n— Ты опять перечитываешь конспект?\n— Ага, повторение — мать учения.', zh: '重复是学习之母。\n— 你又在重读笔记？\n— 嗯，重复是学习之母。', en: 'Repetition is the mother of learning.\n— Reading your notes again?\n— Yes, repetition is the mother of learning.', ctx: '谈复习方法' },
  { ru: 'Не стыдно не знать, стыдно не учиться.', zh: '不知道并不可耻，不学习才可耻。', en: 'It is not shameful not to know; it is shameful not to learn.', ctx: '安慰不懂的人' },
  { ru: 'Корень учения горек, а плоды его сладки.', zh: '学问的根是苦的，果实却是甜的。', en: 'The root of learning is bitter, but its fruits are sweet.', ctx: '谈苦学与收获' },
  { ru: 'Кто хочет много знать, тому не надо много спать.', zh: '想要知道得多，就得睡得少。', en: 'He who wants to know much must sleep little.', ctx: '谈勤奋苦读' },
  { ru: 'Знание — сила.\n— Зачем тебе вторая специальность?\n— Знание — сила!', zh: '知识就是力量。\n— 你干吗还要修第二专业？\n— 知识就是力量！', en: 'Knowledge is power.\n— Why do you need a second major?\n— Knowledge is power!', ctx: '谈知识的力量' },
  { ru: 'Грамоте учиться — всегда пригодится.', zh: '读书识字，早晚有用。', en: 'Learning to read and write always comes in handy.', ctx: '谈识字有用' },
  { ru: 'Учёного учить — только портить.\n— Давай я объясню тебе правила шахмат!\n— Учёного учить — только портить.', zh: '教行家只是糟蹋他（别班门弄斧）。\n— 我来给你讲讲国际象棋规则！\n— 教行家只是糟蹋他。', en: 'Don\'t teach a learned man — you\'ll only spoil him.\n— Let me explain the rules of chess to you!\n— Don\'t teach your grandmother to suck eggs.', ctx: '劝人别班门弄斧' },
  { ru: 'Без науки — как без рук.', zh: '没有知识，就像没有双手。', en: 'Without knowledge it\'s like being without hands.', ctx: '谈知识的重要' },
  { ru: 'Терпение и труд всё перетрут.\n— Не получается китайская грамматика?\n— Ничего, терпение и труд всё перетрут.', zh: '耐心和劳动能磨平一切。\n— 语法学不会？\n— 没事，耐心和劳动能磨平一切。', en: 'Patience and hard work will overcome everything.\n— Grammar won\'t stick?\n— Patience and hard work will overcome everything.', ctx: '谈耐心与劳动' },
  { ru: 'Без труда не вытащишь и рыбку из пруда.', zh: '不花力气，连池塘里的小鱼也捞不上来（不劳则无获）。', en: 'Without effort you can\'t even pull a little fish out of the pond.', ctx: '谈不劳无获' },
  { ru: 'Дело мастера боится.', zh: '活儿怕行家。', en: 'The work fears the master.', ctx: '夸行家手艺' },
  { ru: 'Куй железо, пока горячо.', zh: '趁热打铁。', en: 'Strike while the iron is hot.', ctx: '劝人抓住时机' },
  { ru: 'Не спеши языком, торопись делом.', zh: '舌头别抢快，手脚要麻利（少说多做）。', en: 'Don\'t hurry with your tongue; hurry with your deeds.', ctx: '劝人少说多做' },
  { ru: 'Глаза страшатся, а руки делают.\n— Дров целая гора, не переносим!\n— Ничего, глаза страшатся, а руки делают.', zh: '眼怕手不怕。\n— 柴火堆成山，搬不完啊！\n— 没事，眼怕手不怕。', en: 'The eyes are afraid, but the hands do the work.\n— Such a pile of firewood, we\'ll never finish!\n— The eyes are afraid, but the hands do the work.', ctx: '鼓励别畏难' },
  { ru: 'Кончил дело — гуляй смело.', zh: '做完活儿，安心去玩。', en: 'Finished the work — now relax with a clear conscience.', ctx: '谈劳逸结合' },
  { ru: 'Работа не волк, в лес не убежит.', zh: '工作不是狼，不会跑进森林（活儿跑不了，先歇歇）。', en: 'Work is not a wolf; it won\'t run off into the forest.', ctx: '劝人别太焦虑' },
  { ru: 'Кто рано встаёт, тому Бог подаёт.', zh: '谁起得早，上帝给谁赐福（早起的鸟儿有虫吃）。', en: 'God helps those who rise early.', ctx: '谈早起的好处' },
  { ru: 'Любишь кататься — люби и саночки возить.', zh: '爱坐雪橇，就得爱拉雪橇（有享受就得有付出）。', en: 'If you like sledding, you have to like hauling the sled too.', ctx: '谈有享受有付出' },
  { ru: 'Дружба дороже золота.', zh: '友谊贵于黄金。', en: 'Friendship is more precious than gold.', ctx: '谈友谊珍贵' },
  { ru: 'Старый друг лучше новых двух.', zh: '一个老朋友胜过两个新朋友。', en: 'An old friend is better than two new ones.', ctx: '谈老友可贵' },
  { ru: 'Не имей сто рублей, а имей сто друзей.\n— Зачем тебе столько знакомых?\n— Не имей сто рублей, а имей сто друзей.', zh: '宁要一百个朋友，不要一百卢布。\n— 你要那么多熟人干什么？\n— 宁要一百个朋友，不要一百卢布。', en: 'Better a hundred friends than a hundred rubles.\n— Why do you need so many friends?\n— Better a hundred friends than a hundred rubles.', ctx: '谈朋友胜金钱' },
  { ru: 'Друзья познаются в беде.\n— Когда я заболел, только Оля пришла помочь.\n— Друзья познаются в беде.', zh: '患难见真情。\n— 我生病时只有奥莉娅来帮忙。\n— 患难见真情。', en: 'A friend in need is a friend indeed.\n— When I fell ill, only Olya came to help.\n— A friend in need is a friend indeed.', ctx: '谈患难见真情' },
  { ru: 'Дружная стая и волка не боится.', zh: '团结的羊群不怕狼。', en: 'A united flock is not afraid of the wolf.', ctx: '谈团结力量' },
  { ru: 'Скажи мне, кто твой друг, и я скажу, кто ты.', zh: '告诉我你的朋友是谁，我就知道你是什么样的人。', en: 'Tell me who your friend is, and I\'ll tell you who you are.', ctx: '谈择友观人' },
  { ru: 'На вкус и цвет товарищей нет.\n— Как тебе может нравиться этот фильм?\n— На вкус и цвет товарищей нет.', zh: '口味和颜色，各有所好（萝卜青菜，各有所爱）。\n— 你怎么会喜欢这部电影？\n— 萝卜青菜，各有所爱。', en: 'There\'s no arguing about tastes.\n— How can you like this film?\n— There\'s no arguing about tastes.', ctx: '谈各有所好' },
  { ru: 'Дружба дружбой, а служба службой.', zh: '交情是交情，公事是公事。', en: 'Friendship is friendship, but business is business.', ctx: '谈公私分明' },
  { ru: 'Нет друга — ищи, а нашёл — береги.', zh: '没有朋友就去寻找，找到了就要珍惜。', en: 'No friend — seek one; found one — treasure them.', ctx: '谈珍惜朋友' },
  { ru: 'С волками жить — по-волчьи выть.\n— В этой компании все кричат, приходится тоже.\n— С волками жить — по-волчьи выть.', zh: '与狼为伍，就得学狼嚎（入乡随俗）。\n— 这公司人人都嚷嚷，我也只能跟着。\n— 入乡随俗。', en: 'When you live with wolves, you howl like a wolf.\n— Everyone shouts in this company, so I have to as well.\n— When in Rome, do as the Romans do.', ctx: '谈入乡随俗' },
  { ru: 'Мой дом — моя крепость.', zh: '我的家就是我的城堡。', en: 'My home is my castle.', ctx: '谈家是港湾' },
  { ru: 'В гостях хорошо, а дома лучше.\n— Поездка была отличная, но я так рад вернуться!\n— В гостях хорошо, а дома лучше.', zh: '做客虽好，总不如家。\n— 这趟旅行棒极了，但回家真好！\n— 做客虽好，总不如家。', en: 'Being a guest is nice, but home is better.\n— The trip was great, but I\'m so glad to be back!\n— East or west, home is best.', ctx: '谈归家心情' },
  { ru: 'Вся семья вместе — и душа на месте.', zh: '全家团聚，心里才踏实。', en: 'When the whole family is together, the soul is at peace.', ctx: '谈家庭团聚' },
  { ru: 'Не выноси сору из избы.\n— Не рассказывай соседям о нашей ссоре.\n— Верно, не выноси сору из избы.', zh: '家丑不可外扬。\n— 别把咱们吵架的事告诉邻居。\n— 对，家丑不可外扬。', en: 'Don\'t wash dirty linen in public.\n— Don\'t tell the neighbours about our quarrel.\n— Right, don\'t wash dirty linen in public.', ctx: '谈家丑外扬' },
  { ru: 'Яблоко от яблони недалеко падает.\n— Сын опять сидит за чертежами, как отец.\n— Яблоко от яблони недалеко падает.', zh: '苹果不会落在离树很远的地方（有其父必有其子）。\n— 儿子又像爸爸一样埋头画图纸。\n— 有其父必有其子。', en: 'The apple doesn\'t fall far from the tree.\n— The son is bent over his drawings again, just like his father.\n— The apple doesn\'t fall far from the tree.', ctx: '谈家风遗传' },
  { ru: 'Муж и жена — одна сатана.', zh: '夫妻同心（夫妻俩是一路人）。', en: 'Husband and wife are of one spirit.', ctx: '谈夫妻同心' },
  { ru: 'Кровь — не вода.', zh: '血浓于水。', en: 'Blood is thicker than water.', ctx: '谈血浓于水' },
  { ru: 'Дитя — что тесто: как замесил, так и выросло.', zh: '孩子就像面团：怎么揉，就怎么长。', en: 'A child is like dough: as you knead it, so it grows.', ctx: '谈教育孩子' },
  { ru: 'Без отца — полсироты, а без матери — и вся сирота.', zh: '没有父亲是半个孤儿，没有母亲就是整个孤儿。', en: 'Without a father you\'re half an orphan; without a mother, a full orphan.', ctx: '谈父母之恩' },
  { ru: 'Не красна изба углами, а красна пирогами.', zh: '屋子不以角落漂亮，而以馅饼香（家贵在温馨，不在华丽）。', en: 'The hut is beautiful not for its corners but for its pies.', ctx: '谈家贵温馨' },
  { ru: 'Время — деньги.', zh: '时间就是金钱。', en: 'Time is money.', ctx: '谈珍惜时间' },
  { ru: 'Всему своё время.', zh: '万物皆有时。', en: 'Everything has its time.', ctx: '谈耐心等待' },
  { ru: 'Обещанного три года ждут.\n— Ты обещал ещё в прошлом году!\n— Обещанного три года ждут.', zh: '答应了的事，要等三年（别急）。\n— 你去年就答应了！\n— 答应了的事要等三年。', en: 'A promised thing takes three years.\n— You promised last year!\n— A promised thing takes three years.', ctx: '调侃承诺拖延' },
  { ru: 'Дорога ложка к обеду.', zh: '午饭时的勺子最金贵（来得正是时候）。', en: 'A spoon is precious at dinner time.', ctx: '谈及时才好' },
  { ru: 'Под лежачий камень вода не течёт.\n— Сидишь и ждёшь звонка от работодателя?\n— Под лежачий камень вода не течёт, пойду сам спрошу.', zh: '躺着的石头下面，水流不过去（坐等无收获）。\n— 你就坐着等雇主来电话？\n— 坐等无收获，我自己去问。', en: 'Water doesn\'t flow under a lying stone.\n— Just sitting and waiting for the employer\'s call?\n— Nothing ventured, nothing gained — I\'ll go ask myself.', ctx: '谈坐等无果' },
  { ru: 'Лучше синица в руках, чем журавль в небе.', zh: '手中的山雀胜过天上的仙鹤。', en: 'A bird in the hand is worth two in the bush.', ctx: '谈知足稳妥' },
  { ru: 'Утро вечера мудренее.\n— Решай сейчас!\n— Нет, утро вечера мудренее.', zh: '早晨比晚上更明智（大事睡一觉再定）。\n— 现在就决定！\n— 不，睡一觉再说。', en: 'The morning is wiser than the evening.\n— Decide now!\n— No, I\'ll sleep on it.', ctx: '劝人隔夜再定' },
  { ru: 'Каждому овощу своё время.', zh: '每种蔬菜都有自己的时令（凡事各有其时）。', en: 'Every vegetable has its season.', ctx: '谈各有其时' },
  { ru: 'Пока солнце взойдёт, роса очи выест.', zh: '太阳还没出来，露水先伤了眼（久等误事）。', en: 'Before the sun rises, the dew will eat your eyes.', ctx: '谈久等误事' },
  { ru: 'Время лечит.', zh: '时间能治愈一切。', en: 'Time heals.', ctx: '安慰时间疗愈' },
  { ru: 'Семь раз отмерь, один раз отрежь.\n— Может, сразу писать заявление?\n— Семь раз отмерь, один раз отрежь.', zh: '量七次，剪一次（三思而后行）。\n— 要不直接写申请？\n— 三思而后行。', en: 'Measure seven times, cut once.\n— Should I just write the application right away?\n— Measure twice, cut once.', ctx: '劝人三思后行' },
  { ru: 'Тише едешь — дальше будешь.', zh: '走得越稳，走得越远（欲速则不达）。', en: 'The slower you go, the further you\'ll get.', ctx: '劝人稳中求快' },
  { ru: 'Не рой яму другому — сам в неё попадёшь.', zh: '别给别人挖坑，小心自己掉进去（害人终害己）。', en: 'Don\'t dig a pit for another — you\'ll fall into it yourself.', ctx: '劝人别害人' },
  { ru: 'Поспешишь — людей насмешишь.', zh: '忙中出错，惹人笑话。', en: 'Haste makes waste.', ctx: '谈忙中出错' },
  { ru: 'Знает кошка, чьё мясо съела.\n— Почему он так прячет глаза?\n— Знает кошка, чьё мясо съела.', zh: '猫知道自己吃了谁的肉（做贼心虚）。\n— 他怎么老躲着人？\n— 做贼心虚。', en: 'The cat knows whose meat it ate.\n— Why does he keep avoiding eye contact?\n— A guilty conscience needs no accuser.', ctx: '谈做贼心虚' },
  { ru: 'Не хвались, идучи на рать, а хвались, идучи с рати.', zh: '出征前别夸口，凯旋后再吹牛。', en: 'Don\'t boast on the way to war; boast on the way back.', ctx: '谈别夸海口' },
  { ru: 'Бережёного Бог бережёт.\n— Возьми зонт: бережёного Бог бережёт.', zh: '上帝保佑谨慎的人（小心驶得万年船）。\n— 带上伞吧：小心驶得万年船。', en: 'God protects the careful.\n— Take an umbrella: better safe than sorry.', ctx: '谈谨慎有福' },
  { ru: 'Тихая вода берега подмывает.', zh: '平静的水能冲垮堤岸（静水流深）。', en: 'Still water undermines the banks.', ctx: '谈静水深流' },
  { ru: 'Не буди лихо, пока оно тихо.', zh: '麻烦还睡着，别去惹它（别自找麻烦）。', en: 'Don\'t wake trouble while it sleeps.', ctx: '劝人别惹事' },
  { ru: 'Ум хорошо, а два лучше.', zh: '一个脑袋好，两个脑袋更妙（三个臭皮匠，顶个诸葛亮）。', en: 'One mind is good, but two are better.', ctx: '谈集思广益' },
  { ru: 'Капля камень точит.\n— Каждый день по десять слов: капля камень точит.', zh: '水滴石穿。\n— 每天背十个单词：水滴石穿。', en: 'A drop wears away the stone.\n— Ten words every day: constant dropping wears the stone.', ctx: '谈滴水穿石' },
  { ru: 'Москва не сразу строилась.\n— Не выходит за месяц выучить падежи.\n— Москва не сразу строилась.', zh: '莫斯科不是一天建成的。\n— 一个月学不会变格。\n— 莫斯科不是一天建成的。', en: 'Moscow wasn\'t built in a day.\n— I can\'t master the cases in a month.\n— Rome wasn\'t built in a day.', ctx: '劝人别急求成' },
  { ru: 'Кто не рискует, тот не пьёт шампанского.', zh: '不冒险的人喝不上香槟（不入虎穴，焉得虎子）。', en: 'Nothing ventured, nothing gained.', ctx: '谈敢闯敢试' },
  { ru: 'Лиха беда начало.', zh: '万事开头难。', en: 'The first step is the hardest.', ctx: '谈开头最难' },
  { ru: 'Взялся за гуж — не говори, что не дюж.', zh: '既然套上了车轭，就别说拉不动（答应了就做到底）。', en: 'If you\'ve taken the harness, don\'t say you\'re not up to it.', ctx: '谈有始有终' },
  { ru: 'Не боги горшки обжигают.\n— Не бойся пробовать: не боги горшки обжигают.', zh: '瓦罐不是神烧的（别人能会，你也能会）。\n— 别怕尝试：瓦罐又不是神烧的。', en: 'It\'s not gods who fire the pots.\n— Don\'t be afraid to try: it\'s not rocket science.', ctx: '谈事在人为' },
  { ru: 'Без мученья нет ученья.', zh: '不吃苦，学不成。', en: 'No pain, no gain.', ctx: '谈吃苦成才' },
  { ru: 'Дорогу осилит идущий.', zh: '路要靠走的人才能走完（行者常至）。', en: 'The walker will master the road.', ctx: '谈行者常至' },
  { ru: 'Сколько верёвочке ни виться, а конец будет.', zh: '绳子再怎么绕，总有到头的时候（坏事总有尽头）。', en: 'No matter how the rope twists, it will come to an end.', ctx: '谈恶有尽头' },
  { ru: 'Терпи, казак, — атаманом будешь.\n— Тяжело на первом курсе?\n— Терпи, казак, — атаманом будешь.', zh: '忍耐吧，哥萨克，你会当上首领的（吃得苦中苦，方为人上人）。\n— 一年级太苦了。\n— 忍忍吧，熬出头就是首领。', en: 'Endure, Cossack — you\'ll become an ataman.\n— First year is tough?\n— Hang in there — you\'ll come out on top.', ctx: '谈忍耐出头' },
  { ru: 'Не в деньгах счастье.\n— Он богат, но совсем один.\n— Вот видишь, не в деньгах счастье.', zh: '幸福不在金钱。\n— 他很有钱，却孤身一人。\n— 你看，幸福不在金钱。', en: 'Money can\'t buy happiness.\n— He\'s rich but completely alone.\n— See, money can\'t buy happiness.', ctx: '谈金钱与幸福' },
  { ru: 'Копейка рубль бережёт.', zh: '省下一戈比，保住一卢布（积少成多）。', en: 'A kopeck saved saves the ruble.', ctx: '谈积少成多' },
  { ru: 'Долг платежом красен.\n— Вот твои пятьсот рублей, спасибо!\n— Долг платежом красен.', zh: '债还得漂亮，人才体面（好借好还，再借不难）。\n— 这是还你的五百卢布，谢谢！\n— 好借好还，再借不难。', en: 'A debt is beautiful when repaid.\n— Here are your five hundred rubles, thanks!\n— Pay back what you owe, and borrowing stays easy.', ctx: '谈有借有还' },
  { ru: 'Дружба дружбой, а табачок врозь.', zh: '交情归交情，烟叶各抽各（亲兄弟，明算账）。', en: 'Friendship is friendship, but tobacco is separate.', ctx: '谈明算账' },
  { ru: 'Скупой платит дважды.', zh: '吝啬鬼付双倍（贪便宜吃大亏）。', en: 'The miser pays twice.', ctx: '谈贪小便宜' },
  { ru: 'Деньги счёт любят.', zh: '钱喜欢被数（精打细算）。', en: 'Money loves to be counted.', ctx: '谈精打细算' },
  { ru: 'Дарёному коню в зубы не смотрят.\n— Подарили старенький телефон, но я рад: дарёному коню в зубы не смотрят.', zh: '赠送的马，不看牙口（受礼不挑）。\n— 送了我一部旧手机，但我很高兴：受礼不挑。', en: 'Don\'t look a gift horse in the mouth.\n— They gave me an old phone, but I\'m glad: don\'t look a gift horse in the mouth.', ctx: '谈受礼不挑' },
  { ru: 'Бедность не порок.', zh: '贫穷不是罪过。', en: 'Poverty is not a vice.', ctx: '谈贫穷非罪' },
  { ru: 'За двумя зайцами погонишься — ни одного не поймаешь.\n— Решил, что важнее: работа или учёба. За двумя зайцами погонишься — ни одного не поймаешь.', zh: '追两只兔子，一只也抓不到（贪多嚼不烂）。\n— 我决定哪个更重要：工作还是学习。贪多嚼不烂。', en: 'Chase two hares and you\'ll catch neither.\n— I decided what matters more: work or studies. If you chase two hares, you catch neither.', ctx: '谈贪多必失' },
  { ru: 'На чужой каравай рот не разевай.', zh: '别对着别人的大面包张嘴（别觊觎别人的东西）。', en: 'Don\'t open your mouth at someone else\'s loaf.', ctx: '谈别觊觎' },
  { ru: 'В здоровом теле здоровый дух.', zh: '健康的精神寓于健康的身体。', en: 'A sound mind in a sound body.', ctx: '谈身心健康' },
  { ru: 'Здоровье дороже золота.', zh: '健康贵于黄金。', en: 'Health is more precious than gold.', ctx: '谈健康无价' },
  { ru: 'Здоровье за деньги не купишь.\n— Опять ночами работаешь?\n— Здоровье за деньги не купишь.', zh: '金钱买不来健康。\n— 你又熬夜工作？\n— 金钱买不来健康。', en: 'You can\'t buy health with money.\n— Working nights again?\n— You can\'t buy health with money.', ctx: '谈健康买不来' },
  { ru: 'Болезнь входит пудами, а выходит золотниками.', zh: '病来如山倒，病去如抽丝。', en: 'Illness comes in poods and leaves in zolotniks.', ctx: '谈病来病去' },
  { ru: 'Здоров будешь — всё добудешь.', zh: '有了健康，什么都能得到。', en: 'If you\'re healthy, you\'ll achieve everything.', ctx: '谈健康是根本' },
  { ru: 'Жить — не поле перейти.', zh: '生活不是走过一片田野（人生不易）。', en: 'Life is no walk across a field.', ctx: '谈人生不易' },
  { ru: 'Что посеешь, то и пожнёшь.\n— Он всем грубил, теперь никто ему не помогает.\n— Что посеешь, то и пожнёшь.', zh: '种瓜得瓜，种豆得豆。\n— 他对谁都粗鲁，现在没人帮他。\n— 种瓜得瓜，种豆得豆。', en: 'You reap what you sow.\n— He was rude to everyone, and now nobody helps him.\n— You reap what you sow.', ctx: '谈因果报应' },
  { ru: 'Как аукнется, так и откликнется.', zh: '喊声怎样，回声就怎样（善有善报）。', en: 'As the call, so the echo.', ctx: '谈善有善报' },
  { ru: 'Готовь сани летом, а телегу зимой.\n— Почему ты в сентябре ищешь зимнюю куртку?\n— Готовь сани летом, а телегу зимой.', zh: '夏天备雪橇，冬天备大车（未雨绸缪）。\n— 你怎么九月份就找冬装？\n— 未雨绸缪。', en: 'Prepare the sleigh in summer and the cart in winter.\n— Why are you looking for a winter coat in September?\n— Prepare the sleigh in summer.', ctx: '谈未雨绸缪' },
  { ru: 'Береги честь смолоду.', zh: '从小就要爱惜名誉。', en: 'Take care of your honor from your youth.', ctx: '谈珍惜名誉' },
  { ru: 'Слово — серебро, молчание — золото.', zh: '雄辩是银，沉默是金。', en: 'Speech is silver, silence is golden.', ctx: '谈沉默是金' },
  { ru: 'Слово не воробей, вылетит — не поймаешь.\n— Жаль, что я это сказал...\n— Слово не воробей, вылетит — не поймаешь.', zh: '话不是麻雀，飞出去就抓不回来（一言既出，驷马难追）。\n— 真后悔说了那句话……\n— 一言既出，驷马难追。', en: 'A word is not a sparrow; once it flies out, you can\'t catch it.\n— I regret saying that...\n— A word spoken is past recalling.', ctx: '谈一言既出' },
  { ru: 'Молчи — за умного сойдёшь.', zh: '沉默不语，反显得聪明。', en: 'Keep silent and you\'ll pass for a wise man.', ctx: '谈沉默显智' },
  { ru: 'Кто много говорит, тот мало делает.', zh: '说得多的人，做得少。', en: 'He who talks much does little.', ctx: '谈说多做少' },
  { ru: 'Язык мой — враг мой.\n— Зачем я это ляпнул? Язык мой — враг мой.', zh: '我的舌头是我的敌人（祸从口出）。\n— 我干嘛多这句嘴？真是祸从口出。', en: 'My tongue is my enemy.\n— Why did I blurt that out? My tongue is my enemy.', ctx: '谈祸从口出' },
  { ru: 'Язык до Киева доведёт.', zh: '有舌头问路，能走到基辅（多问不迷路）。', en: 'The tongue will lead you to Kiev.', ctx: '谈多问不迷路' },
  { ru: 'Молчание — знак согласия.', zh: '沉默就是同意。', en: 'Silence means consent.', ctx: '谈沉默即同意' },
  { ru: 'На языке мёд, а на сердце лёд.', zh: '嘴上抹蜜，心里结冰（口蜜腹剑）。', en: 'Honey on the tongue, ice on the heart.', ctx: '谈口蜜腹剑' },
  { ru: 'Острый язык — дарование, длинный язык — наказание.', zh: '嘴快是天赋，话多是祸根。', en: 'A sharp tongue is a gift; a long tongue is a punishment.', ctx: '谈慎言' },
  { ru: 'Доброе слово и кошке приятно.\n— Спасибо за добрые слова!\n— Доброе слово и кошке приятно.', zh: '好话连猫也爱听（良言一句三冬暖）。\n— 谢谢你的鼓励！\n— 好话连猫也爱听。', en: 'A kind word pleases even a cat.\n— Thank you for the kind words!\n— A kind word pleases even a cat.', ctx: '谈良言暖人' },
  { ru: 'На ошибках учатся.\n— Опять ошибся в спряжении.\n— Ничего, на ошибках учатся.', zh: '吃一堑，长一智（在错误中学习）。\n— 动词变位又错了。\n— 没事，吃一堑，长一智。', en: 'We learn from our mistakes.\n— Got the conjugation wrong again.\n— Never mind, we learn from our mistakes.', ctx: '谈从错误学习' },
  { ru: 'Цыплят по осени считают.\n— Рано радуешься, цыплят по осени считают.', zh: '小鸡要到秋天才数（秋后算账，别高兴太早）。\n— 别高兴得太早，秋后算账。', en: 'Chicks are counted in autumn.\n— Don\'t celebrate too early; don\'t count your chickens before they hatch.', ctx: '谈秋后算账' },
  { ru: 'За битого двух небитых дают.', zh: '一个挨过打的，顶两个没挨过打的（经验最宝贵）。', en: 'A beaten one is worth two unbeaten.', ctx: '谈经验宝贵' },
  { ru: 'Старый конь борозды не испортит.\n— Поручим это Ивану Петровичу: старый конь борозды не испортит.', zh: '老马不会踩坏犁沟（老马识途）。\n— 这事交给伊万·彼得罗维奇吧：老马识途。', en: 'An old horse won\'t spoil the furrow.\n— Let\'s entrust it to Ivan Petrovich: an old horse won\'t spoil the furrow.', ctx: '谈老马识途' },
  { ru: 'Умный учится на чужих ошибках, а дурак — на своих.', zh: '聪明人从别人的错误中学习，傻瓜从自己的错误中学习。', en: 'A smart man learns from others\' mistakes; a fool from his own.', ctx: '谈借鉴他人' },
  { ru: 'Кто старое помянет, тому глаз вон.\n— А помнишь, как ты тогда опоздал?\n— Кто старое помянет, тому глаз вон.', zh: '谁翻旧账，挖谁眼睛（既往不咎）。\n— 还记得你那次迟到吗？\n— 谁翻旧账，挖谁眼睛。', en: 'Whoever brings up the past should lose an eye.\n— Remember when you were late that time?\n— Let bygones be bygones.', ctx: '谈既往不咎' },
  { ru: 'После драки кулаками не машут.', zh: '打完架再挥拳头，为时已晚（事后诸葛亮）。', en: 'Don\'t wave your fists after the fight.', ctx: '谈事后诸葛' },
  { ru: 'Первый блин — комом.\n— Эссе получилось так себе.\n— Первый блин — комом, дальше пойдёт.', zh: '第一张煎饼总是糊的（头一回难免失手）。\n— 这篇作文写得不怎么样。\n— 第一张煎饼总是糊的，往后会好的。', en: 'The first pancake is always a lump.\n— The essay turned out so-so.\n— The first pancake is always a lump; it\'ll get better.', ctx: '谈开头难免错' },
  { ru: 'Шила в мешке не утаишь.', zh: '袋子里藏不住锥子（纸包不住火）。', en: 'You can\'t hide an awl in a sack.', ctx: '谈纸包不住火' },
  { ru: 'Дважды в одну реку не войдёшь.', zh: '人不能两次踏入同一条河流。', en: 'You cannot step into the same river twice.', ctx: '谈世事变迁' },
  { ru: 'Волка ноги кормят.', zh: '狼靠四条腿吃饭（勤快人才有饭吃）。', en: 'The wolf is fed by his legs.', ctx: '谈勤劳得食' },
  { ru: 'Волков бояться — в лес не ходить.\n— А вдруг на собеседовании провалюсь?\n— Волков бояться — в лес не ходить.', zh: '怕狼就别进森林。\n— 万一面试砸了怎么办？\n— 怕狼就别进森林。', en: 'If you\'re afraid of wolves, don\'t go into the forest.\n— What if I fail the interview?\n— If you\'re afraid of wolves, don\'t go into the forest.', ctx: '谈勇者无惧' },
  { ru: 'В тихом омуте черти водятся.\n— Он всегда молчит, а какие идеи выдаёт!\n— В тихом омуте черти водятся.', zh: '静水潭里藏着鬼（静水流深，闷人有主意）。\n— 他平时不声不响，点子倒不少！\n— 静水流深。', en: 'Still waters run deep.\n— He\'s always quiet, but what ideas he comes up with!\n— Still waters run deep.', ctx: '谈静水藏深' },
  { ru: 'Сколько волка ни корми, он в лес смотрит.', zh: '狼喂得再饱，眼睛还望着森林（本性难移）。', en: 'No matter how much you feed a wolf, it keeps looking at the forest.', ctx: '谈本性难移' },
  { ru: 'Без кота мышам раздолье.\n— Учитель заболел, класс гудит.\n— Без кота мышам раздолье.', zh: '猫不在家，老鼠翻天（山中无老虎，猴子称大王）。\n— 老师病了，全班闹翻了天。\n— 山中无老虎，猴子称大王。', en: 'When the cat\'s away, the mice will play.\n— The teacher is ill and the class is in uproar.\n— When the cat\'s away, the mice will play.', ctx: '谈山中无老虎' },
  { ru: 'Ворон ворону глаз не выклюет.', zh: '乌鸦不啄乌鸦的眼（官官相护）。', en: 'A crow won\'t peck out another crow\'s eye.', ctx: '谈同类相护' },
  { ru: 'Рыба гниёт с головы.', zh: '鱼从头烂起（上梁不正下梁歪）。', en: 'The fish rots from the head.', ctx: '谈上梁不正' },
  { ru: 'Седина в бороду, бес в ребро.\n— Дедушка в шестьдесят лет записался на танцы.\n— Седина в бороду, бес в ребро.', zh: '白胡子长出来，魔鬼钻进肋骨（人老心不老）。\n— 爷爷六十岁还报了舞蹈班。\n— 人老心不老。', en: 'Grey hair in the beard, a devil in the ribs.\n— Grandpa signed up for dance classes at sixty.\n— There\'s no fool like an old fool.', ctx: '谈人老心不老' },
  { ru: 'У каждой пташки свои замашки.', zh: '每只小鸟都有自己的脾气（各人有各人的习惯）。', en: 'Every bird has its own habits.', ctx: '谈各有脾性' },
  { ru: 'Птица видна по полёту.', zh: '看飞行识鸟（观其行而知其人）。', en: 'A bird is known by its flight.', ctx: '谈观其行知人' },
  { ru: 'Не было бы счастья, да несчастье помогло.\n— Опоздал на поезд, зато встретил старого друга на вокзале.\n— Не было бы счастья, да несчастье помогло.', zh: '要不是倒霉，哪来好运（塞翁失马，焉知非福）。\n— 误了火车，却在车站碰上了老朋友。\n— 塞翁失马，焉知非福。', en: 'If it weren\'t for bad luck, there\'d be no luck at all.\n— I missed the train but met an old friend at the station.\n— A blessing in disguise.', ctx: '谈塞翁失马' },
  { ru: 'От судьбы не уйдёшь.', zh: '命运是躲不开的。', en: 'You can\'t escape fate.', ctx: '谈命运难逃' },
  { ru: 'Чему быть, того не миновать.', zh: '该发生的事，躲也躲不掉。', en: 'What must be, cannot be avoided.', ctx: '谈该来躲不掉' },
  { ru: 'Будь что будет.\n— Страшно лететь одному в Россию?\n— Немного, но будь что будет!', zh: '该怎样就怎样（听天由命）。\n— 一个人飞俄罗斯，害怕吗？\n— 有点，但听天由命吧！', en: 'Come what may.\n— Scared to fly to Russia alone?\n— A little, but come what may!', ctx: '谈听天由命' },
  { ru: 'На ловца и зверь бежит.\n— Как раз тебя вспоминали!\n— На ловца и зверь бежит.', zh: '猎物自己跑向猎人（踏破铁鞋无觅处，得来全不费工夫）。\n— 我们正好在念叨你！\n— 得来全不费工夫。', en: 'The beast runs to the catcher.\n— We were just talking about you!\n— Speak of the devil.', ctx: '谈得来不费工夫' },
  { ru: 'Рожденный ползать летать не может.', zh: '生来会爬的不会飞（江山易改，本性难移）。', en: 'Born to crawl cannot fly.', ctx: '谈天生禀赋' },
  { ru: 'Все дороги ведут в Рим.\n— Он учил слова по песням, а я по карточкам.\n— Все дороги ведут в Рим.', zh: '条条大路通罗马。\n— 他靠唱歌记单词，我靠卡片。\n— 条条大路通罗马。', en: 'All roads lead to Rome.\n— He learned words through songs, I used flashcards.\n— All roads lead to Rome.', ctx: '谈殊途同归' },
  { ru: 'Ничто не вечно под луной.', zh: '月无长圆（天下没有不散的筵席）。', en: 'Nothing lasts forever under the moon.', ctx: '谈世事无常' },
  { ru: 'Судьба — индейка, жизнь — копейка.', zh: '命运是只火鸡，人生只值一戈比（戏谈命运无常）。', en: 'Fate is a turkey, life is a kopeck.', ctx: '戏谈命运无常' },
  { ru: 'Легко пришло — легко ушло.\n— Выигранные деньги сразу проиграл.\n— Легко пришло — легко ушло.', zh: '来得容易，去得快（易得易失）。\n— 赢来的钱转眼又输光了。\n— 来得容易，去得快。', en: 'Easy come, easy go.\n— He lost all his winnings right away.\n— Easy come, easy go.', ctx: '谈易得易失' },
  { ru: 'Ни пуха ни пера!\n— Завтра экзамен по русскому.\n— Ни пуха ни пера!\n— К чёрту!', zh: '祝你满载而归！（猎人送行语；按习俗要回答“见鬼去吧”）\n— 明天考俄语。\n— 祝你一根毛也捞不着！\n— 见鬼去吧！', en: 'Break a leg! (lit. neither down nor feather; the customary reply is "To the devil!")\n— My Russian exam is tomorrow.\n— Break a leg!\n— To the devil!', ctx: '考前祝福应答' },
  { ru: 'Висеть на телефоне\n— Она весь вечер висит на телефоне с подругой.', zh: '煲电话粥\n— 她一晚上都在跟闺蜜煲电话粥。', en: 'To be glued to the phone\n— She\'s been on the phone with her friend all evening.', ctx: '谈煲电话粥' },
  { ru: 'Бить баклуши\n— Хватит бить баклуши, садись за учебники!', zh: '游手好闲，无所事事\n— 别再游手好闲了，坐下看书！', en: 'To twiddle one\'s thumbs\n— Stop loafing around and get to your textbooks!', ctx: '谈游手好闲' },
  { ru: 'Дело в шляпе\n— Отправил документы на визу? — Дело в шляпе!', zh: '事情办妥了，大功告成\n— 签证材料交了吗？——办妥了！', en: 'It\'s in the bag\n— Did you submit the visa documents? — It\'s in the bag!', ctx: '谈大功告成' },
  { ru: 'Как с гуся вода\n— Ему все замечания как с гуся вода.', zh: '像鹅身上的水一样，滑过去就完（满不在乎）。\n— 批评对他来说都是耳边风。', en: 'Like water off a duck\'s back\n— All remarks are like water off a duck\'s back to him.', ctx: '谈满不在乎' },
  { ru: 'Спустя рукава\n— Сделал домашку спустя рукава — опять ошибки.', zh: '马马虎虎，敷衍了事\n— 作业敷衍了事——又错了。', en: 'Carelessly, half-heartedly\n— He did his homework half-heartedly — mistakes again.', ctx: '谈敷衍了事' },
  { ru: 'Витать в облаках', zh: '想入非非，心不在焉', en: 'To have one\'s head in the clouds', ctx: '谈心不在焉' },
  { ru: 'Зарубить на носу\n— Заруби себе на носу: сначала согласование, потом сроки.', zh: '牢牢记住（刻在鼻子上）\n— 你给我牢牢记住：先一致性，后期限。', en: 'To get it into one\'s head\n— Get this into your head: agreement first, deadlines later.', ctx: '谈牢记在心' },
  { ru: 'Водить за нос', zh: '牵着鼻子走，蒙骗人', en: 'To lead someone by the nose', ctx: '谈蒙骗他人' },
  { ru: 'Сесть в лужу\n— Перепутал «жена» и «жерна» — сел в лужу перед всеми.', zh: '出洋相，栽跟头\n— 把“妻子”说成了别的词——当众出了洋相。', en: 'To put one\'s foot in it\n— He mixed up the words and made a fool of himself in front of everyone.', ctx: '谈出洋相' },
  { ru: 'Хлеб — всему голова.', zh: '面包是万物之首（民以食为天）。', en: 'Bread is the head of everything.', ctx: '谈民以食为天' },
  { ru: 'Хлеб-соль ешь, а правду режь.', zh: '吃着人家的面包和盐，也要说真话（忠言逆耳）。', en: 'Eat one\'s bread and salt, but speak the truth.', ctx: '谈忠言逆耳' },
  { ru: 'Кашу маслом не испортишь.\n— Положи побольше укропа: кашу маслом не испортишь.', zh: '粥里油多不坏（多多益善；礼多人不怪）。\n— 多放点茴香：多多益善。', en: 'You can\'t spoil porridge with butter.\n— Add more dill: you can\'t spoil porridge with butter.', ctx: '谈多多益善' },
  { ru: 'Щи да каша — пища наша.\n— Опять щи на обед?\n— Щи да каша — пища наша.', zh: '菜汤和粥就是我们的饭。\n— 午饭又是菜汤？\n— 菜汤和粥就是我们的饭。', en: 'Cabbage soup and porridge are our food.\n— Cabbage soup for lunch again?\n— Soup and porridge are our fare.', ctx: '谈家常便饭' },
  { ru: 'Без соли, без хлеба — половина обеда.', zh: '没有盐和面包，宴席就少了一半。', en: 'Without salt and bread, dinner is half a meal.', ctx: '谈盐与面包' },
  { ru: 'Голод не тётка, пирожка не поднесёт.\n— Ешь что дают: голод не тётка, пирожка не поднесёт.', zh: '饥饿不是姑姑，不会给你递馅饼（饥不择食）。\n— 给什么吃什么：饥饿不是姑姑，不会递馅饼。', en: 'Hunger is no auntie; it won\'t hand you a pie.\n— Eat what you\'re given: hunger is no auntie.', ctx: '谈饥不择食' },
  { ru: 'Сыт голодного не разумеет.', zh: '饱汉不知饿汉饥。', en: 'The full don\'t understand the hungry.', ctx: '谈饱汉不知饿' },
  { ru: 'Дорог не подарок — дорого внимание.\n— Это всего лишь магнитик из Москвы.\n— Дорог не подарок — дорого внимание.', zh: '礼物不贵，情意可贵（礼轻情意重）。\n— 这只是从莫斯科带的小冰箱贴。\n— 礼轻情意重。', en: 'It\'s not the gift that\'s precious, but the attention.\n— It\'s just a little magnet from Moscow.\n— It\'s the thought that counts.', ctx: '谈礼轻情意重' },
  { ru: 'Аппетит приходит во время еды.', zh: '胃口越吃越有（吃着吃着就开胃了）。', en: 'Appetite comes with eating.', ctx: '谈越吃越开胃' },
  { ru: 'У голодной кумы хлеб на уме.\n— Разговор снова сошёл на еду.\n— У голодной кумы хлеб на уме.', zh: '饿着肚子的干亲家满脑子都是面包（饥者易为食）。\n— 话题又绕到吃的上了。\n— 饿汉满脑子都是面包。', en: 'A hungry godmother has bread on her mind.\n— The conversation turned to food again.\n— The hungry think only of bread.', ctx: '谈饥者易为食' },
]

